# 文献正文里的结构化标记（标题/图表/公式锚点），喂给 LLM 生成卡片/小测前一律剥掉。
# 它们携带方括号、花括号、反斜杠等字符，混入 prompt 极易破坏 JSON、诱发模型死循环。
_SOURCE_LLM_MARKER_RE = re.compile(r"\[\[[^\]]*\]\]")


def _clean_source_text_for_llm(text: str) -> str:
    """把 source 原文本清洗成可安全喂给 LLM 的正文：剥掉 [[...]] 结构标记 + 归一空白。"""
    if not text:
        return ""
    text = _SOURCE_LLM_MARKER_RE.sub(" ", text)
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n[ \t]*\n+", "\n\n", text)
    return text.strip()


# source.formulas 每个条目常携带 base64 的公式图片截图（image 可达数 MB）。
# 该截图仅供前端渲染原图，LLM 提示词完全用不到，却会把单次请求撑爆 max_context。
# 提示词里只保留轻量文本字段并限长限条数。
_FORMULA_PROMPT_FIELDS = ("id", "text", "formula", "raw", "page", "number")
_FORMULA_PROMPT_MAX_LATEX = 1200
_FORMULA_PROMPT_MAX_PER_SOURCE = 80


def _first_json_object(text: str) -> tuple[Any, int] | None:
    """若 text 以一个完整闭合的顶层 JSON 对象开头，返回 (解析结果, 该对象的结束下标)；否则 None。

    用花括号配平 + 字符串状态机扫描，不靠正则 —— 正文里出现 `{` 或引号时不会误判。
    """
    t = text.strip()
    if not t.startswith("{"):
        return None
    depth = 0
    in_str = False
    esc = False
    for i, ch in enumerate(t):
        if in_str:
            if esc:
                esc = False
            elif ch == "\\":
                esc = True
            elif ch == '"':
                in_str = False
            continue
        if ch == '"':
            in_str = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                try:
                    return json.loads(t[: i + 1]), i
                except Exception:
                    return None
    return None


_FIELD_LABEL_WORDS: tuple[str, ...] = ("content", "title", "answer")
_FIELD_LABEL_COLONS = (":", "：")


def _field_label_state(text: str) -> str:
    """判定开头是不是（或可能是一个）字段名标签：``label`` / ``maybe`` / ``no``。

    为什么需要：教学模式的人设要求模型"把话写进 content"，而流式链路没有 JSON schema，
    模型偶发把这个字段名当标签写进正文 —— 2026-09-26 真机实测出现过
    `content: 趋肤深度 ...`，气泡里就多出一截字段名。
    提示词侧不能再补"不要输出 content:"这类禁令（一提 JSON / 字段名，模型反而更爱输出，
    见 teaching_mode 里那条反向验证记录），只能在输出侧剥。

    ``maybe`` 表示"还没看完，可能正在写标签词"（如 `cont`）—— 流式链路靠它决定继续攒。
    """
    body = str(text or "").lstrip().lower()
    if not body:
        return "maybe"
    for word in _FIELD_LABEL_WORDS:
        if not body.startswith(word):
            continue
        rest = body[len(word) :].lstrip()
        if not rest:
            return "maybe"  # 只写到 "content"，冒号可能还在下一个 chunk
        return "label" if rest[0] in _FIELD_LABEL_COLONS else "no"
    return (
        "maybe" if any(word.startswith(body) for word in _FIELD_LABEL_WORDS) else "no"
    )


def _strip_field_label(text: str) -> str:
    """剥掉正文开头的 `content:` / `title:` / `answer:` 字段名标签（只在开头，最多两层）。"""
    body = str(text or "")
    for _ in range(2):
        stripped = body.lstrip()
        lowered = stripped.lower()
        for word in _FIELD_LABEL_WORDS:
            if not lowered.startswith(word):
                continue
            rest = stripped[len(word) :].lstrip()
            if rest[:1] in _FIELD_LABEL_COLONS:
                body = rest[1:].lstrip()
                break
        else:
            break
    return body


def _shell_end(text: str) -> int:
    """宽松扫描：返回顶层 JSON 对象闭合 ``}`` 的下标；没闭合返回 -1。

    与 ``_first_json_object`` 的区别是**不做转义校验**：字符串里的反斜杠只认 ``\\"`` 与 ``\\\\``，
    其余一律当普通字符。为什么必须宽松 —— 2026-09-26 真机实测：教学模式的 shell 里全是 LaTeX，
    `$\\delta$` 里的 `\\d` 是非法 JSON 转义，`json.loads` 直接抛错，
    于是 ``_first_json_object`` 判不出外壳、原文整段漏给用户（气泡里又是一坨 JSON）。
    """
    depth = 0
    in_str = False
    i = 0
    while i < len(text):
        ch = text[i]
        if in_str:
            if ch == "\\" and i + 1 < len(text):
                i += 2
                continue
            if ch == '"':
                in_str = False
            i += 1
            continue
        if ch == '"':
            in_str = True
        elif ch == "{":
            depth += 1
        elif ch == "}":
            depth -= 1
            if depth == 0:
                return i
        i += 1
    return -1


_JSON_SHELL_KEY_RE = re.compile(r'"(answer|content)"\s*:\s*"')


def _read_json_string(body: str) -> str:
    """从（可能未闭合的）JSON 字符串值里取正文，**保留 LaTeX 反斜杠**。

    不能交给 ``json.loads``：`\\nu` / `\\frac` / `\\theta` 会被当成 `\\n` / `\\f` / `\\t` 转义，
    轻则报错、重则把公式转义坏。这里只把 ``\\"`` 还原成引号、``\\\\`` 还原成反斜杠，
    其余反斜杠原样保留。
    """
    out: list[str] = []
    i = 0
    while i < len(body):
        ch = body[i]
        if ch == "\\" and i + 1 < len(body):
            nxt = body[i + 1]
            if nxt == '"':
                out.append('"')
                i += 2
                continue
            if nxt == "\\":
                out.append("\\")
                i += 2
                continue
            out.append("\\")  # LaTeX 反斜杠：原样留，不做转义
            i += 1
            continue
        if ch == '"':
            break
        out.append(ch)
        i += 1
    return "".join(out)


def _unwrap_answer_json(text: str) -> str:
    """弱模型偶尔无视"去 JSON 外壳"指令，把答案包成 {"answer":"..."}，写库前把外壳剥掉。

    仅当文本以一个完整的、带 string 类型 answer / content 字段的顶层 JSON 对象开头时解包，
    其后若还有残留正文则拼回；其余情况原样返回，绝不臆改正文。

    也要认 content：教学模式的人设要求模型"把话写进 content"（另给一个 title），
    于是产出 {"title":...,"content":...}。只认 answer 的话这层外壳会原样进库，
    而前端 stripAnswerJsonWrapper 也只认 answer，用户就在气泡里看到一坨 JSON
    —— 2026-09-26 真机截图复现，且 app.js 属硬约束不能改，只能后端剥。

    严格解析失败时走 ``_shell_end`` 宽松路径：教学模式的 shell 里常带 LaTeX
    （`$\\delta$` 的 `\\d` 是非法转义），``json.loads`` 会抛错 —— 这条路径才能剥掉它。
    外壳剥掉后还要过一遍 ``_strip_field_label``：模型有时连 JSON 都不写，
    直接以 `content: ...` 起头（同一个"字段口径"锚点的另一种漏法）。
    """
    if not text:
        return text
    stripped = text.strip()
    if not stripped.startswith("{"):
        return _strip_field_label(text)
    parsed = _first_json_object(text)
    if parsed is not None:
        obj, end = parsed
        if isinstance(obj, dict):
            # 优先 answer：旧形态不受影响；content 是教学模式新增的那层壳。
            for key in ("answer", "content"):
                value = obj.get(key)
                if isinstance(value, str):
                    return _strip_field_label(value + stripped[end + 1 :])
    # 严格解析失败（多半是 LaTeX 反斜杠）→ 宽松切外壳 + 宽松取值
    end = _shell_end(stripped)
    if end >= 0:
        match = _JSON_SHELL_KEY_RE.search(stripped[: end + 1])
        if match is not None:
            value = _read_json_string(stripped[match.end() : end])
            if value.strip():
                return _strip_field_label(value + stripped[end + 1 :])
    return _strip_field_label(text)


def _unwrap_double_encoded_json(text: str) -> str:
    """解掉模型偶尔输出的「双重编码」JSON 字符串。

    多次引导续问后，弱模型偶发把苏格拉底 JSON 再包一层字符串转义输出，形如
    `"{\\"question\\":\\"...\\",...}"`（最外是英文双引号、内部键/值转义）。若不处理，
    前端 kbTryParseSocratic 把它当普通正文展示，用户会看到一坨转义 JSON。
    这里逐层 json.loads 解包，直到不再是「整段是一个字符串字面量」为止；非此形态原样返回。
    """
    if not text:
        return text
    t = text.strip()
    changed = False
    for _ in range(3):
        if not (t.startswith('"') and t.endswith('"')):
            break
        try:
            inner = json.loads(t)
        except Exception:  # noqa: BLE001 - 解析失败按原文处理
            break
        if not isinstance(inner, str):
            break
        inner_stripped = inner.strip()
        if not (inner_stripped.startswith("{") or inner_stripped.startswith('"')):
            break
        t = inner_stripped
        changed = True
    return t if changed else text


def _extract_completed_questions(text: str) -> list[str]:
    """从累计文本中提取当前已收齐的 `questions` 数组字符串元素。

    只返回已完整闭合的字面量；正在流式、尚未闭合的元素不返回，等后续 token 闭合引号后再出现。
    """
    t = text or ""
    key = t.find('"questions"')
    if key < 0:
        return []
    br = t.find("[", key)
    if br < 0:
        return []
    n = len(t)
    out: list[str] = []
    i = br + 1
    while i < n:
        ch = t[i]
        if ch == '"':
            j = i + 1
            esc = False
            buf: list[str] = []
            closed = False
            while j < n:
                c2 = t[j]
                if esc:
                    buf.append(c2)
                    esc = False
                elif c2 == "\\":
                    esc = True
                elif c2 == '"':
                    closed = True
                    break
                else:
                    buf.append(c2)
                j += 1
            if closed:
                out.append("".join(buf))
                i = j + 1
                continue
            break  # 未闭合字符串：等待更多 token，本次不再继续扫
        elif ch == "]":
            break
        i += 1
    return out


def _prompt_formulas(formulas: Any) -> list[dict[str, Any]]:
    if not formulas:
        return []
    kept: list[dict[str, Any]] = []
    for f in formulas:
        if not isinstance(f, dict):
            continue
        slim = {k: f.get(k) for k in _FORMULA_PROMPT_FIELDS if k in f}
        for k in ("text", "formula", "raw"):
            v = slim.get(k)
            if isinstance(v, str) and len(v) > _FORMULA_PROMPT_MAX_LATEX:
                slim[k] = v[:_FORMULA_PROMPT_MAX_LATEX]
        kept.append(slim)
        if len(kept) >= _FORMULA_PROMPT_MAX_PER_SOURCE:
            break
    return kept


def source_excerpts(
    sources: list[Any],
    per_source_limit: int = 5000,
    total_limit: int = 28000,
    query: str = "",
) -> list[dict[str, Any]]:
    """Return bounded excerpts, searching the whole source for question answering."""

    usable_sources = [
        source
        for source in sources
        if str(source.text or "").strip() or getattr(source, "formulas", [])
    ]
    if not usable_sources or total_limit <= 0 or per_source_limit <= 0:
        return []

    # Share the context budget so later selected files cannot be hidden by earlier ones.
    fair_limit = max(1, total_limit // len(usable_sources))
    source_limit = min(per_source_limit, fair_limit)
    remaining = total_limit
    excerpts: list[dict[str, Any]] = []
    for source in usable_sources:
        if remaining <= 0:
            break
        limit = min(source_limit, remaining)
        raw_text = _clean_source_text_for_llm(str(source.text or ""))
        text = (
            _relevant_source_text(raw_text, query, limit)
            if query.strip()
            else raw_text[:limit]
        )
        if not text and not getattr(source, "formulas", []):
            continue
        excerpts.append(
            {
                "source_id": source.source_id,
                "filename": source.filename,
                "text": text,
                "formulas": _prompt_formulas(getattr(source, "formulas", [])),
            }
        )
        remaining -= len(text)
    return excerpts


class DiscussionStartRequest(BaseModel):
    node_id: str = Field(..., min_length=1)
    quote: str | None = (
        None  # 用户在笔记/预览中划选的讨论焦点句（可空，空则整节点讨论）
    )


class DiscussionActRequest(BaseModel):
    conversation_id: str = Field(..., min_length=1)
    user_reply: str | None = None
    listen_only: bool = False
    correct: bool | None = None  # 仅 wait_user 作答时：True → 掌握度加额
    force_skip: bool = False  # 自由对话：不想作答时点「继续讨论」跳过等待


class PetReactRequest(BaseModel):
    """让 tju-llm 为海小棠生成一句有温度的反馈/鼓励/评价（不落库、不改掌握度）。"""

    kind: str = Field(..., min_length=1)
    context: dict[str, Any] = Field(default_factory=dict)


class WxFollowRequest(BaseModel):
    """校园速递「关注清单」的勾选。

    四种模式，按优先级取第一个命中的：
    - ``only``  —— 只关注这些号，其余取消（"学院号按需，只留必看"）
    - ``all``   —— 全部关注 / 全部取消
    - ``names`` —— 批量设置（清单里按类别整组处理）
    - ``name``  —— 单条切换
    """

    name: str = ""
    follow: bool = True
    all: bool | None = None
    names: list[str] | None = None
    only: list[str] | None = None


class PromptOverrideRequest(BaseModel):
    """提示词实验室：改写/重置某个 AI 任务的 system prompt。

    必须定义在模块层：本文件启用了 ``from __future__ import annotations``，
    函数内定义的模型注解会退化成 ForwardRef 而无法解析（报 class-not-fully-defined）。
    """

    task: str = Field(..., min_length=1)
    prompt: str = ""


def _hxt_react_gains(g: Any) -> str:
    if not g:
        return "暂无明显变化"
    if isinstance(g, list):
        parts = [str(x) for x in g]
        return "、".join(parts) if parts else "暂无明显变化"
    s = str(g)
    # 前端传的 gains 常带「掌握度上涨：」前缀，这里剥离，避免与场景句式重复
    if s.startswith("掌握度上涨："):
        s = s[len("掌握度上涨：") :]
    return s.strip() or "暂无明显变化"


# 把学习动作翻译成一句给 LLM 的自然场景描述（注入具体信息，让海小棠的话更贴切）
def _hxt_react_scene(kind: str, ctx: dict[str, Any]) -> str:
    gains = _hxt_react_gains(ctx.get("gains"))
    if kind == "rate":
        return f"刚在知识卡片上把一道题自评为「{ctx.get('rate') or '…'}」。（各节点掌握度变化：{gains}）"
    if kind == "quiz":
        return f"刚做完一份小测验，得分 {int(ctx.get('correct') or 0)}/{int(ctx.get('total') or 0)}。（掌握度更新：{gains}）"
    if kind == "dialog":
        return f"刚进行了一轮关于知识点的对话学习。（对话后掌握度更新：{gains}）"
    if kind == "dialog_quiz":
        return f"刚在引导对话里做完一次节点小测验。（掌握度更新：{gains}）"
    if kind == "diff":
        diff = ctx.get("difficulty") or ""
        meaning = {
            "自动": "结合你目前的掌握情况，从易到难自动挑题，先巩固再挑战",
            "简单": "对应认知层级的「记忆」与「理解」，考的是对知识的定义、概念与基本理解",
            "中等": "对应「应用」与「分析」，把概念放进情景里，考运用知识解决问题、分析拆解的能力",
            "困难": "对应「评价」与「创造」，是开放、综合的高阶题，考评判、综合与创造力",
        }.get(diff, "")
        if meaning:
            return (
                f"刚选择了测验难度「{diff}」。这一档的设定含义是：{meaning}。"
                "请别照抄设定，要用你自己的话向学习者解释清楚这一档到底考什么、适合什么阶段。"
            )
        return f"刚选择了测验难度「{diff}」。"
    if kind == "graph_drag":
        node = ctx.get("node") or ""
        links = ctx.get("links") or []
        links_s = "、".join(str(x) for x in links) if links else "（还没有双链邻居）"
        return f"刚在双链图谱上拖动了节点「{node}」，它的关联节点是：{links_s}。"
    if kind == "card_hint":
        q = (ctx.get("question") or "").strip()
        if len(q) > 120:
            q = q[:120] + "…"
        if q:
            return (
                f"学习者在复习知识卡片，把指针悬停在题面上还没翻面看答案。"
                f"这张卡片的题目是：「{q}」。"
                "请给一句引导思考的提示，点到回忆方向或解题思路即可，不要直接说出答案。"
            )
        return "学习者在复习知识卡片，把指针悬停在题面上还没翻面看答案。"
    return "学习者刚刚做了一件学习上的事。"


def anchor_discussion_source(
    db: Database,
    project_id: str,
    node_id: str,
    per_source_limit: int = 1200,
    total_limit: int = 4500,
) -> dict[str, str]:
    """T4/D3 锚点：把节点 node_id 解析成「话题 + 锚定原文」，供 AI 同学讨论注入。

    复用 source_excerpts 做有界截取（per_source≈1200 / total≈4500，对齐 design.md 上下文预算）。
    节点缺 source_ids 时回退到全量可用来源，避免空锚点；节点不存在时返回空 dict。
    """
    try:
        node = db.get_framework_node(project_id, node_id)
    except NodeNotFound:
        return {}
    if node is None:
        return {}
    all_sources = db.list_sources(project_id)
    active = [
        source
        for source in all_sources
        if source.status == "ok" and (source.text or "").strip()
    ]
    active_ids = {source.source_id for source in active}
    node_source_ids = [sid for sid in (node.source_ids or []) if sid in active_ids]
    chosen = (
        [source for source in active if source.source_id in node_source_ids]
        if node_source_ids
        else active
    )
    excerpts = source_excerpts(
        chosen, per_source_limit, total_limit, query=node.name or ""
    )
    source_text = "\n\n".join(
        f"[{ex['filename']}] {ex['text']}" for ex in excerpts if ex["text"]
    )
    return {
        "node_id": node.node_id,
        "topic": node.name or "未命名知识点",
        "source_text": source_text,
    }


