def _estimate_difficulty_pool_capacities(
    sources: list[Any],
) -> dict[int, int]:
    """
    【新版：基于来源真实内容估算三个难度级别的「可出题考点库存」】
    用于决定「下一批难度」——避免原 max+1 粗暴升级导致来源撑不起高难度时模型乱造题。

    方法：扫描 sources 文本，统计能抽取出的「知识点信号」总量（基础 = 定义/术语/公式名）；
    然后统计这些知识点附近出现的「机制/对比/条件」关键词比例 → 作为中级库存；
    再统计「迁移/综合/辨析/易错」关键词 → 作为高级库存。

    返回：{1: n_basic, 2: n_intermediate, 3: n_advanced}
    """
    from core.framework import (
        _knowledge_name_from_line,
        _contains_knowledge_signal,
        _evidence_subject,
        _clean_evidence_text,
    )

    basic_terms: set[str] = set()
    intermediate_terms: set[str] = set()
    advanced_terms: set[str] = set()

    INTERMEDIATE_KEYWORDS = (
        "条件",
        "适用范围",
        "为什么",
        "原因",
        "机制",
        "区别",
        "对比",
        "比较",
        "推导",
        "步骤",
        "流程",
        "方法",
        "判断",
        "优缺点",
        "分类",
        "影响因素",
        "因果",
        "关系",
        "如何计算",
        "如何推导",
        "规则",
        "推导步骤",
    )
    ADVANCED_KEYWORDS = (
        "综合",
        "迁移",
        "边界",
        "辨析",
        "易错",
        "常见错误",
        "误判",
        "矛盾",
        "实验",
        "误差",
        "偏差",
        "场景",
        "实例",
        "应用到",
        "改变",
        "调整后",
        "失效",
        "假设",
        "设计",
        "约束",
        "容差",
        "极限",
        "近似失效",
    )

    for source in sources:
        if source is None:
            continue
        raw_text = ""
        try:
            raw_text = str(getattr(source, "text", "") or "")
        except Exception:  # noqa: BLE001
            raw_text = ""
        if not raw_text and isinstance(source, dict):
            raw_text = str(source.get("text") or source.get("content") or "")
        if not raw_text:
            continue
        cleaned = _clean_evidence_text(raw_text)
        for line in re.split(r"[。；;\n]", cleaned):
            line = line.strip()
            if len(line) < 4:
                continue
            # 1) 抽取基础知识点名
            term_candidates: list[str] = []
            kn_info = _knowledge_name_from_line(line)
            if isinstance(kn_info, tuple):
                kn_name, _ = kn_info
            else:
                kn_name = kn_info
            if kn_name:
                term_candidates.append(str(kn_name)[:60])
            # 同时用 evidence_subject 抓主语
            try:
                subj = _evidence_subject(line)
            except Exception:
                subj = None
            if subj:
                # _evidence_subject 有时会返回 paired str；保险转 str
                term_candidates.append(str(subj)[:60])
            if _contains_knowledge_signal(line):
                term_candidates.append(line[:60])
            for term in term_candidates:
                if not term or not isinstance(term, str) or len(term) < 2:
                    continue
                basic_terms.add(term)
            # 2) 中级：该行同时出现知识点信号 + 机制/条件/对比词 → 记入中级库存
            if term_candidates and any(kw in line for kw in INTERMEDIATE_KEYWORDS):
                for term in term_candidates:
                    if term and isinstance(term, str) and len(term) >= 2:
                        intermediate_terms.add(term + "|" + line[:40])
            # 3) 高级：行内出现综合/辨析/易错/误差/场景 等高级关键词
            if term_candidates and any(kw in line for kw in ADVANCED_KEYWORDS):
                for term in term_candidates:
                    if term and isinstance(term, str) and len(term) >= 2:
                        advanced_terms.add(term + "|" + line[:40])

    # 下限保护：空来源或识别失败时，退化为「默认先出 2 批难度1再升级」的保守估计
    n_basic = max(len(basic_terms), 6)
    n_intermediate = max(
        len(intermediate_terms),
        n_basic // 3,  # 合理假设：机制类题目约为基础类 1/3
    )
    n_advanced = max(
        len(advanced_terms),
        n_intermediate // 2,  # 高级类约为机制类 1/2
    )
    return {1: n_basic, 2: n_intermediate, 3: n_advanced}


def _next_card_difficulty(
    existing_cards: list[Card],
    sources: list[Any] | None = None,
) -> int:
    """
    【新版：难度 1 优先直到库存不足才升】
    策略：
    1) 估算来源的基础/中级/高级考点库存（n1/n2/n3）；
    2) 统计历史产出中各难度题目数量 used1/used2/used3；
    3) 若「剩余基础库存」remaining1 = n1 - used1 ≥ MIN_BASIC_KEEP（默认4）→ 继续难度 1；
    4) 否则若 remaining2 ≥ MIN_MID_KEEP（默认3）→ 难度 2；
    5) 否则 → 难度 3。

    彻底修正原逻辑「只要 existing_cards 中存在 difficulty=2 就下一批出 3」的粗暴升级。
    """
    MIN_BASIC_KEEP = 4  # 基础库存 ≥ 4 没覆盖 → 坚持先出 D1（打牢基础）
    MIN_MID_KEEP = 1  # 中级：只要剩余 ≥ 1 就先出 D2，不跳级到 D3
    MIN_ADV_KEEP = 1

    used1 = sum(1 for c in existing_cards if int(c.difficulty) == 1)
    used2 = sum(1 for c in existing_cards if int(c.difficulty) == 2)
    used3 = sum(1 for c in existing_cards if int(c.difficulty) == 3)

    if sources:
        capacities = _estimate_difficulty_pool_capacities(sources)
    else:
        # 无来源信息时采用保守默认值（常见 PPT 约有 12 定义 + 4 机制 + 2 综合）
        capacities = {1: 12, 2: 4, 3: 2}

    remaining1 = capacities[1] - used1
    remaining2 = capacities[2] - used2

    if remaining1 >= MIN_BASIC_KEEP:
        return 1
    if remaining2 >= MIN_MID_KEEP:
        return 2
    return 3


def _next_quiz_difficulty(
    latest_quiz: dict[str, Any] | None,
    requested_source_ids: list[str] | None = None,
    quiz_history: list[dict[str, Any]] | None = None,
    sources: list[Any] | None = None,
) -> int:
    """同卡片版：统计历史所有同 sources 的题的难度使用量，按库存剩余决定难度。"""
    MIN_BASIC_KEEP = 4  # 基础库存 ≥ 4 没覆盖 → 坚持先出 D1
    MIN_MID_KEEP = 1  # 中级：只要还有 D2 没问完，就不要跳级到 D3

    # 1) 如果是换了一批 sources 或第一次出题 → 重置到难度 1
    if latest_quiz is None and not quiz_history:
        return 1
    if (
        requested_source_ids is not None
        and latest_quiz is not None
        and set(latest_quiz.get("source_ids") or []) != set(requested_source_ids)
    ):
        return 1

    # 2) 汇总所有相关 quiz 的难度使用量
    used1 = used2 = used3 = 0
    all_quizzes: list[dict[str, Any]] = list(quiz_history or [])
    if latest_quiz is not None:
        all_quizzes.append(latest_quiz)
    # 如果用户指定了 requested_source_ids，则仅统计同 sources 交集的历史题
    for quiz in all_quizzes:
        if requested_source_ids is not None:
            quiz_src = set(quiz.get("source_ids") or [])
            if not quiz_src & set(requested_source_ids):
                continue
        for q in quiz.get("questions", []):
            d = int(q.get("difficulty") or 1)
            if d == 1:
                used1 += 1
            elif d == 2:
                used2 += 1
            else:
                used3 += 1

    if sources:
        capacities = _estimate_difficulty_pool_capacities(sources)
    else:
        capacities = {1: 12, 2: 4, 3: 2}

    remaining1 = capacities[1] - used1
    remaining2 = capacities[2] - used2

    if remaining1 >= MIN_BASIC_KEEP:
        return 1
    if remaining2 >= MIN_MID_KEEP:
        return 2
    return 3


def _bounded_generation_difficulty(raw_value: Any, target_difficulty: int) -> int:
    return max(1, min(3, int(target_difficulty or 1)))


# ======================================================================
# 迁移（泛化）出题侧的共用口径
# ======================================================================
#
# 这一段解决的问题在调研里被反复点到：单节点出题只投喂 parent/child/wikilinks，
# `prerequisite_ids` 一个都没投 —— 于是「傅里叶变换」出题时看不见它的前置
# 「复变函数」。前置图覆盖率本来就只有 ~9%（framework.prerequisite_stats 自测），
# 再不把它接进出题上下文，这张图就只是一张用来排序的装饰图。
#
# 所以下面这组函数干四件事，全是纯本地计算、零模型调用：
#   1. _node_layer_map        —— Kahn 层号（转调 progress_engine 的同一份实现）
#   2. _prereq_briefs          —— 把前置压成「名字 + 一句说明 + 层号」
#   3. _stage_floor_difficulty —— 按学习位阶抬难度下限（修 MIN_BASIC_KEEP 死锁）
#   4. _interleave_plan        —— 跨节点交错出题计划（第三刀）

# 交错出题时希望一轮覆盖几个知识点。取 3 是折中：
# 2 个交错效应太弱（对照 Brunmair & Richter 2019 的元分析，3+ 个概念混排才显著），
# 5 个以上会让「这一轮考了什么」变得难复盘，用户就放弃了。
INTERLEAVE_TARGET_NODES = 3
INTERLEAVE_MIN_NODES = 2


def _node_layer_map(nodes: list[Any]) -> dict[str, int]:
    """知识点 → Kahn 层号。转调 progress_engine 的 node_layers，保证与推荐排序同源。"""
    return progress_engine_mod.node_layers(
        {n.node_id: list(n.prerequisite_ids or []) for n in nodes}
    )


def _prereq_briefs(
    nodes: list[Any],
    by_id: dict[str, Any],
    layers: dict[str, int],
    *,
    limit: int = 4,
) -> list[dict[str, Any]]:
    """把一个节点（或一组节点）的前置压成简报：名字 + 一句说明 + 层号。

    只给名字和层号，**不给全文** —— 前置全文会让模型把题出在前置上，
    于是「考傅里叶变换」变成「考复变函数」。层号是必需的：模型要靠它知道
    哪一步在前、哪一步在后，才能设计出「先做 A 再做 B」这种有顺序的题。
    """
    out: list[dict[str, Any]] = []
    seen: set[str] = set()
    for node in nodes:
        for prereq_id in (node.prerequisite_ids or []):
            if prereq_id in seen or prereq_id == node.node_id:
                continue
            target = by_id.get(prereq_id)
            if target is None:
                continue
            seen.add(prereq_id)
            out.append(
                {
                    "node_id": prereq_id,
                    "name": target.name,
                    "description": (target.description or "")[:140],
                    "layer": layers.get(prereq_id, 0),
                    "layer_gap": abs(layers.get(node.node_id, 0) - layers.get(prereq_id, 0)),
                }
            )
    return out[:limit]


def _stage_floor_difficulty(stage_by_node: dict[str, str]) -> int:
    """按「这一批节点的学习位阶」抬难度下限。

    为什么必须有这个：`_next_quiz_difficulty` 走的是「库存还有 4 个基础考点就先出 D1」
    的策略，于是一个 183 节点的项目里 D3 几乎只会被用户手动选中 ——
    MIN_BASIC_KEEP=4 意味着只要还剩 4 个没出过的基础考点，就永远不会升到 D3。
    而 learning science 那条结论恰恰是「检索练习对技能泛化几乎无效」，
    于是系统当前的行为恰好是：**只训练最不泛化的那一档**。

    改法不是删掉库存策略（打牢基础仍然对），而是给它加一个**下限**：
    已经「会了」的节点不配再刷 D1，「稳了」的节点直接配 D3。
    """
    floors = {"get": 2, "hold": 3}
    best = 0
    for stage in stage_by_node.values():
        best = max(best, floors.get(stage, 1))
    return best


def _stage_by_node(db: Any, project_id: str) -> dict[str, str]:
    """节点的位阶（none/seen/get/hold）。走 progress_engine 同一套判据，不另立一套。

    直接调 ``progress_engine.plan`` 太重（它会连带算推荐队列），
    所以这里只取它最底层的那一层：events + BKT + FSRS 闸门。
    仍然通过 progress_engine 读，避免两份 BKT 参数漂移。
    """
    project = progress_engine_mod._load(db.path, _owner_of(db, project_id), project_id)
    if project is None:
        return {}
    return {node_id: project.stage_of(node_id) for node_id in project.nodes}


def _owner_of(db: Any, project_id: str) -> str:
    """项目属主。progress_engine 的读接口必须带 owner_id（多用户隔离），这里取一次。"""
    row = db._conn.execute(
        "SELECT owner_id FROM projects WHERE project_id = ?", (project_id,)
    ).fetchone()
    return str(row["owner_id"]) if row else ""


def _interleave_plan(
    nodes: list[Any],
    layers: dict[str, int],
    *,
    seed: str,
) -> dict[str, Any]:
    """跨节点交错出题计划：点名这一轮必须覆盖哪几个节点，以及怎么排。

    为什么是「计划」而不是「打乱顺序」：交错练习（interleaving）在 learning science
    里是效应量最大、成本最低的干预之一（Sana & Yan 2022：每周 10~12 分钟、
    一个月后 d=0.71），但它必须真的**混**起来才有效。原先「一个节点出一套题」
    恰好就是阻塞练习，等于主动站在对照组的对面。
    而模型调用的次数一点不用增加 —— 只是把「必须覆盖哪几个点」写进 payload。

    计划里刻意带上层号：优先挑跨层的节点，因为同层相邻节点往往是同一个概念的
    近义改写，混排它们没有辨别性（interleaving 的效应依赖于「需要先判断
    该用哪个」这一步，同义概念不触发那一步）。
    """
    usable = [n for n in nodes if (n.description or "").strip() or (n.name or "").strip()]
    if len(usable) < INTERLEAVE_MIN_NODES:
        return {}
    picked = transfer_mod.pick_interleaved(
        usable, limit=INTERLEAVE_TARGET_NODES, seed=int(hashlib.sha1(str(seed).encode()).hexdigest()[:6], 16)
    )
    if len(picked) < INTERLEAVE_MIN_NODES:
        return {}
    picked_layers = [layers.get(n.node_id, 0) for n in picked]
    spread = (max(picked_layers) - min(picked_layers)) if picked_layers else 0
    return {
        "target_nodes": [
            {
                "node_id": n.node_id,
                "name": n.name,
                "layer": layers.get(n.node_id, 0),
                "prereq_count": len(n.prerequisite_ids or []),
            }
            for n in picked
        ],
        "layer_spread": spread,
        "rule": (
            f"【本轮必须跨 {len(picked)} 个知识点出题，不得全部押在一个节点上】"
            f"这一轮要同时覆盖：" + "、".join(n.name for n in picked) + "。"
            "它们之间要**穿插**出题（同一道题考 A、下一道考 B、再下一道又回 A），"
            "而不是先出完 A 的题再出 B 的 —— 按知识点分块出题等于阻塞练习，"
            "对「判断该用哪个」的辨别能力没有帮助。\n"
            "若某两个目标节点的层号相差 ≥1，请至少出一道把它们**组合起来**的题"
            "（先做前置那一步的什么、再做本节点那一步的什么），这类题必须 difficulty=3。"
        ),
    }


def _item_fingerprint(text: Any) -> str:
    """题干 → 稳定指纹（同一道题的判定口径必须由出题方决定）。

    归一化：去空白、去全角标点、小写。之所以不在事后从库里反推，
    是因为出题侧本来就有「同义改写不算新题」的避让规则（``avoid_repeating``），
    事后用 strip 比字符串会与那道规则漂移，于是「第几遍」就变成了另一个定义。
    """
    raw = str(text or "")
    if not raw.strip():
        return ""
    normalized = re.sub(r"[\s\u3000]+", "", raw)
    normalized = normalized.translate(
        str.maketrans("：，。、；？！（）「」『』《》【】", ":,..;?!()\"\"''<>[]")
    )
    normalized = normalized.lower()
    return "ifp_" + hashlib.sha1(normalized.encode("utf-8")).hexdigest()[:16]


# ---- 迁移（泛化）端点的共用小工具 -------------------------------------


def _node_transfer_score(db: Any, project_id: str, node_id: str) -> float:
    """某个节点的迁移分。节点可能已被删 → 返回 0.0，不抛。"""
    try:
        return round(db.get_framework_node(project_id, node_id).transfer_score, 4)
    except Exception:
        return 0.0


def _transfer_next_hint(stage: str) -> str:
    """迁移分落在哪一档之后，下一步该做什么。诚实优先：不许说「你已掌握迁移」。"""
    if stage == "solid":
        return (
            "迁移分到「迁移得动」了：你在新情境里能把这个概念调出来。"
            "接下来换个更远的距离（中迁移 → 远迁移）验一遍，才算真的站得住。"
        )
    if stage == "partial":
        return (
            "迁移分到「迁移待验证」了：一道题还不能说明什么，"
            "再来一道**不同距离**的（这道是近迁移，下一道换中或远）才作数。"
        )
    return (
        "还只是第一道迁移题，别急着下结论。"
        "连续做 2~3 道不同距离的迁移题，系统才会给出「迁移得动」。"
    )


def _concept_nodes(db: Any, project_id: str) -> list[dict[str, Any]]:
    """项目知识点 → 概念层的输入（名字 + 层号 + 两个分数 + 前置数）。"""
    nodes = db.list_framework_nodes(project_id)
    layers = _node_layer_map(nodes)
    return [
        {
            "node_id": n.node_id,
            "name": n.name,
            "layer": layers.get(n.node_id, 0),
            "mastery": n.mastery_score,
            "transfer_score": n.transfer_score,
            "prereq_count": len(n.prerequisite_ids or []),
        }
        for n in nodes
    ]


def _apply_concept_align(
    store: Any, items: list[Any]
) -> list[dict[str, Any]]:
    """把模型给的对齐结果落进概念图，并**逐条如实标出是否采纳**。

    三条纪律（core/concept_graph 模块头写过，这里是执行侧）：
    1. confidence 低于 0.6 一律不采纳 —— 跨学科判断本来就容易错，宁缺勿滥；
    2. 采纳时把术语记进该概念的 aliases，不覆盖 canonical_name；
    3. 同一个 concept_key 本批只能被一个 term 占用，冲突的后者丢弃。
    """
    out: list[dict[str, Any]] = []
    claimed: set[str] = set()
    for raw in items or []:
        if not isinstance(raw, dict):
            continue
        term = str(raw.get("term") or "").strip()
        key = str(raw.get("concept_key") or "").strip()
        try:
            confidence = float(raw.get("confidence") or 0.0)
        except (TypeError, ValueError):
            confidence = 0.0
        record = {
            "term": term,
            "concept_key": key,
            "canonical_name": str(raw.get("canonical_name") or "").strip(),
            "confidence": round(confidence, 3),
        }
        if not term:
            record["accepted"] = False
            record["reason"] = "没有回填术语。"
            out.append(record)
            continue
        if not key:
            record["accepted"] = False
            record["reason"] = "模型判定为新概念（未命中已有概念），本次不做跨项目合并。"
            out.append(record)
            continue
        if confidence < 0.6:
            record["accepted"] = False
            record["reason"] = f"置信度 {confidence:.2f} 低于 0.6，宁可不合并不冒错并的风险。"
            out.append(record)
            continue
        if key in claimed:
            record["accepted"] = False
            record["reason"] = "本批里这个概念已被另一个术语占用。"
            out.append(record)
            continue
        claimed.add(key)
        store.add_alias(concept_key=key, alias=term)
        record["accepted"] = True
        record["reason"] = "已对齐到已知概念。"
        out.append(record)
    return out
    raw = str(text or "")
    if not raw.strip():
        return ""
    normalized = re.sub(r"[\s\u3000]+", "", raw)
    normalized = normalized.translate(str.maketrans("：，。、；？！（）「」『』《》【】", ":,..;?!()\"\"''<>[]"))
    normalized = normalized.lower()
    return "ifp_" + hashlib.sha1(normalized.encode("utf-8")).hexdigest()[:16]


def _count_transfer_attempts(store: Any, project_id: str, node_id: str, distance: str) -> int:
    """该节点该距离档的迁移作答已做过几次（权威来源：concept_graph.transfer_attempts）。

    注意与 mastery 那条路的区别：普通题的重复次数由
    ``framework.count_fingerprint_repeats`` 自己数（不把负担散到调用点），
    而迁移题的次数在 concept_graph 的表里 —— 那才是它的真值所在地，
    所以这一处必须显式数。
    """
    return store.count_repeats(
        project_id=project_id,
        node_id=node_id,
        distance=distance,
        since_days=transfer_mod.REPEAT_WINDOW_DAYS,
    )


def _quiz_node_spread(questions: list[Any]) -> dict[str, Any]:
    """这一轮实际跨了几个知识点 / 几层 —— 交错是否真的发生了，如实回传。

    刻意做成「生成后测量」而不是「生成时相信」：payload 里要求了交错，
    但模型不一定照做。界面上显示的必须是**实际值**，否则就成了假进度条。
    """
    node_ids: set[str] = set()
    for question in questions or []:
        raw = getattr(question, "node_ids", None)
        if raw is None and isinstance(question, dict):
            raw = question.get("node_ids")
        for node_id in raw or ():
            if str(node_id).strip():
                node_ids.add(str(node_id))
    return {
        "node_count": len(node_ids),
        "node_ids": sorted(node_ids),
        "interleaved": len(node_ids) >= INTERLEAVE_MIN_NODES,
    }


def _requested_or_auto_difficulty(requested: Any, auto_difficulty: int) -> int:
    try:
        if requested is not None:
            return max(1, min(3, int(requested)))
    except (TypeError, ValueError):
        pass
    return max(1, min(3, int(auto_difficulty or 1)))


# —— 认知层级（2026-09-25 新增）——
#
# 既有命题只按「难度 1/2/3」控制思维深度，但难度是**题目属性**，不是**考查能力**。
# 同一道 difficulty=2 的题，可能在考"背定义"（remember），也可能在考"说明机制"（understand）。
# 实测的坏味道是：题目数量堆上去之后，绝大多数落在识记层 —— 刷得很熟，一考迁移就崩。
#
# 这里引入认知层级作为**第二维度**，由节点掌握度驱动：
#   掌握度低 → remember / understand（先把地基问实）
#   掌握度高 → apply / analyze / evaluate（不再问"是什么"，改问"条件变了会怎样"）
# 角度是「对比 / 优缺点」的考点直接判 compare，不受难度上限约束 —— 那类题本身就是对比题。
COGNITIVE_LEVELS: tuple[str, ...] = (
    "remember",
    "understand",
    "apply",
    "analyze",
    "evaluate",
    "compare",
)


def _normalize_cognitive_level(value: Any) -> str:
    """模型回填的认知层级 → 合法枚举；认不出就返回空串（= 未标注）。

    **不猜、不拦**：认知层级是描述性字段，错了只影响分组统计，
    而拦下整道题会让「模型少填一个描述字段」变成「这道题白出」。
    真实防线在出题侧（llm 的提示词明确要求按层级设问 + 难度虚标质检 Pattern-G）。
    """
    text = str(value or "").strip().lower()
    return text if text in COGNITIVE_LEVELS else ""

COGNITIVE_LABELS: dict[str, str] = {
    "remember": "识记",
    "understand": "理解",
    "apply": "应用",
    "analyze": "分析",
    "evaluate": "评价",
    "compare": "对比",
}

# 难度封顶：difficulty=1 的题不该出现需要多步评价的设问，否则"难度"这个字段就失真了。
_COGNITIVE_CEILING_BY_DIFFICULTY: dict[int, str] = {
    1: "understand",
    2: "apply",
    3: "evaluate",
}

_COMPARE_ANGLES = {"对比", "优缺点"}


def _pick_cognitive_level(
    point: dict[str, Any], nodes: list[Any], target_difficulty: int
) -> str:
    """按考点角度 + 节点掌握度 + 题目难度上限，选一个认知层级。"""
    angle = str((point or {}).get("angle") or "").strip()
    if angle in _COMPARE_ANGLES:
        return "compare"

    node_ids = set((point or {}).get("node_ids") or [])
    mastery = 0.0
    for node in nodes:
        if getattr(node, "node_id", None) in node_ids:
            try:
                mastery = max(
                    mastery, float(getattr(node, "mastery_score", 0.0) or 0.0)
                )
            except (TypeError, ValueError):
                continue

    if mastery >= 0.8:
        want = "analyze"
    elif mastery >= 0.5:
        want = "apply"
    elif mastery >= 0.2:
        want = "understand"
    else:
        want = "remember"

    try:
        difficulty = max(1, min(3, int(target_difficulty or 1)))
    except (TypeError, ValueError):
        difficulty = 1
    ceiling = _COGNITIVE_CEILING_BY_DIFFICULTY.get(difficulty, "apply")
    if COGNITIVE_LEVELS.index(want) > COGNITIVE_LEVELS.index(ceiling):
        return ceiling
    return want


def _study_generation_policy(target_difficulty: int) -> dict[str, Any]:
    return {
        "target_difficulty": target_difficulty,
        "difficulty_ladder": DIFFICULTY_LADDER,
        "knowledge_focus_blueprint": STUDY_FOCUS_BLUEPRINT,
        "source_grounding": [
            "每一张卡片或每一道题都必须直接来自 payload.sources 中的文字或公式。",
            "不得用来源外常识补全；来源不足时围绕已有证据降低问题范围，而不是编造。",
            "每个结果必须填写至少一个有效 source_id；能对应知识节点时同时填写 node_ids。",
            "答案、背面或解析必须写出来源中的具体事实、条件、公式或原句含义，禁止只写泛泛总结。",
            "正文中不要出现 src_ 开头的来源 ID；来源 ID 只允许填写在 source_ids 字段里。",
        ],
        "progression": [
            "未指定难度时，第一次生成优先产出 difficulty=1 的基础内容。",
            "再次生成时必须基于 previous_basis 中已有的低难度内容继续加深；若目标是高难度，避免重复问同一个定义。",
            "指定 target_difficulty 时，本批所有内容都按该难度生成；再次生成仍要避开历史重复。",
            "difficulty=2 要从基础定义推进到条件、机制、对比或推导；difficulty=3 要推进到综合应用、辨析和易错边界。",
            "输出 difficulty 必须等于 target_difficulty。",
        ],
        "quality_bar": [
            "题干要像教材复习题：短、明确、只考一个核心目标，禁止使用空泛的“谈谈你的理解”。",
            "题干必须点名来源中的具体术语、机制、结构、条件、数值、公式或对比对象；禁止把页码、目录名、文件名或“相关概念”当作考点。",
            "答案/解析必须像 Agent 问答区的教材知识点总结：先给来源证据，再用分点解释机制、条件、用途、差异或考试抓手；涉及公式时保留符号、条件和变量含义。",
            "卡片 back 和测验 explanation 必须显式包含“来源依据：”与“关键解释：”。“关键解释：”下面用数字分点（2~5 点，有几个写几个、如实分点，不硬凑三点），写清楚定义、物理机制、关键条件、对比差异或应用边界，而不是一句空泛总结。",
            "选择题的干扰项要来自相近概念、条件误用或常见错误，禁止使用“随机结论、未上传来源、浏览器缓存”等无效选项。",
            "同一批内部及 avoid_repeating 中的历史题目都不得重复，也不得只做同义改写。",
            "优先覆盖课程知识常见考点：概念、定义、公式、方法、对比、优缺点、种类、条件应用；来源没有对应内容时才跳过该维度。",
        ],
    }


