    TIER = {1: D1, 2: D2, 3: D3}
    tier = TIER.get(target_difficulty, D1)
    # 主示例 = 对应目标难度的 5 张
    examples: list[dict[str, str]] = [dict(ex) for ex in tier]
    # 追加：相邻难度各 1 张参考，帮助模型理解「深度差异」
    for neighbor in (target_difficulty - 1, target_difficulty + 1):
        if neighbor in TIER:
            neighbor_ex = dict(TIER[neighbor][0])
            neighbor_ex["front"] = (
                f"[参考·难度 {neighbor}] {neighbor_ex['front']}"  # 显式标注
            )
            examples.append(neighbor_ex)
    return examples


