# 整理类任务（建链 / 补笔记）常常需要「建一个 → 再建一个 → 再连上」，3 轮不够用。
AGENT_MAX_ROUNDS_WRITABLE = 5


def _agent_offer_action_label(arguments: dict[str, Any]) -> str:
    """给「待用户确认的提议」生成一句人话，前端确认卡片直接显示它。"""

    def text(key: str, default: str = "") -> str:
        value = str(arguments.get(key) or "").strip()
        return value or default

    node = text("node_name") or text("node_id")
    raw_kinds = arguments.get("kinds")
    kinds = [str(k).strip() for k in raw_kinds if str(k).strip()] if isinstance(raw_kinds, list) else []
    labels = [AGENT_STUDY_ACTION_LABELS[k] for k in kinds if k in AGENT_STUDY_ACTION_LABELS]
    # 跳转族可以没有节点（用户问「我卡片在哪」时手里就只有项目），这时候硬写
    # 「针对『该知识点』」是在编一个不存在的东西，直接说要看什么就行。
    if not node:
        return " / ".join(labels) if labels else "看下已有的学习产物"
    return f"针对「{node}」：{' / '.join(labels) if labels else '看下这一块'}"


def _agent_staged_action_label(name: str, arguments: dict[str, Any]) -> str:
    """待确认卡片上行文案的总入口。写操作与提议型动作各有各的说法。"""
    if name in AGENT_OFFER_TOOLS:
        return _agent_offer_action_label(arguments)
    return _agent_write_action_label(name, arguments)


def _agent_write_action_label(name: str, arguments: dict[str, Any]) -> str:
    """给「待用户确认的写操作」生成一句人话，前端确认卡片直接显示它。"""

    def text(key: str, default: str = "") -> str:
        value = str(arguments.get(key) or "").strip()
        return value or default

    if name == "add_node":
        return f"新建节点「{text('name', '未命名')}」"
    if name == "delete_node":
        return f"删除节点「{text('node_id', '未知节点')}」"
    if name == "create_link":
        return f"建立双链「{text('a_name', '?')}」→「{text('b_name', '?')}」"
    if name == "update_node":
        parts = []
        if str(arguments.get("note_content") or "").strip():
            parts.append("笔记正文")
        if arguments.get("tags"):
            parts.append("标签")
        if arguments.get("wikilinks"):
            parts.append("双链")
        if str(arguments.get("description") or "").strip():
            parts.append("描述")
        detail = "、".join(parts) or "描述"
        return f"更新节点「{text('node_id', text('name', '未知节点'))}」的{detail}"
    return name


async def _request_question(request: Request) -> str:
    """从请求体里取「用户这一问」，供教学模式按问题性质定制本轮引导。

    只读小体量 JSON：上传（multipart）与超过 64KB 的体一律跳过，绝不把文件读进内存。
    Starlette 的 ``_CachedRequest`` 会把读过的 body 缓存下来交给下游，所以这里读一次
    不会影响端点自己再读一次（``await request.json()`` 依旧拿得到）。
    """
    if request.method not in ("POST", "PUT", "PATCH"):
        return ""
    ctype = (request.headers.get("content-type") or "").lower()
    if "application/json" not in ctype:
        return ""
    try:
        length = int(request.headers.get("content-length") or 0)
    except ValueError:
        length = 0
    if length > 64 * 1024:
        return ""
    try:
        data = await request.json()
    except Exception:
        return ""
    if not isinstance(data, dict):
        return ""
    for key in ("message", "question", "input", "query", "text"):
        value = data.get(key)
        if isinstance(value, str) and value.strip():
            return value.strip()
    return ""


def _teaching_history_block(db, project_id: str, conversation_id: str = "") -> str:
    """引导/严格档专用：把最近几轮压成「轮次摘要」，让阶梯能判断"第几次尝试"。

    为什么必须在这里做：``/chat`` 与 ``/chat/stream`` 只把**当前这一问**发给模型，
    "第一次尝试 vs 第二次仍偏"这条核心闸门根本没有输入，阶梯只能退化成静态口径。
    摘要由**有 db 的端点**渲染好，绑到 contextvar，llm 层读一次即可。

    ``direct`` 档直接返回空串 —— 不查库、不注入，既有行为一个字都不变。
    """
    if teaching_mode_mod.active_mode() == teaching_mode_mod.DEFAULT_MODE:
        return ""
    try:
        messages = db.list_messages(project_id, conversation_id=conversation_id)
    except Exception:
        # 查历史失败不能影响这次回答 —— 当作没有历史，回落到单轮口径。
        return ""
    return teaching_mode_mod.history_block(messages)


def _agent_system_prompt(
    db,
    project_id: str,
    mode: str,
    focus_node_id: str | None,
    message: str,
    *,
    surface: str = "kb",
) -> str:
    """按 mode 组装 agent 人设：organize→质量人设，guide→苏格拉底人设，default→原样。"""
    base = AGENT_SYSTEM_PROMPT
    persona = ""
    focus_note = ""
    weak_names: list[str] = []
    weak_flag: bool | None = None

    if mode == "organize":
        persona = NOTE_QUALITY_SYSTEM_PROMPT
    elif mode == "guide":
        persona = SOCRATIC_TUTOR_SYSTEM_PROMPT
        # 待攻克/薄弱点清单（S1：你在场时自动带入）
        try:
            digest_info = db.get_digest(project_id) or {}
            weak_names = (digest_info.get("weak_points") or [])[:8]
            if weak_names:
                focus_note += "\n【薄弱点】" + "、".join(weak_names)
        except Exception:
            pass

    if focus_node_id:
        try:
            node = db.get_framework_node(project_id, focus_node_id)
            focus_note = f"\n【当前聚焦节点】「{node.name}」" + (
                f"\n{(node.note_content or '')[:800]}"
                if (node.note_content or "").strip()
                else ""
            )
            # 聚焦节点正好是已知薄弱点 → 提示要给得更细（类比 + 单步），
            # 这是"提示具体度随掌握度变化"的最小可用版本，数据本来就已经在手上。
            if weak_names:
                weak_flag = node.name in weak_names
        except Exception:
            pass

    prompt = base
    if persona:
        prompt = f"{prompt}\n\n【{'整理模式' if mode == 'organize' else '引导模式'} 专用人设】\n{persona}"
    if focus_note:
        prompt = f"{prompt}\n{focus_note}\n请围绕该聚焦节点作答或整理。"
    if surface == "conversation":
        # 主界面对话区没有收敛条、也没有建议稿面板：换一套与这一屏对得上的说法。
        # ① 引用的句末标出来源编号（检索工具会给片段编号），界面据此渲染可点来源；
        # ② 写库动作已由工具层拦截为「待确认」，这里只让模型把意图与理由讲清楚。
        prompt = (
            f"{prompt}\n\n【对话区作答规范】\n"
            "1) 用 search_sources 检索到资料后，在每个有依据的句末标出来源编号（如 [1]、"
            "[2]，编号就是检索结果里的【1】【2】），一句一标，不要整段只在末尾标一次。\n"
            "2) 事实、定义、公式必须来自检索到的资料；资料没覆盖的部分直接说资料里没有写，"
            "不要用学科通识补齐。\n"
            "3) **两类动作的说话方式完全不同，别混** ——\n"
            "   · add_node / update_node / delete_node / create_link（改知识库）：只登记为"
            "「待用户确认」，界面上是一张勾选卡片。不要让用户去点任何按钮、也不要让用户打字确认，"
            "只用一句话说清「我要做什么、为什么」。**绝对不要编造「执行按钮」「确认卡片里的执行」"
            "这类说法** —— 那里没有一个叫「执行」的按钮，模型看不见界面，凭空指路会让用户找不到出口。\n"
            "   · plan_study_action（给学习产物选项）：这个工具的**全部意义**就是在回答下方给用户"
            "一张可点选项卡。用户说「生成知识卡片/小测验/速查表/学习路径/清单」「这个知识点怎么补」"
            "「给我看看我的卡片/速查表在哪」时，**必须**调它给出选项，不要空口承诺。调完之后："
            "选项卡上会列出具体项，每项都有一句说明；你只要用一句话说清「为什么推荐这几项、"
            "建议先做哪个」，并提到「下方选项卡里勾选后提交」，**不要**逐条念按钮名、"
            "也不要声称已经生成过任何东西。\n"
            "   · 用户问「我的卡片/测验/速查表在哪看」这类找东西的问题：用 plan_study_action 的"
            "跳转族选项（view_*）给出入口，那张卡只负责把界面带到那一页，不会改数据。\n"
            "4) 不要输出 apply / redo / stop、收敛点选择之类的字样。"
        )
    else:
        prompt = f"{prompt}{AGENT_APPROVAL_RULE_KB}"
    # ⚠️ 教学模式阶梯必须在这条链路上也加一次：带工具的 agent 聊天
    # （POST /api/projects/{id}/agent）走的是本函数，**不经过** core/llm.py 的
    # _system_prompt —— 漏掉这里，用户切了档位就会"感觉不到任何区别"（2026-09-25 踩过）。
    # 2026-09-26：改为把**用户这一问**一起传进去，按问题类型给出本轮动作，
    # 而不是所有问题共用一份模板。
    ladder = teaching_mode_mod.ladder_block(
        teaching_mode_mod.active_mode(),
        "answer_question",
        question=message,
        weak=weak_flag,
    )
    if ladder:
        prompt = f"{prompt}\n\n{ladder}"
    return prompt


