def _campus_desks(query: str) -> str:
    """按问题主题匹配办事对口部门，把「没查到」变成「找谁」。

    检索不到时只丢一句「请关注官方渠道」，对同学等于没说——他真正要知道的是
    「这事归哪个部门管」。词表见 core/campus_lexicon。
    """
    try:
        from core import campus_lexicon

        return campus_lexicon.routing_note(query)
    except Exception as exc:  # noqa: BLE001 - 词表不可用不应影响问答
        LOGGER.debug("campus_query: 办事口路由失败 %s", exc)
        return ""


def _campus_wants_desk(query: str) -> bool:
    """问句是否在问办事流程（是则值得把对口部门一并给出，否则是噪声）。"""
    try:
        from core import campus_lexicon

        return campus_lexicon.wants_desk(query)
    except Exception:  # noqa: BLE001
        return False


