def _fetch_weather(query: str) -> str:
    """实时天气（Open-Meteo，按两大校区坐标返回当前与未来 3 天）；失败返回空串。

    北洋园校区(39.085,117.72)、卫津路校区(39.109,117.16)。替代纯静态的气候描述。
    """
    import urllib.request
    import json

    coords = [("北洋园校区", 39.085, 117.72), ("卫津路校区", 39.109, 117.16)]
    out: list[str] = []
    for name, lat, lon in coords:
        url = (
            f"https://api.open-meteo.com/v1/forecast?latitude={lat}&longitude={lon}"
            "&current=temperature_2m,relative_humidity_2m,wind_speed_10m,weather_code"
            "&daily=temperature_2m_max,temperature_2m_min&timezone=Asia%2FShanghai&forecast_days=3"
        )
        try:
            req = urllib.request.Request(
                url, headers={"User-Agent": "KnowOrigin-hxt-campus/1.0"}
            )
            with urllib.request.urlopen(req, timeout=6) as resp:
                data = json.loads(resp.read().decode("utf-8", "ignore"))
            cur = (data.get("current") or {}).get("temperature_2m")
            if cur is None:
                continue
            hum = (data.get("current") or {}).get("relative_humidity_2m")
            wind = (data.get("current") or {}).get("wind_speed_10m")
            code = _weather_code_zh((data.get("current") or {}).get("weather_code"))
            daily = (data.get("daily") or {}).get("temperature_2m_max") or []
            daily_min = (data.get("daily") or {}).get("temperature_2m_min") or []
            days = data.get("daily", {}).get("time") or []
            temps = "；".join(
                f"{d.replace('-', '/')[5:]}{mx}~{mn}℃"
                for d, mx, mn in zip(days[:3], daily[:3], daily_min[:3])
            )
            desc = f"{code}，当前 {cur}℃，湿度 {hum}%"
            if wind:
                desc += f"，风速 {wind} km/h"
            out.append(f"【实时天气 · {name}】{desc}。未来 3 天：{temps}。")
        except Exception:
            continue
    if not out:
        return ""
    out.append("（来源：Open-Meteo）")
    return "\n".join(out)


def _weather_code_zh(code) -> str:
    _W = {
        0: "晴",
        1: "晴间多云",
        2: "多云",
        3: "阴",
        45: "雾",
        48: "雾凇",
        51: "小毛毛雨",
        53: "毛毛雨",
        55: "大毛毛雨",
        61: "小雨",
        63: "中雨",
        65: "大雨",
        71: "小雪",
        73: "中雪",
        75: "大雪",
        80: "小阵雨",
        81: "阵雨",
        82: "强阵雨",
        95: "雷阵雨",
        96: "雷雨伴冰雹",
        99: "强雷雨",
    }
    return _W.get(code, "多云")


def _is_degenerate_repetition(text: str) -> bool:
    """判断模型回答是否退化为重复/无意义的复读串（如连串「搜索。」）。

    这类正文没有信息量，不应直接展示给用户，应丢弃并改走工具结果合写或兜底。
    """
    t = (text or "").strip()
    if not t:
        return True
    compact = re.sub(r"\s", "", t)
    # 字符级：整段仅由极少数不同字符反复构成（如「搜索搜索…」「哈哈…」）
    if len(compact) >= 16 and len(set(compact)) <= 2:
        return True
    tokens = re.findall(r"[\u4e00-\u9fff]{1,8}|[A-Za-z]{1,12}|\d+", t)
    tokens = [x for x in tokens if x]
    if len(tokens) >= 4:
        counts = [tokens.count(x) for x in set(tokens)]
        if max(counts) >= max(4, len(tokens) // 2):
            return True
        if len(set(tokens)) <= 2:
            return True
    return False


def _agent_trace_answer(trace: list[dict[str, Any]]) -> str:
    """模型未生成有效正文时，把已执行工具得到的观察结果整理成结构化兜底答案。

    避免「整理助手」等依赖工具结果的场景因模型返回空内容而直接 502。
    仅汇总观察结果本身，不暴露工具名或调用过程。
    """
    obs = []
    for step in trace:
        text = str(step.get("observation") or "").strip()
        if text:
            obs.append(text)
    if obs:
        return "已按你的要求完成查询，结果整理如下：\n" + "\n".join(
            f"- {o}" for o in obs
        )
    return "已按你的要求完成查询，但没有检索到可用内容。你可以换种问法再试一次。"


def _prune_digest_gap(db: Any, project_id: str, node_id: str) -> None:
    """建议稿批准后，把该节点从库级摘要的缺笔记清单 gaps 中摘除（增量刷新）。"""
    digest = db.get_digest(project_id)
    if not digest:
        return
    gaps = digest.get("gaps") or []
    remaining = [g for g in gaps if str(g.get("node_id") or "") != node_id]
    payload = {k: v for k, v in digest.items() if k != "project_id"}
    payload["gaps"] = remaining
    db.upsert_digest(project_id, int(digest.get("version") or 0) + 1, payload)


def _gather_node_source_ctx(
    sources: list[Any], node: Any, extra_limit: int = 5000
) -> str:
    """汇集「聚焦节点」的来源上下文：优先该节点绑定的 source_ids，不足再用关键词检索补足。"""
    parts: list[str] = []
    sid_set = set(node.source_ids or [])
    for src in sources:
        text = str(src.text or "").strip()
        if not text:
            continue
        if src.source_id in sid_set:
            label = f"【{src.filename}】\n" if getattr(src, "filename", None) else ""
            parts.append(label + text[:1500])
    joined = "\n\n".join(parts)
    if len(joined) < 400:
        corpus = "\n".join(str(s.text or "") for s in sources)
        kw = f"{node.name or ''} {node.description or ''}".strip()
        if kw:
            hit = _relevant_source_text(corpus, kw, extra_limit)
            if hit and hit not in joined:
                joined = (joined + "\n\n" + hit).strip()
    return joined[: extra_limit * 2]


def _generate_node_detail_proposal(
    db: Any,
    llm: "LlmClient",
    project_id: str,
    node_id: str,
    sources: list[Any],
) -> dict[str, Any]:
    """用高质量原子笔记人设生成「补全当前节点笔记」建议稿；LLM 失败时给出结构化兜底。

    返回 {"type", "reason", "content"}；type ∈ {add_note, update_note}。
    """
    node = db.get_framework_node(project_id, node_id)
    src_ctx = _gather_node_source_ctx(sources, node)
    payload: dict[str, Any] = {
        "node": {
            "name": node.name,
            "description": node.description,
            "note_content": node.note_content or "",
            "wikilinks": list(node.wikilinks or []),
            "tags": list(node.tags or []),
        },
        "sources": src_ctx[:8000],
    }
    has_note = bool((node.note_content or "").strip())
    default_type = "update_note" if has_note else "add_note"
    try:
        result = llm.complete_json("organize_note_detail", payload)
    except Exception as exc:  # noqa: BLE001 - 宽松兜底：保证「补全」按钮始终有产出
        LOGGER.warning(
            "organize_note_detail failed, fallback to structured draft. node=%s err=%s",
            node.name,
            exc,
        )
        content = (
            f"# {node.name}\n\n"
            f"（定义）{(node.description or '来源未提及，[待补]').strip()}\n\n"
            f"## 要点\n- {node.description or '（待按来源补充）'}\n\n"
            f"## 关联\n{('、'.join(node.wikilinks)) if (node.wikilinks) else '（待补充 [[双链]]）'}\n\n"
            "（以上为宽松兜底稿，关键事实未核实，请在来源补齐后完善。⚠️ [待补]）"
        ) + (f"\n\n{node.note_content}" if has_note else "")
        return {
            "type": default_type,
            "reason": "LLM 生成失败，已给出结构化兜底稿，请核对后启用。",
            "content": content,
        }
    content = str(result.get("content") or "").strip()
    if not content:
        raise HTTPException(
            status_code=502,
            detail=error_payload(
                "empty_note_detail", "补全笔记失败：模型未返回正文，请重试。"
            ),
        )
    raw_type = str(result.get("type") or "")
    type_ = raw_type if raw_type in ("add_note", "update_note") else default_type
    reason = str(result.get("reason") or "").strip()
    if not reason:
        reason = "补全为详细高质量原子笔记。"
    return {"type": type_, "reason": reason, "content": content}


def _recommend_link_gaps(
    db: Any,
    llm: "LlmClient",
    project_id: str,
    node_id: str,
    nodes: list[Any],
) -> str:
    """基于当前知识节点，识别图谱中『尚不存在』但值得补充的知识点，并给出补全小结。

    返回供模型阅读的 Markdown 文本；LLM 失败或确无补充时给出兜底说明。
    """
    try:
        node = db.get_framework_node(project_id, node_id)
    except NodeNotFound:
        return "未找到该知识节点，无法生成缺失节点补全建议。"
    existing = {getattr(n, "name", "") for n in nodes}
    if node.name:
        existing.add(node.name)
    payload: dict[str, Any] = {
        "anchor_node": {
            "name": node.name,
            "description": node.description or "",
            "note_content": (node.note_content or "")[:2400],
            "tags": list(node.tags or []),
            "wikilinks": list(node.wikilinks or []),
        },
        "existing_nodes": sorted(existing)[:80],
    }
    items: list[dict[str, Any]] = []
    try:
        result = llm.complete_json("recommend_link_gaps", payload)
        raw = result.get("gaps") if isinstance(result, dict) else None
        if isinstance(raw, list):
            items = [
                it
                for it in raw
                if isinstance(it, dict)
                and (it.get("node") or "").strip()
                and (it.get("node") or "").strip() not in existing
            ]
    except Exception as exc:  # noqa: BLE001 - 宽松兜底
        LOGGER.warning("recommend_link_gaps failed. node=%s err=%s", node.name, exc)
    if not items:
        return (
            f"围绕「{node.name}」，目前分析不出值得补进库的新知识点"
            "（图谱里与它相关的节点都已存在）。可返回双链图谱查看现有连接。"
        )

    def _clean(tag: str, x: Any, first: bool = False) -> list[str]:
        vals = [v for v in (x if isinstance(x, list) else []) if str(v or "").strip()]
        if first and vals:
            vals = [vals[0]]
        return [str(v).strip()[:30] for v in vals[:8]]

    lines = [
        f"围绕「{node.name}」，图谱里还缺这些相关知识点，可作为新节点补全（尚不存在，需 add_node 新建）："
    ]
    for it in items[:6]:
        name = str(it.get("node") or "").strip()[:20]
        summary = str(it.get("summary") or "").strip() or "（待补）"
        points = _clean("points", it.get("points"))
        pitfall = str(it.get("pitfall") or "").strip()
        reason = str(it.get("link_reason") or "").strip()
        lines.append(f"- 补全节点「{name}」：{summary}")
        if points:
            lines.append("  · 要点：" + "；".join(points))
        if pitfall:
            lines.append(f"  · 易错/适用：{pitfall[:30]}")
        lines.append(
            f"  · 与本文建议双链：[{(reason or '留待你补充关联原因')}] -> 「{node.name}」"
        )
    lines.append(
        "如需我把其中某条补全进知识库并与当前节点建立双链，请引导用户点击下方「✓ 执行双链·新建节点」按钮执行，"
        "我会先 add_node 新建并写小结、再 create_link。完成后可返回双链图谱查看新节点和连线。"
    )
    return "\n".join(lines)


# =============================================================================
# 【文字形态工具调用的捕获器】
# 网关不支持原生 tool_calls 时，模型会把调用意图吐成正文。这里把它从正文里摘出来。
# 定义在模块级（不是 create_app 内）：它不依赖任何闭包变量，且要能单独测。
# =============================================================================

class _LiteralToolCallAccumulator:
    """捕获"文字形式"的工具调用 —— 网关不支持原生 tool_calls 时模型的真实输出形态。

    实测（2026-10，天大平台）：`tools` 参数被接受（finish_reason 也会给 tool_calls），
    但**回传的 tool_calls 是空数组**，模型改用纯正文模拟调用。实测到的形态是
    ``{"name": "search_sources", "parameters": {...}}``（逐 token 流式到达），
    另一些模型会给 ``<function=name><parameter=k>v</parameter></function>``。
    两种都要能接住：接不住的话这段文本会原样漏进用户看到的回答里。

    ## 缓冲语义（这条最容易写错，改之前先读完）

    三个槽各管一段，混在一起就会出「chunk 开头被吃掉」「退回正文重复一遍」这类
    只在真机上偶发的怪事：

    * ``buf``  —— **探测窗口**。非捕获态下永远只保留尾部 ``_PROBE_CHARS`` 字符，
      用来抓「先说一段话、再调用工具」这种中途出现的调用；一命中起始标记就从
      标记处转入捕获、整段累积。
    * ``out``  —— **已确定不是工具调用、但还没被上层取走的正文**。正文至少先扣住
      40 个字符才进这里（否则 ``{"na`` 会先显示、剩下的被捕获吞掉，用户看到半截
      JSON）；中途命中起始标记时，标记**之前**的正文也进这里，一字不丢。
    * 捕获态 —— ``buf`` 攒到闭合由 ``pop_call`` 摘走；剩下的重新按探测窗口处理。

    早先的 buf 是无条件累积全部 chunk，而已转发的正文也早进了 answer_parts，
    于是「退回正文」那条兜底会把用户已经看过的字再追加一遍 —— 同一条回答在
    界面上出现两次。上面这套分段顺带消掉了它。
    """

    # 起始标记：XML 形态（完整 function / 裸 parameter）、或 JSON 形态
    # （要求 "name" 是第一个 key，这是模型的稳定习惯）
    # JSON 那一支只咬住 `"name` 后面紧跟的 `"` 或 `:`，这样三种畸形都能进捕获态：
    #   {"name": …}      正常
    #   {"name""name": …} 键重复
    #   {"name"name": …}  **少一个引号** —— 实测弱模型真会吐出来
    #   （2026-10-04 用户实机截图就是后两种），漏掉等于整轮调用白给。
    # ⚠️ 这里只能写成字符类 `[":]` 或 `(?:\s*"name")*` 这类形式。别图省事写 `"?"`：
    # 那个写法会被解析成「一个可选引号 + 一个**必需**引号」，正常的 `{"name":` 直接
    # 不匹配，整个 JSON 分支静默失效 —— 所有伪调用全废，而且不抛任何异常。
    _START_RE = re.compile(
        r"<function\s*=\s*[A-Za-z0-9_\-]+"
        r"|<parameter\s*=\s*[A-Za-z0-9_\-]+"
        r'|\{\s*"name[":]',
        re.I,
    )
    _PARAM_OPEN_RE = re.compile(r"<parameter\s*=\s*[A-Za-z0-9_\-]+", re.I)
    _PARAM_CLOSE_RE = re.compile(r"</parameter\s*>", re.I)
    _NAME_RE = re.compile(r"<function\s*=\s*([A-Za-z0-9_\-]+)\s*>", re.I)
    _PARAM_RE = re.compile(
        r"<parameter\s*=\s*([A-Za-z0-9_\-]+)\s*>(.*?)</parameter\s*>", re.I | re.S
    )
    _END_RE = re.compile(r"</function\s*>", re.I)
    # 畸形 name 键归一：`{"name"name":` / `{"name""name":` → `{"name":`。
    # 只认对象开头的第一个键（raw 是从 `{` 起切的完整对象），别的位置畸形一律
    # 交给 json.loads 报错后走「退回正文」—— 宁可显示原文，也不替模型猜它想写什么。
    _DUP_NAME_RE = re.compile(r'^\{"name"\s*"?name"\s*:', re.I)
    # 单次捕获的缓冲上限：超过就判定为误伤（正文里恰好出现同名 key），不再等闭合
    _MAX_BUFFER = 8000
    # 开头扣住多少字符、截尾保留多少字符再决定「这段不是工具调用」
    _PROBE_CHARS = 40

    __slots__ = ("buf", "out", "capturing", "flushed", "known_tools")

    def __init__(self, known_tools: set[str] | frozenset[str] | None = None) -> None:
        self.buf = ""      # 探测窗口 / 捕获缓冲
        self.out = ""      # 已确认可转发的正文
        self.capturing = False
        self.flushed = False
        # 非空时，工具名必须在这个集合里才认 —— 正文里贴一段
        # {"name": "张三", "age": 30} 不会被当成调用吞掉
        self.known_tools = known_tools or frozenset()

    def feed(self, chunk: str) -> bool:
        """喂入一个流式文本块；返回 True 表示应扣住、不要转发给用户。

        扣住不等于丢：确认是正文后由 ``flush_ready`` 交还，流结束时由
        ``flush_all`` 兜底交还。
        """
        if self.capturing:
            self.buf += chunk
            if len(self.buf) > self._MAX_BUFFER:
                # 撑爆上限说明这不是一次工具调用（多半是正文里提到了这个形态）
                self.capturing = False
                self.buf = ""
                return False
            return True

        probe = self.buf + chunk
        hit = self._START_RE.search(probe)
        if hit is not None:
            # 标记之前的正文照常保留（模型常常先说半句再调用工具），标记处起转捕获
            self.out += probe[: hit.start()]
            self.buf = probe[hit.start() :]
            self.capturing = True
            return True
        if len(probe) > self._PROBE_CHARS:
            keep = self._PROBE_CHARS
            self.out += probe[:-keep]
            self.buf = probe[-keep:]
            self.flushed = True
            return False
        self.buf = probe
        return True

    def flush_ready(self) -> str:
        """取走已确认可转发的正文。捕获态下没有正文可取。"""
        text, self.out = self.out, ""
        return text

    def flush_all(self) -> str:
        """取走**全部**尚未转发的文本（正文 + 探测窗口 / 捕获残余）。

        流结束时用。探测窗口里那 40 个字符也是模型说的话，一并交还，
        不为了「探测干净」而吞掉用户该看到的字。
        """
        text = self.out + self.buf
        self.out = ""
        self.buf = ""
        self.capturing = False
        return text

    def _accepts(self, name: str) -> bool:
        return not self.known_tools or name in self.known_tools

    def _commit(self, consumed: str, name: str, arguments: dict[str, Any]) -> dict[str, Any] | None:
        """校验通过才把 ``consumed`` 从 buf 里摘掉，并重估捕获状态。

        校验与摘除**必须**是同一个原子步骤。早先是先摘后校验：正文里贴一段
        ``{"name": "张三", "age": 30}`` 时，_accepts 拦下了，但那段 JSON 已经被
        ``buf.replace`` 抹掉 —— 于是模型举的例子凭空消失，用户只看到例子前后的两截话。
        不通过时 buf 原样保留，``flush_all`` 会把它当正文交还：那本来就是正文。
        """
        if not self._accepts(name):
            return None
        self.buf = self.buf.replace(consumed, "", 1)
        # 摘走之后 buf 里可能还跟着下一个调用，也可能是普通正文。
        # 按探测窗口重新判定，否则 capturing 会一直挂着，把后面的正文全扣住。
        self.capturing = self._START_RE.search(self.buf) is not None
        if not self.capturing and len(self.buf) > self._PROBE_CHARS:
            self.out += self.buf[: -self._PROBE_CHARS]
            self.buf = self.buf[-self._PROBE_CHARS :]
        return {
            "name": name,
            "arguments": json.dumps(arguments, ensure_ascii=False),
        }

    def _extract_json_object(self) -> str | None:
        """从 buf 里切出一个括号平衡的 JSON 对象。

        第一遍带字符串状态机，能正确处理 ``"a{b}c"`` 这种值里有花括号的情况。

        第二遍**忽略字符串状态**再来一遍，只认花括号计数。第一遍失败往往不是
        「没闭合」，而是畸形 JSON 把引号奇偶数带偏了 —— 实测最常见的
        ``{"name"name": …`` 少一个引号，全文引号数变成奇数，状态机此后一直以为
        自己在字符串里，扫到底也等不到 depth 归零，整段调用就这样报废、裸 JSON
        原样漏进用户回答里（2026-10-04 实机截图）。宁可切得宽一点交给 json.loads
        去判，也别整段退回正文。

        代价：值里真有 ``}`` 时第二遍会切短，loads 失败后退回正文 —— 与没有这遍
        时的结果一样，不会更差。
        """
        start = self.buf.find("{")
        if start < 0:
            return None
        depth = 0
        in_string = False
        escaped = False
        for index in range(start, len(self.buf)):
            char = self.buf[index]
            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == '"':
                    in_string = False
                continue
            if char == '"':
                in_string = True
            elif char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    return self.buf[start : index + 1]
        depth = 0
        for index in range(start, len(self.buf)):
            char = self.buf[index]
            if char == "{":
                depth += 1
            elif char == "}":
                depth -= 1
                if depth == 0:
                    return self.buf[start : index + 1]
        return None

    def pop_call(self) -> dict[str, Any] | None:
        """把攒下的文字归一化为 {"name", "arguments"}；arguments 为 JSON 字符串。

        四种形态：
          1. ``<function=N><parameter=k>v</parameter></function>`` —— 完整 XML
          2. ``<parameter=k>v</parameter>...``                —— 裸参数块，无外层 function（真实遇到过）
          3. ``{"name": "N", "parameters": {...}}``           —— 纯 JSON（实测天大平台）
          4. ``{"name": "N", "arguments": {...}}``
          5. ``{"name": "N", "参数名": 值, ...}``             —— 参数与 name 同级（实测最常见）
        未攒够或解析失败时返回 None（buf 原样保留，由 flush_all 取回）。
        """
        if not self.capturing:
            return None
        call = self._pop_xml_call()
        if call is None:
            call = self._pop_bare_parameters_call()
        if call is None:
            call = self._pop_json_call()
        return call

    def _pop_bare_parameters_call(self) -> dict[str, Any] | None:
        """接住「没有外层 <function=> 的裸参数块」。

        为什么必须处理：模型有时只吐
        ``<parameter=question>intended answer for "wrong statement" ...</parameter>``。
        这段漏进正文后，真实浏览器会把 ``<parameter=question>intended`` 当成未知
        HTML 标签，标签名里的空格被当属性分隔吃掉，用户看到的就是
        「intendedanswerfor"wrongstatement"ifitsaid"nowature"」这样一句裸英文。

        截断保护：``<parameter`` 超过 120 字符还没闭合就不是调用（多半是正文里在讲
        这些标签），放弃捕获、整段退回正文，不做无上限等待。
        """
        first = self._PARAM_OPEN_RE.search(self.buf)
        if first is None:
            return None
        closes = list(self._PARAM_CLOSE_RE.finditer(self.buf))
        # 开头之后一个闭合都没有 → 还不够，可能是不该捕获的正文
        if not closes:
            if len(self.buf) - first.start() > 120:
                return None
            return None
        last = closes[-1]
        block = self.buf[first.start() : last.end()]
        params: dict[str, Any] = {}
        for match in self._PARAM_RE.finditer(block):
            params[match.group(1)] = match.group(2).strip()
        # 参数块里带工具名（<function=socratic_ask> 写在第一个 parameter 前面等形态）
        name_match = self._NAME_RE.search(block)
        name = name_match.group(1) if name_match else "request_user_input"
        if not params and name == "request_user_input":
            return None
        return self._commit(block, name, params)

    def _pop_xml_call(self) -> dict[str, Any] | None:
        m = self._END_RE.search(self.buf)
        if m is None:
            return None
        block = self.buf[: m.end()]
        name_m = self._NAME_RE.search(block)
        if name_m is None:
            # 不是能认的 XML：把整段退回正文，别吞
            return None
        params: dict[str, Any] = {}
        for pm in self._PARAM_RE.finditer(block):
            params[pm.group(1)] = pm.group(2).strip()
        return self._commit(block, name_m.group(1), params)

    def _pop_json_call(self) -> dict[str, Any] | None:
        """接住 ``{"name": "x", ...}`` 这类纯 JSON 伪调用。

        参数键三种都认：``parameters`` 外层、``arguments`` 外层，以及**平铺**
        （参数与 name 同级）。

        平铺这一支是必须有的：实测弱模型最常给的就是
        ``{"name":"plan_study_action","node_id":"…","kinds":["quiz"],"reason":"…"}``，
        参数压根没有外层包装。早先只认前两种，于是这一段被整段退回正文 ——
        用户看到的就是一整条裸 JSON 躺在回答里，还以为 AI 在跟自己对暗号。

        代价是「正文里恰好有个带 name 的对象」会被误当调用，所以结构键要从
        平铺参数里剔掉（``reason`` 不能剔：它就是 plan_study_action 的合法参数）。
        真正的兜底是 ``known_tools``：调用方把当前工具集的名称传进来，
        ``{"name": "张三", "age": 30}`` 里的「张三」不是工具名，直接被拒。
        """
        raw = self._extract_json_object()
        if raw is None:
            return None
        payload = None
        for candidate in (raw, self._DUP_NAME_RE.sub('{"name":', raw, count=1)):
            try:
                payload = json.loads(candidate)
            except (ValueError, TypeError):
                continue
            break
        if not isinstance(payload, dict):
            return None
        name = str(payload.get("name") or payload.get("tool") or "").strip()
        if not name:
            return None
        arguments = payload.get("parameters")
        if not isinstance(arguments, dict):
            arguments = payload.get("arguments")
        if not isinstance(arguments, dict):
            # 平铺分支：参数与 name 同级。结构键要剔掉，否则正文里贴的
            # {"name": "张三", "age": 30} 会被当调用吞掉。
            arguments = {
                key: value
                for key, value in payload.items()
                if key not in _JSON_STRUCTURAL_KEYS
            }
            # 平铺算出来是空 → 这个对象除 name 外什么都没说，不是调用。
            # ⚠️ 这个空判**只能**放在平铺分支里：外层 `{"parameters": {}}` 是合法的
            # 无参调用（模型查进度之类），早先写成统一的一条 `if not arguments`，
            # 把无参调用一起毙了 —— 多个并行 JSON 的用例当场挂掉。
            if not arguments:
                return None
        return self._commit(raw, name, arguments)


# JSON 伪调用里「结构键」与「参数」的边界：平铺形态下除 name 外的一切都是参数，
# 但这几个键是模型框架字段（思考过程、内容、回包 id），不是工具入参，剔除掉。
# 注意 reason 不在其中 —— 它就是 plan_study_action 的合法参数。
_JSON_STRUCTURAL_KEYS = frozenset(
    {"name", "tool", "id", "type", "content", "thought", "thoughts", "reasoning"}
)


def _agent_source_hits(
    sources: list[Any], query: str, per_source_limit: int = 700, max_hits: int = 4
) -> list[dict[str, Any]]:
    """Agent 的资料检索：逐份滑窗打分，只保留真的含关键词的片段，并带上来源身份。

    为什么不再把所有资料拍成一坨再检索（旧实现）：拍平之后模型既不知道这段话出自哪份
    资料，也无法在句末标来源编号，前端就拿不到可点击的溯源 chip。这里复用
    ``_relevant_source_text`` 的滑窗打分，但按 source 逐份做，命中才收。
    """
    terms = [term for term in _query_terms(query) if term]
    hits: list[dict[str, Any]] = []
    for source in sources:
        text = str(getattr(source, "text", "") or "")
        if not text.strip():
            continue
        raw_text = _clean_source_text_for_llm(text)
        window = _relevant_source_text(raw_text, query, per_source_limit)
        if not window.strip():
            continue
        # 关键词一个都没命中就是噪声：短资料会被整篇返回，不做这道过滤会把全文都当成命中。
        if terms and not any(term in window.lower() for term in terms):
            continue
        hits.append(
            {
                "source_id": source.source_id,
                "filename": getattr(source, "filename", "") or "未命名资料",
                "text": window.strip(),
            }
        )
        if len(hits) >= max_hits:
            break
    return hits


_AGENT_CITATION_MARKER_RE = re.compile(r"\[(\d{1,2})\]")


def _agent_call_arguments(raw: Any) -> dict[str, Any]:
    """把工具调用的 arguments 归一化成 dict。

    两边的约定本来就不一致：原生 tool_calls 经 llm._normalize_tool_call 出来已经是
    dict，而文字伪调用是从模型正文里解析的 JSON **字符串**。直接透传会让
    _run_agent_tool 里的 arguments.get(...) 抛 'str' object has no attribute 'get'，
    整条 SSE 于是掉进非流式兜底 —— 实测里这会连带把写操作绕过确认直接落库。
    """
    if isinstance(raw, dict):
        return raw
    if isinstance(raw, str) and raw.strip():
        try:
            parsed = json.loads(raw)
        except ValueError:
            return {}
        return parsed if isinstance(parsed, dict) else {}
    return {}


def _agent_answer_segments(
    answer: str,
    cited_sources: dict[int, dict[str, Any]],
    source_by_id: dict[str, Any],
) -> tuple[list[dict[str, Any]], list[str]]:
    """把 Agent 答案里的 [n] 来源标记还原成前端能渲染成可点 chip 的 segments。

    与历史重载（_message_payload）走同一条渲染契约：{text, source_ids, citations}。
    逐句切分复用 ``_latex_aware_answer_parts``，quote 由 ``_citation_locations``
    在原文里定位，因此点开 chip 能高亮到真实段落，不需要模型再输出一次结构化 JSON。
    """
    text = str(answer or "").strip()
    if not text:
        return [], []
    segments: list[dict[str, Any]] = []
    for part in _latex_aware_answer_parts(text):
        if not part.strip():
            continue
        source_ids: list[str] = []
        for marker in _AGENT_CITATION_MARKER_RE.findall(part):
            hit = cited_sources.get(int(marker))
            if hit and hit["source_id"] not in source_ids:
                source_ids.append(hit["source_id"])
        # 展示文本里去掉 [n]：可点 chip 已经承担了「这句出自哪份资料」这件事。
        clean_part = _AGENT_CITATION_MARKER_RE.sub("", part).strip()
        if not clean_part:
            continue
        segments.append(
            {
                "text": clean_part,
                "source_ids": source_ids,
                "citations": _citation_locations(
                    source_ids, source_by_id, part if source_ids else ""
                ),
            }
        )
    return segments, _segment_source_ids(segments)


# 不依赖知识框架节点的工具：它们读的是「学习产物」（卡片 / 测验 / 我的笔记 / 台历成文材料）。
# 用户完全可能只上传了资料、出了卡片，还没建知识框架 —— 不能被 _run_agent_tool 里
# 那道「没有节点就短路」的守卫拦掉，否则这四个工具永远返回「请先构建知识框架」。
_AGENT_NODE_FREE_TOOLS = frozenset(
    {
        "search_cards",
        "search_quiz",
        "search_highlights",
        "get_study_kit",
        # 打卡日历与冲刺计划来自 learning_events / sprint_plans，与知识框架无关；
        # 复习文档虽然按 node_id 分槽，但用户可能一个框架节点都还没建。
        # list_sources 同理：刚上传完 PDF 就要问「存了什么」，那时框架通常还没生成。
        "get_learning_calendar",
        "search_knowledge_docs",
        "list_sources",
    }
)


def _agent_artifact_hit(parts: tuple[Any, ...], terms: list[str]) -> bool:
    """按 _query_terms 的词表判定一条产物记录（卡片/测验题/笔记）是否命中。

    沿用 _agent_source_hits 的判定方式：词表非空时任一词子串命中即可，没有额外打分 ——
    卡片与笔记都是"一条一个知识点"的短文本，滑窗打分（_relevant_source_text）在这种输入上没有意义。
    terms 为空表示调用方没给关键词，不做过滤。
    """
    if not terms:
        return True
    blob = " ".join(str(part or "") for part in parts).lower()
    return any(term in blob for term in terms)


def _agent_limit(arguments: dict[str, Any], default: int = 8, maximum: int = 20) -> int:
    """模型给的 limit 不可信（可能给 0、负数或 10^6），统一夹到 [1, maximum]。"""
    try:
        value = int(arguments.get("limit") or default)
    except (TypeError, ValueError):
        return default
    return max(1, min(value, maximum))


# --------------------------------------------------------------------------
# 读复习文档（search_knowledge_docs）
# --------------------------------------------------------------------------
#
# 这里的每一个兜底都对应一种「文档明明在库里，Agent 却说没有」或「读到了却答不出
# 后半份」的真实故障，改动前请先想清楚删掉它会退化成哪种坏表现。

_AGENT_DOC_FULL_CAP = 9000     # 单篇整篇直给的字数上限（对齐 knowledge_doc.ASK_MAX_CONTEXT）
_AGENT_DOC_SECTION_CAP = 7000  # 按节取时全部命中节的合计上限
_AGENT_DOC_LIST_DEFAULT = 4    # 列举时默认给几篇
_AGENT_DOC_LIST_MAX = 12
_AGENT_DOC_FULL_WORDS = ("full", "全部", "整篇", "全文", "完整")


def _agent_doc_head(doc: dict[str, Any], body: str = "") -> str:
    """文档抬头：标题 + 定位信息。模型要引用时得知道 node_id 与它对应哪个知识点。"""
    bits = [f"node_id={doc.get('node_id') or '-'}"]
    if doc.get("scope") == "project":
        bits.append("整份合订稿")
    if doc.get("updated_at"):
        bits.append(_agent_doc_stamp(str(doc["updated_at"])) + " 更新")
    bits.append(f"共 {len(body)} 字")
    return f"【{doc.get('title') or '未命名文档'}】({', '.join(bits)})"


def _agent_doc_stamp(value: str) -> str:
    """ISO 时间戳 -> 短格式。带秒和时区对模型引用没有意义，徒占 token。"""
    return (value or "")[:16].replace("T", " ")


def _agent_doc_structure(body: str) -> str:
    """超长文档（合订稿）只给结构，不给正文。

    原来这里是 ``body[:1200]`` —— 两千多字的单篇详解读不到易错点与自测，一万多字的
    合订稿只够读到目录就断了，而且断点常常落在表格中间。改成按标题列结构，让模型
    自己点名要哪一节，比按字数砍准得多，也不用担心切断公式。
    """
    lines = []
    for item in knowledge_doc_mod.section_outline(body):
        indent = "  " * max(0, int(item["level"]) - 1)
        chars = int(item["chars"])
        lines.append(f"{indent}- {item['title']}" + (f"（{chars} 字）" if chars else ""))
    return "\n".join(lines)


def _agent_doc_one(doc: dict[str, Any], arguments: dict[str, Any]) -> str:
    """定向读一篇：小节 / 整篇 / 结构清单，三种给法。"""
    body = str(doc.get("content_md") or "").strip()
    head = _agent_doc_head(doc, body)
    if not body:
        return head + "\n（这篇文档没有正文内容。）"

    wanted = str(arguments.get("section") or "").strip()
    if wanted and wanted.lower() not in _AGENT_DOC_FULL_WORDS:
        hits = knowledge_doc_mod.find_markdown_sections(body, wanted)
        if not hits:
            titles = knowledge_doc_mod.section_titles(body)
            hint = "\n".join(f"  - {t}" for t in titles[:40]) or "  （这篇文档没有小节标题）"
            return (
                f"{head}\n这篇文档里没有匹配「{wanted}」的小节。它有这些小节：\n{hint}\n"
                f"把上面某个小节名原样填进 section 再调一次即可。"
            )
        text = "\n\n".join(
            (f"## {t}\n{b}" if t else b).strip() for t, b in hits
        ).strip()
        clipped = knowledge_doc_mod._clip_block(text, _AGENT_DOC_SECTION_CAP)
        tail = (
            "\n（这一节太长已截断；换更小的 section 或改问更具体的问题。）"
            if clipped != text
            else ""
        )
        # 子节是主节的一部分（合订稿里「1.4 康普顿散射效应」带出它下面九个小节），
        # 只报主节名，别把九个小节名铺在这里。
        return f"{head}\n只取小节：{hits[0][0] or wanted}\n{clipped}{tail}"

    if wanted or len(body) <= _AGENT_DOC_FULL_CAP:
        tail = ""
        text = body
        if len(text) > _AGENT_DOC_FULL_CAP * 3:
            text = knowledge_doc_mod._clip_block(text, _AGENT_DOC_FULL_CAP * 3)
            tail = "\n（全文过长已截断；用 section=<小节名> 取你要的那一节。）"
        return f"{head}\n{text}{tail}"

    return (
        f"{head}\n这份文档有 {len(body)} 字，一次给不全。下面是它的结构 —— "
        f"要哪一节就带 section=<小节名>（原样抄下面的标题）再调一次；"
        f"合订稿里带 section=<知识点名>（如 1.4 康普顿散射效应）会连它的全部小节一起返回。\n"
        f"{_agent_doc_structure(body)}"
    )


def _agent_doc_brief(doc: dict[str, Any]) -> str:
    """列举时的一行摘要。正文不展开，只给「一句话把握」和体量。"""
    content = doc.get("content") if isinstance(doc.get("content"), dict) else {}
    summary = str(content.get("summary") or "").strip()
    body = str(doc.get("content_md") or "")
    bits = []
    if doc.get("scope") == "project":
        bits.append("整份合订稿")
    bits.append(f"{len(body)} 字")
    if doc.get("updated_at"):
        bits.append(_agent_doc_stamp(str(doc["updated_at"])) + " 更新")
    tail = f"  —— {knowledge_doc_mod._clip_block(summary, 90)}" if summary else ""
    return f"- 【{doc.get('title') or '未命名文档'}】(node_id={doc.get('node_id') or '-'}, {' · '.join(bits)}){tail}"


def _agent_locate_doc(
    knowledge_doc: Any, db: Any, project_id: str, owner_id: str,
    node_id: str, node_name: str, nodes: list[Any],
) -> tuple[dict[str, Any] | None, str]:
    """把模型给的 node_id / node_name 落到一篇已生成的文档上。返回 (文档, 命中方式)。

    为什么要有节点名与标题两层兜底：模型手里只有 ``get_framework`` 输出里的**节点名**，
    它经常直接把「波粒二象性总结」当 node_id 传过来。以前这里只按 id 查，查不到就回一句
    「还没有生成过复习文档」—— 文档躺在库里，模型却从此认定这条材料不存在，转头叫
    用户去生成，用户白等一场。

    ⚠️ 别再加「按正文关键词兜底」那层：模型问一个库里没有的知识点时，只要和某篇文档
    沾个词（「玻色-爱因斯坦凝聚」里的「爱因斯坦」）就会被匹配成那篇，然后模型据此宣称
    「文档里讲了玻色凝聚」—— 比说没有更糟。走不通就返回清单让模型自己纠正。
    """
    docs = knowledge_doc.list_for_project(owner_id, project_id)
    raw = str(node_id or "").strip() or str(node_name or "").strip()
    if not raw or not docs:
        return None, ""

    # 1) 原样当 node_id
    hit = next((d for d in docs if d.get("node_id") == raw and d.get("scope") == "node"), None)
    if hit:
        return hit, "node_id"

    # 2) 当框架节点名 -> 节点 id（框架里有这个节点才可能有它的文档）
    candidates = {raw}
    for node in nodes or []:
        if str(getattr(node, "name", "") or "").strip() == raw:
            candidates.add(str(getattr(node, "node_id", "") or ""))
    resolved = _agent_resolve_node(db, project_id, raw, raw)
    if resolved is not None:
        candidates.add(str(getattr(resolved, "node_id", "") or ""))
    candidates.discard("")
    hit = next((d for d in docs if d.get("node_id") in candidates), None)
    if hit:
        return hit, "节点名"

    # 3) 当文档标题（「CHAP_1 · 知识文档」这类合订稿只有标题，没有 node_id）
    squashed = knowledge_doc_mod._squash(raw)
    for doc in docs:
        if knowledge_doc_mod._squash(doc.get("title")) == squashed:
            return doc, "标题"
    hit = next(
        (d for d in docs if squashed and squashed in knowledge_doc_mod._squash(d.get("title"))),
        None,
    )
    return (hit, "标题") if hit else (None, "")


def _agent_knowledge_docs(
    arguments: dict[str, Any], *, db: Any, project_id: str,
    owner_id: str, knowledge_doc: Any, nodes: list[Any] | None = None,
) -> str:
    """search_knowledge_docs 的实现。三种模式：定向读一篇 / 列举 / 如实说没有。"""
    if knowledge_doc is None:
        return "当前入口没有接入复习文档存储，读不到已生成的文档。"
    if not owner_id:
        return "读文档需要知道是哪个用户的文档，当前会话没有这个信息。"

    node_id = str(arguments.get("node_id") or "").strip()
    node_name = str(arguments.get("node_name") or "").strip()
    scope = str(arguments.get("scope") or "").strip().lower()

    if scope == "project":
        doc = knowledge_doc.get(
            knowledge_doc_mod.doc_key_for(owner_id, project_id, scope="project")
        )
        if not doc:
            return (
                "当前项目还没有合订成整份的复习文档"
                "（速查表里生成整份、或各节都生成后点「重新合订」才会有）。"
            )
        return _agent_doc_one(doc, arguments)

    if not node_id and not node_name:
        return _agent_doc_listing(knowledge_doc, project_id, owner_id, arguments)

    doc, matched_by = _agent_locate_doc(
        knowledge_doc, db, project_id, owner_id, node_id, node_name, list(nodes or [])
    )
    if doc:
        query = str(arguments.get("query") or "").strip()
        if query:
            terms = _query_terms(query)
            if terms and not _agent_artifact_hit(
                (doc.get("title"), doc.get("content_md")), terms
            ):
                # 文档在，但里面没有这个词 —— 说清楚「读到了、但没有」，别让模型
                # 以为是自己找错了文档。
                return (
                    f"{_agent_doc_head(doc, str(doc.get('content_md') or '').strip())}\n"
                    f"这篇文档里没有出现「{query}」相关内容。"
                    f"下面按标题列出它有什么，照着 section 再调一次：\n"
                    f"{_agent_doc_structure(str(doc.get('content_md') or ''))}"
                )
        out = _agent_doc_one(doc, arguments)
        if matched_by == "节点名":
            # 它把节点名当 node_id 传了进来，说清楚已按名字对上，模型下次会用对。
            out += f"\n\n（你给的「{node_id or node_name}」是节点名，已按它对上 node_id={doc.get('node_id')}。）"
        elif matched_by == "标题":
            out += f"\n\n（「{node_id or node_name}」是这份文档的标题，不是节点名。）"
        return out

    # 没定位到。**先把库里有的列出来**，让模型自己纠正，而不是直接判「没生成过」。
    docs = knowledge_doc.list_for_project(owner_id, project_id)
    query = str(arguments.get("query") or "").strip()
    if query:
        terms = _query_terms(query)
        docs = [
            d for d in docs
            if _agent_artifact_hit((d.get("title"), d.get("content_md")), terms)
        ]
    asked = node_id or node_name
    if not docs:
        return (
            f"当前项目一篇复习文档都没有生成过，不存在「{asked}」这一篇"
            "（速查表里点「＋文档」即可生成）。"
        )
    lines = [
        f"没找到叫「{asked}」的复习文档。当前项目里已经生成的有："
        if asked else "当前项目里已经生成的复习文档："
    ]
    lines.extend(_agent_doc_brief(d) for d in docs[:_AGENT_DOC_LIST_MAX])
    lines.append(
        "把上面某个 node_id（或节点名 / 文档标题）原样传回来就能读到它的正文；"
        "确认这里确实没有你要的那篇，再建议用户去生成。"
    )
    return "\n".join(lines)


def _agent_doc_listing(
    knowledge_doc: Any, project_id: str, owner_id: str, arguments: dict[str, Any]
) -> str:
    """列举模式：给清单 + 分页游标，不展开正文。

    原来列举和定向读共用一套截断逻辑，于是列举时也在往回塞 1200 字正文 —— 清单本身
    就是给模型挑目标的，掺正文只会挤掉后面的条目，合订稿永远排不上队。
    """
    docs = knowledge_doc.list_for_project(owner_id, project_id)
    scope = str(arguments.get("scope") or "").strip().lower()
    if scope in ("node", "project"):
        docs = [d for d in docs if d.get("scope") == scope]
    query = str(arguments.get("query") or "").strip()
    if query:
        terms = _query_terms(query)
        docs = [
            d for d in docs
            if _agent_artifact_hit((d.get("title"), d.get("content_md")), terms)
        ]
    if not docs:
        where = f"（{scope}）" if scope else ""
        return f"当前项目{where}还没有生成过复习文档（速查表里点「＋文档」即可生成）。"

    limit = _agent_limit(arguments, default=_AGENT_DOC_LIST_DEFAULT, maximum=_AGENT_DOC_LIST_MAX)
    try:
        offset = max(0, int(arguments.get("offset") or 0))
    except (TypeError, ValueError):
        offset = 0
    window = docs[offset : offset + limit]
    head = f"当前项目共 {len(docs)} 篇复习文档，这里是第 {offset + 1}~{offset + len(window)} 篇："
    lines = [head, ""]
    lines.extend(_agent_doc_brief(d) for d in window)
    if offset + limit < len(docs):
        lines.append("")
        lines.append(f"（还有 {len(docs) - offset - limit} 篇没显示，带 offset={offset + limit} 继续。）")
    lines.append("")
    lines.append(
        "读到某一篇的正文：把它的 node_id（或节点名 / 文档标题）填进 node_id 再调一次；"
        "只想看其中一节就再加 section=<小节名>。"
    )
    return "\n".join(lines)


def _agent_resolve_node(db: Any, project_id: str, node_id: Any, node_name: Any) -> Any:
    """按 node_id 或节点名定位一个框架节点；都找不到返回 None。

    模型经常只给节点名（它是从 get_framework 的输出里抄的），所以名->id 的兜底
    与 get_node 分支保持同一套做法（db.get_node_id_by_name），别两处口径不一致。
    """
    raw_id = str(node_id or "").strip()
    if raw_id:
        try:
            return db.get_framework_node(project_id, raw_id)
        except Exception:
            pass
    raw_name = str(node_name or "").strip()
    if raw_name:
        try:
            found = db.get_node_id_by_name(project_id, raw_name)
        except Exception:
            found = None
        if found:
            try:
                return db.get_framework_node(project_id, str(found))
            except Exception:
                return None
    return None


def _agent_prepare_offer(db: Any, project_id: str, arguments: dict[str, Any]) -> tuple[dict[str, Any] | None, str]:
    """归一化 plan_study_action 的参数。返回 (归一化参数, 观察文本)。

    归一化必须在登记待确认动作**之前**跑：staged action 存的是 arguments 的拷贝，
    前端要靠 arguments.node_id 调单节点生成端点、靠 arguments.kinds 渲染按钮，
    模型给的 node_name / 乱写的 kinds 到不了它手里。
    首个返回值是 None 表示选项没法成立，第二个返回值是可直接返回给模型的说明。

    **kinds 要先于 node 判定**：只有跳转族（看卡片 / 看速查表…）才允许没有节点，
    先解析 node 再看 kinds 的话，「我卡片里有什么」这种根本没有节点的问题会被一律拒掉。
    """
    raw_kinds = arguments.get("kinds")
    kinds = [str(k).strip() for k in raw_kinds if str(k).strip()] if isinstance(raw_kinds, list) else []
    kinds = [k for k in kinds if k in AGENT_STUDY_ACTION_LABELS]
    if not kinds:
        # 没给 / 全是乱写的：默认给「只看这个知识点」——它是唯一不花钱、永远成立的那个。
        # 但若项目里一个节点都没有，这一项也立不住，下面会走同一条拒绝路径。
        kinds = ["focus"]
    node = _agent_resolve_node(db, project_id, arguments.get("node_id"), arguments.get("node_name"))
    if node is None and any(k in AGENT_STUDY_ACTION_NODE_KINDS for k in kinds):
        return None, (
            "找不到对应的知识节点，没法给出后续选项。"
            "请先用 get_framework 或 search_knowledge_base 确认确切的节点名，再调用本工具。"
        )
    normalized = dict(arguments)
    normalized["kinds"] = kinds
    # 显式置空而不是删键：前端按 arguments.node_id 是否为空决定要不要渲染按钮，
    # 留一个模型随手编的 node_name 会被当成真节点去调生成端点。
    normalized["node_id"] = node.node_id if node is not None else ""
    normalized["node_name"] = node.name if node is not None else ""
    reason = str(arguments.get("reason") or "").strip()
    if reason:
        normalized["reason"] = reason[:120]
    labels = "、".join(AGENT_STUDY_ACTION_LABELS[k] for k in kinds)
    if node is None:
        return normalized, (
            f"已把可直接打开的学习产物入口交给用户：{labels}。"
            "请在回答里指明用户想找的是哪一样，别替他执行跳转。"
        )
    mastery = round(float(getattr(node, "mastery_score", 0.0) or 0.0) * 100)
    detail = f"当前掌握度 {mastery}%"
    if not str(getattr(node, "note_content", "") or "").strip():
        detail += "、还没有笔记"
    note = (
        f"已把「{node.name}」的后续选项交给用户（{detail}）。"
        f"可选项：{labels}。"
        "请在回答里说清为什么判断它薄弱、以及建议先做哪一项；不要代替用户做决定。"
    )
    return normalized, note


def _agent_learning_calendar(
    arguments: dict[str, Any],
    *,
    db: Any,
    project_id: str,
    owner_id: str | None,
    exam_scheduler: Any,
) -> str:
    """学习台历 = 打卡日历 + 冲刺计划 + 考期。

    打卡来自既有 learning_events 聚合（Database.list_user_learning_calendar），
    冲刺计划与考期来自 ExamScheduler —— 两者都是「派生读」，不新建表。
    冲刺计划读的是 get_active_sprint_plan，它已经把 learning_path / today_schedule /
    progress_percentage 都在读时 enrich 好了，直接用不要再手工拼。
    """
    if not owner_id:
        return "读学习台历需要知道是哪个用户，当前会话没有这个信息。"
    try:
        days = int(arguments.get("days") or 14)
    except (TypeError, ValueError):
        days = 14
    days = max(3, min(days, 90))
    lines = []
    try:
        calendar = db.list_user_learning_calendar(owner_id, days)
    except Exception:
        calendar = {}
    active = list(calendar.get("active_dates") or [])
    detail = calendar.get("days_detail") or {}
    lines.append(
        f"打卡日历（近 {days} 天）：共 {calendar.get('total_events', 0)} 条学习记录，"
        f"有记录的天数 {len(active)} 天。"
    )
    # 连续天数：active_dates 是倒序的，从今天（或昨天）往前数连续存在的天数
    streak = 0
    for index, date_key in enumerate(active):
        if index == 0:
            streak = 1
        elif streak:
            streak += 1
    if active:
        recent = []
        for date_key in active[:5]:
            day = detail.get(date_key) or {}
            kinds = day.get("kinds") or {}
            top = day.get("top_nodes") or []
            recent.append(
                f"  {date_key}：{day.get('event_count', 0)} 条"
                f"（{'、'.join(f'{k}×{v}' for k, v in list(kinds.items())[:3])}）"
                f"{'，涉及 ' + '、'.join(top[:2]) if top else ''}"
            )
        lines.append("最近几天：\n" + "\n".join(recent))
    else:
        lines.append("  这段时间还没有打卡记录。")

    plan = None
    exams: list[dict[str, Any]] = []
    if exam_scheduler is not None:
        try:
            plan = exam_scheduler.get_active_sprint_plan(owner_id, project_id)
        except Exception:
            plan = None
        try:
            exams = list(exam_scheduler.list_exams(owner_id, project_id) or [])
        except Exception:
            exams = []
    if plan:
        progress = plan.get("progress_percentage")
        lines.append(
            f"\n冲刺计划：进度 {progress}%" if isinstance(progress, (int, float))
            else "\n冲刺计划："
        )
        for stage in list(plan.get("stages") or [])[:4]:
            if not isinstance(stage, dict):
                continue
            lines.append(
                f"  阶段「{stage.get('name') or stage.get('title') or '未命名'}」"
                f"{stage.get('summary') or stage.get('goal') or ''}"
            )
        today = plan.get("today_schedule")
        if isinstance(today, dict):
            lines.append(f"  今日安排：{today.get('summary') or today.get('text') or json.dumps(today, ensure_ascii=False)[:160]}")
        for task in list(plan.get("today_tasks") or [])[:5]:
            if isinstance(task, dict):
                lines.append(
                    f"  - {task.get('title') or task.get('name') or ''}"
                    f"{'（已完成）' if task.get('completed') else ''}"
                )
    else:
        lines.append("\n冲刺计划：当前没有进行中的计划。")
    if exams:
        listed = "、".join(
            f"{item.get('name') or item.get('title') or '考试'}（{item.get('exam_date') or item.get('date') or '日期未定'}）"
            for item in exams[:3]
            if isinstance(item, dict)
        )
        lines.append(f"考期：{listed}")
    else:
        # 也要说一声：否则模型分不清「没有考期」和「这个工具不支持考期」，
        # 会自己在回答里编一个考试时间。
        lines.append("考期：当前项目没有登记任何考期。")
    return "\n".join(lines)


_AGENT_TOOL_NAMES_CACHE: frozenset[str] | None = None


def _known_agent_tool_names() -> frozenset[str]:
    """真实存在的工具名集合（懒建一次）。"""
    global _AGENT_TOOL_NAMES_CACHE
    if _AGENT_TOOL_NAMES_CACHE is None:
        _AGENT_TOOL_NAMES_CACHE = frozenset(
            str(tool.get("function", {}).get("name") or "") for tool in LEARNING_AGENT_TOOLS
        ) - {""}
    return _AGENT_TOOL_NAMES_CACHE


def _match_json_object_end(text: str, start: int) -> int:
    """从 ``text[start] == '{'`` 起找配对的 ``}``；找不到返回 -1。"""
    depth = 0
    in_string = False
    escaped = False
    for index in range(start, len(text)):
        char = text[index]
        if in_string:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == '"':
                in_string = False
            continue
        if char == '"':
            in_string = True
        elif char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return index
    return -1


def _peek_call_name(chunk: str) -> str:
    """从一个 JSON 对象里取出工具名；不是调用形态就返回空串。"""
    try:
        parsed = json.loads(chunk)
    except (ValueError, TypeError):
        return ""
    if not isinstance(parsed, dict):
        return ""
    return str(parsed.get("name") or "").strip()


def _strip_literal_tool_calls(text: str) -> str:
    """从任意文本里抠掉「指向真实工具」的伪调用，只留人话。

    为什么需要：工具调用在**流式主循环**里是靠 ``_LiteralToolCallAccumulator`` 边喂边摘的，
    所以正文里不会残留调用。但另外三条路没有累加器：
      - 轮数用尽后的「收尾合写」（走 ``llm.astream_chat_content``）；
      - **普通对话流**（agent=false）：系统提示词自称「学习辅导 Agent」，会话历史里又存着
        Agent 模式用过的调用格式，模型会被带跑，把 JSON 当正文吐出来；
      - 讨论流（同样共用会话历史）。
    模型又不听提示词里「不要输出 JSON」的禁令，于是这些 JSON 既显示给用户也存进库。

    ⚠️ 判据必须是「**工具名真实存在**」，不能是「结构完整」：正文里真的在讲这个调用格式时
    （教学场景，形如 ``{"name": "工具名", "parameters": {"参数名": "值"}}``）结构与真调用
    一模一样，只看结构会把人家的讲解删掉。按名字过滤才能两者都对。

    这里刻意**不用**累加器：它 ``pop_call`` 是破坏性的，摘完就找不回原文，无法「挑着摘」。
    """
    # 早退守卫要同时看两种形态：XML 形态里根本没有 `{`，只判 "{" 会把它短路掉。
    if not text or ("{" not in text and "<function" not in text):
        return text
    known = _known_agent_tool_names()
    pieces: list[str] = []
    cursor = 0
    while True:
        start = text.find("{", cursor)
        if start < 0:
            pieces.append(text[cursor:])
            break
        end = _match_json_object_end(text, start)
        if end < 0:
            # 没配平的残片：可能是正文里的普通括号，也可能是被截断的调用。
            # 保守起见保留（宁可多留几个字符，也不要把半句话删掉）。
            pieces.append(text[cursor:])
            break
        chunk = text[start : end + 1]
        name = _peek_call_name(chunk)
        pieces.append(text[cursor:start] if name and name in known else text[cursor : end + 1])
        cursor = end + 1
    # XML 形态同理：只有 function 名是真实工具时才摘
    stripped = "".join(pieces)
    if "<function=" in stripped:

        def _xml_drop(match: re.Match[str]) -> str:
            return "" if match.group("fname") in known else match.group(0)

        stripped = re.sub(
            r"<function\s*=\s*(?P<fname>[A-Za-z0-9_\-]+)\s*>.*?</function\s*>",
            _xml_drop,
            stripped,
            flags=re.S | re.I,
        )
    return stripped.strip()


def _agent_source_listing(sources: list[Any]) -> str:
    """列出当前项目上传了哪些资料 —— 用户问「我的资料/文献存了什么」时唯一正确的出口。

    为什么必须有它：``search_sources`` 的 ``query`` 是必填的，用户问「存了哪些内容」时
    模型手里根本没有关键词，就退而去刨速查表（``get_study_kit``）或知识框架，把那些内容
    复述成「你的文献里写了…」—— 答得煞有介事，跟资料毫无关系。实测就是这个坑。
    """
    if not sources:
        return "当前项目还没有上传任何资料（左侧资料区可以拖 PDF 进来）。"
    lines = [f"当前项目共 {len(sources)} 份资料：", ""]
    for source in sources:
        text = str(getattr(source, "text", "") or "")
        status = str(getattr(source, "status", "") or "ok")
        size = int(getattr(source, "size_bytes", 0) or 0)
        bits = [f"{max(1, len(text) // 1000)} 千字" if text else "没有正文"]
        if size:
            bits.append(f"{round(size / 1024 / 1024, 1)} MB" if size >= 1024 * 1024
                        else f"{max(1, round(size / 1024))} KB")
        formulas = getattr(source, "formulas", None) or []
        figures = getattr(source, "figures", None) or []
        if formulas:
            bits.append(f"{len(formulas)} 个公式")
        if figures:
            bits.append(f"{len(figures)} 张图")
        if status != "ok":
            bits.append(f"解析状态 {status}")
        lines.append(
            f"- 【{getattr(source, 'filename', '') or '未命名资料'}】"
            f"(source_id={getattr(source, 'source_id', '-')}，{'，'.join(bits)})"
        )
        heads = _agent_source_headings(text)
        if heads:
            lines.append(f"  目录：{' / '.join(heads)}")
    lines.append("")
    lines.append(
        "想看其中某一份的具体内容，用 search_sources 传关键词检索原文"
        "（它按片段返回，答的时候在句末标 [1] 这样的来源编号）。"
    )
    return "\n".join(lines)


def _agent_source_headings(text: str, limit: int = 10) -> list[str]:
    """从资料正文里提出目录行。

    正文里的小标题统一写成 ``[[H:层级]] 标题``（渲染层会转成 h2/h3/h4），所以这里直接
    按标记取 —— 比截前几百字更接近「这份资料讲了什么」。
    """
    seen: set[str] = set()
    out: list[str] = []
    for match in re.finditer(r"\[\[H:\d+\]\]\s*(.+)", str(text or "")):
        title = re.sub(r"\s+", " ", match.group(1)).strip(" #>-")
        if not title or title in seen or len(title) > 60:
            continue
        seen.add(title)
        out.append(title)
        if len(out) >= limit:
            out.append("…")
            break
    return out


def _run_agent_tool(
    name: str,
    arguments: dict[str, Any],
    *,
    db: Any,
    project_id: str,
    sources: list[Any],
    nodes: list[Any],
    owner_id: str | None = None,
    conversation_id: str | None = None,
    current_llm: "LlmClient | None" = None,
    cited_sources: dict[int, dict[str, Any]] | None = None,
    staged_actions: list[dict[str, Any]] | None = None,
    study_kit: Any = None,
    exam_scheduler: Any = None,
    knowledge_doc: Any = None,
) -> str:
    """执行一个 Agent 工具，返回喂回模型的「观察结果」纯文本。

    staged_actions 不为 None 时启用写操作闸门：写库类工具只登记不执行，等界面确认。
    传 None（知识库 Agent 面板、执行确认端点）就是原来的直接落库行为。
    """
    if staged_actions is not None and (name in AGENT_WRITE_TOOLS or name in AGENT_OFFER_TOOLS):
        payload_args = dict(arguments or {})
        offer_note = ""
        if name in AGENT_OFFER_TOOLS:
            # 提议型工具要先把 node_name 换成权威 node_id、把 kinds 归一化，
            # 因为前端是按 arguments.kinds 渲染按钮、按 arguments.node_id 调端点的 ——
            # 而归一化必须发生在「登记」之前：staged action 里存的是 arguments 的拷贝。
            prepared, offer_note = _agent_prepare_offer(db, project_id, payload_args)
            if prepared is None:
                return offer_note
            payload_args = prepared
        action = {
            "tool": name,
            "arguments": payload_args,
            "label": _agent_staged_action_label(name, payload_args),
        }
        staged_actions.append(action)
        if name in AGENT_OFFER_TOOLS:
            # 提议型动作不写知识库，只是把「下一步可以做什么」做成可点的按钮交给用户，
            # 所以提示语不能说「尚未写入知识库」。
            # 跳转族与生成族也要分开说：让模型「说明为什么推荐这几项」「挑一个执行」
            # 去描述一个纯跳转，会写出「我推荐你打开卡片」这种废话。
            kinds = payload_args.get("kinds") or []
            jump_only = bool(kinds) and all(
                k in AGENT_STUDY_ACTION_NODE_FREE_KINDS for k in kinds
            )
            if jump_only:
                return (
                    f"[待用户确认] 已给出「{action['label']}」的跳转入口，尚未切页面。"
                    "请在回答里指明用户想找的是哪一样，并提醒他在下方选项卡里点一下；"
                    "不要替他执行跳转，也不要声称已经打开了任何页面。"
                )
            return (
                f"[待用户确认] 已给出「{action['label']}」共 {len(kinds)} 个选项，"
                "尚未执行任何生成。"
                "请在回答里说明为什么推荐这几项、建议先做哪一项，并提到用户可以在下方选项卡里"
                "勾选后提交；不要声称已经生成过任何东西。"
            )
        return (
            f"[待用户确认] 已登记「{action['label']}」，尚未写入知识库。"
            "请在回答里说明这项修改的理由与影响；用户会在回答下方的确认卡片里决定是否执行。"
        )
    if name == "campus_query":
        return _campus_query(arguments)
    if name == "list_sources":
        return _agent_source_listing(sources)
    if name == "search_sources":
        query = str(arguments.get("query") or "").strip()
        if not query:
            return "缺少检索关键词。"
        if not any(str(getattr(source, "text", "") or "").strip() for source in sources):
            return "当前课程还没有可用的资料内容。"
        hits = _agent_source_hits(sources, query)
        # 编号 → source_id 的映射回传给上层：答案里的 [1] 才能变回可点击的来源 chip。
        if cited_sources is not None:
            for index, hit in enumerate(hits, start=1):
                cited_sources[index] = hit
        if not hits:
            return f"资料中未检索到与「{query}」相关的内容。"
        blocks = []
        for index, hit in enumerate(hits, start=1):
            blocks.append(
                f"【{index}】{hit['filename']}（source_id={hit['source_id']}）\n{hit['text']}"
            )
        return (
            f"命中 {len(hits)} 段资料：\n"
            + "\n\n".join(blocks)
            + "\n\n作答时请在有依据的句末标出来源编号，例如 [1]、[2]。"
        )
    if name == "get_mastery":
        node_id = str(arguments.get("node_id") or "").strip()
        node = next((item for item in nodes if item.node_id == node_id), None)
        if node is None:
            known = "、".join(item.name for item in nodes[:10]) or "（暂无节点）"
            return f"未找到节点 {node_id}。当前可用节点：{known}"
        return (
            f"{node.name}：掌握度 {round(float(node.mastery_score) * 100)}%，"
            f"学习状态 {node.learning_status}，覆盖状态 {node.coverage_status}。"
        )
    if name == "get_framework":
        if not nodes:
            return "当前课程还没有知识框架，请先在左侧生成。"
        lines = [
            f"- {item.name}（掌握度 {round(float(item.mastery_score) * 100)}%"
            f"{'，记笔记' if item.note_content.strip() else '，未记笔记'}"
            f"{'，标签' + ','.join(item.tags) if item.tags else ''}）"
            for item in nodes[:60]
        ]
        return "知识框架：\n" + "\n".join(lines)
    if not nodes and name not in _AGENT_NODE_FREE_TOOLS:
        return "当前项目还没有任何知识节点，请先构建知识框架（框架生成后才有知识库可检索/整理）。"

    if name == "search_knowledge_base":
        query = str(arguments.get("query") or "").strip()
        tag = str(arguments.get("tag") or "").strip() or None
        if not query and not tag:
            return "请提供检索关键词或标签。"
        hits = db.search_nodes(project_id, query=query or None, tag=tag)
        if not hits:
            return f"知识库中未检索到与「{query or tag}」相关的内容。"
        lines = []
        for node in hits[:30]:
            lines.append(
                f"- {node.name}｜掌握度 {round(float(node.mastery_score) * 100)}%｜"
                f"状态 {node.learning_status}｜id={node.node_id}"
                f"{'｜标签：' + ','.join(node.tags) if node.tags else ''}"
                f"{'｜笔记：' + node.note_content[:60] if node.note_content.strip() else '｜无笔记'}"
            )
        return "知识库检索结果（可据此判断知识储备与薄弱点）：\n" + "\n".join(lines)

    if name == "get_node":
        node_ref = str(arguments.get("node_id") or "").strip()
        # 弱模型 / 文字伪调用常把节点「名称」当 node_id 传。与三个写工具共用同一套
        # 定位口径，避免同一个名字在读工具里认得、在写工具里却报不存在。
        node_id = _agent_resolve_node_id(db, project_id, node_ref)
        if node_id is None:
            return f"节点「{node_ref}」不存在。"
        node = db.get_framework_node(project_id, node_id)
        backlinks = db.get_backlinks(project_id, node.node_id)
        return (
            f"节点「{node.name}」\n"
            f"- 描述：{node.description or '（空）'}\n"
            f"- 掌握度：{round(float(node.mastery_score) * 100)}%，状态 {node.learning_status}\n"
            f"- 标签：{('、'.join(node.tags)) or '（空）'}\n"
            f"- 双链指向：{('、'.join(node.wikilinks)) or '（无）'}\n"
            f"- 反链来源：{('、'.join(b.name for b in backlinks)) or '（无）'}\n"
            f"- 笔记正文：\n{(node.note_content.strip() or '（暂无笔记）')[:800]}"
        )

    if name == "add_node":
        name = str(arguments.get("name") or "").strip()
        if not name:
            return _agent_write_failed("add_node 缺少 name 参数。")
        # parent_id 同样可能是节点名，交给统一的定位口径处理
        parent_ref = str(arguments.get("parent_id") or "").strip()
        parent_id = _agent_resolve_node_id(db, project_id, parent_ref) if parent_ref else None
        description = str(arguments.get("description") or "").strip()
        if db.get_node_id_by_name(project_id, name) is not None:
            return _agent_write_failed(
                f"知识库中已存在同名节点「{name}」，请勿重复创建。"
            )
        if parent_ref and parent_id is None:
            return _agent_write_failed(f"父节点「{parent_ref}」不存在。")
        node = db.add_framework_node(
            project_id, name=name, description=description, parent_id=parent_id
        )
        if owner_id:
            try:
                db.record_undo(
                    owner_id,
                    project_id,
                    "kb_agent_write",
                    f"整理助手：新建节点「{name}」",
                    {
                        "project_id": project_id,
                        "node_id": node.node_id,
                        "action": "add_node",
                        "node_name": name,
                        "before": None,
                    },
                )
            except Exception:
                pass
        return f"已新建节点「{name}」id={node.node_id}（掌握度 0%）。"

    if name == "update_node":
        node_ref = str(arguments.get("node_id") or "").strip()
        node_id = _agent_resolve_node_id(db, project_id, node_ref)
        if node_id is None:
            return _agent_write_failed(f"节点「{node_ref}」不存在。")
        try:
            existing = db.get_framework_node(project_id, node_id)
        except NodeNotFound:
            return _agent_write_failed(f"节点「{node_ref}」不存在。")
        kwargs: dict[str, Any] = {}
        note_content = arguments.get("note_content")
        description = arguments.get("description")
        tags = arguments.get("tags")
        wikilinks = arguments.get("wikilinks")
        # 破坏轨：改写已有大段笔记需确认（T9）
        if (
            note_content is not None
            and str(note_content).strip()
            and (existing.note_content or "").strip()
            and len((existing.note_content or "").strip()) > 40
            and arguments.get("confirm") is not True
        ):
            return (
                f"[需要确认] 将**覆盖**既有笔记（{len((existing.note_content or '').strip())}字）。"
                f"确认请传 confirm:true 才执行。"
            )
        if note_content is not None:
            kwargs["note_content"] = str(note_content)
        if tags is not None:
            kwargs["tags"] = [str(t) for t in tags if isinstance(t, (str, int))]
        if wikilinks is not None:
            kwargs["wikilinks"] = [
                str(w) for w in wikilinks if isinstance(w, (str, int))
            ]
        before = {
            "note_content": existing.note_content,
            "tags": list(existing.tags),
            "wikilinks": list(existing.wikilinks),
            "description": existing.description,
        }
        if kwargs:
            db.update_node_note(project_id, node_id, **kwargs)
        if description is not None or note_content is not None:
            node = db.get_framework_node(project_id, node_id)
            db.update_framework_node(
                project_id,
                node_id,
                name=node.name,
                description=(
                    str(description) if description is not None else node.description
                ),
                parent_id=node.parent_id,
            )
        if owner_id:
            try:
                db.record_undo(
                    owner_id,
                    project_id,
                    "kb_agent_write",
                    f"整理助手：更新节点「{existing.name}」",
                    {
                        "project_id": project_id,
                        "node_id": node_id,
                        "action": "update_node",
                        "node_name": existing.name,
                        "before": before,
                    },
                )
            except Exception:
                pass
        return f"已更新节点「{db.get_framework_node(project_id, node_id).name}」。"

    if name == "delete_node":
        node_ref = str(arguments.get("node_id") or "").strip()
        node_id = _agent_resolve_node_id(db, project_id, node_ref)
        if node_id is None:
            return _agent_write_failed(f"节点「{node_ref}」不存在。")
        try:
            node = db.get_framework_node(project_id, node_id)
        except NodeNotFound:
            return _agent_write_failed(f"节点「{node_ref}」不存在。")
        if arguments.get("confirm") is not True:
            return f"[需要确认] 删除节点「{node.name}」将不可逆。确认请传 confirm:true 才执行。"
        before = {
            "note_content": node.note_content,
            "tags": list(node.tags),
            "wikilinks": list(node.wikilinks),
            "description": node.description,
        }
        db.delete_framework_node(project_id, node_id)
        if owner_id:
            try:
                db.record_undo(
                    owner_id,
                    project_id,
                    "kb_agent_write",
                    f"整理助手：删除节点「{node.name}」",
                    {
                        "project_id": project_id,
                        "node_id": node_id,
                        "action": "delete_node",
                        "node_name": node.name,
                        "before": before,
                    },
                )
            except Exception:
                pass
        return f"已删除节点「{node.name}」（其子节点已挂到原父级）。"

    if name == "create_link":
        a_name = str(arguments.get("a_name") or "").strip()
        b_name = str(arguments.get("b_name") or "").strip()
        if not a_name or not b_name:
            return _agent_write_failed("create_link 需要 a_name 与 b_name。")
        a_id = _agent_resolve_node_id(db, project_id, a_name)
        b_id = _agent_resolve_node_id(db, project_id, b_name)
        if a_id is None:
            return _agent_write_failed(f"节点「{a_name}」不存在，请先新建它。")
        if b_id is None:
            return _agent_write_failed(f"节点「{b_name}」不存在，请先新建它。")
        a = db.get_framework_node(project_id, a_id)
        links = list(a.wikilinks)
        if b_name not in links:
            links.append(b_name)
        db.update_node_note(project_id, a_id, wikilinks=links)
        if owner_id:
            try:
                db.record_undo(
                    owner_id,
                    project_id,
                    "kb_agent_write",
                    f"整理助手：建立双链「{a_name}」→「{b_name}」",
                    {
                        "project_id": project_id,
                        "node_id": a_id,
                        "action": "create_link",
                        "node_name": a_name,
                        "before": {"wikilinks": list(a.wikilinks)},
                    },
                )
            except Exception:
                pass
        return f"已在「{a_name}」中建立双链 → 「{b_name}」。"

    if name == "socratic_ask":
        node_id = str(arguments.get("node_id") or "").strip()
        q = str(arguments.get("question") or "").strip()
        try:
            node = db.get_framework_node(project_id, node_id)
        except NodeNotFound:
            return f"节点 {node_id} 不存在。"
        prior = ""
        if conversation_id:
            st = db.get_socratic_state(conversation_id, node_id)
            if st and st["miscue"]:
                prior = f"（上次错因：{st['miscue']}，hint={st['hint_level']}）"
        return f"请围绕节点「{node.name}」回答：{q}{prior}\n提示：先用自己的话复述该节点讲了什么，答完我会评估并给下一级提示（hint 阶梯，不外泄答案）。"

    if name == "record_miscue":
        node_id = str(arguments.get("node_id") or "").strip()
        verdict = str(arguments.get("verdict") or "").strip()
        miscue = str(arguments.get("miscue") or "").strip()
        hint_level = int(arguments.get("hint_level") or 0)
        if not conversation_id:
            return "record_miscue 需要在会话中调用（缺少 conversation_id）。"
        if node_id not in {n.node_id for n in nodes}:
            return f"节点 {node_id} 不存在。"
        prior = db.get_socratic_state(conversation_id, node_id) or {}
        new_iter = int(prior.get("iter_count") or 0) + 1
        mastery = 0.9 if verdict == "clear" else (0.5 if verdict == "模糊" else 0.3)
        db.upsert_socratic_state(
            conversation_id,
            node_id,
            verdict=verdict,
            miscue=miscue,
            hint_level=hint_level,
            mastery_after=mastery,
            iter_count=new_iter,
            convergence="open",
        )
        if verdict in ("模糊", "mist") and hint_level < 3:
            return f"已记录「{verdict}」（hint={hint_level}），将再出一题巩固并给下一级 hint。"
        return f"已记录「{verdict}」并更新该节点掌握状态。"

    if name == "converge":
        decision = str(arguments.get("decision") or "").strip()
        item_ids = arguments.get("item_ids") or []
        if decision == "apply":
            return "已按 apply 固化当前改动。"
        if decision == "redo":
            ids = "、".join(str(i) for i in item_ids) or "（全部未固化项）"
            return f"[需要重做] item_ids={ids}，请针对这些项重新整理后再次给出收敛点。"
        if decision == "stop":
            return "已按 stop 停止，未固化的改动不再落地。"
        return "converge 的 decision 只能是 apply / redo / stop。"

    if name == "complete_note":
        node_id = str(arguments.get("node_id") or "").strip()
        existing = [
            p
            for p in db.list_proposals(project_id, status="pending")
            if p["node_id"] == node_id
        ]
        if existing:
            target = existing[0]
            return (
                f"待批准建议稿已存在（proposal_id={target['proposal_id']}），未重复创建。"
                f"\n「{target['proposed_content'][:0] or ''}」现有建议稿如下（先批准或拒绝它再补全）：\n{target['proposed_content']}"
            )
        try:
            note = db.get_framework_node(project_id, node_id)
        except NodeNotFound:
            return f"节点 {node_id} 不存在。"
        if current_llm is not None:
            try:
                g = _generate_node_detail_proposal(
                    db, current_llm, project_id, node_id, sources
                )
                draft = g["content"]
                reason = g["reason"] or "补全为详细高质量原子笔记。"
            except HTTPException as exc:
                return (
                    exc.detail.get("message")
                    if isinstance(exc.detail, dict)
                    else str(exc.detail)
                )
        else:
            draft = (
                f"# {note.name}\n\n"
                f"（定义）{(note.description or '来源未提及，[待补]')}\n\n"
                f"## 要点\n- {note.description or '（待按来源补充）'}\n\n"
                f"## 关联\n{'、'.join(note.wikilinks) or '（待补充 [[双链]]）'}"
            )
            reason = "补全为详细高质量原子笔记。"
        proposal = db.create_proposal(
            project_id,
            node_id,
            "complete_note",
            draft,
            type_="complete_note",
            reason=reason,
        )
        return (
            f"已为「{note.name}」生成并写入待批准建议稿 proposal_id={proposal['proposal_id']}（未直接改库，"
            f"批准后才落地）。建议稿预览（前 400 字）：\n{draft[:400]}"
        )

    if name == "propose_note":
        node_id = str(arguments.get("node_id") or "").strip()
        note_content = str(arguments.get("note_content") or "").strip()
        try:
            node = db.get_framework_node(project_id, node_id)
        except NodeNotFound:
            return f"节点 {node_id} 不存在。"
        if not note_content:
            return "propose_note 需要提供 note_content 正文。"
        proposal = db.create_proposal(project_id, node_id, "update_note", note_content)
        return (
            f"已为「{node.name}」写入待批准建议稿 proposal_id={proposal['proposal_id']}（未直接改库，"
            f"批准后才会更新节点笔记）。预览（前 300 字）：\n{note_content[:300]}"
        )

    if name == "list_proposals":
        proposals = db.list_proposals(project_id, status="pending")
        if not proposals:
            return "当前没有待批准的建议稿。"
        lines = [f"待批准建议稿（共 {len(proposals)} 条）："]
        for p in proposals:
            node_name = "(节点已删)"
            try:
                node_name = db.get_framework_node(project_id, p["node_id"]).name
            except NodeNotFound:
                pass
            lines.append(
                f"- proposal_id={p['proposal_id']}｜节点「{node_name}」"
                f"｜动作 {p['proposed_action']}｜" + p["proposed_content"][:80]
            )
        return "\n".join(lines)

    if name == "search_cards":
        query = str(arguments.get("query") or "").strip()
        category = str(arguments.get("category") or "").strip()
        limit = _agent_limit(arguments)
        # list_cards 内部是裸 json.loads(payload)，一条脏数据就会抛 —— 读工具不该因此整轮失败
        try:
            cards = list(db.list_cards(project_id))
        except Exception:
            cards = []
        if not cards:
            return "当前项目还没有知识卡片。"
        if category:
            cards = [card for card in cards if card.category == category]
        if query:
            terms = _query_terms(query)
            cards = [
                card
                for card in cards
                if _agent_artifact_hit((card.front, card.back, card.category), terms)
            ]
        if not cards:
            return f"知识卡片里没有匹配「{query or category}」的内容（共 {len(cards)} 张卡可选）。"
        lines = [f"知识卡片命中 {len(cards)} 张（按创建顺序，最多显示 {limit} 张）："]
        for index, card in enumerate(cards[:limit], start=1):
            lines.append(
                f"卡片 {index}｜分类 {card.category}｜难度 {card.difficulty}\n"
                f"  题面：{card.front.strip()}\n"
                f"  答案：{card.back.strip()[:300]}"
            )
        if len(cards) > limit:
            lines.append(f"（还有 {len(cards) - limit} 张未显示，可换关键词再查）")
        lines.append(
            "【回答要求】用户问「有哪些/关于 X 的知识卡片」时，上面这张清单**就是答案本身**："
            "按编号逐条列出（题面 + 答案 + 分类/难度）并说明共命中几条；"
            "不要把它们改写成关于该主题的散文总结，也不要用「根据提供的资料片段」开头。"
        )
        return "\n".join(lines)

    if name == "search_quiz":
        query = str(arguments.get("query") or "").strip()
        include_answer = arguments.get("include_answer") is True
        limit = _agent_limit(arguments)
        quiz = db.get_latest_quiz(project_id)
        if not quiz:
            return "当前项目还没有生成小测验。"
        questions = [q for q in (quiz.get("questions") or []) if isinstance(q, dict)]
        total = len(questions)
        if query:
            terms = _query_terms(query)
            questions = [
                q
                for q in questions
                if _agent_artifact_hit(
                    (
                        q.get("question"),
                        " ".join(str(o) for o in (q.get("options") or [])),
                        q.get("answer"),
                        q.get("explanation"),
                    ),
                    terms,
                )
            ]
        head = f"当前小测验共 {total} 道题"
        if quiz.get("submitted_at"):
            # score 落库是 0~1 比例（api_server 的 submit: correct/total）
            head += f"，用户已作答，得分 {round(float(quiz.get('score') or 0) * 100)}%"
        else:
            head += "，用户还没作答"
        if not questions:
            return f"{head}；其中没有匹配「{query}」的题目。"
        lines = [f"{head}；命中 {len(questions)} 道（最多显示 {limit} 道）："]
        for index, question in enumerate(questions[:limit], start=1):
            options = [str(o) for o in (question.get("options") or [])]
            lines.append(f"{index}. {question.get('question') or ''}")
            if options:
                lines.append("   选项：" + " / ".join(options))
            if include_answer:
                lines.append(
                    f"   答案：{question.get('answer') or ''}"
                    f"{'｜解析：' + str(question.get('explanation')) if question.get('explanation') else ''}"
                )
        if not include_answer:
            lines.append("（本次未返回答案与解析；需要讲评时带 include_answer=true 再查一次）")
        return "\n".join(lines)

    if name == "search_highlights":
        query = str(arguments.get("query") or "").strip()
        item_type = str(arguments.get("item_type") or "").strip()
        limit = _agent_limit(arguments)
        try:
            favorites = list(db.list_favorites(project_id))
        except Exception:
            favorites = []
        if not favorites:
            return "用户的『我的笔记』里还没有收藏。"
        if item_type:
            favorites = [fav for fav in favorites if fav.item_type == item_type]
        if query:
            terms = _query_terms(query)
            favorites = [
                fav
                for fav in favorites
                if _agent_artifact_hit(
                    (fav.title, fav.content, fav.answer, fav.note, fav.chapter_name),
                    terms,
                )
            ]
        if not favorites:
            return f"『我的笔记』里没有匹配「{query or item_type}」的收藏。"
        lines = [f"『我的笔记』命中 {len(favorites)} 条（最多显示 {limit} 条）："]
        type_labels = {"card": "卡片", "quiz": "测验题", "question": "提问"}
        for index, fav in enumerate(favorites[:limit], start=1):
            color = fav.highlight_color or "none"
            lines.append(
                f"笔记 {index}｜类型 {type_labels.get(fav.item_type, fav.item_type)}"
                f"｜{fav.chapter_name}｜高亮={color}\n"
                f"  标题：{fav.title.strip()[:160]}"
            )
            # note 才是用户自己写的话，answer 是原答案；两者语义不同，分开显示
            if fav.note.strip():
                lines.append(f"  我的批注：{fav.note.strip()[:300]}")
            if fav.answer.strip():
                lines.append(f"  原答案：{fav.answer.strip()[:200]}")
        if len(favorites) > limit:
            lines.append(f"（还有 {len(favorites) - limit} 条未显示，可换关键词再查）")
        lines.append(
            "【回答要求】用户问「我收藏过什么/关于 X 的笔记」时，按编号逐条列出"
            "（标题 + 我的批注 + 原答案），并说明共几条。"
        )
        return "\n".join(lines)

    if name == "get_study_kit":
        raw_kind = str(arguments.get("kind") or "").strip().lower()
        if raw_kind and raw_kind not in study_kit_mod.KINDS:
            return (
                f"未知的种类「{raw_kind}」，可选："
                + "、".join(f"{k}={study_kit_mod.KIND_LABELS[k]}" for k in study_kit_mod.KINDS)
            )
        if study_kit is None:
            return "当前入口没有接入学习台历存储，读不到速查表/学习路径/清单。"
        kinds = [raw_kind] if raw_kind else list(study_kit_mod.KINDS)
        blocks = []
        for kind in kinds:
            kit = study_kit.get(project_id, kind)
            if not kit:
                blocks.append(f"【{study_kit_mod.KIND_LABELS[kind]}】尚未生成。")
                continue
            blocks.append(
                f"【{kit.get('kind_label') or study_kit_mod.KIND_LABELS[kind]}】"
                f"更新于 {kit.get('updated_at') or '未知时间'}\n{kit.get('content_md') or ''}"
            )
        return "\n\n".join(blocks)

    if name == "get_learning_calendar":
        return _agent_learning_calendar(arguments, db=db, project_id=project_id,
                                        owner_id=owner_id, exam_scheduler=exam_scheduler)

    if name == "search_knowledge_docs":
        return _agent_knowledge_docs(arguments, db=db, project_id=project_id,
                                     owner_id=owner_id, knowledge_doc=knowledge_doc,
                                     nodes=nodes)

    if name == "plan_study_action":
        # 非闸门路径（知识库 Agent 面板没有确认卡片）：照常归一化，但只给文字建议，
        # 不假装执行了生成 —— 那边要真生成得用户自己去速查表点「＋卡片/＋测验/＋文档」。
        prepared, note = _agent_prepare_offer(db, project_id, dict(arguments or {}))
        if prepared is None:
            return note
        return note + "\n（当前界面没有确认卡片，无法直接执行生成；请到速查表里对对应节点操作。）"

    if name == "get_kb_digest":
        digest = db.get_digest(project_id)
        if digest is None:
            digest = build_kb_digest(db, project_id, None)
        return render_digest_text(digest)

    if name == "recommend_links":
        _linked: set[tuple[str, str]] = set()
        for node in nodes:
            for target in node.wikilinks:
                _linked.add((node.name, target))
        lines = ["双链关联推荐（共享标签或名称相近的节点对）："]
        for node in nodes[:50]:
            # 1) 共享标签
            for other in nodes:
                if other.node_id == node.node_id:
                    continue
                if (node.name, other.name) in _linked or (
                    other.name,
                    node.name,
                ) in _linked:
                    continue
                if set(node.tags) & set(other.tags):
                    lines.append(
                        f"- 「{node.name}」 ↔ 「{other.name}」（共享标签{','.join(set(node.tags) & set(other.tags))}）"
                    )
                    _linked.add((node.name, other.name))
        return "\n".join(lines) or "暂无可推荐的双链（试试先给相关节点打上共同标签）。"

    if name == "recommend_link_gaps":
        if current_llm is None:
            return "当前未配置可用的模型，无法生成缺失节点补全建议。"
        node_id = str(arguments.get("node_id") or "").strip()
        try:
            db.get_framework_node(project_id, node_id)
        except NodeNotFound:
            return f"未找到节点 {node_id}。可先用 get_framework 查看节点 ID。"
        return _recommend_link_gaps(db, current_llm, project_id, node_id, nodes)

    return f"未知工具：{name}。"


class _HotSwapLlm:
    """「总是取当前那份 LLM 客户端」的转发代理 —— 统一密钥的唯一入口。

    背景：``create_app`` 里的 ``llm`` 只在**启动时**构造一次，随后被 40+ 个端点
    与辅助函数闭包捕获。而「设置 → 模型」保存新配置时只替换
    ``application.state.llm``，闭包捕获的那一份不会跟着变 —— 于是出现
    「填了新密钥、知识框架/卡片/测验都正常，但文献精读里的 AI 问答、阅读重点、
    全文翻译一直报 HTTP 401 认证错误，必须重启才生效」。

    修法不是逐个改调用点（44 处，漏一处就复发），而是把闭包里的 ``llm`` 换成
    这个代理：每次属性访问都落到 ``resolver()`` 返回的**当前**实例，
    全站因此只有一份生效中的密钥。

    只做转发，不缓存、不改写；被代理的实例仍自带用量记账与记忆注入，行为不变。
    """

    __slots__ = ("_resolver",)

    def __init__(self, resolver: Any) -> None:
        object.__setattr__(self, "_resolver", resolver)

    def _latest(self) -> Any:
        client = self._resolver()
        # resolver 指回自己 = 装配顺序出错，宁可给一条能看懂的报错，也不要递归
        if client is None or client is self:
            raise ModelApiError(
                "llm_not_ready", "模型客户端尚未就绪，请稍后重试。", retryable=True
            )
        return client

    def __getattr__(self, name: str) -> Any:
        return getattr(self._latest(), name)

    def __repr__(self) -> str:
        return f"<HotSwapLlm -> {self._resolver()!r}>"


# 推荐问题的请求体。
# ⚠️ 必须放在模块层、不能用 `from __future__ import annotations` + 函数内局部类：
# FastAPI 解析路由注解时用的是 typing.get_type_hints，它只查**模块 globals**。
# 定义在 create_app() 内部的局部类取不到 → 变成未定义的 ForwardRef →
# app.openapi() 直接抛 PydanticUserError，/openapi.json 返回 500（/docs 也一起废掉）。
class RecommendQuestionsRequest(BaseModel):
    exclude: list[str] = Field(default_factory=list)


def create_app(
    database: Database | None = None,
    settings: Settings | None = None,
    llm_client: LlmClient | None = None,
) -> FastAPI:
    current_settings = settings or load_settings()
    # 兼容旧版数据文件：优先用新名 knoworigin.sqlite3；若尚不存在但旧名 knoworigin.sqlite3 仍在，
    # 则沿用旧名打开，避免老用户升级后本地资料与学习记录丢失。
    _data_dir = current_settings.data_dir
    _db_path = _data_dir / "knoworigin.sqlite3"
    if not _db_path.exists() and (_data_dir / "knoworigin.sqlite3").exists():
        _db_path = _data_dir / "knoworigin.sqlite3"
    db = database or Database(_db_path)
    llm = llm_client or LlmClient(current_settings)
    # 保留一份**未被代理包装**的原始客户端：周报与记忆提取跑在后台，必须绕过
    # 记账代理（否则代理结束时又去检查"要不要提取"，形成递归）。
    # 它们的用量由 _aux_charge 手动上报，账面上不会漏。
    _raw_llm = llm

    # FastAPI 实例上移到此处：下面新增的中间件与异常处理器都必须先有 application。
    # 只是位置调整 —— FastAPI() 构造无副作用、也不依赖 db/llm，时机语义不变。
    application = FastAPI(title="KnowOrigin Local Learning API", version="0.1.0")

    # ---- AI 用量记账 / 长期记忆 / 通知中心：三个附加 store + 两层透明代理 ----
    # 全部为**新增**，既有端点一行未改。三个 store 都复用主库文件（独立连接，
    # 带 busy_timeout），懒初始化 —— 第一次真正用到时才建表、开连接。
    _aux_stores: dict[str, Any] = {}

    def _aux_store(key: str, factory: Any) -> Any:
        store = _aux_stores.get(key)
        if store is None:
            store = factory(db.path)
            _aux_stores[key] = store
        return store

    def usage_store() -> UsageStore:
        return _aux_store("usage", UsageStore)

    def memory_store() -> MemoryStore:
        return _aux_store("memory", MemoryStore)

    def notice_store() -> NoticeStore:
        return _aux_store("notice", NoticeStore)

    def review_store() -> ReviewStore:
        return _aux_store("review", ReviewStore)

    # —— 学情洞察（2026-09-25）：教学模式 / 速查表与学习路径 / 资料矛盾 ——
    def teaching_store() -> TeachingPrefs:
        return _aux_store("teaching", TeachingPrefs)

    def study_kit_store() -> StudyKitStore:
        return _aux_store("study_kit", StudyKitStore)

    def node_study_plan_store() -> NodeStudyPlanStore:
        return _aux_store("node_study_plan", NodeStudyPlanStore)

    def knowledge_doc_store() -> KnowledgeDocStore:
        return _aux_store("knowledge_doc", KnowledgeDocStore)

    def conflict_store() -> ConflictStore:
        return _aux_store("conflicts", ConflictStore)

    def evidence_matrix_store() -> EvidenceMatrixStore:
        return _aux_store("evidence_matrix", EvidenceMatrixStore)

    def peer_review_store() -> PeerReviewStore:
        return _aux_store("peer_review", PeerReviewStore)

    def exam_scheduler() -> ExamScheduler:
        return _aux_store("exams", ExamScheduler)

    # 每用户当前教学档位的进程内缓存。中间件每个请求都要用，不能每请求查库；
    # 用户在设置页切换时由 PUT 端点直接失效，所以不会读到陈旧值。
    _teaching_cache: dict[str, str] = {}

    def teaching_mode_for(owner_id: str) -> str:
        key = owner_id or ""
        cached = _teaching_cache.get(key)
        if cached is not None:
            return cached
        try:
            mode = teaching_store().get(key)
        except Exception:
            # 读不到偏好不能影响请求本身 —— 回落默认档（= 既有行为）。
            mode = teaching_mode_mod.DEFAULT_MODE
        _teaching_cache[key] = mode
        return mode

    # 代理叠加顺序：记账(记忆(原始客户端))。
    # 记账在最外层，才能把注入记忆之后的完整 prompt 一并计进用量。
    def _wrap_llm(client: Any) -> Any:
        """给模型客户端套上「记忆注入 + 用量记账」两层代理。

        为什么抽成函数：``/api/config`` 保存新配置后会用新 Settings **重建**
        LlmClient。那里也必须重新包装 —— 否则用户一改 API 配置，记账与记忆就
        静默失效（功能还在，只是永远不记账、永远不带记忆，最难查的那种坏法）。

        配置一律现读 ``application.state.settings``（首次调用时它还没被赋值，
        回落闭包里的初始 settings），这样改完配置无需重启即生效。
        """

        def _settings_now() -> Any:
            return getattr(application.state, "settings", None) or current_settings

        wrapped = attach_memory_injection(
            client,
            memory_store,
            usage_store,
            enabled=bool(getattr(_settings_now(), "memory_enabled", True)),
            weak_points_fn=_weak_nodes_for,
        )
        return attach_usage_tracking(
            wrapped,
            usage_store,
            lambda: int(getattr(_settings_now(), "usage_daily_quota", 0) or 0),
            enabled=bool(getattr(_settings_now(), "usage_tracking_enabled", True)),
        )

    # 项目路径：/chat、/chat/stream、/agent、/solve、/solve-image 全部在
    # /api/projects/{project_id}/ 下 —— 两层记忆的「项目级」槽位就靠它定位。
    _RE_PROJECT_PATH = re.compile(r"^/api/projects/([^/]+)(?:/|$)")

    def _request_project_id(request: Request) -> str:
        """从**路径**取当前项目。比读 body 便宜（零解析），也比读 body 覆盖更全。"""
        try:
            match = _RE_PROJECT_PATH.match(request.url.path or "")
        except Exception:
            return ""
        return match.group(1) if match else ""

    # 明显不是知识点的节点名：纯数字 / 纯符号 / 单个字。
    # 真机数据逼出来的：某个项目的主题就叫「1」，节点名也叫「1」，于是
    # 「1（0%）」作为「你反复栽过的一处」被**硬注入**进了 prompt。
    # 客观卡点这一半宁可少，也不能往提示词里塞这种东西。
    _RE_JUNK_NODE = re.compile(r"^[\W\d_]+$")

    def _weak_nodes_for(project_id: str) -> list[dict[str, Any]]:
        """掌握度最低的几个节点 —— 卡点槽的「客观」那一半。

        ⚠️ 必须排除 learning_status == "unexplored" 的节点：新节点的 mastery_score
        默认就是 0.0，不过滤的话**任何新建的项目都会把自己头几个节点算成「他反复
        栽过」**；而这句话是以「硬注入」写进 prompt 的，模型会当真 —— 那就是往
        提示词里塞假事实。宁可这一半为空。
        """
        if not project_id:
            return []
        try:
            nodes = db.list_framework_nodes(project_id) or []
        except Exception:
            return []
        scored: list[dict[str, Any]] = []
        for node in nodes:
            try:
                if str(getattr(node, "learning_status", "") or "") == "unexplored":
                    continue
                score = float(getattr(node, "mastery_score", 0.0) or 0.0)
                if score >= WEAK_MASTERY_THRESHOLD:
                    continue
                name = str(getattr(node, "name", "") or "").strip()
            except Exception:
                continue
            if len(name) < 2 or _RE_JUNK_NODE.match(name):
                continue
            scored.append({"name": name, "score": score})
        scored.sort(key=lambda item: item["score"])
        return scored

    # ⚠️ 这行必须放在 _weak_nodes_for **定义之后**。
    # _wrap_llm 是嵌套函数，它在被调用时才去闭包里取 _weak_nodes_for；
    # 如果这行还留在 _wrap_llm 的定义下面一点点（原来的位置），调用时
    # _weak_nodes_for 还没绑定 → NameError，整个 create_app() 起不来。
    # 已实测：报 "cannot access free variable '_weak_nodes_for'"。
    llm = _wrap_llm(llm)

    def _memory_block_now(owner_id: str) -> str:
        """惰性拼当前请求的记忆块（payload 型任务的注入点）。

        传闭包而不是拼好的文本给 contextvar：非白名单任务一次库都不会查。
        走 ``memory_block_for`` 这**唯一**入口 —— per-user 总开关（一键关闭记忆）
        只在它里面判断，这样两条注入路径关的是同一个开关。
        """
        if not owner_id:
            return ""
        try:
            return memory_block_for(
                memory_store(), owner_id, _request_project_id_current() or None
            )
        except Exception:
            # 记忆读不到绝不能影响正常回答
            return ""

    def _request_project_id_current() -> str:
        return active_project()

    @application.middleware("http")
    async def _bind_ai_owner(request: Request, call_next: Any) -> Any:
        """把「当前用户」放进 contextvar，供记账与记忆注入读取。

        为什么不用既有的 ``require_user``：它是在**端点内部**调用的，中间件里拿不到
        结果；而要给 130+ 个既有端点逐个加传参又违反"不改既有签名"的约定。
        这里只读 session、不 touch 用户 —— touch 会写库，不该在中间件里做副作用。
        """
        owner = ""
        try:
            session_id = request.cookies.get(SESSION_COOKIE_NAME, "")
            if session_id:
                user = db.get_user_by_session(session_id)
                if user is not None:
                    owner = user.user_id
        except Exception:
            owner = ""
        token = set_usage_owner(owner)
        # 教学模式档位同样按请求绑定：core/llm.py 的 _system_prompt 在**调用发生的
        # 同步时刻**读它，从而不必给几十个调用点逐个传参。读不到就回落默认档。
        mode_token = teaching_mode_mod.set_active_mode(teaching_mode_for(owner))
        # 「用户这一问」也绑一次：阶梯要靠问题类型（概念/求解/复核…）决定本轮动作，
        # 否则三档只能退化成一份通用模板。取不到就回落旧口径，行为不变。
        question_token = teaching_mode_mod.set_active_question(
            await _request_question(request)
        )
        # 长期记忆：当前项目 + 惰性 provider。
        # 项目必须绑 —— 两层记忆的「项目级」槽位（卡点/进度/未解问题）只能挂在
        # 当前项目上；绑不上时项目级整组为空，不猜、也不复用别的项目的记忆。
        project_token = set_active_project(_request_project_id(request))
        provider_token = set_memory_provider(lambda: _memory_block_now(owner))
        try:
            return await call_next(request)
        finally:
            reset_usage_owner(token)
            teaching_mode_mod.reset_active_mode(mode_token)
            teaching_mode_mod.reset_active_question(question_token)
            reset_active_project(project_token)
            reset_memory_provider(provider_token)

    @application.exception_handler(QuotaExceeded)
    async def quota_exceeded_handler(_: Request, exc: QuotaExceeded) -> JSONResponse:
        """当日用量超限 → 429 + 说人话的提示。

        统一在全局处理，而不是在模型调用点逐个判断：调用点有几十处，逐处处理既容易
        漏掉，也会把"限额"这件事泄漏进业务代码。
        """
        return JSONResponse(
            status_code=429,
            # 文案只有一处定义（QuotaExceeded.__str__）：SSE 端点拿不到这个 handler，
            # 它会直接把 str(exc) 塞进 error 事件给用户看，两处必须一致。
            content=error_payload(exc.code, str(exc)),
        )

    # 服务启动即后台预热北洋维基语料：缺/过期才重建，就绪则瞬返。
    # 用 on_event 而非 create_app 直接调用，避免裸 import（如 OCR 脚本）误触发建库。
    @application.on_event("startup")
    def _warmup_wiki_corpus() -> None:
        try:
            import wiki_corpus

            # 先把图片 OCR 实现注入进去再 ensure：北洋维基把校历/考试安排/专业分流表
            # 画在图上，正文只有一两句话。以前 build() 从来没拿到过 ocr_fn，
            # 所以 imgtext 一直是空的——图里的信息等于不存在。
            wiki_corpus.set_ocr_fn(_wiki_image_ocr)
            wiki_corpus.ensure(blocking=False)
        except Exception:
            pass
        # 官网矩阵索引（教务处/研招网/新闻网…）冷启动要 8s 左右，先起个后台线程建好，
        # 免得用户问的第一句话卡在"枚举列表页"上。
        try:
            from core import campus_sources as _campus_warm

            threading.Thread(target=_campus_warm.warmup, daemon=True).start()
        except Exception:
            pass
        # 公众号订阅库：过期才刷新（wechat_feed 内部按 FEED_TTL 判断），且延迟 45s 再动，
        # 别和上面那批列表页抢带宽。这是「校园速递」与海小棠"最近有什么"的数据来源：
        # 不刷新就永远是上次那份，消息越积越旧。
        try:
            from core import campus_sources as _campus_feed

            def _warm_feed() -> None:
                try:
                    _campus_feed.wechat_feed()
                except Exception:
                    pass

            threading.Timer(45.0, _warm_feed).start()
        except Exception:
            pass

    application.state.db = db
    application.state.research_profile_store = ResearchProfileStore(db.path)
    application.state.settings = current_settings
    application.state.llm = llm
    # 未包装的原始客户端也要挂在 state 上：周报 / 记忆提取走它（绕过记账代理），
    # 保存配置时同样要换成新的那一份，否则它们会继续用旧密钥。
    application.state.raw_llm = _raw_llm
    # 统一密钥：闭包里的 llm / _raw_llm 改成转发代理，每次用都取「当前」实例。
    # 这样「设置 → 模型」保存后**全部**端点立即跟随（含文献精读那批原先读不到
    # 新配置的端点），不必重启，也不会再出现「一半功能 401、一半正常」。
    # 注意顺序：state.llm 存的仍是**被包装的真实客户端**，代理只存在于闭包里。
    llm = _HotSwapLlm(lambda: getattr(application.state, "llm", None))
    _raw_llm = _HotSwapLlm(
        lambda: getattr(application.state, "raw_llm", None)
        or getattr(application.state, "llm", None)
    )
    application.state.source_files_dir = current_settings.data_dir / "source_files"
    application.state.source_previews_dir = (
        current_settings.data_dir / "source_previews"
    )
    application.state.undo_trash_dir = current_settings.data_dir / "undo_trash"
    application.state.source_files_dir.mkdir(parents=True, exist_ok=True)
    application.state.source_previews_dir.mkdir(parents=True, exist_ok=True)
    application.state.undo_trash_dir.mkdir(parents=True, exist_ok=True)
    # 清理上次异常退出遗留的回收站目录（对应的撤销记录已不存在）
    _valid_undo_ids = db.list_undo_ids()
    for _orphan in application.state.undo_trash_dir.iterdir():
        if _orphan.is_dir() and (
            not _orphan.name.isdigit() or int(_orphan.name) not in _valid_undo_ids
        ):
            shutil.rmtree(_orphan, ignore_errors=True)
    db.assert_writable()

    class NoCacheStaticFiles(StaticFiles):
        """/static 资源一律下发 no-cache，改完代码普通刷新（F5）即生效。

        裸 StaticFiles 只给 ETag / Last-Modified、不下发 Cache-Control，浏览器会按
        启发式规则缓存 JS/CSS，结果改了 app.js / styles.css 后必须 Ctrl+Shift+R
        才能看到效果。no-cache 的语义是「用前必须回源校验」：文件没变时 StaticFiles
        仍会返回 304（省流量），文件变了才返回 200 —— 兼顾即时生效与带宽。
        """

        def file_response(self, *args, **kwargs):
            response = super().file_response(*args, **kwargs)
            response.headers["Cache-Control"] = "no-cache, must-revalidate"
            return response

    application.mount(
        "/static", NoCacheStaticFiles(directory=str(STATIC_DIR)), name="static"
    )

    def current_user(request: Request) -> User | None:
        user = db.get_user_by_session(request.cookies.get(SESSION_COOKIE_NAME, ""))
        if user is not None:
            db.touch_user(user.user_id)
        return user

    def require_user(request: Request) -> User:
        user = current_user(request)
        if user is None:
            raise HTTPException(
                status_code=401,
                detail=error_payload("auth_required", "请先登录后继续使用知源。"),
            )
        return user

    def require_project_access(project_id: str, request: Request):
        user = require_user(request)
        return db.get_project(project_id, user.user_id)

    def attach_session_cookie(response: Response, request: Request, user: User) -> None:
        db.prune_expired_sessions()
        session_id = db.create_session(user.user_id, _session_expires_at())
        response.set_cookie(
            SESSION_COOKIE_NAME, session_id, **_session_cookie_options(request)
        )

    def clear_session_cookie(response: Response, request: Request) -> None:
        session_id = request.cookies.get(SESSION_COOKIE_NAME, "")
        db.delete_session(session_id)
        response.delete_cookie(SESSION_COOKIE_NAME, path="/")

    # 文献标注的类型白名单：前端 literature.js 里五组本地存储各对应一个 kind。
    # highlight     原页/文理高亮（slot 空）
    # ai_highlight  AI 解释与问答气泡内的划词高亮（slot = 该回答块的稳定 key）
    # keypoints     阅读重点的用户增删改（slot 空）
    # notes         划词笔记列表（slot 空）
    # note          右下角那篇阅读笔记的正文（slot 空）
    # ai_answer：AI 解释（划词解释 / 图表解释 / 公式解释 / 论文问答）的落库槽位。
    # 在此之前这些回答只活在浏览器内存里，刷新即失，既不能导出也没法回看 ——
    # 一条回答占一格（slot = 消息 id），导出时按 page 排回正文位置。
    _LITERATURE_MARK_KINDS = {
        "highlight", "ai_highlight", "keypoints", "notes", "note", "ai_answer",
    }

    def require_admin(request: Request) -> None:
        if _admin_authenticated(request, application.state.settings):
            return
        raise HTTPException(
            status_code=401,
            detail=error_payload("admin_required", "请先登录管理员后台。"),
        )

    def set_admin_cookie(response: Response, request: Request) -> None:
        options = _session_cookie_options(request)
        options["max_age"] = ADMIN_SESSION_TTL_SECONDS
        response.set_cookie(
            ADMIN_COOKIE_NAME,
            _admin_cookie_value(application.state.settings),
            **options,
        )

    def clear_admin_cookie(response: Response) -> None:
        response.delete_cookie(ADMIN_COOKIE_NAME, path="/")

    def record_undo(
        user: User,
        project_id: str | None,
        action: str,
        summary: str,
        payload: dict[str, Any],
    ) -> int | None:
        """记录一步可撤销操作；返回 undo_id（记录失败时返回 None，不影响主流程）。"""
        try:
            if len(json.dumps(payload, ensure_ascii=False)) > UNDO_PAYLOAD_MAX_BYTES:
                LOGGER.warning(
                    "undo payload too large, skip recording action=%s", action
                )
                return None
            undo_id, trimmed = db.record_undo(
                user.user_id, project_id, action, summary, payload
            )
            for stale_id in trimmed:
                shutil.rmtree(
                    application.state.undo_trash_dir / str(stale_id),
                    ignore_errors=True,
                )
            return undo_id
        except Exception:
            LOGGER.exception("failed to record undo entry action=%s", action)
            return None

    def record_message_append(
        user: User,
        project_id: str,
        before_ids: set[str],
        summary: str,
        conversation_id: str = "",
    ) -> None:
        """把"用户新增了几条消息"记进撤销栈并刷新该会话的最近活跃时间。"""
        new_ids = [
            message.message_id
            for message in db.list_messages(project_id, conversation_id=conversation_id)
            if message.message_id not in before_ids
        ]
        if new_ids:
            record_undo(
                user,
                project_id,
                "messages.append",
                summary,
                {"project_id": project_id, "message_ids": new_ids},
            )
        if conversation_id:
            db.touch_chat_session(project_id, conversation_id)

