    @application.exception_handler(sqlite3.OperationalError)
    async def sqlite_operational_error_handler(
        _: Request, exc: sqlite3.OperationalError
    ) -> JSONResponse:
        if _is_readonly_database_error(exc):
            return JSONResponse(
                status_code=503,
                content=error_payload(
                    "database_readonly",
                    "本地数据库无法写入。请确认 data 目录和 data/knoworigin.sqlite3 可写，然后重启本地服务。",
                    False,
                ),
            )
        return JSONResponse(
            status_code=500,
            content=error_payload(
                "database_error", "本地数据库操作失败，请查看服务日志。", True
            ),
        )

