    @application.post("/api/admin/login")
    async def admin_login(
        payload: AdminCredentials, request: Request, response: Response
    ) -> dict[str, Any]:
        if not application.state.settings.admin_password:
            raise HTTPException(
                status_code=503,
                detail=error_payload("admin_disabled", "管理员后台还没有配置密码。"),
            )
        if not hmac.compare_digest(
            payload.password, application.state.settings.admin_password
        ):
            raise HTTPException(
                status_code=401,
                detail=error_payload("invalid_admin_login", "管理员密码不正确。"),
            )
        set_admin_cookie(response, request)
        return {"authenticated": True}

    @application.post("/api/admin/logout")
    async def admin_logout(response: Response) -> dict[str, Any]:
        clear_admin_cookie(response)
        return {"authenticated": False}

