    @application.get("/api/auth/session")
    async def auth_session(request: Request) -> dict[str, Any]:
        user = current_user(request)
        return {
            "authenticated": user is not None,
            **(_user_payload(user) if user else {}),
        }

    @application.post("/api/auth/register", status_code=201)
    async def register(
        payload: AuthCredentials, request: Request, response: Response
    ) -> dict[str, Any]:
        email = _validate_email(payload.email)
        name = (payload.name or "").strip() or email.split("@", 1)[0]
        try:
            user = db.create_user(email, name, _password_hash(payload.password))
        except UserAlreadyExists as exc:
            db.record_login_event(
                "register",
                False,
                email,
                ip_address=_request_ip(request),
                user_agent=request.headers.get("user-agent", ""),
            )
            raise HTTPException(
                status_code=409,
                detail=error_payload("user_exists", "该邮箱已经注册，请直接登录。"),
            ) from exc
        attach_session_cookie(response, request, user)
        db.record_login_event(
            "register",
            True,
            email,
            user.user_id,
            _request_ip(request),
            request.headers.get("user-agent", ""),
        )
        return {"authenticated": True, **_user_payload(user)}

    @application.post("/api/auth/login")
    async def login(
        payload: AuthCredentials, request: Request, response: Response
    ) -> dict[str, Any]:
        email = _validate_email(payload.email)
        try:
            user, password_hash = db.get_user_by_email(email)
        except UserNotFound as exc:
            db.record_login_event(
                "login",
                False,
                email,
                ip_address=_request_ip(request),
                user_agent=request.headers.get("user-agent", ""),
            )
            raise HTTPException(
                status_code=401,
                detail=error_payload("invalid_login", "邮箱或密码不正确。"),
            ) from exc
        if not _verify_password(payload.password, password_hash):
            db.record_login_event(
                "login",
                False,
                email,
                user.user_id,
                _request_ip(request),
                request.headers.get("user-agent", ""),
            )
            raise HTTPException(
                status_code=401,
                detail=error_payload("invalid_login", "邮箱或密码不正确。"),
            )
        attach_session_cookie(response, request, user)
        db.record_login_event(
            "login",
            True,
            email,
            user.user_id,
            _request_ip(request),
            request.headers.get("user-agent", ""),
        )
        return {"authenticated": True, **_user_payload(user)}

    @application.post("/api/auth/logout")
    async def logout(request: Request, response: Response) -> dict[str, Any]:
        user = current_user(request)
        if user is not None:
            db.record_login_event(
                "logout",
                True,
                user.email,
                user.user_id,
                _request_ip(request),
                request.headers.get("user-agent", ""),
            )
        clear_session_cookie(response, request)
        return {"authenticated": False}

    @application.get("/api/config")
    async def get_api_config(request: Request) -> dict[str, Any]:
        current = application.state.settings
        return {
            "model_configured": bool(current.tju_api_key),
            "base_url": current.tju_base_url,
            "model": current.tju_model,
            # 视觉模型（扫描件 / 拍照讲义识别）。只回报密钥**是否已单独配置**，
            # 绝不把密钥本身回传给浏览器。
            "vision_model": current.tju_vision_model,
            "vision_base_url": current.tju_vision_base_url,
            "vision_key_configured": bool(current.tju_vision_api_key),
            "local_editable": _is_local_request(request),
        }

    @application.put("/api/config")
    async def update_api_config(
        payload: ApiSettingsUpdate, request: Request
    ) -> dict[str, Any]:
        if not _is_local_request(request):
            raise HTTPException(
                status_code=403,
                detail=error_payload(
                    "local_config_only", "API 配置只能在运行服务的本机修改。"
                ),
            )
        current = application.state.settings
        base_url = _validated_api_base_url(payload.base_url)
        model = payload.model.strip()
        if not re.fullmatch(r"[A-Za-z0-9._:/-]+", model):
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "invalid_model",
                    "模型名称只能包含字母、数字、点、下划线、冒号、斜杠或连字符。",
                ),
            )
        api_key = (
            current.tju_api_key if payload.api_key is None else payload.api_key.strip()
        )
        if payload.api_key is not None and api_key and len(api_key) < 8:
            raise HTTPException(
                status_code=422,
                detail=error_payload("invalid_api_key", "API 密钥至少需要 8 个字符。"),
            )
        # 视觉模型是可选覆盖：None = 保持现状；空串 = 显式关闭（模型）/ 回落（地址、密钥）。
        if payload.vision_model is None:
            vision_model = current.tju_vision_model
        else:
            vision_model = payload.vision_model.strip()
            if vision_model and not re.fullmatch(r"[A-Za-z0-9._:/-]+", vision_model):
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "invalid_vision_model",
                        "视觉模型名称只能包含字母、数字、点、下划线、冒号、斜杠或连字符。",
                    ),
                )
        if payload.vision_base_url is None:
            vision_base_url = current.tju_vision_base_url
        elif payload.vision_base_url.strip():
            vision_base_url = _validated_api_base_url(
                payload.vision_base_url, "视觉模型服务地址"
            )
        else:
            vision_base_url = ""
        if payload.vision_api_key is None:
            vision_api_key = current.tju_vision_api_key
        else:
            vision_api_key = payload.vision_api_key.strip()
            if vision_api_key and len(vision_api_key) < 8:
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "invalid_vision_api_key",
                        "视觉模型 API 密钥至少需要 8 个字符。",
                    ),
                )
        updated = Settings(
            tju_api_key=api_key,
            tju_base_url=base_url,
            tju_model=model,
            data_dir=current.data_dir,
            tju_proxy_url=current.tju_proxy_url,
            tju_timeout_seconds=current.tju_timeout_seconds,
            tju_json_mode=current.tju_json_mode,
            tju_vision_api_key=vision_api_key,
            tju_vision_base_url=vision_base_url,
            tju_vision_model=vision_model,
            session_secret=current.session_secret,
            admin_password=current.admin_password,
            # 新增功能的配置必须一并透传：这里的 Settings 是**显式字段列表**构造的，
            # 漏掉谁，谁就会在用户保存一次 API 配置后被静默打回默认值。
            usage_tracking_enabled=getattr(current, "usage_tracking_enabled", True),
            usage_daily_quota=getattr(current, "usage_daily_quota", 0),
            memory_enabled=getattr(current, "memory_enabled", True),
            notice_weekly_enabled=getattr(current, "notice_weekly_enabled", True),
        )
        save_local_api_config(updated)
        application.state.settings = updated
        # 重新包装：直接赋原生的 LlmClient 会让记账与记忆注入当场失效。
        # 同时重建一份**未包装**的原始客户端（周报 / 记忆提取走它）并刷新
        # state.raw_llm —— 闭包里的 llm / _raw_llm 是转发代理，两份都换掉
        # 它们才会跟着走，否则旧密钥会被一直用到重启。
        _fresh_client = LlmClient(updated, responder=application.state.llm.responder)
        application.state.raw_llm = _fresh_client
        application.state.llm = _wrap_llm(_fresh_client)
        return {
            "saved": True,
            "model_configured": bool(updated.tju_api_key),
            "base_url": updated.tju_base_url,
            "model": updated.tju_model,
            "vision_model": updated.tju_vision_model,
            "vision_base_url": updated.tju_vision_base_url,
            "vision_key_configured": bool(updated.tju_vision_api_key),
            "message": "API 配置已保存并立即生效；密钥已加密存入本机 data/ 凭据文件，重启服务后不用再填一次。",
        }

    @application.post("/api/config/session")
    async def push_session_api_config(
        payload: SessionApiConfig, request: Request
    ) -> dict[str, Any]:
        """浏览器把本地保管的密钥下发到本机服务内存（**不回写凭据文件**）。

        主存储已经是 data/local_api_config.json（加密落盘，PUT /api/config 写入），
        这个端点只是把它补进内存，让本次运行立刻可用。**不回写文件**是刻意的：
        每次刷新页面都会发一遍，为它白折腾磁盘没有意义；真要换密钥走
        PUT /api/config，那条路径才落盘。仅限本机请求 —— 远程访客不该往这台
        共享的服务端内存里塞凭据，那会让配置面板的 local_editable 限制形同虚设。
        """

        if not _is_local_request(request):
            raise HTTPException(
                status_code=403,
                detail=error_payload(
                    "local_config_only", "API 配置只能在运行服务的本机修改。"
                ),
            )
        current = application.state.settings
        api_key = current.tju_api_key
        vision_api_key = current.tju_vision_api_key
        if payload.api_key is not None:
            api_key = payload.api_key.strip()
            if api_key and len(api_key) < 8:
                raise HTTPException(
                    status_code=422,
                    detail=error_payload("invalid_api_key", "API 密钥至少需要 8 个字符。"),
                )
        if payload.vision_api_key is not None:
            vision_api_key = payload.vision_api_key.strip()
            if vision_api_key and len(vision_api_key) < 8:
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "invalid_vision_api_key",
                        "视觉模型 API 密钥至少需要 8 个字符。",
                    ),
                )
        if (
            api_key == current.tju_api_key
            and vision_api_key == current.tju_vision_api_key
        ):
            # 内存态已经一致（首屏加载 + 用户没换过密钥）：不重建客户端。
            # 每次刷新页面都重造 LlmClient 会把连接池和预热状态一起丢掉。
            return {
                "synced": False,
                "model_configured": bool(current.tju_api_key),
                "vision_key_configured": bool(current.tju_vision_api_key),
            }
        # 用 replace 而不是显式构造 Settings：后者的字段列表是手抄的，
        # 新增配置项漏一个就会在用户刷一次页面后被静默打回默认值。
        from dataclasses import replace as _dc_replace

        updated = _dc_replace(
            current, tju_api_key=api_key, tju_vision_api_key=vision_api_key
        )
        application.state.settings = updated
        _fresh_client = LlmClient(updated, responder=application.state.llm.responder)
        application.state.raw_llm = _fresh_client
        application.state.llm = _wrap_llm(_fresh_client)
        return {
            "synced": True,
            "model_configured": bool(updated.tju_api_key),
            "vision_key_configured": bool(updated.tju_vision_api_key),
        }

    @application.get("/api/projects")
    async def list_projects(request: Request) -> dict[str, Any]:
        user = require_user(request)
        return {
            "projects": [
                model_to_dict(project) for project in db.list_projects(user.user_id)
            ]
        }

    @application.post("/api/projects", status_code=201)
    async def create_project(
        payload: ProjectCreate, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        subject = payload.subject.strip()
        project = db.create_project(payload.year.strip(), subject, user.user_id)
        record_undo(
            user,
            project.project_id,
            "project.create",
            f"新建课程「{project.subject}」",
            {"project_id": project.project_id},
        )
        # 自动从天大课程库导入 README（如果课名精确匹配），让用户立刻有内容可用。
        # 任何异常（网络/无 README/解析失败）都静默；项目照常创建，导入是锦上添花。
        auto_imported: dict[str, Any] | None = None
        matched = next((entry for entry in TJU_COURSES if entry[1] == subject), None)
        if matched is not None:
            code, _, _ = matched
            try:
                import httpx
                from core.parsers import extract_source

                dir_name = f"{code}_{subject}"
                url = f"{TJU_SHARE_BASE_URL}/api/raw/?path=/{quote(dir_name, safe='/')}/README.md"
                async with httpx.AsyncClient(timeout=15) as client:
                    resp = await client.get(
                        url,
                        headers={"User-Agent": "knoworigin-local"},
                        follow_redirects=True,
                    )
                if resp.status_code == 200:
                    header = (
                        f"<!-- 导入自 cs.tjuse.com（{dir_name}）\n"
                        f"     许可：CC BY-NC-SA 4.0（署名 - 非商业性使用 - 相同方式共享）\n"
                        f"     本文件仅含课程 README 文本（选课攻略/学长经验），不含课件/试卷等资料。 -->\n\n"
                    )
                    final_text = header + resp.text
                    extracted = extract_source(
                        filename=f"{dir_name} README.md",
                        content=b"",
                        pasted_text=final_text,
                    )
                    saved = db.add_source(project.project_id, extracted)
                    auto_imported = {
                        "source_id": saved.source_id,
                        "filename": saved.filename,
                        "course_code": code,
                    }
                    record_undo(
                        user,
                        project.project_id,
                        "source.add",
                        f"自动导入天大课程库 {subject} 的 README",
                        {
                            "project_id": project.project_id,
                            "sources": [
                                db.get_source_row(project.project_id, saved.source_id)
                            ],
                        },
                    )
            except Exception:  # noqa: BLE001 - 导入失败是预期可恢复的，绝不影响项目创建
                LOGGER.warning(
                    "Auto TJU import failed for subject=%r code=%s",
                    subject,
                    code,
                    exc_info=True,
                )
        result = model_to_dict(project)
        if auto_imported is not None:
            result["auto_imported"] = auto_imported
        return result

    @application.get("/api/projects/{project_id}")
    async def get_project(project_id: str, request: Request) -> dict[str, Any]:
        project = require_project_access(project_id, request)
        # ⚠️ 会话清单必须 try/except 兜底：它在「打开项目」的关键路径上，
        # 抛错就表现为「项目加载不出来」。取不到就当没有会话，项目本体照常返回。
        try:
            chat_sessions: list[dict[str, Any]] = db.list_chat_sessions(project_id)
        except Exception:  # noqa: BLE001
            LOGGER.warning(
                "list_chat_sessions failed project=%s", project_id, exc_info=True
            )
            chat_sessions = []
        return {
            "project": model_to_dict(project),
            "chat_sessions": chat_sessions,
            "sources": [
                _source_payload(application, source)
                for source in db.list_sources(project_id)
            ],
            "nodes": [
                model_to_dict(node) for node in db.list_framework_nodes(project_id)
            ],
            # 双链「理解」：图谱随项目一次性取回，边上的关系说明不必再单独请求
            "link_notes": db.list_link_notes(project_id),
            "cards": [
                _card_payload(card)
                for card in db.list_cards(project_id)
                if not _is_historical_placeholder_card(card)
            ],
            "quiz": db.get_latest_quiz(project_id),
            "favorites": [
                model_to_dict(item) for item in db.list_favorites(project_id)
            ],
            "messages": [
                _message_payload(message)
                for message in db.list_messages(project_id, conversation_id="")
            ],
        }

    @application.delete("/api/projects/{project_id}")
    async def delete_project(project_id: str, request: Request) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        bundle = db.snapshot_project_bundle(project_id)
        undo_id = record_undo(
            user,
            project_id,
            "project.delete",
            f"删除课程「{bundle['project']['subject']}」",
            {"bundle": bundle},
        )
        db.delete_project(project_id)
        if undo_id is not None:
            # 文件移入回收站而非直接删除，撤销时可完整还原
            await asyncio.gather(
                asyncio.to_thread(
                    _move_to_trash,
                    application,
                    undo_id,
                    "source_files_dir",
                    project_id,
                ),
                asyncio.to_thread(
                    _move_to_trash,
                    application,
                    undo_id,
                    "source_previews_dir",
                    project_id,
                ),
            )
        else:
            await asyncio.gather(
                asyncio.to_thread(
                    _remove_project_directory,
                    application.state.source_files_dir,
                    project_id,
                ),
                asyncio.to_thread(
                    _remove_project_directory,
                    application.state.source_previews_dir,
                    project_id,
                ),
            )
        return {"deleted": True, "project_id": project_id}

    @application.delete("/api/projects/{project_id}/messages")
    async def delete_messages(
        project_id: str, payload: MessageDeleteRequest, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        rows = db.list_message_rows(project_id, payload.message_ids)
        deleted_ids = db.delete_messages(project_id, payload.message_ids)
        kept = [row for row in rows if row["message_id"] in set(deleted_ids)]
        if kept:
            record_undo(
                user,
                project_id,
                "messages.delete",
                f"删除 {len(kept)} 条对话记录",
                {"messages": kept},
            )
        return {"deleted": True, "message_ids": deleted_ids}

    # =====================================================================
    # 主界面问答会话（Agent 布局：每个项目多条会话）
    # 消息本体仍在 messages 表里，这里只管理「会话壳」。空串会话（老数据的项目默认
    # 单线程）不登记壳，也不在这组端点里出现。
    # ⚠️ 别和 /agent/sessions（整理助手，走 kb_conversations、conv_ 前缀）搞混：
    # 那套与本组并存但互不干扰，list_chat_sessions 靠 substr(...) <> 'conv_' 排除它。
    # =====================================================================

