    @application.delete("/api/projects/{project_id}/chat/sessions/{session_id}")
    async def delete_chat_session(
        project_id: str, session_id: str, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        if db.get_chat_session(project_id, session_id) is None:
            raise HTTPException(
                status_code=404,
                detail=error_payload("chat_session_not_found", "会话不存在。"),
            )
        # 先取回原始行（含 content / node_ids 等）再删：撤销栈要靠它回滚，
        # 删完就只剩 message_id 了。
        session_rows = db.list_message_rows(
            project_id,
            [
                message.message_id
                for message in db.list_messages(
                    project_id, conversation_id=session_id
                )
            ],
        )
        deleted_ids = db.delete_chat_session(project_id, session_id)
        # 刚建好还没说过话的会话删掉是 0 条消息，这是合法场景，不是「不存在」——
        # 存在性已经在上面的 get_chat_session 判过了。
        kept = [
            row for row in session_rows if row["message_id"] in set(deleted_ids)
        ]
        if kept:
            record_undo(
                user,
                project_id,
                "messages.delete",
                f"删除会话（{len(kept)} 条对话记录）",
                {"messages": kept, "session_id": session_id},
            )
        return {
            "deleted": True,
            "message_ids": deleted_ids,
            "sessions": db.list_chat_sessions(project_id),
        }

    @application.post("/api/projects/{project_id}/sources")
    async def upload_sources(
        project_id: str,
        request: Request,
        files: list[UploadFile] = File(default=[]),
        pasted_text: str | None = Form(default=None),
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        if not files and pasted_text is None:
            raise HTTPException(
                status_code=422,
                detail=error_payload("missing_source", "请选择文件或粘贴文本。"),
            )

        # 初始化进度追踪
        total = max(len(files), 1)
        _source_upload_progress[project_id] = {
            "total": total,
            "completed": 0,
            "current_file": "",
            "stage": "uploading",
            "stage_label": "正在上传文件",
            "status": "active",
            "ocr_total": 0,
            "ocr_done": 0,
            "ocr_used": False,
        }
        lock = asyncio.Lock()

        # 阶段 1：读出全部上传字节（内存驻留，后续阶段不再占用上传流）
        file_blobs: list[tuple[str, bytes]] = []
        for upload in files:
            content = await upload.read()
            file_blobs.append((upload.filename or "unnamed", content))

        # 预判扫描件：图片必走 OCR，PDF 按全文文字层判断（与实际提取规则一致）
        scanned_flags = list(
            await asyncio.gather(
                *(
                    asyncio.to_thread(_file_needs_ocr, fname, content)
                    for fname, content in file_blobs
                )
            )
        )
        ocr_total = sum(1 for flag in scanned_flags if flag)
        _source_upload_progress[project_id]["ocr_total"] = ocr_total
        _source_upload_progress[project_id]["ocr_done"] = 0

        # 阶段 2：并发解析（PDF 重 CPU/子进程限 2 并发，其余格式限 4 并发）
        pdf_sem = asyncio.Semaphore(2)
        other_sem = asyncio.Semaphore(4)

        async def parse_upload(fname: str, content: bytes, is_scanned: bool) -> Any:
            sem = pdf_sem if fname.lower().endswith(".pdf") else other_sem
            async with sem:
                async with lock:
                    _source_upload_progress[project_id]["current_file"] = fname
                    _source_upload_progress[project_id]["ocr_used"] = is_scanned
                    _source_upload_progress[project_id]["stage"] = "extracting"
                    _source_upload_progress[project_id]["stage_label"] = (
                        "正在识别扫描件（OCR）" if is_scanned else "正在解析文档内容"
                    )
                return await _extract_uploaded_source(application, fname, content)

        parsed = await asyncio.gather(
            *(
                parse_upload(fname, content, is_scanned)
                for (fname, content), is_scanned in zip(file_blobs, scanned_flags)
            ),
            return_exceptions=True,
        )

        # 阶段 3：串行入库（SQLite 需串行写），保持与上传顺序一致的结果列表
        results: list[dict[str, Any]] = []
        saved_rows: list[dict[str, Any]] = []
        async with lock:
            _source_upload_progress[project_id]["stage"] = "saving"
            _source_upload_progress[project_id]["stage_label"] = "正在保存文件"
        for idx, ((fname, content), extracted) in enumerate(zip(file_blobs, parsed)):
            if isinstance(extracted, Exception):
                LOGGER.warning("parse failed for %s: %s", fname, extracted)
                results.append(
                    {
                        "source_id": None,
                        "filename": fname,
                        "status": "parse_error",
                        "error_message": f"解析异常：{type(extracted).__name__}",
                    }
                )
                continue
            if extracted.status == "unsupported":
                results.append({"source_id": None, **model_to_dict(extracted)})
                continue
            saved = await asyncio.to_thread(db.add_source, project_id, extracted)
            await _persist_source_file(application, saved, content)
            saved_rows.append(
                await asyncio.to_thread(db.get_source_row, project_id, saved.source_id)
            )
            results.append(_source_payload(application, saved))
            async with lock:
                _source_upload_progress[project_id]["completed"] = idx + 1
                _source_upload_progress[project_id]["current_file"] = fname
                if scanned_flags[idx]:
                    _source_upload_progress[project_id]["ocr_done"] += 1

        if pasted_text is not None:
            async with lock:
                _source_upload_progress[project_id]["current_file"] = "粘贴文本"
                _source_upload_progress[project_id]["stage"] = "extracting"
                _source_upload_progress[project_id]["stage_label"] = "正在解析文本"
            extracted = extract_source("粘贴文本.txt", b"", pasted_text=pasted_text)
            saved = db.add_source(project_id, extracted)
            saved_rows.append(db.get_source_row(project_id, saved.source_id))
            results.append(_source_payload(application, saved))

        if saved_rows:
            names = "、".join(row["filename"] for row in saved_rows[:3])
            record_undo(
                user,
                project_id,
                "source.add",
                f"导入 {len(saved_rows)} 份资料（{names}）",
                {"project_id": project_id, "sources": saved_rows},
            )

        async with lock:
            _source_upload_progress[project_id]["completed"] = total
            _source_upload_progress[project_id]["status"] = "complete"
            _source_upload_progress[project_id]["stage"] = "done"
            _source_upload_progress[project_id]["stage_label"] = "导入完成"

        return {"sources": results}

    # —— 把文献阅读结论并入课程知识网（来源视图缺的那条边）——
    # 背景：文献项目与课程项目在 projects 表里靠 project_type 分流，而 node.source_ids
    # 只可能指向同一个 project 内的 source。于是「多文献对比」在主界面来源视图里
    # 永远没有落点，点「在来源视图中查看」只能跳回一个与对比无关的视图。
    # 这里补上那条边：把对比报告落成课程下的一条影子来源，再把它的 source_id
    # 并集追加到它真正讨论到的节点上（只增不删，不动掌握度与既有来源）。
    _attach_title_max = 80
    _attach_report_budget = 20000
    _attach_node_budget = 120

    @application.post(
        "/api/projects/{project_id}/sources/attach-literature", status_code=201
    )
    def attach_literature_sources(
        project_id: str, payload: AttachLiteratureRequest, request: Request
    ) -> dict[str, Any]:
        project = require_project_access(project_id, request)
        user = require_user(request)
        if project.project_type != "course":
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "not_course_project", "只能把文献结论并入课程项目的知识网。"
                ),
            )
        report = (payload.report or "").strip()
        if not report:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "empty_report", "对比报告为空，没有可并入的内容。"
                ),
            )

        titles: list[str] = []
        for literature_id in payload.literature_project_ids:
            try:
                paper = db.get_project(literature_id, user.user_id)
            except ProjectNotFound:
                continue
            if paper.project_type != "literature":
                continue
            meta = db.get_literature_meta(literature_id)
            titles.append(str(meta.get("title") or paper.subject or "").strip())

        label = " / ".join(title for title in titles if title) or "文献"
        filename = f"多文献对比：{label}"
        if len(filename) > _attach_title_max:
            filename = filename[: _attach_title_max - 1] + "…"

        source = db.add_source(
            project_id,
            ExtractedSource(
                filename=filename,
                mime_type="text/markdown",
                size_bytes=len(report.encode("utf-8")),
                text=report,
                status="ok",
            ),
        )

        nodes = db.list_framework_nodes(project_id)
        matched: list[dict[str, str]] = []
        nodes_updated: list[str] = []
        note = ""
        if not nodes:
            note = "这门课还没有知识框架，已先把报告存为资料；生成框架后它会一起参与。"
        elif (
            not application.state.settings.tju_api_key
            and application.state.llm.responder is None
        ):
            note = "未配置模型，已先把报告存为资料；配置模型后可重新并入以对齐概念。"
        else:
            by_id = {node.node_id: node for node in nodes}
            try:
                result = application.state.llm.complete_json(
                    "attach_literature",
                    {
                        "nodes": [
                            {
                                "node_id": node.node_id,
                                "name": node.name,
                                "description": node.description,
                            }
                            for node in nodes[:_attach_node_budget]
                        ],
                        "report": report[:_attach_report_budget],
                    },
                )
            except Exception:
                LOGGER.exception(
                    "attach_literature alignment failed project_id=%s", project_id
                )
                result = {}
                note = "概念对齐失败，已先把报告存为资料；可重试并入。"

            raw = result.get("matches") if isinstance(result, dict) else None
            additions: dict[str, list[str]] = {}
            for item in raw if isinstance(raw, list) else []:
                if not isinstance(item, dict):
                    continue
                node_id = str(item.get("node_id") or "").strip()
                # 只认框架里真实存在的 node_id，模型编出来的 id 一律丢弃
                if not node_id or node_id not in by_id or node_id in additions:
                    continue
                additions[node_id] = [source.source_id]
                matched.append(
                    {
                        "node_id": node_id,
                        "name": by_id[node_id].name,
                        "evidence": str(item.get("evidence") or "").strip()[:120],
                    }
                )
            nodes_updated = sorted(
                db.merge_node_source_ids(project_id, additions).keys()
            )
            if not nodes_updated and not note:
                note = (
                    "这份报告没有讲到你课程框架里的已有概念，暂时只作为一份资料存着。"
                )

        record_undo(
            user,
            project_id,
            "source.add",
            f"并入多文献对比（{filename}）",
            {
                "project_id": project_id,
                "sources": [db.get_source_row(project_id, source.source_id)],
            },
        )

        return {
            "source": _source_payload(application, source),
            "matched": matched,
            "nodes_updated": nodes_updated,
            "note": note,
        }

    # —— 多文献对比 → 独立的「对比阅读项目」——
    # 为什么单独建项目，而不是并进当前课程：一次对比的成果是「N 篇文献 + 一份对比报告」，
    # 并进已有课程会被淹没在课程资料里；独立成项后它有自己的知识框架与来源视图，
    # 走 db.list_projects 里正常的 course 项目路径，侧栏可见、可长期使用。
    # 幂等：同一组文献只建一个项目（指纹写在 tags 里），重复对比是复用而非越建越多。
    _compare_group_prefix = "对比组:"
    _compare_subject_prefix = "多文献对比："
    _compare_report_filename = "多文献对比报告.md"
    _compare_subject_max = 60

    def _build_compare_framework(project: Any) -> tuple[list[Any], bool]:
        """给对比项目建知识框架：与 framework/build 走同一条路，模型输出不合格退启发式。"""
        usable = [
            source
            for source in db.list_sources(project.project_id)
            if source.status == "ok" and (source.text or "").strip()
        ]
        if not usable:
            return [], False
        use_fallback = (
            not application.state.settings.tju_api_key
            and application.state.llm.responder is None
        )
        try:
            return (
                build_framework(
                    project.project_id,
                    usable,
                    database=db,
                    llm_client=None if use_fallback else application.state.llm,
                    root_name=project.subject,
                    replace_existing=True,
                ),
                use_fallback,
            )
        except ModelOutputError as exc:
            LOGGER.warning(
                "Compare framework fell back to heuristic. project_id=%s error=%s",
                project.project_id,
                exc,
            )
            return (
                build_framework(
                    project.project_id,
                    usable,
                    database=db,
                    root_name=project.subject,
                    replace_existing=True,
                ),
                True,
            )

    @application.post("/api/literature/compare/project", status_code=201)
    async def create_compare_project(
        payload: AttachLiteratureRequest, request: Request
    ) -> dict[str, Any]:
        from core.database import utc_now

        user = require_user(request)
        report = (payload.report or "").strip()
        if not report:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "empty_report", "对比报告为空，没有可建项目的成果。"
                ),
            )

        papers = []
        for literature_id in payload.literature_project_ids:
            try:
                paper = db.get_project(literature_id, user.user_id)
            except ProjectNotFound:
                continue
            if paper.project_type == "literature":
                papers.append(paper)
        if len(papers) < 2:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "not_enough_papers", "至少要有两篇文献才能建立对比项目。"
                ),
            )

        paper_ids = {paper.project_id for paper in papers}
        titles: list[str] = []
        for paper in papers:
            meta = db.get_literature_meta(paper.project_id)
            titles.append(
                str(meta.get("title") or paper.subject or "").strip() or "未命名论文"
            )
        signature = _compare_group_prefix + ",".join(sorted(paper_ids))

        # 同一组文献 → 复用已有项目。文献没变就不重跑框架（省一次模型调用），
        # 只把报告正文换成最新的一份；框架缺失（上次失败/被清空）时才补建。
        existing = None
        for project in db.list_projects(user.user_id):
            if project.project_id in paper_ids:
                continue
            if signature in (project.tags or []):
                existing = project
                break

        if existing is not None:
            report_source = next(
                (
                    source
                    for source in db.list_sources(existing.project_id)
                    if (source.filename or "").startswith(
                        _compare_report_filename.rsplit(".", 1)[0]
                    )
                ),
                None,
            )
            if report_source is None:
                db.add_source(
                    existing.project_id,
                    ExtractedSource(
                        filename=_compare_report_filename,
                        mime_type="text/markdown",
                        size_bytes=len(report.encode("utf-8")),
                        text=report,
                        status="ok",
                    ),
                )
            elif (report_source.text or "").strip() != report:
                db.update_source_extraction(
                    existing.project_id,
                    report_source.source_id,
                    ExtractedSource(
                        filename=report_source.filename,
                        mime_type=report_source.mime_type,
                        size_bytes=len(report.encode("utf-8")),
                        text=report,
                        formulas=report_source.formulas,
                        figures=report_source.figures,
                        status="ok",
                    ),
                )
            nodes = db.list_framework_nodes(existing.project_id)
            if nodes:
                note = "复用了同一组文献已有的对比项目，知识框架未重建（文献没变）"
            else:
                nodes, _ = _build_compare_framework(existing)
                note = (
                    "复用了已有的对比项目，并补建了知识框架"
                    if nodes
                    else "复用了已有的对比项目，但知识框架仍未建成"
                )
            return {
                "project": model_to_dict(existing),
                "reused": True,
                "imported_papers": titles,
                "source_count": len(db.list_sources(existing.project_id)),
                "nodes_count": len(nodes),
                "note": note,
            }

        subject = _compare_subject_prefix + " / ".join(titles)
        if len(subject) > _compare_subject_max:
            subject = subject[: _compare_subject_max - 1] + "…"
        project = db.create_project(str(utc_now().year), subject, user.user_id)
        db.set_project_tags(project.project_id, ["对比阅读", signature])
        record_undo(
            user,
            project.project_id,
            "project.create",
            f"新建对比项目「{subject}」",
            {"project_id": project.project_id},
        )

        report_source = db.add_source(
            project.project_id,
            ExtractedSource(
                filename=_compare_report_filename,
                mime_type="text/markdown",
                size_bytes=len(report.encode("utf-8")),
                text=report,
                status="ok",
            ),
        )

        imported: list[dict[str, str]] = []
        for paper, title in zip(papers, titles):
            source = next(
                (
                    item
                    for item in db.list_sources(paper.project_id)
                    if item.status == "ok" and (item.text or "").strip()
                ),
                None,
            )
            if source is None:
                continue
            # 只带正文与公式，不复制 figures 里的 base64 图片：一份文献的图可能有十几 MB，
            # 而原始 PDF 会一起带过去，「打开资料」照样能看图，没必要在库里存两份。
            copied = db.add_source(
                project.project_id,
                ExtractedSource(
                    filename=source.filename,
                    mime_type=source.mime_type,
                    size_bytes=source.size_bytes,
                    text=source.text,
                    formulas=source.formulas,
                    figures=[],
                    status="ok",
                ),
            )
            old_path = _source_file_path(application, source)
            if old_path.is_file():
                try:
                    new_path = _source_file_path(application, copied)
                    new_path.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(old_path, new_path)
                except OSError:
                    LOGGER.warning(
                        "Copy paper file into compare project failed: %s", old_path
                    )
            imported.append(
                {
                    "title": title,
                    "filename": source.filename,
                    "source_id": copied.source_id,
                }
            )

        nodes, use_fallback = _build_compare_framework(project)
        return {
            "project": model_to_dict(project),
            "reused": False,
            "imported_papers": titles,
            "imported": imported,
            "report_source_id": report_source.source_id,
            "source_count": len(db.list_sources(project.project_id)),
            "nodes_count": len(nodes),
            "framework_fallback": use_fallback,
            "note": (
                f"已建立对比项目并导入 {len(imported)} 篇文献"
                + (f"，生成 {len(nodes)} 个知识概念" if nodes else "，知识框架未能生成")
            ),
        }

    # —— 文献组合 → 来源视图（不需要对比报告）——
    # 与「对比项目」共用同一套组合指纹（tags 里的 「对比组:<id,id>」），因此同一组文献
    # 无论先建立来源视图还是先做对比，都只会有一个项目，互为复用、不会越建越多。
    # 与对比项目的唯一差别：没有对比报告，不落「多文献对比报告.md」这条来源，
    # 资料列里就只剩各篇文献本身 —— 这正是来源视图要看的「资料 ⇄ 概念」关系。
    @application.post("/api/literature/source-view/project", status_code=201)
    async def create_source_view_project(
        payload: CompareRequest, request: Request, refresh: bool = False
    ) -> dict[str, Any]:
        from core.database import utc_now

        user = require_user(request)
        papers = []
        for literature_id in payload.project_ids:
            try:
                paper = db.get_project(literature_id, user.user_id)
            except ProjectNotFound:
                continue
            if paper.project_type == "literature":
                papers.append(paper)
        if len(papers) < 2:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "not_enough_papers", "至少要有两篇文献才能生成来源视图。"
                ),
            )

        paper_ids = {paper.project_id for paper in papers}
        titles: list[str] = []
        for paper in papers:
            meta = db.get_literature_meta(paper.project_id)
            titles.append(
                str(meta.get("title") or paper.subject or "").strip() or "未命名论文"
            )
        signature = _compare_group_prefix + ",".join(sorted(paper_ids))

        # 同一组文献已有项目 → 直接复用：框架缺失（上次失败 / 被清空 / 还没建）才补建，
        # 框架在就不重跑模型，重复点「生成来源视图」不该反复花钱。
        existing = None
        for project in db.list_projects(user.user_id):
            if project.project_id in paper_ids:
                continue
            if signature in (project.tags or []):
                existing = project
                break

        if existing is not None:
            nodes = db.list_framework_nodes(existing.project_id)
            # refresh=1 是卡片上的「重新生成」：对上次结果不满意时强制重跑一次，
            # 否则只有「框架缺失」才补建，用户没有第二次机会。
            if refresh or not nodes:
                nodes, _ = _build_compare_framework(existing)
            return {
                "project": model_to_dict(existing),
                "reused": True,
                "titles": titles,
                "source_count": len(db.list_sources(existing.project_id)),
                "nodes_count": len(nodes),
                "note": (
                    "复用了同一组文献已有的项目，直接读它的知识框架。"
                    if nodes
                    else "复用了同一组文献已有的项目，但知识框架仍未建成。"
                ),
            }

        subject = _compare_subject_prefix + " / ".join(titles)
        if len(subject) > _compare_subject_max:
            subject = subject[: _compare_subject_max - 1] + "…"
        project = db.create_project(str(utc_now().year), subject, user.user_id)
        db.set_project_tags(project.project_id, ["对比阅读", signature])
        record_undo(
            user,
            project.project_id,
            "project.create",
            f"新建来源视图项目「{subject}」",
            {"project_id": project.project_id},
        )

        imported: list[dict[str, str]] = []
        for paper, title in zip(papers, titles):
            source = next(
                (
                    item
                    for item in db.list_sources(paper.project_id)
                    if item.status == "ok" and (item.text or "").strip()
                ),
                None,
            )
            if source is None:
                continue
            # 与对比项目同口径：只带正文与公式，不复制 figures 里的 base64 图片，
            # 一份文献的图可能有十几 MB，原 PDF 会一起带过来，没必要在库里存两份。
            copied = db.add_source(
                project.project_id,
                ExtractedSource(
                    filename=source.filename,
                    mime_type=source.mime_type,
                    size_bytes=source.size_bytes,
                    text=source.text,
                    formulas=source.formulas,
                    figures=[],
                    status="ok",
                ),
            )
            old_path = _source_file_path(application, source)
            if old_path.is_file():
                try:
                    new_path = _source_file_path(application, copied)
                    new_path.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(old_path, new_path)
                except OSError:
                    LOGGER.warning(
                        "Copy paper file into source-view project failed: %s", old_path
                    )
            imported.append(
                {
                    "title": title,
                    "filename": source.filename,
                    "source_id": copied.source_id,
                }
            )

        nodes, use_fallback = _build_compare_framework(project)
        return {
            "project": model_to_dict(project),
            "reused": False,
            "titles": titles,
            "imported": imported,
            "source_count": len(db.list_sources(project.project_id)),
            "nodes_count": len(nodes),
            "framework_fallback": use_fallback,
            "note": (
                f"已导入 {len(imported)} 篇文献"
                + (
                    f"，生成 {len(nodes)} 个知识概念"
                    if nodes
                    else "，知识概念未能生成（多为未配置模型，可稍后重试）"
                )
            ),
        }

    # 单文件上传进度追踪
    _source_upload_progress: dict[str, dict[str, Any]] = {}

    @application.get("/api/projects/{project_id}/sources/upload-progress")
    async def get_upload_progress(project_id: str, request: Request) -> dict[str, Any]:
        """轮询单文件上传的实时进度。"""
        require_user(request)
        require_project_access(project_id, request)
        progress = _source_upload_progress.get(project_id)
        if progress is None:
            return {
                "total": 0,
                "completed": 0,
                "current_file": "",
                "stage": "",
                "stage_label": "",
                "status": "idle",
            }
        return progress

    # ---- 文献精读（Literature）----

    _LITERATURE_EXTRACT_BUDGET = 16000
    _TRANSLATE_CHUNK_CHARS = 1800

    def _literature_texts(project_id: str) -> str:
        return "\n\n".join(
            source.text
            for source in db.list_sources(project_id)
            if source.text and source.text.strip()
        )

    def _comparison_cache_key(owner_id: str, project_ids: list[str]) -> str:
        """同一组论文（与勾选顺序无关）共用一个缓存槽位。"""
        joined = "|".join(sorted(project_ids))
        return hashlib.sha1(f"{owner_id}|{joined}".encode("utf-8")).hexdigest()

    def _literature_extract(project_id: str, text: str | None = None) -> dict[str, Any]:
        text = (text or _literature_texts(project_id)).strip()
        if not text:
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_source", "论文正文为空，无法抽取元数据。"),
            )
        result = llm.complete_json(
            "extract_paper_metadata",
            {
                "title": db.get_project(project_id).subject,
                "text": text[:_LITERATURE_EXTRACT_BUDGET],
            },
        )

        def _str(key: str) -> str:
            value = result.get(key)
            return value if isinstance(value, str) else ""

        def _list(key: str) -> list[Any]:
            value = result.get(key)
            return value if isinstance(value, list) else []

        def _headings(key: str) -> list[dict[str, Any]]:
            """规范化模型给的 section_headings（目录只当兜底用）。

            两件事必须做：
            ①**丢掉 page** —— payload 里根本没有页码，模型给的页码必然是编造的
              （实测某文献 34 条 title 的 page 全是 '3'）。页码只能由解析器提供，
              这里留着假的比没有更糟。
            ②用与解析器**同一套**正文反例判据过滤：模型常把正文句当标题
              （「所以」「4.2」「Blackbody：能吸收辐射到其」），
              两边用同一判据才不会出现「解析器修好了、LLM 那份还在」。
            """
            from core.parsers import _heading_cue_strength, _looks_like_prose_line

            value = result.get(key)
            if not isinstance(value, list):
                return []
            out: list[dict[str, Any]] = []
            seen: set[str] = set()
            for item in value:
                if isinstance(item, str):
                    heading, level = item.strip(), 2
                elif isinstance(item, dict):
                    heading = str(
                        item.get("heading") or item.get("title") or ""
                    ).strip()
                    try:
                        level = int(item.get("level") or 2)
                    except (TypeError, ValueError):
                        level = 2
                else:
                    continue
                if not heading:
                    continue
                if _heading_cue_strength(heading) <= 1 and (
                    len(heading) <= 3 or _looks_like_prose_line(heading)
                ):
                    continue
                norm = heading.lower()
                if norm in seen:
                    continue
                seen.add(norm)
                out.append({"heading": heading, "level": max(1, min(6, level))})
            return out

        meta = {
            "title": _str("title"),
            "authors": _str("authors"),
            "year": _str("year"),
            "venue": _str("venue"),
            "doi": _str("doi"),
            "arxiv_id": _str("arxiv_id"),
            "language": _str("language"),
            "keywords": _list("keywords"),
            "abstract": _str("abstract"),
            "section_headings": _headings("section_headings"),
            "references_count": _str("references_count"),
            "extract_status": "done",
        }
        db.upsert_literature_meta(project_id, meta)
        abstract = meta["abstract"].strip()
        if abstract:
            try:
                translated = llm.complete_json("translate_section", {"text": abstract})
                db.upsert_literature_meta(
                    project_id,
                    {"abstract_translated": str(translated.get("answer") or "")},
                )
            except Exception:  # noqa: BLE001 - 摘要翻译失败不阻断抽取主流程
                LOGGER.warning(
                    "abstract translate failed project=%s", project_id, exc_info=True
                )
        return db.get_literature_meta(project_id)

    def _translation_chunks(text: str) -> list[str]:
        text = text.strip()
        if not text:
            return []
        return [
            text[i : i + _TRANSLATE_CHUNK_CHARS]
            for i in range(0, len(text), _TRANSLATE_CHUNK_CHARS)
        ]

    _REARRANGE_CHUNK_CHARS = 4000
    # 后台 AI 整理排版的看门狗阈值：超过后对外返回 done，避免前端长时间卡在"AI 整理排版中"；
    # 后台任务继续跑完仍会照常落库。
    REARRANGE_WATCHDOG_SEC = 300

    def _rearrange_chunks(text: str) -> list[str]:
        """按自然段边界切分，避免切断 [[MATH:*]]/[[FIG:*]]/[[H:*]] 标记。"""
        text = text.strip()
        if not text:
            return []
        paragraphs = [p for p in re.split(r"\n{2,}", text) if p.strip()]
        chunks: list[str] = []
        current = ""
        for para in paragraphs:
            if current and len(current) + len(para) + 2 > _REARRANGE_CHUNK_CHARS:
                chunks.append(current)
                current = para
            else:
                current = f"{current}\n\n{para}" if current else para
        if current:
            chunks.append(current)
        return chunks

    def _formula_roster_for_chunk(
        chunk: str, formulas: list[dict[str, Any]] | None
    ) -> list[dict[str, Any]]:
        """提取出现在该块内的公式花名册（id + 印刷编号），供 LLM 把 [[MATH:id]] 归位到对应上下文。"""
        if not formulas:
            return []
        in_chunk = set(re.findall(r"\[\[MATH:([^\]]+)\]\]", chunk))
        if not in_chunk:
            return []
        roster = []
        for f in formulas:
            fid = str(f.get("id") or "")
            if fid in in_chunk:
                roster.append({"id": fid, "number": f.get("number") or None})
        return roster

    def _repair_formulas_latex(
        formulas: list[dict[str, Any]], llm: Any
    ) -> list[dict[str, Any]]:
        """把每条公式记录的 OCR/文本层原始碎片交给 LLM 重组成干净、完整、可被 KaTeX 渲染的 LaTeX。

        - 只覆盖有可修复原始文本的条目；模型给出合法 latex 时写回 formula 字段并标记 _repaired；
        - 分批调用控制 token 成本；单批失败不影响其它公式，也不阻断调用方。
        """
        if not formulas:
            return formulas
        todo = [
            {
                "id": str(f.get("id") or ""),
                "raw": str(f.get("raw") or f.get("text") or ""),
                "number": f.get("number") or None,
            }
            for f in formulas
            if str(f.get("raw") or f.get("text") or "").strip()
        ]
        if not todo:
            return formulas
        repaired: dict[str, str] = {}
        batch_size = 12
        for start in range(0, len(todo), batch_size):
            batch = todo[start : start + batch_size]
            try:
                result = llm.complete_json("repair_formulas", {"formulas": batch})
            except Exception as exc:  # noqa: BLE001 - 单批失败不影响其它公式
                LOGGER.warning("repair_formulas batch failed: %s", exc)
                continue
            for item in result.get("formulas", []) or []:
                fid = str(item.get("id") or "")
                latex = str(item.get("latex") or "").strip()
                if fid and latex and item.get("ok") is not False:
                    repaired[fid] = latex
        if not repaired:
            return formulas
        out: list[dict[str, Any]] = []
        for f in formulas:
            fid = str(f.get("id") or "")
            if fid in repaired:
                f = dict(f)
                f["formula"] = repaired[fid]
                f["_repaired"] = True
            out.append(f)
        return out

    async def _auto_rearrange_source(
        application: FastAPI,
        text: str,
        formulas: list[dict[str, Any]] | None = None,
    ) -> str | None:
        """对导入的文献正文自动调用 LLM 整理排版。返回整理后的文本，失败返回 None。"""
        llm = application.state.llm
        model_configured = (
            bool(application.state.settings.tju_api_key) or llm.responder is not None
        )
        if not model_configured:
            return None
        rearranged_parts: list[str] = []
        for chunk in _rearrange_chunks(text):
            payload: dict[str, Any] = {"text": chunk}
            roster = _formula_roster_for_chunk(chunk, formulas)
            if roster:
                payload["formulas"] = roster
            try:
                result = await asyncio.to_thread(
                    llm.complete_json, "rearrange_paper", payload
                )
                part = str(result.get("text") or "").strip()
            except Exception:
                part = ""
            if part:
                part = _literal_escape_to_control(part)
                part = _repair_rearranged_markers(chunk, part)
            else:
                # 单块失败/空输出时回退原文，避免整段内容（含图表公式锚点）丢失
                part = chunk
            rearranged_parts.append(part)
        if not rearranged_parts:
            return None
        return "\n\n".join(rearranged_parts)

    def _schedule_rearrange_job(project_id: str, source_id: str) -> None:
        """把 AI 整理排版 + 公式修复放到后台任务执行，导入请求即刻返回已提取文本，避免客户端超时。"""
        jobs = getattr(application.state, "rearrange_jobs", None)
        if jobs is None:
            jobs = {}
            application.state.rearrange_jobs = jobs
        jobs[project_id] = {"state": "running", "started_at": time.time()}
        asyncio.create_task(_run_rearrange_job(project_id, source_id))

    async def _run_rearrange_job(project_id: str, source_id: str) -> None:
        jobs = getattr(application.state, "rearrange_jobs", {}) or {}
        try:
            src = db.get_source(project_id, source_id)
            if src is None:
                jobs[project_id] = {"state": "done", "error": "source_gone"}
                return
            llm = application.state.llm
            arranged = await _auto_rearrange_source(application, src.text, src.formulas)
            changed = arranged is not None and arranged != src.text
            if arranged and arranged != src.text:
                arranged = _finalize_rearranged_text(
                    arranged, src.figures, src.formulas
                )
                repaired = await asyncio.to_thread(
                    _repair_formulas_latex, src.formulas, llm
                )
                payload = ExtractedSource(
                    filename=src.filename,
                    mime_type=src.mime_type,
                    size_bytes=src.size_bytes,
                    text=arranged,
                    formulas=repaired,
                    figures=src.figures,
                    status="ok" if arranged else src.status,
                    error_message=None if arranged else src.error_message,
                )
                content = _source_file_bytes(application, src)
                if content:
                    payload = _fill_empty_formula_images(content, payload)
                db.update_source_extraction(project_id, src.source_id, payload)
            jobs[project_id] = {
                "state": "done",
                "changed": bool(changed),
                "finished_at": time.time(),
            }
        except Exception as exc:  # noqa: BLE001 - 后台重排失败不阻断已完成导入
            LOGGER.exception("async rearrange job failed project=%s", project_id)
            jobs[project_id] = {"state": "failed", "error": str(exc)}

    @application.get("/api/library-links")
    async def library_links() -> dict[str, Any]:
        raw = application.state.settings.library_links or DEFAULT_LIBRARY_LINKS or "[]"
        try:
            links = json.loads(raw)
            if not isinstance(links, list):
                links = []
        except ValueError:
            links = []
        return {"links": links}

    @application.get("/api/literature")
    async def list_literature(
        request: Request, tag: str | None = None
    ) -> dict[str, Any]:
        user = require_user(request)
        projects = db.list_literature(user.user_id, tag=tag)
        items = [
            {
                "project": model_to_dict(project),
                "meta": db.get_literature_meta(project.project_id),
            }
            for project in projects
        ]
        return {"literature": items}

    @application.post("/api/literature", status_code=201)
    async def create_literature(
        request: Request,
        file: UploadFile | None = File(default=None),
        title: str | None = Form(default=None),
        pasted_text: str | None = Form(default=None),
        auto_rearrange: bool = Form(default=True),
    ) -> dict[str, Any]:
        user = require_user(request)
        if file is None and pasted_text is None:
            raise HTTPException(
                status_code=422,
                detail=error_payload("missing_source", "请上传论文 PDF 或粘贴文本。"),
            )
        content = b""
        if file is not None:
            content = await file.read()
            extracted = await _extract_uploaded_source(
                application, file.filename or "paper.pdf", content
            )
            if extracted.status == "unsupported":
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "unsupported_source", "暂不支持该文件格式，请上传 PDF。"
                    ),
                )
            source_title = (file.filename or "未命名论文").rsplit(".", 1)[0]
        else:
            extracted = extract_source("粘贴文本.txt", b"", pasted_text=pasted_text)
            source_title = "粘贴文本"
        paper_title = (title or "").strip() or source_title or "论文"
        project = db.create_literature(user.user_id, paper_title)
        saved = db.add_source(project.project_id, extracted)
        if file is not None:
            await _persist_source_file(application, saved, content)

        # 自动 AI 整理排版：提取成功后立即调用 LLM 清理页眉页脚、整理公式与段落
        if auto_rearrange and saved.text and saved.text.strip():
            try:
                rearranged_text = await _auto_rearrange_source(application, saved.text)
                if rearranged_text and rearranged_text != saved.text:
                    rearranged_text = _finalize_rearranged_text(
                        rearranged_text, saved.figures, saved.formulas
                    )
                    payload = ExtractedSource(
                        filename=saved.filename,
                        mime_type=saved.mime_type,
                        size_bytes=saved.size_bytes,
                        text=rearranged_text,
                        formulas=saved.formulas,
                        figures=saved.figures,
                        status="ok",
                        error_message=None,
                    )
                    saved = db.update_source_extraction(
                        project.project_id, saved.source_id, payload
                    )
            except Exception:
                pass  # 整理失败不阻断导入

        # 自动 AI 整理排版后，确保所有图表均具备可用图像 data URI
        saved = _fill_empty_media_images(content, saved)

        record_undo(
            user,
            project.project_id,
            "project.create",
            f"新建文献「{paper_title}」",
            {"project_id": project.project_id},
        )
        meta: dict[str, Any] = {"extract_status": "pending"}
        return {
            "project": model_to_dict(project),
            "source": _source_payload(application, saved),
            "meta": meta,
        }

    @application.post("/api/literature/stream")
    async def create_literature_stream(
        request: Request,
        file: UploadFile = File(...),
        title: str | None = Form(default=None),
        auto_rearrange: bool = Form(default=True),
    ) -> StreamingResponse:
        """流式文献导入：SSE 逐页推送 PDF 提取结果，前端边提取边渲染。"""
        user = require_user(request)
        content = await file.read()
        source_title = (file.filename or "未命名论文").rsplit(".", 1)[0]
        paper_title = (title or "").strip() or source_title or "论文"

        def _sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream() -> Any:
            try:
                import fitz
                from core.parsers import (
                    _page_figures,
                    _vector_figure_regions,
                    _reflow_paragraphs,
                    _mark_headings_in_text,
                    _mark_formulas_in_text,
                    _strip_repeated_header_footer,
                    _dedupe_formulas,
                    _assign_formula_ids,
                    _formula_candidates_from_pymupdf,
                    _ocr_page_pymupdf,
                    _ocr_page_paddle,
                    _MAX_FIGURES,
                    _outline_headings,
                    _font_heading_lines,
                    _dedupe_headings,
                    _normalize_heading_levels,
                    _insert_figure_markers,
                    _finalize_figures_and_markers,
                    _caption_driven_figure_fallback,
                    _strip_pipe_artifacts,
                    _attach_heading_pages,
                    _normalize_heading_markers,
                    attach_figure_contexts,
                )

                doc = None
                try:
                    # 1. 打开 PDF
                    doc = fitz.open(stream=content, filetype="pdf")
                    total_pages = doc.page_count
                    yield _sse({"type": "start", "total_pages": total_pages})

                    # 提取大纲标题（带真实页码，最终写成 [[H:level@page]] 标记）
                    outline_headings = _outline_headings(doc)
                    headings: list[tuple[Any, ...]] = _normalize_heading_levels(
                        [
                            (level, title, page)
                            for page, entries in outline_headings.items()
                            for (level, title) in entries
                        ]
                    )

                    all_texts: list[str] = []
                    all_figures: list[dict[str, Any]] = []
                    fig_id_counter = 0

                    # 2. 逐页提取
                    for page_idx in range(total_pages):
                        yield _sse(
                            {
                                "type": "page_progress",
                                "page": page_idx + 1,
                                "total": total_pages,
                            }
                        )
                        page = doc[page_idx]

                        page_text = page.get_text("text") or ""
                        # 扫描页 OCR 兜底
                        if not page_text.strip():
                            try:
                                page_text = _ocr_page_pymupdf(page)
                            except Exception:
                                pass
                        if not page_text.strip():
                            try:
                                page_text = _ocr_page_paddle(page)
                            except Exception:
                                pass

                        # 字号启发式标题（带本页页码）
                        headings.extend(_font_heading_lines(page, page_idx + 1))

                        # 提取图片
                        page_figs: list[dict[str, Any]] = []
                        bitmap_bboxes: list[list[float]] = []
                        # 本页被判为伪图（框住正文 / 水印层）而剔除的候选。
                        # 剔过东西就说明候选已找过，不能再触发按图注兜底 —— 详见
                        # core/parsers.py 同名变量处的说明。
                        dropped_figs: list[dict[str, Any]] = []
                        try:
                            page_figs = _page_figures(
                                doc,
                                page,
                                page_idx,
                                fig_id_counter,
                                max_figures=_MAX_FIGURES - len(all_figures),
                                dropped=dropped_figs,
                            )
                            for pf in page_figs:
                                fig_id_counter = max(
                                    fig_id_counter, int(pf["id"].replace("fig", "")) + 1
                                )
                            bitmap_bboxes = [
                                pf["bbox"] for pf in page_figs if "bbox" in pf
                            ]
                        except Exception:
                            page_figs = []

                        try:
                            vec_figs = _vector_figure_regions(
                                page,
                                page_idx,
                                fig_id_counter,
                                bitmap_bboxes,
                                max_figures=_MAX_FIGURES
                                - len(all_figures)
                                - len(page_figs),
                                dropped=dropped_figs,
                            )
                            for vf in vec_figs:
                                fig_id_counter = max(
                                    fig_id_counter, int(vf["id"].replace("fig", "")) + 1
                                )
                            page_figs = page_figs + vec_figs
                        except Exception:
                            pass

                        # 页面无位图/矢量图时，以「图 N」标题驱动区域截取兜底
                        if not page_figs and not dropped_figs:
                            try:
                                page_figs = _caption_driven_figure_fallback(
                                    doc, page, page_idx, fig_id_counter
                                )
                                fig_id_counter += len(page_figs)
                            except Exception:
                                page_figs = []

                        all_figures.extend(page_figs)
                        # 把 [[FIG:id]] 标记按 y 坐标原位插入正文（AI 重排与前端渲染的锚点）
                        if page_text.strip() and page_figs:
                            try:
                                page_text = _insert_figure_markers(
                                    page_text, page, page_figs
                                )
                            except Exception:
                                pass

                        all_texts.append(page_text)
                        yield _sse(
                            {
                                "type": "page_text",
                                "page": page_idx + 1,
                                "text": page_text,
                                "figures": all_figures[-5:]
                                if len(all_figures) > 5
                                else all_figures,
                            }
                        )

                    # 提取公式候选（需要 doc 对象，在关闭前调用）
                    pymupdf_formulas = (
                        _formula_candidates_from_pymupdf(doc) if all_texts else []
                    )
                finally:
                    if doc is not None:
                        try:
                            doc.close()
                        except Exception:
                            pass

                # 3. 后处理
                yield _sse({"type": "processing", "stage": "postprocess"})
                # 过滤期刊信息图、重排 fig id 并同步重写正文标记
                all_figures, all_texts = _finalize_figures_and_markers(
                    all_figures, all_texts
                )
                all_texts = _strip_repeated_header_footer(all_texts)
                full_text = "\n\n".join(
                    pt.strip() for pt in all_texts if pt.strip()
                ).strip()
                full_text = _mark_headings_in_text(
                    full_text, _dedupe_headings(headings)
                )

                deduped = _dedupe_formulas(pymupdf_formulas)
                assigned = _assign_formula_ids(deduped)
                full_text = _mark_formulas_in_text(full_text, assigned)
                full_text = _reflow_paragraphs(full_text)
                full_text = _strip_pipe_artifacts(full_text)
                # 后处理补出来的标题标记没有页码 → 按标题行落在哪一页回填；再清掉
                # 没有标题的空标记（否则前端目录会把下一行正文吞成标题）；最后给
                # 无图注的图挂上所在章节标题，前端图表列表据此显示。
                full_text = _attach_heading_pages(full_text, all_texts)
                full_text = _normalize_heading_markers(full_text)
                attach_figure_contexts(full_text, all_figures)

                # 4. 保存到数据库
                extracted = ExtractedSource(
                    filename=file.filename or "paper.pdf",
                    mime_type="application/pdf",
                    size_bytes=len(content),
                    text=full_text,
                    formulas=assigned,
                    figures=all_figures,
                    status="ok",
                )
                extracted = _fill_empty_media_images(content, extracted)
                project = db.create_literature(user.user_id, paper_title)
                saved = db.add_source(project.project_id, extracted)
                await _persist_source_file(application, saved, content)

                # 5. AI 整理排版改为后台异步执行，导入即刻返回已提取文本，避免客户端超时
                if auto_rearrange and full_text.strip():
                    yield _sse(
                        {"type": "processing", "stage": "ai_rearrange", "async": True}
                    )
                    _schedule_rearrange_job(project.project_id, saved.source_id)

                record_undo(
                    user,
                    project.project_id,
                    "project.create",
                    f"新建文献「{paper_title}」",
                    {"project_id": project.project_id},
                )

                yield _sse(
                    {
                        "type": "done",
                        "project_id": project.project_id,
                        "source_id": saved.source_id,
                        "project": model_to_dict(project),
                        "source": _source_payload(application, saved),
                        "meta": {"extract_status": "done", "ai_rearrange": "pending"},
                        "rearranged": False,
                    }
                )
            except Exception as exc:
                LOGGER.exception("Literature stream import failed")
                yield _sse({"type": "error", "message": f"导入失败：{exc}"})

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

