    @application.post("/api/literature/{project_id}/rearrange")
    def rearrange_literature(project_id: str, request: Request) -> dict[str, Any]:
        """对文献正文做 AI 整理排版：纠正抽取乱序、去残留页眉页脚，保留 [[H/MATH/FIG]] 标记。"""
        require_project_access(project_id, request)
        sources = db.list_sources(project_id)
        if not sources or not any(s.text and s.text.strip() for s in sources):
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_source", "论文正文为空，无法整理排版。"),
            )
        updated: list[dict[str, Any]] = []
        for source in sources:
            if not (source.text and source.text.strip()):
                continue
            rearranged_parts: list[str] = []
            for chunk in _rearrange_chunks(source.text):
                payload: dict[str, Any] = {"text": chunk}
                roster = _formula_roster_for_chunk(chunk, source.formulas)
                if roster:
                    payload["formulas"] = roster
                try:
                    result = llm.complete_json("rearrange_paper", payload)
                    part = str(result.get("text") or "").strip()
                except Exception as exc:  # noqa: BLE001 - 单块失败不阻断整篇
                    LOGGER.warning(
                        "rearrange chunk failed source=%s: %s", source.source_id, exc
                    )
                    part = ""
                if part:
                    part = _literal_escape_to_control(part)
                    part = _repair_rearranged_markers(chunk, part)
                else:
                    # 单块失败/空输出时回退原文，避免整段内容（含图表公式锚点）丢失
                    part = chunk
                rearranged_parts.append(part)
            if not rearranged_parts:
                continue
            new_text = "\n\n".join(rearranged_parts)
            # 落库前收口：清残留、删悬空/重复标记、散开扎堆图片、锚定未引用图片
            new_text = _finalize_rearranged_text(
                new_text, source.figures, source.formulas
            )
            # 公式规整：把 OCR/文本层解析出的碎片交给 LLM 重组成可被 KaTeX 渲染的完整 LaTeX
            repaired_formulas = _repair_formulas_latex(source.formulas, llm)
            payl = ExtractedSource(
                filename=source.filename,
                mime_type=source.mime_type,
                size_bytes=source.size_bytes,
                text=new_text,
                formulas=repaired_formulas,
                figures=source.figures,
                status="ok" if new_text else source.status,
                error_message=None if new_text else source.error_message,
            )
            content = _source_file_bytes(application, source)
            if content:
                payl = _fill_empty_formula_images(content, payl)
            saved = db.update_source_extraction(project_id, source.source_id, payl)
            updated.append(_source_payload(application, saved))
        return {"sources": updated, "rearranged": len(updated)}

    @application.post("/api/literature/{project_id}/{source_id}/repair-formulas")
    def repair_source_formulas(
        project_id: str, source_id: str, request: Request
    ) -> dict[str, Any]:
        """对单条已导入文献的公式做规整：把 OCR/文本层解析碎片交给 LLM 重组成完整 LaTeX，
        无需重新跑全文重排。"""
        require_project_access(project_id, request)
        source = db.get_source(project_id, source_id)
        if source is None:
            raise HTTPException(
                status_code=404,
                detail=error_payload("source_not_found", "未找到该文献来源。"),
            )
        repaired_formulas = _repair_formulas_latex(source.formulas, llm)
        payload = ExtractedSource(
            filename=source.filename,
            mime_type=source.mime_type,
            size_bytes=source.size_bytes,
            text=source.text,
            formulas=repaired_formulas,
            figures=source.figures,
            status=source.status,
            error_message=source.error_message,
        )
        saved = db.update_source_extraction(project_id, source.source_id, payload)
        return _source_payload(application, saved)

    @application.get("/api/literature/{project_id}/rearrange-status")
    async def rearrange_status(project_id: str, request: Request) -> dict[str, Any]:
        """查询后台 AI 整理排版任务的执行状态（running/done/failed/idle）。

        带看门狗：大论文/多来源的 LLM 排版可能耗时很久，若超过 REARRANGE_WATCHDOG_SEC，
        即使协程还没跑完也对外返回 done，让前端收起"AI 整理排版中"遮罩、恢复阅读；
        后台任务继续跑完会照常落库，下次刷新正文即可看到最终排版。
        """
        require_project_access(project_id, request)
        jobs = getattr(application.state, "rearrange_jobs", {}) or {}
        info = jobs.get(project_id) or {"state": "idle"}
        if info.get("state") == "running" and info.get("started_at"):
            elapsed = time.time() - info["started_at"]
            if elapsed >= REARRANGE_WATCHDOG_SEC:
                return {
                    "project_id": project_id,
                    "state": "done",
                    "watchdog": True,
                    "running_elapsed_sec": round(elapsed, 1),
                }
        return {"project_id": project_id, **info}

    @application.post("/api/literature/{project_id}/translate")
    def translate_literature(
        project_id: str, payload: TranslateRequest, request: Request
    ) -> dict[str, Any]:
        require_project_access(project_id, request)
        source_text = (payload.source_text or "").strip()
        if not source_text:
            raise HTTPException(
                status_code=422,
                detail=error_payload("missing_text", "缺少待翻译文本。"),
            )
        digest = hashlib.sha256(source_text.encode("utf-8")).hexdigest()
        cached = db.get_translation_by_hash(project_id, digest)
        if cached is not None and cached["translated_text"]:
            return {"translated_text": cached["translated_text"], "cached": True}
        result = llm.complete_json("translate_section", {"text": source_text})
        translated = str(result.get("answer") or "").strip()
        db.upsert_translation(project_id, 0, digest, source_text, translated, "done")
        return {"translated_text": translated, "cached": False}

    @application.post("/api/literature/{project_id}/translate-all")
    def translate_all_literature(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        require_project_access(project_id, request)
        text = _literature_texts(project_id)
        if not text.strip():
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_source", "论文正文为空，无法翻译。"),
            )
        chunks = _translation_chunks(text)
        segments: list[dict[str, Any]] = []
        for index, chunk in enumerate(chunks):
            digest = hashlib.sha256(chunk.encode("utf-8")).hexdigest()
            cached = db.get_translation_by_hash(project_id, digest)
            if cached is not None and cached["translated_text"]:
                segments.append(cached)
                continue
            result = llm.complete_json("translate_section", {"text": chunk})
            translated = str(result.get("answer") or "").strip()
            segments.append(
                db.upsert_translation(
                    project_id, index, digest, chunk, translated, "done"
                )
            )
        done = sum(1 for segment in segments if segment.get("translated_text"))
        return {"segments": segments, "total": len(chunks), "translated": done}

    @application.get("/api/literature/{project_id}/translate/status")
    async def translate_status(project_id: str, request: Request) -> dict[str, Any]:
        require_project_access(project_id, request)
        segments = db.list_translations(project_id)
        total = len(segments)
        done = sum(1 for segment in segments if segment.get("translated_text"))
        return {"total": total, "done": done, "pending": total - done}

    @application.post("/api/literature/compare")
    def compare_literature(
        payload: CompareRequest, request: Request, refresh: bool = False
    ) -> dict[str, Any]:
        """多篇文献对比。

        同一组论文重复打开对比弹窗时复用上次结果（对比一次要等一次 LLM，不该每次都重来）；
        正文被重新抽取/重排后指纹变化，缓存自动失效；`refresh=true` 强制重算。
        """
        user = require_user(request)
        papers: list[dict[str, str]] = []
        signatures: list[str] = []
        for project_id in payload.project_ids:
            require_project_access(project_id, request)
            project = db.get_project(project_id, user.user_id)
            meta = db.get_literature_meta(project_id)
            text = _literature_texts(project_id)
            abstract = (meta.get("abstract") or "")[:1200]
            introduction = text[:3000] if len(text) > 300 else text
            conclusion = text[-3000:] if len(text) > 3000 else ""
            papers.append(
                {
                    "title": meta.get("title") or project.subject,
                    "abstract": abstract,
                    "introduction": introduction,
                    "conclusion": conclusion,
                }
            )
            # 指纹带上 project_id 再排序：勾选顺序变了（A,B → B,A）不该算成另一组对比。
            signatures.append(
                f"{project_id}:{hashlib.sha1(text.encode('utf-8')).hexdigest()}"
            )

        cache_key = _comparison_cache_key(user.user_id, payload.project_ids)
        signature = hashlib.sha1(
            "|".join(sorted(signatures)).encode("utf-8")
        ).hexdigest()
        if not refresh:
            cached = db.get_literature_comparison(cache_key)
            if (
                str(cached.get("signature") or "") == signature
                and str(cached.get("comparison") or "").strip()
            ):
                return {
                    "comparison": cached["comparison"],
                    "cached": True,
                    "created_at": cached.get("created_at"),
                }

        result = llm.complete_json("compare_papers", {"papers": papers})
        comparison = str(result.get("answer") or "")
        if comparison.strip():
            db.save_literature_comparison(
                cache_key, user.user_id, payload.project_ids, signature, comparison
            )
        return {"comparison": comparison, "cached": False, "created_at": None}

    @application.post("/api/literature/{project_id}/ask")
    def ask_literature(
        project_id: str, payload: AskRequest, request: Request
    ) -> dict[str, Any]:
        require_project_access(project_id, request)
        question = (payload.question or "").strip()
        if not question:
            raise HTTPException(
                status_code=422,
                detail=error_payload("missing_question", "请输入要提问的问题。"),
            )
        text = _literature_texts(project_id).strip()
        if not text:
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_source", "论文正文为空，无法问答。"),
            )
        result = llm.complete_json(
            "ask_paper",
            {"question": question, "text": text[:_LITERATURE_EXTRACT_BUDGET]},
        )
        return {"answer": str(result.get("answer") or "")}

    @application.post("/api/literature/{project_id}/insights")
    def literature_insights(
        project_id: str, request: Request, refresh: bool = False
    ) -> dict[str, Any]:
        require_project_access(project_id, request)
        cached = db.get_literature_meta(project_id)
        questions = cached.get("suggested_questions")
        keypoints = cached.get("keypoints")
        if not refresh and questions and keypoints:
            return {
                "suggested_questions": questions,
                "keypoints": keypoints,
                "cached": True,
            }
        text = _literature_texts(project_id).strip()
        if not text:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "empty_source", "论文正文为空，无法生成阅读重点。"
                ),
            )
        result = llm.complete_json(
            "paper_insights", {"text": text[:_LITERATURE_EXTRACT_BUDGET]}
        )
        questions = (
            result.get("suggested_questions")
            if isinstance(result.get("suggested_questions"), list)
            else []
        )
        keypoints = (
            result.get("keypoints") if isinstance(result.get("keypoints"), list) else []
        )
        db.upsert_literature_meta(
            project_id, {"suggested_questions": questions, "keypoints": keypoints}
        )
        return {
            "suggested_questions": questions,
            "keypoints": keypoints,
            "cached": False,
        }

