    # —— 文献精读导出（新增端点，既有端点一律不动）——
    # 导出的全是**库里已经存在**的东西：元数据、逐段中英对照、笔记与高亮、
    # AI 解释、文献对比。**零模型调用、零 token 成本** —— 这是纯渲染，
    # 不是「再生成一份报告」。
    # 渲染逻辑全在 core/literature_export.py，这里只负责取数、鉴权、打包。
    def _literature_export_options(request: Request) -> dict[str, Any]:
        q = request.query_params

        def _flag(name: str, default: bool = True) -> bool:
            raw = q.get(name)
            if raw is None or raw.strip() == "":
                return default
            return raw.strip().lower() not in {"0", "false", "no", "off"}

        return {
            "include_fulltext": _flag("fulltext"),
            "include_figures": _flag("figures"),
            "include_translation": _flag("translation"),
            "include_notes": _flag("notes"),
            "include_ai": _flag("ai"),
            "include_comparison": _flag("comparison"),
            "include_deep": _flag("deep"),
            "folder_name": (q.get("folder") or "").strip() or None,
        }

    def _literature_export_payload(
        project_id: str, request: Request, deep_analysis: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        """读库 → 渲染 → {root, files, assets, stats}。

        deep_analysis 由调用方生成好后传入（LLM 较慢，不在这里同步跑）；
        预览端点不传，导出端点用 asyncio.to_thread 生成后再传。
        """
        project = require_project_access(project_id, request)
        options = _literature_export_options(request)
        meta = db.get_literature_meta(project_id) or {}
        title = (meta.get("title") or "").strip() or (
            getattr(project, "subject", "") or ""
        ).strip()
        if not options["folder_name"]:
            options["folder_name"] = title or "文献精读"

        # 这篇文献参与过的多篇对比（取最近一组）；没有就跳过该章节。
        comparison = ""
        for row in db.list_literature_comparisons_for(project_id, project.owner_id):
            text = (row.get("comparison") or "").strip()
            if text:
                comparison = text
                break

        result = build_literature_export(
            title=title,
            sources=db.list_sources(project_id),
            marks=db.list_literature_marks(project_id),
            meta=meta,
            segments=db.list_translations(project_id),
            comparison=comparison,
            deep_analysis=deep_analysis,
            options=options,
        )
        # 「AI 解释」章节是否有内容，取决于库里有没有 kind=ai_answer 的标注。
        # 没有时如实报 0，界面据此提示「AI 解释还没落库」，而不是让用户以为丢了。
        result["stats"]["has_ai_answers"] = result["stats"].get("ai_answers", 0) > 0
        return result

    def _generate_deep_analysis_for_export(
        title: str, abstract: str, venue: str, user_id: str
    ) -> dict[str, Any]:
        """导出时生成深度解析（LLM 较慢，由导出端点放进 asyncio.to_thread 跑）。

        摘要为空时调用方不会进到这里；画像未配置则返回无画像的诚实降级结果。
        """
        from core import paper_search as _ps

        llm = getattr(application.state, "llm", None)
        store = getattr(application.state, "research_profile_store", None)
        profile = store.load(user_id) if store else None
        return _ps.generate_paper_deep_analysis(
            {"title": title, "abstract": abstract, "venue": venue}, llm, profile
        )

    @application.get("/api/literature/{project_id}/export/preview")
    async def preview_literature_export(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """导出前先报数：界面用它显示「将生成哪些章节」再让用户点下载。

        深度解析不在这里真实生成（LLM 较慢），只在有摘要时预告会包含该章节。
        """
        result = _literature_export_payload(project_id, request)
        sections = sorted(result["files"])
        options = _literature_export_options(request)
        meta = db.get_literature_meta(project_id) or {}
        if options.get("include_deep", True) and (meta.get("abstract") or "").strip():
            if "06-AI-深度解析.md" not in sections:
                sections.append("06-AI-深度解析.md")
        return {
            "ok": True,
            "root": result["root"],
            "stats": result["stats"],
            "sections": sections,
        }

    @application.get("/api/literature/{project_id}/export")
    async def export_literature_reading(project_id: str, request: Request) -> Response:
        """下载精读成果 zip（标准 Markdown + assets/ 图片，含 AI 深度解析章节）。"""
        user = require_user(request)
        options = _literature_export_options(request)
        meta = db.get_literature_meta(project_id) or {}
        project = require_project_access(project_id, request)
        title = (meta.get("title") or "").strip() or (
            getattr(project, "subject", "") or ""
        ).strip()
        abstract = (meta.get("abstract") or "").strip()

        deep_analysis = None
        if options.get("include_deep", True) and abstract:
            deep_analysis = await asyncio.to_thread(
                _generate_deep_analysis_for_export,
                title,
                abstract,
                (meta.get("venue") or "").strip(),
                user.user_id,
            )

        result = _literature_export_payload(project_id, request, deep_analysis=deep_analysis)
        if not result["files"]:
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_export", "这篇文献还没有可导出的精读内容。"),
            )
        data = build_literature_zip(result["root"], result["files"], result["assets"])
        import urllib.parse as _urlparse

        encoded = _urlparse.quote(f"{result['root']}.zip")
        stats = result["stats"]
        return Response(
            content=data,
            media_type="application/zip",
            headers={
                "Content-Disposition": f"attachment; filename={encoded}; filename*=UTF-8''{encoded}",
                "Content-Length": str(len(data)),
                # 供前端在下载后显示「已导出 N 个章节 / K 张图」——不用再解析 zip
                "X-Export-Sections": str(stats.get("sections", 0)),
                "X-Export-Files": str(stats.get("files", 0)),
                "X-Export-Figures": str(stats.get("figures", 0)),
                "X-Export-Ai-Answers": str(stats.get("ai_answers", 0)),
                "Access-Control-Expose-Headers": (
                    "X-Export-Sections, X-Export-Files, X-Export-Figures, X-Export-Ai-Answers"
                ),
            },
        )

    # —— 提示词实验室（可编辑 / 可重置）——
    # 把 core/llm.py 与调用方里的 AI 任务 system prompt 摆到界面上，让「AI 怎么想的」可见。
    # 任务清单见 core/prompt_catalog.py（现有 54 个），与真实调用的对齐由
    # tools/check_prompt_catalog.py 把关 —— 它扫代码里的调用点跟目录对拍，漏登记直接报红。
    # 与真实调用走同一条 _system_prompt，所见即所用；用户可就地改写某个任务的提示词，
    # 改写立即对真实调用生效，并可一键重置回 core/llm.py 的出厂默认。
    @application.get("/api/prompts/tasks")
    async def list_prompt_tasks(request: Request) -> dict[str, Any]:
        require_user(request)
        from core.prompt_catalog import PROMPT_GROUPS, PROMPT_TASKS

        return {"groups": PROMPT_GROUPS, "tasks": PROMPT_TASKS}

    @application.get("/api/prompts/preview")
    async def preview_prompt(task: str, request: Request) -> dict[str, Any]:
        require_user(request)
        from core import llm as llm_module
        from core.prompt_catalog import PROMPT_TASKS
        from core.prompt_overrides import get_prompt_override

        meta = next((item for item in PROMPT_TASKS if item["task"] == task), None)
        if meta is None:
            raise HTTPException(
                status_code=404,
                detail=error_payload("prompt_task_unknown", "没有这个 AI 任务。"),
            )
        default_prompt = llm_module._default_system_prompt(task)
        override = get_prompt_override(task)
        # 未知任务会落到通用兜底人设；据此判断该任务是否真的有专用提示词
        fallback = "你是知源 KnowOrigin 的本地学习 Agent。"
        # source 决定「实验室里改了到底生不生效」：
        # system=走 _system_prompt，所见即所用；external=调用方自拼 messages，这里改了也发不出去。
        source = meta.get("source", "system")
        return {
            **meta,
            "system_prompt": override or default_prompt,
            "default_system_prompt": default_prompt,
            "streaming_prompt": llm_module.stream_system_prompt(task),
            "has_dedicated_prompt": fallback not in default_prompt and source != "external",
            "is_overridden": bool(override),
            "source": source,
            # merged_into 非空 = 这个任务没有独立调用点，功能由它指的那个任务承担
            "merged_into": meta.get("merged_into") or "",
            "retired": bool(meta.get("merged_into")),
        }

    @application.post("/api/prompts/override")
    async def save_prompt_override(
        request: Request, payload: PromptOverrideRequest
    ) -> dict[str, Any]:
        """保存某个任务的提示词改写；传空串等于重置。立即对后续真实调用生效。"""

        require_user(request)
        from core.prompt_catalog import PROMPT_TASKS
        from core.prompt_overrides import set_prompt_override

        if not any(item["task"] == payload.task for item in PROMPT_TASKS):
            raise HTTPException(
                status_code=404,
                detail=error_payload("prompt_task_unknown", "没有这个 AI 任务。"),
            )
        overridden = set_prompt_override(payload.task, payload.prompt)
        return {"ok": True, "task": payload.task, "is_overridden": overridden}

    @application.post("/api/prompts/reset")
    async def reset_prompt_override(
        request: Request, payload: PromptOverrideRequest
    ) -> dict[str, Any]:
        """把某个任务的提示词重置回 core/llm.py 的出厂默认。"""

        require_user(request)
        from core.prompt_catalog import PROMPT_TASKS
        from core.prompt_overrides import clear_prompt_override

        if not any(item["task"] == payload.task for item in PROMPT_TASKS):
            raise HTTPException(
                status_code=404,
                detail=error_payload("prompt_task_unknown", "没有这个 AI 任务。"),
            )
        clear_prompt_override(payload.task)
        return {"ok": True, "task": payload.task, "is_overridden": False}

    @application.post("/api/projects/{project_id}/research-insights")
    def project_research_insights(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """AI 研究洞察：通读当前知识库，给出能直接推动研究与写作的灵感。

        只读：取节点 / 资料 / 笔记做一次模型调用，不写库、不改动任何既有数据。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        project = db.get_project(project_id, user.user_id)

        nodes = db.list_framework_nodes(project_id)
        sources = db.list_sources(project_id)
        favorites = db.list_favorites(project_id)
        name_of = {s.source_id: (s.filename or "未命名资料") for s in sources}

        # 控制 token：只送模型判断所需的最小结构
        node_payload = []
        for node in nodes[:80]:
            ids = [sid for sid in (node.source_ids or []) if sid in name_of]
            node_payload.append(
                {
                    "name": node.name,
                    "desc": (node.description or "")[:180],
                    "sources": [name_of[sid] for sid in ids],
                    "coverage": node.coverage_status,
                    "learning": node.learning_status,
                    "mastery": round(float(node.mastery_score or 0.0), 2),
                }
            )
        note_payload = [
            {
                "title": (fav.title or "")[:60],
                "note": (fav.note or fav.content or "")[:200],
            }
            for fav in favorites[:30]
        ]

        result = llm.complete_json(
            "research_insights",
            {
                "project": getattr(project, "name", "")
                or getattr(project, "subject", ""),
                "sources": [s.filename for s in sources],
                "nodes": node_payload,
                "notes": note_payload,
            },
        )

        def _as_list(value: Any) -> list[Any]:
            return value if isinstance(value, list) else []

        return {
            "overview": str(result.get("overview") or ""),
            "solid_claims": _as_list(result.get("solid_claims")),
            "tensions": _as_list(result.get("tensions")),
            "blanks": _as_list(result.get("blanks")),
            "next_questions": _as_list(result.get("next_questions")),
            "node_count": len(nodes),
            "source_count": len(sources),
        }

    @application.post("/api/projects/{project_id}/source-view/explain")
    def project_source_view_explain(
        project_id: str, payload: SourceViewExplainRequest, request: Request
    ) -> dict[str, Any]:
        """来源视图里任一节点的 AI 解释（知识点 / 资料 / 笔记）。

        只读：取该节点自身 + 它在库内的关联 + 资料正文片段，做一次模型调用；
        不写库、不改动任何既有数据。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        project = db.get_project(project_id, user.user_id)

        nodes = db.list_framework_nodes(project_id)
        sources = db.list_sources(project_id)
        favorites = db.list_favorites(project_id)
        by_source = {s.source_id: s for s in sources}
        by_node = {n.node_id: n for n in nodes}

        kind = payload.kind
        if kind == "concept":
            node = by_node.get(payload.id)
            if node is None:
                raise HTTPException(status_code=404, detail="未找到该知识点。")
            linked = [sid for sid in (node.source_ids or []) if sid in by_source]
            target = {
                "kind": "concept",
                "name": node.name,
                "desc": (node.description or "")[:300],
                "coverage": node.coverage_status,
                "learning": node.learning_status,
                "mastery": round(float(node.mastery_score or 0.0), 2),
                # 只送命中处附近，控制 token；找不到就退回开头一段
                "sources": [
                    {
                        "filename": by_source[sid].filename,
                        "excerpt": _explain_excerpt(by_source[sid].text, node.name),
                    }
                    for sid in linked[:3]
                ],
                "my_notes": [
                    {
                        "title": (fav.title or "")[:60],
                        "note": (fav.note or fav.content or "")[:200],
                    }
                    for fav in favorites
                    if node.node_id in (fav.node_ids or [])
                ][:3],
                # 只给一小把相关概念名。给太多会诱导模型「逐条罗列」——
                # 实测塞 60 个名字时，它写出了 117 条同义要点直到烧完 token，
                # 后面的 connections / pitfalls / follow_up 全丢。
                "other_nodes": [x.name for x in nodes if x.node_id != node.node_id][
                    :12
                ],
            }
        elif kind == "source":
            source = by_source.get(payload.id)
            if source is None:
                raise HTTPException(status_code=404, detail="未找到该资料。")
            target = {
                "kind": "source",
                "name": source.filename,
                "text_chars": len(source.text or ""),
                "excerpt": _explain_excerpt(source.text, "", head=1800),
                "supports": [
                    {
                        "name": x.name,
                        "mastery": round(float(x.mastery_score or 0.0), 2),
                    }
                    for x in nodes
                    if source.source_id in (x.source_ids or [])
                ][:20],
            }
        else:
            favorite = next(
                (fav for fav in favorites if fav.favorite_id == payload.id), None
            )
            if favorite is None:
                raise HTTPException(status_code=404, detail="未找到该笔记。")
            target = {
                "kind": "note",
                "name": favorite.title or "未命名笔记",
                "body": (favorite.note or favorite.content or favorite.answer or "")[
                    :1200
                ],
                "chapter": favorite.chapter_name or "",
                "attached_nodes": [
                    by_node[nid].name
                    for nid in (favorite.node_ids or [])
                    if nid in by_node
                ],
            }

        result = llm.complete_json(
            "node_explain",
            {
                "project": getattr(project, "subject", "") or "",
                "target": target,
            },
        )

        def _strings(value: Any, limit: int = 0) -> list[str]:
            return _explain_strings(value, limit)

        return {
            "kind": kind,
            "name": str(target.get("name") or ""),
            "summary": str(result.get("summary") or "").strip(),
            "key_points": _strings(result.get("key_points"), 5),
            "connections": _strings(result.get("connections"), 3),
            "pitfalls": _strings(result.get("pitfalls"), 3),
            "follow_up": _strings(result.get("follow_up"), 4),
        }

    @application.get("/api/projects/{project_id}/sources/{source_id}/content")
    async def source_content(
        project_id: str, source_id: str, request: Request
    ) -> FileResponse:
        require_project_access(project_id, request)
        source = db.get_source(project_id, source_id)
        path = _source_file_path(application, source)
        if not path.exists():
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "source_content_unavailable",
                    "该材料导入时未保留原文件，可查看已提取文本或重新上传原文件。",
                ),
            )
        encoded_filename = quote(source.filename, safe="")
        return FileResponse(
            path,
            media_type=source.mime_type,
            headers={
                "Content-Disposition": f"inline; filename*=UTF-8''{encoded_filename}",
                "X-Content-Type-Options": "nosniff",
            },
        )

