    @application.get(
        "/api/projects/{project_id}/sources/{source_id}/preview-images/{image_name}"
    )
    async def source_preview_image(
        project_id: str, source_id: str, image_name: str, request: Request
    ) -> FileResponse:
        require_project_access(project_id, request)
        source = db.get_source(project_id, source_id)
        if not re.fullmatch(
            r"image_\d{3}\.(?:png|jpe?g|gif|webp|bmp)", image_name, re.IGNORECASE
        ):
            raise HTTPException(
                status_code=404,
                detail=error_payload("preview_image_not_found", "预览图片不存在。"),
            )
        path = (
            application.state.source_previews_dir
            / source.project_id
            / source.source_id
            / image_name
        )
        if not path.is_file():
            # 懒加载：首次访问时生成预览图
            await _ensure_source_preview_images(application, source)
        if not path.is_file():
            raise HTTPException(
                status_code=404,
                detail=error_payload("preview_image_not_found", "预览图片不存在。"),
            )
        return FileResponse(
            path,
            media_type=mimetypes.guess_type(image_name)[0]
            or "application/octet-stream",
            headers={
                "Content-Disposition": "inline",
                "X-Content-Type-Options": "nosniff",
            },
        )

    @application.get("/api/projects/{project_id}/sources/{source_id}/page-image")
    async def source_page_image(
        project_id: str,
        source_id: str,
        page: int = 0,
        dpi: int = 170,
        request: Request = None,
    ):
        """Acrobat 式原页读取：返回某一页的栅格 PNG（按 source_previews 缓存）。"""
        require_project_access(project_id, request)
        source = db.get_source(project_id, source_id)
        content = _source_file_bytes(application, source)
        if not content:
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "source_file_unavailable",
                    "该材料导入时未保留原文件，无法按原页展示。",
                ),
            )
        if dpi < 50 or dpi > 300:
            dpi = 170
        from core.pages import pdf_page_count, rasterize_page

        if page < 0 or page >= pdf_page_count(content):
            raise HTTPException(
                status_code=404,
                detail=error_payload("page_not_found", "页码超出范围。"),
            )
        pages_dir = (
            application.state.source_previews_dir
            / source.project_id
            / source.source_id
            / "pages"
        )
        pages_dir.mkdir(parents=True, exist_ok=True)
        cache_path = pages_dir / f"page_{page}_{dpi}.png"
        if not cache_path.is_file():
            rasterize_page(content, page, dpi=dpi, path=str(cache_path))
        return FileResponse(
            cache_path,
            media_type="image/png",
            headers={"Cache-Control": "public, max-age=86400"},
        )

    @application.get("/api/projects/{project_id}/sources/{source_id}/pages")
    async def source_pages_meta(
        project_id: str, source_id: str, request: Request = None
    ) -> dict[str, Any]:
        """按页元数据：页数/尺寸 + 内置文本层 + 公式区域坐标（仅坐标，不重建 LaTeX）。"""
        require_project_access(project_id, request)
        source = db.get_source(project_id, source_id)
        content = _source_file_bytes(application, source)
        if not content:
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "source_file_unavailable",
                    "该材料导入时未保留原文件，无法读取页面结构。",
                ),
            )
        from core.pages import build_pages_meta

        pages_dir = (
            application.state.source_previews_dir
            / source.project_id
            / source.source_id
            / "pages"
        )
        pages_dir.mkdir(parents=True, exist_ok=True)
        cache_path = pages_dir / "pages_meta.json"
        src_path = _source_file_path(application, source)
        key = (
            f"{src_path.stat().st_mtime_ns}:{src_path.stat().st_size}"
            if src_path.is_file()
            else "inmem"
        )
        # 磁盘缓存命中（同一源文件未变更）则直接复用，避免成百上千页时每次重建拖慢首屏
        try:
            if cache_path.is_file():
                cached = json.loads(cache_path.read_text(encoding="utf-8"))
                if cached.get("_key") == key:
                    return cached
        except Exception:  # noqa: BLE001
            pass
        meta = await asyncio.to_thread(build_pages_meta, content)
        meta["_key"] = key
        try:
            cache_path.write_text(json.dumps(meta), encoding="utf-8")
        except Exception:  # noqa: BLE001
            pass
        return meta

    @application.get("/api/projects/{project_id}/sources/{source_id}/page-crop")
    async def source_page_crop(
        project_id: str,
        source_id: str,
        page: int = 0,
        bbox: str = "0,0,1,1",
        dpi: int = 300,
        request: Request = None,
    ) -> FileResponse:
        """按 bbox=[x0,y0,x1,y1](pt) 返回该页某区域的高清裁剪 PNG（公式放大用）。"""
        require_project_access(project_id, request)
        source = db.get_source(project_id, source_id)
        content = _source_file_bytes(application, source)
        if not content:
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "source_file_unavailable",
                    "该材料导入时未保留原文件，无法按原页展示。",
                ),
            )
        if dpi < 100 or dpi > 600:
            dpi = 300
        from core.pages import pdf_page_count, rasterize_crop

        if page < 0 or page >= pdf_page_count(content):
            raise HTTPException(
                status_code=404,
                detail=error_payload("page_not_found", "页码超出范围。"),
            )
        bboxes = _parse_page_crop_bbox(bbox)
        if bboxes is None:
            raise HTTPException(
                status_code=422,
                detail=error_payload("bad_bbox", "bbox 必须为 x0,y0,x1,y1 且正面积。"),
            )
        pages_dir = (
            application.state.source_previews_dir
            / source.project_id
            / source.source_id
            / "pages"
        )
        pages_dir.mkdir(parents=True, exist_ok=True)
        cache_path = (
            pages_dir
            / f"crop_{page}_{dpi}_{int(bboxes[0])}_{int(bboxes[1])}_{int(bboxes[2])}_{int(bboxes[3])}.png"
        )
        if not cache_path.is_file():
            rasterize_crop(content, page, bboxes, dpi=dpi, path=str(cache_path))
        return FileResponse(
            cache_path,
            media_type="image/png",
            headers={"Cache-Control": "public, max-age=86400"},
        )

