    @application.delete("/api/projects/{project_id}/sources/{source_id}")
    async def delete_source(
        project_id: str, source_id: str, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        row = db.get_source_row(project_id, source_id)
        undo_id = record_undo(
            user,
            project_id,
            "source.delete",
            f"删除资料「{row['filename']}」",
            {"source": row},
        )
        source = db.delete_source(project_id, source_id)
        if undo_id is not None:
            # 文件移入回收站，撤销时随数据库记录一起还原
            suffix = Path(source.filename).suffix.lower()
            safe_suffix = suffix if re.fullmatch(r"\.[a-z0-9]{1,8}", suffix) else ""
            await asyncio.gather(
                asyncio.to_thread(
                    _move_to_trash,
                    application,
                    undo_id,
                    "source_files_dir",
                    project_id,
                    f"{source_id}{safe_suffix}",
                ),
                asyncio.to_thread(
                    _move_to_trash,
                    application,
                    undo_id,
                    "source_previews_dir",
                    project_id,
                    source_id,
                ),
            )
        else:
            await asyncio.gather(
                asyncio.to_thread(_remove_source_file, application, source),
                asyncio.to_thread(
                    _remove_source_preview_directory, application, source
                ),
            )
        return {"deleted": True, "source_id": source_id}

    @application.post("/api/projects/{project_id}/framework/build")
    async def build_project_framework(
        project_id: str, request: Request
    ) -> StreamingResponse:
        """构建知识框架，进度以 SSE 推送（2026-09-30 改造）。

        此前是同步 JSON 端点：前端进度条只能靠 setInterval 假跳，且 build_framework
        里的 LLM 调用（同步 httpx）直接跑在事件循环上，构建期间整个服务都不响应其它请求。
        现在构建移入 asyncio.to_thread，真实阶段事件经队列 → SSE 推给前端；
        模型等待期（一次不透明的 complete_json 调用）每秒发一条**真实计时**心跳，
        不编造等待期的百分比。
        """
        project = require_project_access(project_id, request)
        sources = db.list_sources(project_id)
        usable = [
            source
            for source in sources
            if source.status == "ok" and source.text.strip()
        ]

        def _build_sse(ev: dict[str, Any]) -> str:
            return f"data: {json.dumps(ev, ensure_ascii=False)}\n\n"

        if not usable:
            async def empty_stream() -> AsyncIterator[str]:
                yield _build_sse(
                    {
                        "type": "result",
                        "data": {
                            "nodes": [
                                model_to_dict(node)
                                for node in db.list_framework_nodes(project_id)
                            ],
                            "fallback": False,
                            "message": "没有可用于构建框架的文本，请先上传可解析材料。",
                        },
                    }
                )

            return StreamingResponse(empty_stream(), media_type="text/event-stream")

        require_user(request)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "知识框架生成需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )

        loop = asyncio.get_running_loop()
        events: asyncio.Queue[dict[str, Any]] = asyncio.Queue()

        def progress(event: dict[str, Any]) -> None:
            # build_framework 跑在工作线程，进度事件必须回到事件循环
            loop.call_soon_threadsafe(events.put_nowait, event)

        def run_build() -> dict[str, Any]:
            framework_snapshot = db.snapshot_framework(project_id)
            use_fallback = False
            try:
                nodes = build_framework(
                    project_id,
                    usable,
                    database=db,
                    llm_client=application.state.llm,
                    root_name=project.subject,
                    replace_existing=True,
                    progress=progress,
                )
                message = None
            except ModelOutputError as exc:
                LOGGER.warning(
                    "Falling back to heuristic framework after malformed model output. project_id=%s error=%s",
                    project_id,
                    exc,
                )
                nodes = build_framework(
                    project_id,
                    usable,
                    database=db,
                    root_name=project.subject,
                    replace_existing=True,
                    progress=progress,
                )
                use_fallback = True
                message = "模型输出结构不符合要求，已改用来源文本生成本地框架。"
            record_undo(
                require_user(request),
                project_id,
                "framework.replace",
                "重新构建知识框架",
                {"project_id": project_id, "snapshot": framework_snapshot},
            )
            return {
                "nodes": [model_to_dict(node) for node in nodes],
                "fallback": use_fallback,
                "message": message,
            }

        async def event_stream() -> AsyncIterator[str]:
            build_task = loop.run_in_executor(None, run_build)
            extract_since: float | None = None
            while True:
                try:
                    event = await asyncio.wait_for(events.get(), timeout=1.0)
                except asyncio.TimeoutError:
                    # 构建线程意外崩溃（未及发 done）：把异常转成 error 事件，流不能挂死
                    if build_task.done():
                        exc = build_task.exception()
                        yield _build_sse(
                            {"type": "error", "message": f"构建失败：{exc}" if exc else "构建失败。"}
                        )
                        return
                    # 心跳：只在模型阶段等待时发，内容是真实已用秒数
                    if extract_since is not None:
                        yield _build_sse(
                            {
                                "type": "heartbeat",
                                "stage": "extract",
                                "elapsed": round(time.monotonic() - extract_since, 1),
                            }
                        )
                    continue
                stage = event.get("stage")
                if stage == "extract" and event.get("percent", 0) <= 30:
                    if extract_since is None:
                        extract_since = time.monotonic()
                elif stage in {"link", "render", "done"}:
                    extract_since = None  # 模型阶段结束，心跳停止
                yield _build_sse(event)
                if stage == "done":
                    result = await build_task
                    yield _build_sse({"type": "result", "data": result})
                    return

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @application.get("/api/projects/{project_id}/framework")
    async def list_project_framework(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """返回当前项目的知识框架节点列表（含名称/状态/覆盖情况），供海小棠桌宠做学习陪伴。

        ``prereq_stats`` 是前置图的覆盖率（多少个知识点标了前置 / 共几条边）。
        它是产品指标不是调试信息：前置图空掉的时候，界面上看不出任何异常
        （排序照旧、推荐照出），但「按前置排期」「前置未达则不推荐」全都落不了地。
        """
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        return {
            "nodes": [model_to_dict(node) for node in nodes],
            "prereq_stats": prerequisite_stats(nodes),
        }

    @application.get("/api/projects/{project_id}/graph/export")
    async def export_project_graph(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """导出知识图谱为通用图数据：节点 + 三类边（tree 父子 / prerequisite 前置 / link 双链）。

        与「导出知识库」（Markdown + 双链）互补：那份是给人看的笔记，这份是给机器/图工具
        （Gephi、networkx、Cytoscape、Mermaid 生成器等）二次处理的原始图结构，所见即库里真值。
        """
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        project = db.get_project(project_id)
        name_to_id = {n.name: n.node_id for n in nodes}
        # 双链「理解」按无序节点对归一，附到对应 link 边上（link 无方向，A↔B 同一条）
        note_by_pair: dict[tuple[str, str], str] = {}
        for row in db.list_link_notes(project_id):
            a, b = sorted((row["a_node_id"], row["b_node_id"]))
            note_by_pair[(a, b)] = row.get("note") or ""

        edges: list[dict[str, Any]] = []
        seen_links: set[tuple[str, str]] = set()
        tree_edges = prereq_edges = link_edges = 0
        for n in nodes:
            if n.parent_id:
                edges.append({"source": n.parent_id, "target": n.node_id, "type": "tree"})
                tree_edges += 1
            for pid in n.prerequisite_ids:
                edges.append({"source": pid, "target": n.node_id, "type": "prerequisite"})
                prereq_edges += 1
            for target_name in n.wikilinks:
                target_id = name_to_id.get(target_name)
                # 双链无方向（A↔B 与 B↔A 同一条）：按字典序归一去重，避免双向出链重复成两条边
                a, b = sorted((n.node_id, target_id if target_id is not None else target_name))
                if (a, b) in seen_links:
                    continue
                seen_links.add((a, b))
                edges.append({
                    "source": a,
                    # 双链按「节点名」存储；名字解析不到任何节点时保留原名（悬空边，诚实标注）
                    "target": b,
                    "type": "link",
                    "note": note_by_pair.get((a, b), "") if target_id is not None else "",
                    "resolved": target_id is not None,
                })
                link_edges += 1

        return {
            "format": "knoworigin-graph-v1",
            "project_id": project_id,
            "project_name": project.subject,
            "exported_at": datetime.now(timezone.utc).isoformat(timespec="seconds"),
            "nodes": [model_to_dict(n) for n in nodes],
            "edges": edges,
            "stats": {
                "nodes": len(nodes),
                "tree_edges": tree_edges,
                "prerequisite_edges": prereq_edges,
                "link_edges": link_edges,
            },
        }

    @application.get("/api/projects/{project_id}/graph/export/xmind")
    async def export_project_graph_xmind(
        project_id: str, request: Request
    ) -> Response:
        """导出知识图谱为可编辑的 .xmind 文件（XMind 2020+ 打开后能继续增删改）。

        树状父子 -> topic 层级；前置边 / 双链 -> 关系线；掌握度 / 已学 / 覆盖状态 -> 标记与备注。
        与上面的 graph/export（JSON 图数据）互补：那份给机器 / 图工具，这份给人 / XMind。
        """
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        if not nodes:
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_graph", "当前项目还没有知识节点，无法导出 XMind 文件。"),
            )
        project = db.get_project(project_id)
        payload = build_xmind(
            project_id,
            project.subject,
            [model_to_dict(n) for n in nodes],
            db.list_link_notes(project_id),
        )
        encoded = quote(f"{project.subject}.xmind")
        return Response(
            content=payload,
            media_type="application/octet-stream",
            headers={
                "Content-Disposition": f"attachment; filename={encoded}; filename*=UTF-8''{encoded}",
                "Content-Length": str(len(payload)),
            },
        )

    @application.post("/api/projects/{project_id}/framework/prereq/suggest")
    async def suggest_framework_prereq(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """给已有节点补建前置 —— **只给建议，不落库**。

        为什么要有这条路：前置图实测覆盖率只有约 9%，而存量项目不可能靠「重新生成框架」来修
        （重生成会换掉全部 node_id，把已有的掌握度、笔记、收藏全废掉）。
        所以补前置必须是**只补边**的动作，并且：AI 建议 → 人确认 → 才落库。
        """
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        stats = prerequisite_stats(nodes)
        if len(nodes) < 4:
            return {
                "suggestions": [], "edge_count": 0, "stats": stats,
                "reason": "知识点太少（<4 个），补建前置没有意义。",
            }
        llm = getattr(application.state, "llm", None)
        if llm is None:
            return {
                "suggestions": [], "edge_count": 0, "stats": stats,
                "reason": "本机没有配置模型，无法补建。可在「API 设置」里配置后重试。",
            }
        try:
            response = llm.complete_json("build_prereq", build_prereq_payload(nodes))
        except Exception as exc:  # noqa: BLE001
            return {
                "suggestions": [], "edge_count": 0, "stats": stats,
                "reason": f"模型调用失败：{exc}",
            }
        parsed = validate_prereq_response(response, nodes)
        parsed["stats"] = stats
        return parsed

    @application.post("/api/projects/{project_id}/framework/prereq/apply")
    async def apply_framework_prereq(
        project_id: str, payload: PrereqApplyRequest, request: Request
    ) -> dict[str, Any]:
        """把确认过的前置边落库。**只追加，不删除**。"""
        require_project_access(project_id, request)
        valid = {n.node_id for n in db.list_framework_nodes(project_id)}
        applied: list[dict[str, Any]] = []
        skipped = 0
        for edge in payload.edges:
            if edge.node_id not in valid:
                skipped += 1
                continue
            ids = [p for p in edge.prerequisite_ids if p in valid and p != edge.node_id]
            if not ids:
                skipped += 1
                continue
            merged = db.add_framework_prerequisites(project_id, edge.node_id, ids)
            applied.append({"node_id": edge.node_id, "prerequisite_ids": merged})
        nodes = db.list_framework_nodes(project_id)
        return {
            "applied": applied,
            "skipped": skipped,
            "stats": prerequisite_stats(nodes),
        }

    @application.post("/api/projects/{project_id}/framework/nodes", status_code=201)
    async def create_framework_node(
        project_id: str, payload: FrameworkNodeCreate, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        _validate_framework_parent(db, project_id, None, payload.parent_id)
        valid_source_ids = {source.source_id for source in db.list_sources(project_id)}
        source_ids = [
            source_id
            for source_id in payload.source_ids
            if source_id in valid_source_ids
        ]
        node = db.add_framework_node(
            project_id,
            name=payload.name.strip(),
            description=payload.description.strip(),
            parent_id=payload.parent_id,
            source_ids=source_ids,
        )
        record_undo(
            user,
            project_id,
            "framework.node_add",
            f"新建节点「{node.name}」",
            {"project_id": project_id, "node_id": node.node_id},
        )
        return {"node": model_to_dict(node)}

    @application.patch("/api/projects/{project_id}/framework/{node_id}")
    async def correct_node(
        project_id: str, node_id: str, payload: NodeCorrection, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        if payload.node_id != node_id:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "node_id_mismatch", "请求路径与正文中的 node_id 不一致。"
                ),
            )
        try:
            node_name = db.get_framework_node(project_id, node_id).name
        except NodeNotFound:
            node_name = node_id
        framework_snapshot = db.snapshot_framework(project_id)
        if payload.action == "confirm":
            updated = [
                db.update_node_state(project_id, node_id, learning_status="encountered")
            ]
        elif payload.action == "remove":
            updated = [
                db.update_node_state(
                    project_id,
                    node_id,
                    coverage_status="uncovered",
                    learning_status="unexplored",
                )
            ]
        elif payload.action == "cover":
            updated = [
                db.update_node_state(project_id, node_id, coverage_status="covered")
            ]
        elif payload.action == "reassign":
            if not payload.target_node_id:
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "missing_target_node", "重新归类时必须提供 target_node_id。"
                    ),
                )
            _validate_framework_parent(db, project_id, node_id, payload.target_node_id)
            node = db.get_framework_node(project_id, node_id)
            updated = [
                db.update_framework_node(
                    project_id,
                    node_id,
                    name=node.name,
                    description=node.description,
                    parent_id=payload.target_node_id,
                ).model_copy(update={"learning_status": "pending_confirmation"}),
                db.update_node_state(
                    project_id, payload.target_node_id, learning_status="encountered"
                ),
            ]
            db.update_node_state(
                project_id, node_id, learning_status="pending_confirmation"
            )
        elif payload.action == "edit":
            node = db.get_framework_node(project_id, node_id)
            name = (payload.name if payload.name is not None else node.name).strip()
            if not name:
                raise HTTPException(
                    status_code=422,
                    detail=error_payload("empty_node_name", "节点名称不能为空。"),
                )
            _validate_framework_parent(db, project_id, node_id, payload.target_node_id)
            updated = [
                db.update_framework_node(
                    project_id,
                    node_id,
                    name=name,
                    description=(
                        payload.description
                        if payload.description is not None
                        else node.description
                    ).strip(),
                    parent_id=payload.target_node_id,
                )
            ]
        else:
            db.delete_framework_node(project_id, node_id)
            updated = db.list_framework_nodes(project_id)
        undo_summaries = {
            "confirm": f"确认节点「{node_name}」",
            "remove": f"取消节点「{node_name}」的覆盖标记",
            "cover": f"标记节点「{node_name}」已覆盖",
            "reassign": f"移动节点「{node_name}」",
            "edit": f"编辑节点「{node_name}」",
        }
        record_undo(
            user,
            project_id,
            "framework.replace",
            undo_summaries.get(payload.action or "", f"删除节点「{node_name}」"),
            {"project_id": project_id, "snapshot": framework_snapshot},
        )
        return {"nodes": [model_to_dict(node) for node in updated]}

