    @application.post("/api/projects/{project_id}/notes/render")
    async def render_note_links(
        project_id: str, payload: NoteRenderRequest, request: Request
    ) -> dict[str, Any]:
        """解析笔记正文中的 Obsidian 双链 [[名|别名]]，返回链接名到 node_id 的映射。"""
        require_user(request)
        require_project_access(project_id, request)
        all_nodes = db.list_framework_nodes(project_id)
        name_to_id = {node.name: node.node_id for node in all_nodes}
        links: list[str] = []
        resolved: dict[str, str | None] = {}
        for m in re.finditer(r"\[\[([^\[\]]+?)\]\]", payload.text):
            raw = m.group(1).strip()
            link_name = raw.split("|", 1)[0].strip()
            if not link_name:
                continue
            if link_name in links:
                continue
            links.append(link_name)
            resolved[link_name] = name_to_id.get(link_name)
        return {"links": links, "resolved": resolved}

