    @application.post("/api/projects/{project_id}/link-notes/suggest")
    async def suggest_link_note(
        project_id: str, payload: LinkNoteSuggest, request: Request
    ) -> dict[str, Any]:
        """双链图谱：让 AI 为某对双链起草一句「理解」。只返回草稿，落库仍由用户确认。"""
        require_user(request)
        require_project_access(project_id, request)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "AI 起草双链理解需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        node_a = db.get_framework_node(project_id, payload.a_node_id)
        node_b = db.get_framework_node(project_id, payload.b_node_id)

        def _side(node: Any) -> dict[str, Any]:
            return {
                "name": node.name,
                "description": (node.description or "")[:600],
                "note_content": (node.note_content or "")[:1200],
                "tags": list(node.tags or [])[:12],
            }

        result = await asyncio.to_thread(
            lambda: application.state.llm.complete_json(
                "link_note",
                {
                    "node_a": _side(node_a),
                    "node_b": _side(node_b),
                    "hint": (payload.hint or "").strip(),
                },
            )
        )
        note = str(result.get("note") or "").strip() if isinstance(result, dict) else ""
        if not note:
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "empty_model_output",
                    "AI 这次没能给出可用的关系理解，请重试或自己写一句。",
                ),
            )
        basis = str(result.get("basis") or "").strip() if isinstance(result, dict) else ""
        return {
            "note": note[:500],
            "basis": basis if basis in {"note", "description", "name"} else "",
        }

    def _norm_text(text: str) -> str:
        """归一化文本用于去重比对（去掉全部空白并小写）。"""
        return "".join(str(text or "").lower().split())

    def _node_existing_kb(pid: str, node_id: str) -> dict:
        """收集该节点已保存的卡片 front 与历史题面，供生成时规避，避免重复考点。"""
        card_fronts: list[str] = []
        used_questions: list[str] = []
        try:
            for card in db.list_cards(pid):
                if card.card_id and node_id in (card.node_ids or []):
                    f = (card.front or "").strip()
                    if f:
                        card_fronts.append(f)
            for quiz in db.list_recent_quizzes(pid, 60):
                for q in quiz.get("questions") or []:
                    if node_id in (q.get("node_ids") or []):
                        t = str(q.get("question") or "").strip()
                        if t:
                            used_questions.append(t)
        except Exception:
            return {"card_fronts": [], "used_questions": []}
        return {"card_fronts": card_fronts[:12], "used_questions": used_questions[:16]}

    def _node_context_text(pid: str, node_id: str) -> str:
        """收集节点的描述 + 笔记 + **前置**/关联/父子节点说明 + 来源原文，作为单节点生成卡片/测验的上下文字段。

        前置（prerequisite_ids）是这里补上的一块：此前只投 parent / child / wikilinks，
        于是出「傅里叶变换」的题时模型看不见它的前置「复变函数」——
        组合题因此几乎出不来，而组合题是迁移的主要来源。
        前置以【前置 L{n}：名称】的标签出现，并注明层差，
        让模型知道哪一步必须在哪一步之前。
        """
        node = db.get_framework_node(pid, node_id)
        chunks: list[str] = []
        if node.description.strip():
            chunks.append(f"【节点说明】{node.description.strip()}")
        try:
            nodes = db.list_framework_nodes(pid)
            by_id = {n.node_id: n for n in nodes}
            layers = _node_layer_map(nodes)
            related: list = []
            # 前置放在最前面：出题时模型先读到「这个概念站在什么之上」，
            # 再读同层/子层的兄弟节点，才可能设计出有顺序的组合题。
            related.extend((by_id[p], "前置") for p in (node.prerequisite_ids or []) if p in by_id)
            if node.parent_id and node.parent_id in by_id:
                related.append((by_id[node.parent_id], "父节点"))
            related.extend((n, "子节点") for n in nodes if n.parent_id == node_id)
            related.extend(
                (by_id[w], "关联节点") for w in (node.wikilinks or []) if w in by_id
            )
            seen_rel: set[str] = set()
            for rel_node, rel_type in related[:8]:
                if rel_node.node_id in seen_rel:
                    continue
                seen_rel.add(rel_node.node_id)
                label = f"【{rel_type} L{layers.get(rel_node.node_id, 0)}：{rel_node.name}】"
                if (rel_node.description or "").strip():
                    label += rel_node.description.strip()
                chunks.append(label)
        except Exception:
            pass
        if (node.note_content or "").strip():
            chunks.append(f"【本节点笔记】{node.note_content.strip()}")
        wanted = set(node.source_ids)
        for source in db.list_sources(pid):
            if source.status != "ok" or not source.text.strip():
                continue
            if wanted and source.source_id not in wanted:
                continue
            chunks.append(f"【来源：{source.filename}】{source.text.strip()}")
        if not chunks:
            chunks.append("（该节点暂无关联资料，请基于节点名称与通用学科知识生成。）")
        return "\n\n".join(chunks)

    @application.post("/api/projects/{project_id}/nodes/{node_id}/card")
    async def generate_node_card(
        project_id: str, node_id: str, payload: NodeCardRequest, request: Request
    ) -> dict[str, Any]:
        """个人知识库：点击知识节点，针对该节点生成一张知识卡片并落库（node_ids 关联该节点）。"""
        user = require_user(request)
        require_project_access(project_id, request)
        node = db.get_framework_node(project_id, node_id)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "知识卡片生成需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        context_text = _node_context_text(project_id, node_id)
        difficulty = payload.difficulty if payload.difficulty is not None else 1
        count = payload.count or 1
        existing = _node_existing_kb(project_id, node_id)
        already: list[str] = [f"卡片：{k}" for k in existing["card_fronts"]]
        already += [f"题目：{k}" for k in existing["used_questions"]]
        already_text = "；".join(already[:8])
        avoid = (
            f"请避开以下已覆盖考点（不要重复生成相同的 front/题面）：{already_text}。"
            if already_text
            else ""
        )
        result = await asyncio.to_thread(lambda: application.state.llm.complete_json(
            "node_card",
            {
                "instruction": (
                    f"请针对知识点「{node.name}」抽取 {count} 个不同考点，为每个考点生成一张课堂知识卡片，"
                    f"各卡片考点彼此不重复。{avoid}"
                    "front 为「概念/标题 + 一句话引导」，back 为该考点的完整解释与关键点，"
                    "category 为分类（如概念/公式/方法/机制），difficulty 为 1~3 的整数。"
                    '只返回 JSON：{"cards":[{"front":"","back":"","category":"","difficulty":1},...]}。'
                    "无法生成 {count} 张时就生成多少张（越少越精），禁止空字段，禁止复制待避开的考点。"
                ),
                "node": {"name": node.name, "description": node.description},
                "difficulty": difficulty,
                "count": count,
                "context": context_text[:6000],
            },
        ))
        raw = result.get("cards")
        if not isinstance(raw, list):
            raw = [result] if result.get("front") is not None else []
        scoped_sources = [
            s
            for s in db.list_sources(project_id)
            if s.status == "ok" and s.source_id in (node.source_ids or [])
        ]
        scoped_nodes = [node]
        scoped_ctx = source_excerpts(scoped_sources) if scoped_sources else []
        covered_prompts = [
            c.front for c in db.list_cards(project_id) if node_id in (c.node_ids or [])
        ]
        cards: list[Card] = []
        if scoped_sources:
            # 走项目级质量校验链路：逐条字段校验 + 学习价值 + 去重
            try:
                cards = _cards_from_model(
                    raw, scoped_nodes, scoped_ctx, difficulty, list(covered_prompts)
                )
                cards = _filter_unique_study_cards(cards, list(covered_prompts))[:count]
            except ModelOutputError:
                cards = []
            if not cards:
                # 内容少、约束过高被全部剔除时，宽松兜底照着再来一次，能出几张算几张
                cards = await asyncio.to_thread(
                    _generate_cards_loose,
                    application.state.llm,
                    scoped_nodes,
                    scoped_sources,
                    difficulty,
                    count,
                )
            if not cards:
                raise ModelOutputError(
                    f"节点「{node.name}」生成的卡片经质量校验后无合格条目，"
                    "请确认该节点有足够、可用的来源资料（来源原文作为卡片证据）。"
                )
        else:
            seen: set[str] = set()
            for r in raw[:count]:
                front = str(r.get("front") or "").strip()
                key = _norm_text(front)
                if not front or key in seen:
                    continue
                seen.add(key)
                cards.append(
                    Card(
                        front=front,
                        back=(
                            str(r.get("back") or node.description or "尚无内容")
                        ).strip(),
                        category=(str(r.get("category") or "概念").strip()[:20])
                        or "概念",
                        difficulty=int(r.get("difficulty") or difficulty),
                        source_ids=list(node.source_ids),
                        node_ids=[node_id],
                    )
                )
                if len(cards) >= count:
                    break
            if not cards:
                cards.append(
                    Card(
                        front=f"{node.name}：要点回顾",
                        back=node.description or "尚无内容",
                        category="概念",
                        difficulty=difficulty,
                        source_ids=list(node.source_ids),
                        node_ids=[node_id],
                    )
                )
        saved = db.add_cards(project_id, cards)
        record_undo(
            user,
            project_id,
            "cards.add",
            f"为节点「{node.name}」生成 {len(saved)} 张卡片",
            {"project_id": project_id, "card_ids": [c.card_id for c in saved]},
        )
        return {"cards": [model_to_dict(c) for c in saved], "node_id": node_id}

    @application.post("/api/projects/{project_id}/nodes/{node_id}/quiz")
    async def generate_node_quiz(
        project_id: str, node_id: str, payload: NodeQuizRequest, request: Request
    ) -> dict[str, Any]:
        """个人知识库：点击知识节点，针对该节点生成一份小测验并落库。"""
        user = require_user(request)
        require_project_access(project_id, request)
        node = db.get_framework_node(project_id, node_id)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "小测验生成需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        context_text = _node_context_text(project_id, node_id)
        difficulty = payload.difficulty if payload.difficulty is not None else 1
        count = max(1, min(int(payload.question_count or 3), 10))
        types = payload.question_types or ["single_choice", "fill_blank"]
        existing = _node_existing_kb(project_id, node_id)
        already: list[str] = [f"卡片：{k}" for k in existing["card_fronts"]]
        already += [f"题目：{k}" for k in existing["used_questions"]]
        already_text = "；".join(already[:8])
        avoid = (
            f"请避开以下已覆盖考点，不要重复出相同题目：{already_text}。"
            if already_text
            else ""
        )
        result = await asyncio.to_thread(lambda: application.state.llm.complete_json(
            "node_quiz",
            {
                "instruction": (
                    f"请针对知识点「{node.name}」抽取 {count} 个不同考点，为每个考点出 1 道题（题型限定：{','.join(types)}）。"
                    f"各题考点彼此不重复。{avoid}"
                    '每题为 JSON 对象：{"question":"","type":"single_choice|fill_blank",'
                    '"options":[""],"answer":"","explanation":"","difficulty":1}。'
                    '只返回 JSON：{"questions":[...]}，type 只能使用上述列举值且以此为准。'
                ),
                "node": {"name": node.name, "description": node.description},
                "difficulty": difficulty,
                "question_count": count,
                "question_types": types,
                "context": context_text[:6000],
            },
        ))
        raw_questions = result.get("questions")
        if not isinstance(raw_questions, list):
            raw_questions = []
        # 节点出题的 prompt 不要求模型回填 node_ids/source_ids（模型也不知道内部 id），
        # 但质量校验链路 _questions_from_model 靠 node_ids 推断 source_ids——缺了会把
        # 每道题都判「no valid source_ids bound」整批跳过，最终 questions 空 → 502。
        # 针对单节点出题，这里直接把当前节点与其来源绑到每道题上（本就是出题归属）。
        for _q in raw_questions:
            if isinstance(_q, dict):
                _q.setdefault("node_ids", [node_id])
                _q.setdefault("source_ids", list(node.source_ids or []))
        scoped_sources = [
            s
            for s in db.list_sources(project_id)
            if s.status == "ok" and s.source_id in (node.source_ids or [])
        ]
        scoped_nodes = [node]
        scoped_ctx = source_excerpts(scoped_sources) if scoped_sources else []
        covered_prompts = [
            c.front for c in db.list_cards(project_id) if node_id in (c.node_ids or [])
        ]
        covered_prompts += [
            str(q.get("question") or "")
            for quiz in db.list_recent_quizzes(project_id, 60)
            for q in (quiz.get("questions") or [])
            if node_id in (q.get("node_ids") or [])
        ]
        questions: list[QuizQuestion] = []
        if scoped_sources:
            # 走项目级质量校验链路：题型/选项/答案规范化 + 学习价值 + 去重
            try:
                if not raw_questions:
                    raise ModelOutputError(
                        f"节点「{node.name}」未返回可用题目，无法生成合格小测验。"
                    )
                questions = _questions_from_model(
                    raw_questions,
                    scoped_nodes,
                    scoped_ctx,
                    difficulty,
                    list(covered_prompts),
                    requested_types=list(types) if types else None,
                )
                questions, _ = _filter_unique_study_questions(
                    questions, [], list(covered_prompts)
                )
                questions = questions[:count]
            except ModelOutputError:
                questions = []
            if not questions:
                # 内容少、约束过高被全部剔除时，宽松兜底照着重出，能出几道算几道
                questions = await asyncio.to_thread(
                    _generate_quiz_loose,
                    application.state.llm,
                    scoped_nodes,
                    scoped_sources,
                    difficulty,
                    list(types) if types else None,
                    count,
                )
            if not questions:
                raise ModelOutputError(
                    f"节点「{node.name}」生成的测验题经质量校验后无合格条目，"
                    "请确认该节点有足够、可用的来源资料（来源原文作为出题证据）。"
                )
        else:
            seen: set[str] = set()
            type_map = {"choice": "single_choice", "fill": "fill_blank"}
            for raw in raw_questions:
                if len(questions) >= count:
                    break
                qtext = str(raw.get("question") or "").strip()
                key = _norm_text(qtext)
                if not qtext or key in seen:
                    continue
                seen.add(key)
                qtype = str(raw.get("type") or "single_choice")
                qtype = type_map.get(qtype, qtype)
                if qtype not in {
                    "single_choice",
                    "multiple_choice",
                    "indefinite_choice",
                    "fill_blank",
                    "short_answer",
                    "calculation",
                }:
                    qtype = "single_choice"
                options = (
                    raw.get("options") if isinstance(raw.get("options"), list) else []
                )
                options = [str(o) for o in options]
                questions.append(
                    QuizQuestion(
                        question=qtext,
                        type=qtype,
                        options=options,
                        answer="",
                        explanation=str(raw.get("explanation") or "").strip(),
                        difficulty=int(raw.get("difficulty") or difficulty),
                        node_ids=[node_id],
                        source_ids=list(node.source_ids),
                    )
                )
            if not questions:
                questions.append(
                    QuizQuestion(
                        question=f"{node.name} 相关问题",
                        type="single_choice",
                        options=[],
                        answer="",
                        explanation="",
                        difficulty=difficulty,
                        node_ids=[node_id],
                        source_ids=list(node.source_ids),
                    )
                )
        quiz_payload = {
            "questions": [model_to_dict(q) for q in questions],
            "source_ids": sorted(node.source_ids),
            "fallback": False,
        }
        quiz_id = db.add_quiz(project_id, quiz_payload)
        record_undo(
            user,
            project_id,
            "quiz.add",
            f"为节点「{node.name}」生成小测验（{len(questions)} 题）",
            {"project_id": project_id, "quiz_id": quiz_id},
        )
        return {"quiz_id": quiz_id, **quiz_payload, "node_id": node_id}

    @application.post("/api/projects/{project_id}/nodes/{node_id}/study-plan")
    async def generate_node_study_plan(
        project_id: str, node_id: str, request: Request, refresh: bool = False
    ) -> dict[str, Any]:
        """「看还缺什么」：针对一个缺材料的节点，由 AI 生成该节点的具体讲解 + 学习规划 + 还缺什么。

        结果按「节点 + 资料指纹」缓存（core/node_study_plan.py）：同一节点、资料没变直接复用，
        不再重跑模型；资料变了自动失效；``?refresh=true`` 强制重算。
        缓存只存「生成成功且非空」的结果，一次失败不会被永久复用。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        node = db.get_framework_node(project_id, node_id)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "补课规划需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        context_text = _node_context_text(project_id, node_id)
        scoped_sources = [
            s
            for s in db.list_sources(project_id)
            if s.status == "ok" and s.source_id in (node.source_ids or [])
        ]
        has_material = bool(scoped_sources) or bool((node.note_content or "").strip())
        material_note = "有资料可用" if has_material else "无可用资料"

        store = node_study_plan_store()
        cache_key = cache_key_for(user.user_id, project_id, node_id)
        signature = signature_for(node, scoped_sources)

        # 复用：同一节点 + 资料没变，直接拿上次结果，不重跑模型。
        if not refresh:
            cached = await asyncio.to_thread(store.get, cache_key)
            if cached and cached.get("signature") == signature and cached.get("content_json", "").strip():
                try:
                    saved = json.loads(cached["content_json"])
                except (ValueError, TypeError):
                    saved = None
                if isinstance(saved, dict) and str(saved.get("content") or "").strip():
                    return {**saved, "cached": True, "created_at": cached.get("created_at")}

        result = await asyncio.to_thread(lambda: application.state.llm.complete_json(
            "node_study_plan",
            {
                "instruction": (
                    f"请针对知识点「{node.name}」补一课：写讲解、学习规划、还缺什么。"
                    f"资料状态：{material_note}。"
                ),
                "node": {"name": node.name, "description": node.description},
                "material_status": material_note,
                "context": context_text[:6000],
            },
        ))
        result = result if isinstance(result, dict) else {}
        content = str(result.get("content") or "").strip()
        plan = result.get("plan")
        if not isinstance(plan, list):
            plan = []
        gaps = result.get("gaps")
        if not isinstance(gaps, list):
            gaps = []
        if not content:
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "node_study_plan_empty",
                    "模型这次没有返回讲解正文，可能被输入长度截断了。可以稍后重试。",
                ),
            )
        payload = {
            "node_id": node_id,
            "name": node.name,
            "content": content,
            "plan": [p for p in plan if isinstance(p, dict)][:8],
            "gaps": [str(g).strip() for g in gaps if str(g).strip()][:12],
            "material_status": material_note,
        }
        await asyncio.to_thread(
            store.save,
            cache_key=cache_key,
            owner_id=user.user_id,
            project_id=project_id,
            node_id=node_id,
            signature=signature,
            content=payload,
        )
        return {**payload, "cached": False, "created_at": None}

    @application.get("/api/projects/{project_id}/vault/export")
    async def export_knowledge_vault(project_id: str, request: Request) -> Response:
        """把个人知识库导出为一个 Obsidian 兼容的 Markdown vault（zip 下载）。

        结构：vault_root/README.md（索引）+ 各分支文件夹/节点名.md。
        每个 .md 含 YAML frontmatter（node_id / tags / links）。
        """
        require_user(request)
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        project = db.get_project(project_id)
        root_name = f"{project.subject}-知识库"
        by_id = {n.node_id: n for n in nodes}
        children_of: dict[str | None, list] = {}
        for n in nodes:
            children_of.setdefault(n.parent_id, []).append(n)
        for lst in children_of.values():
            lst.sort(key=lambda n: n.name)

        # 计算每个节点的「归属章节文件夹」：
        #   根节点(无父) → vault 根；第 1 层节点 → 根节点名文件夹；
        #   更深节点 → 其最近第 1 层祖先节点名的文件夹。
        container_of: dict[str, str | None] = {}
        for n in nodes:
            chain: list = []
            cur = n.parent_id
            while cur in by_id:
                chain.append(by_id[cur])
                if by_id[cur].parent_id is None:
                    break
                cur = by_id[cur].parent_id
            if not chain:
                container_of[n.node_id] = None
            elif len(chain) == 1:
                container_of[n.node_id] = chain[0].name
            else:
                container_of[n.node_id] = chain[-2].name

        def _safe_name(name: str) -> str:
            cleaned = (
                re.sub(r'[<>:"/\\|?*\x00-\x1f]', "", name).strip().replace(" ", "_")
            )
            return cleaned or "节点"

        def _build_note_md(pid: str) -> str:
            n = by_id[pid]
            lines = ["---"]
            lines.append(f"node_id: {n.node_id}")
            if n.tags:
                lines.append(f"tags: [{', '.join(n.tags)}]")
            if n.wikilinks:
                lines.append(f"links: [{', '.join(n.wikilinks)}]")
            lines.append("---")
            body = n.note_content.strip() or n.description.strip()
            if not body:
                body = f"（该知识点暂无笔记，请补充笔记或使用 AI 助手补全。）"
            lines.append("")
            lines.append(body)
            if n.wikilinks:
                lines.append("")
                lines.append("## 关联")
                lines.append("\n".join(f"- [[{t}]]" for t in n.wikilinks))
            return "\n".join(lines) + "\n"

        # 收集待写入文件：{(路径, 内容)}
        files: dict[str, str] = {}
        used: set[str] = set()

        def _dedupe(path: str) -> str:
            if path not in used:
                used.add(path)
                return path
            base, ext = path.rsplit(".", 1)
            i = 1
            while f"{base}_{i}.{ext}" in used:
                i += 1
            candidate = f"{base}_{i}.{ext}"
            used.add(candidate)
            return candidate

        # 根节点放 vault 根，其余节点放所在章节文件夹（用 _safe_name 清洗、去重）
        for n in nodes:
            container = container_of[n.node_id]
            base = _safe_name(n.name)
            if container is None:
                path = f"{base}.md"
            else:
                path = f"{_safe_name(container)}/{base}.md"
            path = path.replace("\\", "/")
            files[_dedupe(path)] = _build_note_md(n.node_id)

        # README 索引
        def _tree_lines(parent: str | None, indent: int) -> list[str]:
            lines: list[str] = []
            for child in children_of.get(parent, []):
                lines.append(
                    "  " * indent + f"- [{child.name}]({_safe_name(child.name)}.md)"
                )
                lines.extend(_tree_lines(child.node_id, indent + 1))
            return lines

        readme_lines = ["# " + root_name, ""]
        year_part = f" ｜ 年份：{project.year}" if project.year else ""
        readme_lines.append(
            f"课程：{project.subject}{year_part} ｜ 共 {len(nodes)} 个知识点"
        )
        readme_lines.append("")
        readme_lines.append(
            "> 由知源 KnowOrigin 导出的个人知识库（Obsidian 兼容），支持 [[双链]]。"
        )
        readme_lines.append("")
        tree = _tree_lines(None, 0)
        if tree:
            readme_lines.extend(tree)
        else:
            readme_lines.append("（暂无知识点）")
        readme_lines.append("")
        files["README.md"] = "\n".join(readme_lines)

        # 打包 zip
        import io as _io

        buf = _io.BytesIO()
        with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as zf:
            for path, content in sorted(files.items()):
                zf.writestr(f"{root_name}/{path}", content)
        buf.seek(0)
        data = buf.getvalue()
        subject = _safe_name(project.subject)
        # RFC 5987 编码，避免中文文件名破坏 latin-1 编码的 HTTP 头
        import urllib.parse as _urlparse

        encoded = _urlparse.quote(f"{subject}-知识库.zip")
        return Response(
            content=data,
            media_type="application/zip",
            headers={
                "Content-Disposition": f"attachment; filename={encoded}; filename*=UTF-8''{encoded}",
                "Content-Length": str(len(data)),
            },
        )

    # —— Obsidian 知识库导出（新增端点，既有的 /vault/export 原样不动）——
    # 比旧端点多出四件事：范围筛选（全部 / 只导有笔记的）、可选索引与关联清单、
    # 自定义顶层文件夹名，以及「先报数再下载」的 preview ——
    # 界面据此在下载前告诉用户会生成多少篇、多少双链、其中多少会成为未创建链接。
    def _obsidian_options(request: Request) -> dict[str, Any]:
        q = request.query_params

        def _flag(name: str, default: bool = True) -> bool:
            raw = q.get(name)
            if raw is None or raw.strip() == "":
                return default
            return raw.strip().lower() not in {"0", "false", "no", "off"}

        scope = (q.get("scope") or "all").strip().lower()
        if scope not in {"all", "noted"}:
            scope = "all"
        return {
            "scope": scope,
            "include_index": _flag("index"),
            "include_links": _flag("links"),
            "include_favorites": _flag("favorites"),
            "include_cards": _flag("cards"),
            "include_quizzes": _flag("quizzes"),
            "folder_name": (q.get("folder") or "").strip() or None,
        }

    def _obsidian_export_payload(project_id: str, request: Request) -> dict[str, Any]:
        """两个新端点共用：读库、算文件、返回 {root, files, stats}。"""
        project = require_project_access(project_id, request)
        options = _obsidian_options(request)
        if not options["folder_name"]:
            subject = (getattr(project, "subject", "") or "").strip() or "知识库"
            options["folder_name"] = f"{subject}-知识库"
        return build_vault_export(
            project,
            db.list_framework_nodes(project_id),
            favorites=db.list_favorites(project_id),
            cards=db.list_cards(project_id) if options["include_cards"] else [],
            quizzes=db.list_all_quizzes(project_id) if options["include_quizzes"] else [],
            link_notes=db.list_link_notes(project_id),
            **options,
        )

    @application.get("/api/projects/{project_id}/obsidian/preview")
    async def preview_obsidian_export(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """导出前先报数：界面用它显示「将生成 N 篇 / K 条双链」再让用户点下载。"""
        result = _obsidian_export_payload(project_id, request)
        return {
            "ok": True,
            "root": result["root"],
            "stats": result["stats"],
            "sample_paths": sorted(result["files"])[:6],
        }

    @application.get("/api/projects/{project_id}/obsidian/export")
    async def export_obsidian_vault(project_id: str, request: Request) -> Response:
        """下载 Obsidian 兼容的知识库 zip（标准 Markdown + [[双链]]）。"""
        result = _obsidian_export_payload(project_id, request)
        data = build_vault_zip(result["root"], result["files"])
        import urllib.parse as _urlparse

        encoded = _urlparse.quote(f"{result['root']}.zip")
        return Response(
            content=data,
            media_type="application/zip",
            headers={
                "Content-Disposition": f"attachment; filename={encoded}; filename*=UTF-8''{encoded}",
                "Content-Length": str(len(data)),
                # 供前端在整体下载完成后显示「已导出 N 篇」——不用再解析 zip
                "X-Vault-Files": str(result["stats"]["files"]),
                "X-Vault-Nodes": str(result["stats"]["nodes_exported"]),
                "X-Vault-Links": str(result["stats"]["links"]),
                "Access-Control-Expose-Headers": "X-Vault-Files, X-Vault-Nodes, X-Vault-Links",
            },
        )

    # ==========================================================================
    # 英语词汇（全部为**新增**端点，命名空间 /api/en/*，既有端点一律不动）
    # --------------------------------------------------------------------------
    # 三条硬约束：新表 `en_` 前缀、不写 learning_events（不污染既有掌握度）、
    # 越权一律返回 404 而不是 403（403 会泄露"这个 id 存在"）。
    # ==========================================================================
    from core import corpus_vocab as en_corpus
    from core import english_vocab as en_vocab
    from core.english_dict import get_dict as _english_dict_singleton
    from core.english_store import EnglishStore as _EnglishStore

    _english_holder: dict[str, Any] = {}

    def en_store() -> _EnglishStore:
        """英语词汇的独立连接。与 Database 指向同一个 sqlite 文件，但互不干涉。"""
        store = _english_holder.get("store")
        if store is None:
            store = _EnglishStore(db.path)
            _english_holder["store"] = store
        return store

    def en_dict():
        return _english_dict_singleton(current_settings.data_dir)

    def en_owner(request: Request) -> str:
        return require_user(request).user_id

    def en_error(status: int, code: str, message: str) -> HTTPException:
        return HTTPException(status_code=status, detail=error_payload(code, message))

    def en_word_payload(
        store: _EnglishStore, dictionary, word: dict, owner: str = ""
    ) -> dict:
        """把词条补齐成界面能直接渲染的形状（语境由调用方按需追加）。

        释义做一次**展示层**清洗：ECDICT 的原始串是给查词典用的
        （`n. 消费, 消费量, 痨病 / [化] 消耗量; 耗量`），直接上背单词卡会夹带
        生僻义与领域标注。原始串仍放在 meaning_full 里，界面上可展开查看。
        """
        out = dict(word)
        try:
            out["roots"] = json.loads(word.get("roots_json") or "[]")
        except (TypeError, json.JSONDecodeError):
            out["roots"] = []
        out.pop("roots_json", None)
        if not out.get("roots"):
            out["roots"] = dictionary.roots_of(word.get("lemma") or "")
        out["root_explain"] = [r for r in out["roots"] if r.get("meaning")][:3]
        raw_meaning = str(out.get("meaning") or "")
        out["meaning_full"] = raw_meaning
        cleaned = en_vocab.clean_meaning(raw_meaning)
        # 语料收进来的词，释义位上常常放的是模型写的**英文注释**
        # （「A subatomic particle with negative charge…」）——不是空，是**一个中文字
        # 都没有**，卡片上看着就像「释义没显示」。补中文只认两个可靠来源：
        #   1. 用户自己资料里的中英对照（zh）：自由粒子 / 光电效应 / 微扰哈密顿 —— 最准；
        #   2. 词典的中文（仅单词）：electron → 电子。
        # 词组绝不机械拼（会拼出「波官能」「校长哈密顿」这种错的中文）。
        # 英文原注搬进 meaning_en 保留，卡片上仍可展开，信息不丢。
        if not en_vocab.has_cjk(cleaned):
            filled = ""
            source = ""
            zh = store.term_zh(owner, out.get("lemma") or "") if owner else ""
            if zh:
                filled, source = zh, "corpus-zh"
            else:
                filled, source = en_vocab.zh_meaning_from_dict(
                    dictionary, out.get("lemma") or ""
                )
            if filled:
                out["meaning"] = filled
                out["meaning_sections"] = en_vocab.meaning_sections(filled)
                out["meaning_zh_source"] = source
                if not out.get("meaning_en"):
                    out["meaning_en"] = raw_meaning
                return out
        out["meaning"] = cleaned
        out["meaning_sections"] = en_vocab.meaning_sections(raw_meaning)
        return out

