    @application.post("/api/en/decks")
    async def english_create_deck(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """建词库。目前只留 kind=builtin（内置词表兜底）。

        曾经还有 kind=import（粘贴自己的词表），2026-09-26 移除：
        那条路鼓励用户从别处抄一份通用词书进来，而产品的主张恰恰相反——
        词该从你自己正在读的资料里来（见 /api/en/corpus/*）。抄来的词书没有
        语境，背完也不知道它出现在你哪份资料里，留着只会把人引回老路。

        幂等：同一个内置词表重复点不会建出两本一样的词库，而是直接返回已有的那本。
        """
        owner = en_owner(request)
        store = en_store()
        dictionary = en_dict()
        kind = str(payload.get("kind") or "builtin").strip().lower()

        if kind == "builtin":
            deck_ref = str(payload.get("deck_id") or "").strip()
            if not dictionary.has_deck(deck_ref):
                raise en_error(404, "english_deck_not_found", "没有这个内置词表。")
            existing = store.find_deck_by_ref(owner, "builtin", deck_ref)
            if existing:
                return {"ok": True, "deck": existing, "created": False, "added": 0}
            label = next(
                (d["name"] for d in dictionary.deck_list() if d["deck_id"] == deck_ref),
                deck_ref,
            )
            deck = store.create_deck(owner, label, "builtin", source_ref=deck_ref)
            entries = [
                {
                    "lemma": w.get("word"),
                    "surface": w.get("word"),
                    "phonetic": w.get("phonetic"),
                    "pos": w.get("pos"),
                    "meaning": w.get("translation") or "",
                    "tags": w.get("tag") or "",
                    "collins": w.get("collins"),
                    "oxford": w.get("oxford"),
                    "frq": w.get("frq"),
                }
                for w in dictionary.deck_words(
                    deck_ref, 0, max(1, dictionary.deck_size(deck_ref))
                )
            ]
            added = store.add_words(owner, deck["deck_id"], entries, source="builtin")
            return {
                "ok": True,
                "deck": store.get_deck(owner, deck["deck_id"]),
                "created": True,
                "added": added,
            }

        raise en_error(400, "english_unknown_kind", "词库类型只能是 builtin。")

