    # --------------------------------------------------------------------------
    # 划词交互层：高亮笔记 / 选区翻译 / 单句同义改写 / 侧边分析
    # --------------------------------------------------------------------------

    def _safe_int(value: Any, default: int) -> int:
        """para_index 可能是 0，所以不能用 `value or default` 那种写法。"""
        try:
            return int(value)
        except (TypeError, ValueError):
            return default

    @application.get("/api/en/exam/highlights")
    async def english_exam_list_highlights(
        request: Request, doc_key: str = ""
    ) -> dict[str, Any]:
        """列出高亮笔记。给了 doc_key 就只取这一篇，否则取全部。"""
        owner = en_owner(request)
        items = en_exam_store().list_highlights(owner, doc_key=doc_key.strip())
        return {"ok": True, "total": len(items), "items": items}

    @application.post("/api/en/exam/highlights")
    async def english_exam_add_highlight(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """记一条高亮。quote 是选中的原文，prefix/suffix 用于文章重排版后认回位置。"""
        owner = en_owner(request)
        doc_key = str(payload.get("doc_key") or "").strip()
        quote = str(payload.get("quote") or "").strip()
        if not doc_key or not quote:
            raise en_error(400, "english_bad_highlight", "缺少文档标识或选中的原文。")
        item = en_exam_store().add_highlight(
            owner,
            doc_key,
            quote,
            doc_title=str(payload.get("doc_title") or "").strip(),
            para_index=_safe_int(payload.get("para_index"), -1),
            prefix=str(payload.get("prefix") or ""),
            suffix=str(payload.get("suffix") or ""),
            note=str(payload.get("note") or ""),
            color=str(payload.get("color") or "gold"),
        )
        return {"ok": True, "item": item}

