    @application.post("/api/en/exam/translate")
    def english_exam_translate_selection(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """划词翻译：优先 TJU-LLM 出整句译文，模型不可用时退回逐词释义。

        兜底刻意不「假装」能翻译整句——词级对照加一句明确说明，比硬凑一句
        读着通顺却可能译错的句子安全得多，这模块是拿来备考的。
        """
        owner = en_owner(request)
        text = str(payload.get("text") or "").strip()
        context = str(payload.get("context") or "").strip()
        if not text:
            raise en_error(400, "english_missing_texts", "请先选中要翻译的片段。")
        text = text[:1200]

        llm = getattr(application.state, "llm", None)
        if llm is not None:
            try:
                resp = llm.complete_json(
                    "english_selection_translate",
                    {
                        "text": text,
                        "context": context,
                        "system_prompt": (
                            "你是一位考研英语翻译名师。把用户划选的英文片段译成地道中文；"
                            "若片段是长难句，译文要体现拆分后的逻辑层次。要求输出合法 JSON：\n"
                            "{\n"
                            '  "translation": "中文译文",\n'
                            '  "notes": "若含长难句结构、熟词生义或代词指代，简述翻译难点；没有就留空",\n'
                            '  "keywords": [{"word": "英文词", "meaning": "它在此处的含义"}]\n'
                            "}"
                        ),
                    },
                )
                if (
                    isinstance(resp, dict)
                    and str(resp.get("translation") or "").strip()
                ):
                    kws = resp.get("keywords")
                    return {
                        "ok": True,
                        "translation": str(resp["translation"]).strip(),
                        "notes": str(resp.get("notes") or "").strip(),
                        "keywords": kws if isinstance(kws, list) else [],
                        "ai_generated": True,
                    }
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning("english_exam_translate LLM failed: %s", exc)

        dictionary = en_dict()
        keywords: list[dict[str, str]] = []
        for token in dict.fromkeys(re.findall(r"[A-Za-z][A-Za-z\-']*", text)):
            if len(keywords) >= 12:
                break
            entry = dictionary.lookup(token) or {}
            meaning = str(entry.get("translation") or "").strip()
            if meaning:
                keywords.append(
                    {"word": token, "meaning": en_vocab.clean_meaning(meaning)}
                )
        return {
            "ok": True,
            "translation": "",
            "notes": "TJU-LLM 暂时不可用，先给出逐词释义，整句译文请稍后重试。",
            "keywords": keywords,
            "ai_generated": False,
        }

    @application.post("/api/en/exam/paraphrase-rewrite")
    def english_exam_paraphrase_rewrite(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """单句同义改写：给一句原文，产出考研真题风格的等价表达。

        与 paraphrase-extract 的分工：那个是「原文句 × 选项句」成对萃取，
        这个是「一句话 → 多个改写」，服务划词场景。
        """
        owner = en_owner(request)
        sentence = str(payload.get("sentence") or "").strip()
        if not sentence:
            raise en_error(400, "english_missing_sentence", "请先选中要改写的句子。")
        count = max(1, min(_safe_int(payload.get("count"), 3), 5))

        llm = getattr(application.state, "llm", None)
        if llm is not None:
            try:
                resp = llm.complete_json(
                    "english_paraphrase_rewrite",
                    {
                        "sentence": sentence,
                        "count": count,
                        "system_prompt": (
                            "你是考研英语同义改写专家，熟悉唐迟「阅读的逻辑」里同义替换的命题方式。"
                            f"请把用户给出的句子改写成 {count} 个语义等价、可用于考研阅读选项的表达。"
                            "改写手段要多样：同义词替换、词性转换、主动被动互换、肯定否定转换、"
                            "上位词概括、句式重组。不得改变原意，不得添加原文没有的信息。"
                            "要求输出合法 JSON：\n"
                            "{\n"
                            '  "core_meaning": "原句核心意思的一句话概括",\n'
                            '  "rewrites": [\n'
                            '    {"rewritten": "改写后的英文句子", "strategy": "同义词替换|词性转换|主动被动互换|肯定否定转换|上位词概括|句式重组", "swaps": [{"from": "原文表达", "to": "改写表达"}], "note": "这一步为什么等价"}\n'
                            "  ]\n"
                            "}"
                        ),
                    },
                )
                if (
                    isinstance(resp, dict)
                    and isinstance(resp.get("rewrites"), list)
                    and resp["rewrites"]
                ):
                    return {
                        "ok": True,
                        "core_meaning": str(resp.get("core_meaning") or "").strip(),
                        "rewrites": resp["rewrites"],
                        "ai_generated": True,
                    }
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning("english_exam_paraphrase_rewrite LLM failed: %s", exc)

        rewrites = en_exam.rule_based_paraphrase_sentence(sentence, count=count)
        return {
            "ok": True,
            "core_meaning": "",
            "rewrites": rewrites,
            "ai_generated": False,
            "notice": (
                "TJU-LLM 暂时不可用，下面是词级替换版改写（语法未必最优，"
                "但替换点都标出来了，可对照看考点）。"
                if rewrites
                else "TJU-LLM 暂时不可用，且这句里没有可替换的高频词，稍后重试。"
            ),
        }

    @application.post("/api/en/exam/side-analysis")
    def english_exam_side_analysis(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """原文侧边分析：一次返回搭配提取 + 论证结构。

        合成一个端点是有意的——侧栏一打开这两块要同时出现，
        分两次请求只会让面板出现两段错开的加载态。
        """
        owner = en_owner(request)
        text = str(payload.get("text") or "").strip()
        raw_paras = payload.get("paragraphs")
        paragraphs = [str(p) for p in raw_paras] if isinstance(raw_paras, list) else []
        if not text and paragraphs:
            text = "\n\n".join(paragraphs)
        if not text:
            raise en_error(400, "english_missing_texts", "请先打开一篇精读文章。")

        doc_key = str(payload.get("doc_key") or "").strip()
        force = bool(payload.get("force"))
        # 指纹掺一个结构版本号：analyze_argument_structure 输出结构一旦变
        # （比如加了 method/methods 字段），bump 这个前缀，旧缓存自动作废重算。
        text_hash = hashlib.sha1(("v2:" + text).encode("utf-8")).hexdigest()
        store = en_exam_store()

        # 结果按篇落库：搭配提取与论证结构都要过模型，关掉阅读页再进来不该
        # 让用户重新等一轮。正文指纹（text_hash）对不上时按失效处理，重算覆盖；
        # force=True 是用户手动「重新生成」，跳过缓存直接重算。
        if doc_key and not force:
            cached = store.get_side_cache(owner, doc_key)
            if cached and cached["text_hash"] == text_hash:
                result = dict(cached["payload"])
                result["ok"] = True
                result["cached"] = True
                return result

        collocations = en_exam.extract_collocations(text, limit=14)
        argument = en_exam.analyze_argument_structure(paragraphs or [text])
        collocation_ai = False

        # 词表命中太少时用 TJU-LLM 补一批：本地词表精度高但召回有限，
        # 冷门外刊常常一个都命中不到，那时侧栏空着比慢更糟。
        llm = getattr(application.state, "llm", None)
        if llm is not None and len(collocations) < 6:
            try:
                resp = llm.complete_json(
                    "english_collocation_extract",
                    {
                        "text": text[:6000],
                        "existing": [c["phrase"] for c in collocations],
                        "system_prompt": (
                            "你是考研英语词汇名师。请从下面这篇英文里挑出最值得记的固定搭配"
                            "（动词短语、介词短语、名词短语），不要挑普通的主谓组合。"
                            f"最多给 {max(0, 10 - len(collocations))} 条，且不要与已有条目重复。"
                            "要求输出合法 JSON：\n"
                            '{"collocations": [{"phrase": "标准形式（动词用原形）", "meaning": "中文释义", "kind": "动词短语|介词短语|名词短语", "sentence": "文中出现它的原句"}]}'
                        ),
                    },
                )
                extra = resp.get("collocations") if isinstance(resp, dict) else None
                if isinstance(extra, list):
                    known = {c["phrase"].lower() for c in collocations}
                    for item in extra:
                        if not isinstance(item, dict):
                            continue
                        phrase = str(item.get("phrase") or "").strip()
                        if not phrase or phrase.lower() in known:
                            continue
                        known.add(phrase.lower())
                        collocations.append(
                            {
                                "phrase": phrase,
                                "surface": phrase,
                                "meaning": str(item.get("meaning") or "").strip(),
                                "kind": str(item.get("kind") or "固定搭配").strip(),
                                "sentence": str(item.get("sentence") or "").strip(),
                                "ai": True,
                            }
                        )
                        # 只有真补进新条目才算「含 AI 补充」，否则界面会挂着一个
                        # 名不副实的标签（模型可能只回了一批与本地词表重复的）。
                        collocation_ai = True
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning("english_exam_collocations LLM failed: %s", exc)

        result = {
            "ok": True,
            "collocations": collocations[:14],
            "argument": argument,
            "collocation_ai": collocation_ai,
            "cached": False,
        }
        if doc_key:
            store.save_side_cache(owner, doc_key, text_hash, result)
        return result

    @application.post("/api/en/exam/selection-vocab")
    async def english_exam_selection_vocab(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """划词入生词库：查本地词典 → 收进自动生词本 → 挂上文中原句。

        与「提取本篇生词」「资料扫描」共用同一本自动生词本，所以划词收的词
        和批量提取的词会出现在同一个复习队列里，不是两套。
        """
        owner = en_owner(request)
        store = en_store()
        dictionary = en_dict()

        word = str(payload.get("word") or "").strip()
        lemma = en_vocab.normalize_token(word)
        if not lemma or not re.fullmatch(r"[a-z][a-z\-']*", lemma):
            raise en_error(
                400,
                "english_no_words",
                "请选中一个英文单词；整段短语请用「提取本篇生词」。",
            )

        entry = dictionary.lookup(lemma) or {}
        meaning = str(entry.get("translation") or "").strip()
        if not meaning:
            raise en_error(
                404,
                "english_word_not_found",
                f"本地词典没有收录「{word}」，可以在生词本里手动添加。",
            )

        deck_id = store.auto_deck(owner)["deck_id"]
        added = store.add_words(
            owner,
            deck_id,
            [
                {
                    "lemma": lemma,
                    "surface": word,
                    "phonetic": entry.get("phonetic") or "",
                    "pos": entry.get("pos") or "",
                    "meaning": meaning,
                    "tags": entry.get("tag") or "",
                    "collins": entry.get("collins"),
                    "oxford": entry.get("oxford"),
                    "frq": entry.get("frq"),
                }
            ],
            source="reading",
        )

        sample = str(payload.get("sample") or "").strip()
        if sample:
            word_id = store.find_word_id(deck_id, lemma)
            if word_id:
                store.add_context(
                    word_id,
                    text=sample,
                    source_title=str(payload.get("source_title") or "外刊精读").strip()
                    or "外刊精读",
                )

        # 与批量收词保持一致：从「待加入」池子里把这个词标为已收，免得重复提示
        pool_ids = [
            c["cand_id"]
            for c in store.list_candidates(owner, limit=100000)
            if c["lemma"] == lemma
        ]
        if pool_ids:
            store.set_candidate_status(owner, pool_ids, "accepted")

        return {
            "ok": True,
            "lemma": lemma,
            "meaning": en_vocab.clean_meaning(meaning),
            "deck_id": deck_id,
            "added": added,
            "pending": store.count_candidates(owner),
        }

    @application.get("/api/en/exam/builtins")
    async def english_exam_list_builtins(
        request: Request, item_id: str = ""
    ) -> dict[str, Any]:
        """获取系统内置的经典真题与名刊精读篇章（如考研真题、The Economist、Nature 等）。"""
        owner = en_owner(request)
        if item_id:
            for p in en_exam.BUILTIN_EXAM_PASSAGES:
                if p["id"] == item_id:
                    res = dict(p)
                    res["false_friends"] = en_exam.scan_false_friends(p["passage"])
                    return {"ok": True, "item": res}
            raise en_error(
                404, "english_passage_not_found", "没有找到指定的真题或外刊篇章。"
            )

        # 列表概览
        summary_list = [
            {
                "id": p["id"],
                "title": p["title"],
                "source_name": p["source_name"],
                "style": p["style"],
                "category": p["category"],
                "word_count": len(p["passage"].split()),
            }
            for p in en_exam.BUILTIN_EXAM_PASSAGES
        ]
        return {"ok": True, "total": len(summary_list), "items": summary_list}

    @application.post("/api/en/exam/generate-reading")
    def english_exam_generate_reading(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """利用 TJU LLM 全自动生成考研外刊精读篇章（正文+长难句+同义替换+命题陷阱选择题）。"""
        owner = en_owner(request)
        topic = str(payload.get("topic") or "").strip()
        style = str(payload.get("style") or "考研真题").strip()
        level = str(payload.get("level") or "考研英语(一)").strip()

        llm = getattr(application.state, "llm", None)
        if llm is not None:
            try:
                prompt_info = en_exam.build_tju_exam_reading_prompt(
                    topic=topic, style=style, level=level
                )
                resp = llm.complete_json(
                    "english_exam_generate_reading",
                    {
                        "topic": prompt_info["topic"],
                        "style": prompt_info["style"],
                        "level": prompt_info["level"],
                        "system_prompt": prompt_info["system_prompt"],
                        "user_prompt": prompt_info["user_prompt"],
                    },
                )
                if isinstance(resp, dict) and resp.get("passage"):
                    p_text = str(resp.get("passage") or "")
                    ffs = en_exam.scan_false_friends(p_text)
                    return {
                        "ok": True,
                        "title": str(resp.get("title") or "AI 生成外刊精读研习"),
                        "source_name": str(
                            resp.get("source_name") or f"TJU-LLM 高仿 {style}"
                        ),
                        "style": style,
                        "category": str(resp.get("category") or "前沿学术外刊"),
                        "passage": p_text,
                        "passage_zh": str(resp.get("passage_zh") or ""),
                        "key_sentences": resp.get("key_sentences")
                        if isinstance(resp.get("key_sentences"), list)
                        else [],
                        "paraphrases": resp.get("paraphrases")
                        if isinstance(resp.get("paraphrases"), list)
                        else [],
                        "false_friends": ffs,
                        "exam_question": resp.get("exam_question") or {},
                        "ai_generated": True,
                        "source_mode": "tju_llm",
                    }
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning(
                    "english_exam_generate_reading LLM failed: %s; using fallback reading",
                    exc,
                )

        # 离线或模型未响应时降级返回真实高质量篇章
        fb = en_exam.offline_fallback_exam_reading(topic=topic, style=style)
        fb["false_friends"] = en_exam.scan_false_friends(fb["passage"])
        fb["ok"] = True
        return fb

    @application.post("/api/en/exam/fetch-reading")
    async def english_exam_fetch_reading(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """从用户指定的外刊网址 (URL) 自动抓取正文并生成精读卡片。"""
        owner = en_owner(request)
        url = str(payload.get("url") or "").strip()
        if not url or not (url.startswith("http://") or url.startswith("https://")):
            raise en_error(
                400,
                "english_invalid_url",
                "请提供以 http:// 或 https:// 开头的合法外刊网址。",
            )

        try:
            res = en_exam.extract_reading_from_web_url(url)
            res["ok"] = True
            return res
        except Exception as exc:  # noqa: BLE001
            LOGGER.warning("english_exam_fetch_reading failed for url %s: %s", url, exc)
            raise en_error(502, "english_fetch_failed", f"外刊正文抓取失败：{exc}")

