    @application.get("/api/en/exam/online-search")
    async def english_exam_online_search(
        request: Request,
        query: str = "",
        source_id: str = "",
        topic: str = "",
        limit: int = 40,
        force: bool = False,
    ) -> dict[str, Any]:
        """实时联网检索：关键词 × 来源 × 主题 三维过滤，结果来自各源站最新 RSS。"""
        owner = en_owner(request)
        stats: dict[str, Any] = {}
        try:
            items = en_exam.search_online_articles(
                query=query,
                source_id=source_id,
                topic=topic,
                limit=max(1, min(int(limit or 40), 120)),
                data_dir=current_settings.data_dir,
                force=bool(force),
                stats=stats,
            )
        except Exception as exc:  # noqa: BLE001
            LOGGER.warning("english_exam_online_search failed: %s", exc)
            raise en_error(502, "english_online_search_failed", f"联网检索失败：{exc}")
        payload = {"ok": True, "total": len(items), "items": items}
        payload.update(stats)
        # 一个源都没连上时给出明确诊断，而不是让用户对着空列表猜
        if stats.get("sources_ok") == 0:
            payload["notice"] = (
                f"{stats.get('sources_total', 0)} 个外刊源全部连接失败，"
                "请检查网络后点「🔄 换一批」重试。"
            )
        return payload

    @application.post("/api/en/exam/online-fetch")
    async def english_exam_online_fetch(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """按 id / url 抓取外刊全文并清洗，补齐长难句与熟词生义标签。"""
        owner = en_owner(request)
        article_id = str(payload.get("article_id") or "").strip()
        url = str(payload.get("url") or "").strip()
        if not article_id and not url:
            raise en_error(400, "english_missing_article", "请给出 article_id 或 url。")
        try:
            article = en_exam.load_online_article(
                article_id, url=url, data_dir=current_settings.data_dir
            )
        except Exception as exc:  # noqa: BLE001
            LOGGER.warning("english_exam_online_fetch failed: %s", exc)
            raise en_error(
                502, "english_online_fetch_failed", f"外刊全文抓取失败：{exc}"
            )
        if not article.get("ok"):
            raise en_error(
                502,
                "english_online_fetch_failed",
                article.get("error") or "这篇外刊正文抓取失败，换一篇试试。",
            )
        article["ok"] = True
        return article

