    # ==========================================================================
    # 六级写作与翻译提分引擎（/api/en/exam/writing/* · /api/en/exam/translation/*）
    # 把公开课与学习博主反复讲的提分技巧落成可交互功能：
    #   写作 —— 评分标准速查 / 三类题型模板骨架 / 高分功能句型 / 基础词升级 /
    #           过渡词库 / 中式英语纠错 / 规则体检 + 可选模型升格
    #   翻译 —— 三步法引导（拆主干→换说法→加被动）/ 文化负载词标准译法 /
    #           逐句结构考点提示 / 译文体检
    # 规则层在 core/english_writing.py，不依赖模型即可用；模型只做锦上添花的升格。
    # ==========================================================================
    from core import english_writing as en_writing

    @application.get("/api/en/exam/writing/kit")
    async def english_exam_writing_kit(request: Request) -> dict[str, Any]:
        """写作工具箱全量数据：评分标准、模板骨架、句型库、升级词库、过渡词、纠错规则。"""
        owner = en_owner(request)
        gems = en_exam_store().list_gems(owner, kind="writing")
        return en_writing.writing_kit(gems)

    @application.post("/api/en/exam/writing/check")
    async def english_exam_writing_check(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """写作体检：字数、段落结构、中式英语、可升级词汇、过渡词、句式多样性、分档粗估。

        纯规则，毫秒级返回，随写随查。
        """
        en_owner(request)
        text = str(payload.get("text") or "").strip()
        if not text:
            raise en_error(400, "english_missing_essay", "请先粘贴你的作文正文。")
        result = en_writing.check_writing(text)
        result["topic"] = str(payload.get("topic") or "").strip()
        return result

    @application.post("/api/en/exam/writing/polish")
    def english_exam_writing_polish(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """作文升格：模型按评分标准给分档点评、逐处修改与升格范文。

        模型不可用时退回规则体检报告，前端会挂「规则版」提示，不让功能整个塌掉。
        """
        en_owner(request)
        text = str(payload.get("text") or "").strip()
        if not text:
            raise en_error(400, "english_missing_essay", "请先粘贴你的作文正文。")
        topic = str(payload.get("topic") or "").strip()
        rule_report = en_writing.check_writing(text)

        llm = getattr(application.state, "llm", None)
        if llm is not None:
            try:
                system_prompt = (
                    "你是四六级写作阅卷与提分专家，熟悉公开评分标准与主流提分讲法。"
                    "请按评分标准给用户的作文做一次升格批改。要求：\n"
                    "1) 先给分档判断（13–15 / 10–12 / 7–9 / 4–6 / 1–3），并说明依据；\n"
                    "2) 指出优点与硬伤，硬伤要具体到句子；\n"
                    "3) 逐处给出修改建议（原句 → 改后 → 为什么改），优先改语法错误和中式英语；\n"
                    "4) 给出升格后的完整范文，保持用户的原有观点与分论点，不要换题目；\n"
                    "5) 给出这篇题目的三段式骨架建议。\n"
                    "所有英文表达必须语法正确、地道，不要为了高级而堆砌生僻词。"
                    "在升格时，可适度使用倒装、强调句、非谓语动词、同位语、插入语等高级句式与学术搭配，"
                    "并避免 with the development of / as we all know / every coin has two sides 等套话。"
                    "要求输出合法 JSON：\n"
                    "{\n"
                    '  "band": "10–12 分",\n'
                    '  "band_reason": "为什么落这一档",\n'
                    '  "strengths": ["优点1", "优点2"],\n'
                    '  "fixes": [{"original": "原句", "improved": "改后", "reason": "改动理由"}],\n'
                    '  "upgraded_essay": "升格后的完整范文",\n'
                    '  "skeleton": [{"para": "开篇段", "role": "作用", "advice": "这段该怎么写"}]\n'
                    "}"
                )
                resp = llm.complete_json(
                    "english_writing_polish",
                    {
                        "topic": topic or "（用户未填写题目）",
                        "essay": text,
                        "system_prompt": system_prompt,
                    },
                )
                if (
                    isinstance(resp, dict)
                    and str(resp.get("upgraded_essay") or "").strip()
                ):
                    return {
                        "ok": True,
                        "ai_generated": True,
                        "topic": topic,
                        "band": str(resp.get("band") or "").strip(),
                        "band_reason": str(resp.get("band_reason") or "").strip(),
                        "strengths": resp.get("strengths")
                        if isinstance(resp.get("strengths"), list)
                        else [],
                        "fixes": resp.get("fixes")
                        if isinstance(resp.get("fixes"), list)
                        else [],
                        "upgraded_essay": str(resp.get("upgraded_essay") or "").strip(),
                        "skeleton": resp.get("skeleton")
                        if isinstance(resp.get("skeleton"), list)
                        else [],
                        "rule_report": rule_report,
                    }
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning("english_exam_writing_polish LLM failed: %s", exc)

        return {
            "ok": True,
            "ai_generated": False,
            "topic": topic,
            "rule_report": rule_report,
            "notice": "TJU-LLM 暂时不可用，下面是规则体检报告（字数 / 结构 / 中式英语 / 可升级词），稍后可重试升格。",
        }

