    @application.post("/api/en/exam/translation/guide")
    async def english_exam_translation_guide(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """翻译三步法引导：逐句拆意群、给主干候选、标结构考点与文化词标准译法。

        只给脚手架不代译 —— 用户自己动手译，卡在哪一步看得见。
        """
