    async def english_exam_translation_check(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """译文体检：中式英语、长度比、文化词覆盖、被动语态漏转、专有名词大写。"""
        en_owner(request)
        zh_text = str(payload.get("source") or "").strip()
        en_text = str(payload.get("target") or "").strip()
