    @application.post("/api/en/exam/writing/demo")
    def english_exam_writing_demo(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """一键演示：按题型出题 → 写范文 → 自己给自己升格。

        给「懒得输入」的用户一条龙，不用自己写一个字就能看完整流程。
        模型负责出题与写，规则层负责体检；模型不可用时退回题库种子范文，
        所以这个端点永远有东西可看。每次演示的结果都会留存进历史，并把
        逐处修改沉淀成工具箱里的精华。
        """
        owner = en_owner(request)
        template_id = str(payload.get("template_id") or "").strip()
        seed = en_writing.writing_demo_seed(template_id)

        llm = getattr(application.state, "llm", None)
        if llm is not None:
            try:
                system_prompt = (
                    "你是四六级写作命题与阅卷专家。请按给定作文题型出一道贴近历年真题风格的题目，"
                    "亲自写一篇高分范文，再对这篇范文做一次自我升格批改。要求：\n"
                    "1) 题目具体可写，避免空泛；同时给出中文题干与英文题干；\n"
                    "2) 范文严格按该题型的段落骨架展开，150–180 词，三到四段，"
                    "每段有明确功能句，用恰当的过渡词，不得出现中式英语；\n"
                    "3) 自我批改按四六级评分口径给出分档、依据、优点、逐处修改建议与升格后范文；\n"
                    "4) 升格范文保留原范文的观点与分论点，只提升语言质量；\n"
                    "5) 所有英文必须语法正确、地道，不要为高级而堆砌生僻词。\n"
                    "要求输出合法 JSON：\n"
                    "{\n"
                    '  "topic_zh": "中文题干",\n'
                    '  "topic_en": "English prompt",\n'
                    '  "essay": "150–180 词范文，段落之间用空行分隔",\n'
                    '  "band": "10–12 分",\n'
                    '  "band_reason": "为什么落这一档",\n'
                    '  "strengths": ["优点1", "优点2"],\n'
                    '  "fixes": [{"original": "原句", "improved": "改后", "reason": "改动理由"}],\n'
                    '  "upgraded_essay": "升格后的完整范文",\n'
                    '  "skeleton": [{"para": "开篇段", "role": "作用", "advice": "这段该怎么写"}]\n'
                    "}"
                )
                resp = llm.complete_json(
                    "english_writing_demo",
                    {
                        "template_id": seed["template_id"],
                        "template_name": seed["template_name"],
                        "topic_zh": seed["topic_zh"],
                        "reference_essay": seed["essay"],
                        "system_prompt": system_prompt,
                    },
                )
                essay = (
                    str(resp.get("essay") or "").strip()
                    if isinstance(resp, dict)
                    else ""
                )
                # 字数不够就是没写出来，宁可退回种子范文，也别把半成品端给用户
                if essay and en_writing.check_writing(essay)["words"] >= 120:
                    result = {
                        "ok": True,
                        "ai_generated": True,
                        "template_id": seed["template_id"],
                        "template_name": seed["template_name"],
                        "topic_zh": str(
                            resp.get("topic_zh") or seed["topic_zh"]
                        ).strip(),
                        "topic_en": str(
                            resp.get("topic_en") or seed["topic_en"]
                        ).strip(),
                        "essay": essay,
                        "band": str(resp.get("band") or "").strip(),
                        "band_reason": str(resp.get("band_reason") or "").strip(),
                        "strengths": resp.get("strengths")
                        if isinstance(resp.get("strengths"), list)
                        else [],
                        "fixes": resp.get("fixes")
                        if isinstance(resp.get("fixes"), list)
                        else [],
                        "upgraded_essay": str(resp.get("upgraded_essay") or "").strip(),
                        "skeleton": resp.get("skeleton")
                        if isinstance(resp.get("skeleton"), list)
                        else [],
                        "rule_report": en_writing.check_writing(essay),
                    }
                    _persist_writing_demo(owner, template_id, result)
                    return result
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning("english_exam_writing_demo LLM failed: %s", exc)

        _persist_writing_demo(owner, template_id, seed)
        return seed

    @application.post("/api/en/exam/translation/demo")
    def english_exam_translation_demo(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """一键演示：按标签出题 → 自己译一版 → 自己体检。

        中文段落固定取自题库（三步法引导才有确定的考点可讲），模型只负责另译一版；
        模型不可用时题库参考译文就是最终结果。每次演示的结果都会留存进历史，并把
        译法笔记沉淀成工具箱里的精华。
        """
        owner = en_owner(request)
        category = str(payload.get("category") or "").strip()
        seed = en_writing.translation_demo_seed(category)

        llm = getattr(application.state, "llm", None)
        if llm is not None:
            try:
                system_prompt = (
                    "你是四六级翻译阅卷与教学专家。给定一段中文，请按四六级翻译评分标准译出英文。要求：\n"
                    "1) 先找准句子主干，再处理定语、状语与并列结构，不要逐字硬译；\n"
                    "2) 文化负载词用约定俗成的标准译法；\n"
                    "3) 中文的被动、无主句、长定语要按英语习惯转换，不得出现中式英语；\n"
                    "4) 专有名词与术语首字母大写要规范。\n"
                    "要求输出合法 JSON：\n"
                    "{\n"
                    '  "translation": "完整英文译文",\n'
                    '  "notes": [{"zh": "中文片段", "en": "译法", "reason": "为什么这样处理"}]\n'
                    "}"
                )
                resp = llm.complete_json(
                    "english_translation_demo",
                    {
                        "category": seed["category"],
                        "title": seed["title"],
                        "source": seed["source"],
                        "reference": seed["reference"],
                        "system_prompt": system_prompt,
                    },
                )
                target = (
                    str(resp.get("translation") or "").strip()
                    if isinstance(resp, dict)
                    else ""
                )
                if target:
                    result = {
                        "ok": True,
                        "ai_generated": True,
                        "category": seed["category"],
                        "title": seed["title"],
                        "source": seed["source"],
                        "target": target,
                        "reference": seed["reference"],
                        "notes": resp.get("notes")
                        if isinstance(resp.get("notes"), list)
                        else [],
                        "guide": seed["guide"],
                        "check": en_writing.check_translation(seed["source"], target),
                    }
                    _persist_translation_demo(owner, category, result)
                    return result
            except Exception as exc:  # noqa: BLE001
                LOGGER.warning("english_exam_translation_demo LLM failed: %s", exc)

        _persist_translation_demo(owner, category, seed)
        return seed

