    @application.post("/api/projects/{project_id}/chat")
    def chat(
        project_id: str, payload: ChatRequest, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        # 会话归属（Agent 布局的「每个项目多个会话」）：空串 = 项目默认单线程。
        cid = str(payload.conversation_id or "")
        before_ids = {
            message.message_id
            for message in db.list_messages(project_id, conversation_id=cid)
        }
        usage_reply = _usage_help_reply(payload.message)
        if usage_reply is not None:
            result = _casual_chat_action(
                db, project_id, payload.message, usage_reply, cid
            )
        else:
            casual_reply = _casual_chat_reply(payload.message)
            if casual_reply is not None:
                result = _casual_chat_action(
                    db, project_id, payload.message, casual_reply, cid
                )
            else:
                result = _study_action(
                    application,
                    db,
                    project_id,
                    payload.message,
                    payload.node_ids,
                    payload.source_ids,
                    "question",
                    conversation_id=cid,
                )
        record_message_append(
            user, project_id, before_ids, f"提问「{payload.message[:24]}」", cid
        )
        return result

    @application.post("/api/projects/{project_id}/chat/stream")
    def chat_stream(
        project_id: str, payload: ChatRequest, request: Request
    ) -> StreamingResponse:
        """流式问答：SSE 逐块返回答案。

        原 /chat 要等模型整段输出完（弱模型常 10~30 秒）才返回，用户只能对着空白等。
        这里边生成边推送；命中节点与来源放在首个 meta 事件，落库结果放在末尾 done 事件。
        ponytail: 只覆盖纯文本提问；题目截图仍走 /solve-image，不重复实现视觉链路。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        # 会话归属：空串 = 项目默认单线程（老布局与老数据都走这一条，行为不变）
        cid = str(payload.conversation_id or "")
        before_ids = {
            message.message_id
            for message in db.list_messages(project_id, conversation_id=cid)
        }

        usage_reply = _usage_help_reply(payload.message)
        if usage_reply is not None:
            result = _casual_chat_action(
                db, project_id, payload.message, usage_reply, cid
            )
            record_message_append(
                user, project_id, before_ids, f"提问「{payload.message[:24]}」", cid
            )

            async def usage_stream() -> Any:
                yield f"data: {json.dumps({'type': 'meta', 'node_ids': [], 'source_ids': [], 'confidence': 0.0}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'done', **result}, ensure_ascii=False)}\n\n"

            return StreamingResponse(
                usage_stream(),
                media_type="text/event-stream",
                headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
            )

        casual_reply = _casual_chat_reply(payload.message)
        if casual_reply is not None:
            result = _casual_chat_action(
                db, project_id, payload.message, casual_reply, cid
            )
            record_message_append(
                user, project_id, before_ids, f"提问「{payload.message[:24]}」", cid
            )

            async def casual_stream() -> Any:
                yield f"data: {json.dumps({'type': 'meta', 'node_ids': [], 'source_ids': [], 'confidence': 0.0}, ensure_ascii=False)}\n\n"
                yield f"data: {json.dumps({'type': 'done', **result}, ensure_ascii=False)}\n\n"

            return StreamingResponse(
                casual_stream(),
                media_type="text/event-stream",
                headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
            )

        # Agent 模式（前端开关打开时）：与知识库 Agent 面板共用同一段 Function Calling
        # 工具循环，模型自己决定检索资料 / 查掌握度 / 改知识库，而不是把检索片段一次性
        # 塞进 prompt 猜答案。关掉开关（或模型压根不可用）就继续走下面的原 RAG 链路。
        # require_write_confirmation=True：写库动作只登记、不落库，改由对话区的确认卡片
        # 调 /agent/actions/execute 执行 —— 这一屏没有 kb 面板的收敛条与建议稿审批流。
        if payload.agent:
            llm_ready = bool(
                application.state.settings.tju_api_key
                or application.state.llm.responder is not None
            )
            if llm_ready:
                return _agent_stream_impl(
                    project_id,
                    payload,
                    request,
                    auto_create_conversation=bool(cid),
                    require_write_confirmation=True,
                )

        all_sources = db.list_sources(project_id)
        valid_source_ids = {source.source_id for source in all_sources}
        if payload.source_ids is None:
            selected_source_ids = valid_source_ids
        else:
            selected_source_ids = {
                sid for sid in payload.source_ids if sid in valid_source_ids
            }
        sources = [
            source
            for source in all_sources
            if source.source_id in selected_source_ids
            and source.status == "ok"
            and source.text.strip()
        ]
        active_source_ids = {source.source_id for source in sources}
        all_nodes = db.list_framework_nodes(project_id)
        nodes = [
            node
            for node in all_nodes
            if payload.source_ids is None
            or not node.source_ids
            or any(sid in active_source_ids for sid in node.source_ids)
        ]
        node_ids, confidence = _map_nodes(payload.message, payload.node_ids, nodes)
        source_ids = sorted(
            {
                sid
                for node in nodes
                if node.node_id in node_ids
                for sid in node.source_ids
                if sid in active_source_ids
            }
        )
        excerpts = source_excerpts(sources, query=payload.message)
        model_payload = {
            "question": payload.message,
            "sources": excerpts,
            "nodes": [
                {
                    "node_id": node.node_id,
                    "name": node.name,
                    "description": node.description,
                }
                for node in nodes
                if node.node_id in node_ids
            ],
        }
        # 引导/严格档要判断"第几次尝试"，但本链路只把当前这一问发给模型 ——
        # 先把最近几轮绑到 contextvar，stream_system_prompt 里的阶梯才读得到轮次。
        #
        # 2026-09-26 第五轮：试过把历史还原成**真正的 messages 数组**插在下面，
        # 真机三轮采样全部是负收益 —— 6 轮触发 7382 字的复读崩坏、2 轮触发 100%
        # 逐字重复、只带用户侧则把话题锁死在上一句（用户说「不知道」，它还在追问
        # 上一句的「上升」）。tju-llm 见到自己上一轮的回复会去**复制它**而不是推进，
        # 所以维持摘要塞 system。真正解决"听不懂 / 判不了对错"的是把提示词削短
        # （见 core/teaching_mode.py 的 _MODE_BRIEF / _HARD_RULES）。
        history_token = teaching_mode_mod.set_active_history(
            _teaching_history_block(db, project_id, cid)
        )
        try:
            sys_prompt = stream_system_prompt("answer_question")
        finally:
            teaching_mode_mod.reset_active_history(history_token)
        if getattr(payload, "pet", False):
            sys_prompt += (
                "\n\n【桌面宠·海小棠】当前问题由桌面宠「海小棠」代用户提出。"
                "请以温柔、耐心、亲切、像贴心陪伴般的口吻回答，内容简洁清楚、有温度；"
                "如引用了课程资料或校园资讯，请在行内注明来源。"
                "不要把本提示写进答复正文。"
            )
        messages = [
            {"role": "system", "content": sys_prompt},
            {
                "role": "user",
                "content": json.dumps(
                    {"task": "answer_question", "payload": model_payload},
                    ensure_ascii=False,
                ),
            },
        ]
        # 撤销基线：流式过程中新写入的消息在撤销时应被移除
        before_ids = {
            message.message_id
            for message in db.list_messages(project_id, conversation_id="")
        }

        def _sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream() -> Any:
            yield _sse(
                {
                    "type": "meta",
                    "node_ids": node_ids,
                    "source_ids": source_ids,
                    "confidence": confidence,
                }
            )
            answer_parts: list[str] = []
            held: list[str] = []  # 已收到、但还没判定"是不是 JSON 外壳"的片段
            prose = False  # 已判定是普通正文 → 之后逐块直发
            shelled = False  # JSON 外壳已剥掉、正文已发完
            try:
                # 真异步流式：用 httpx.AsyncClient 全程留在事件循环里，
                # 不再用 asyncio.to_thread(next, gen) —— 后者每 chunk 切一次线程，
                # 500 token 就是 500 次线程任务创建，长答案下明显拖慢吞吐。
                async for chunk in llm.astream_chat_content(
                    messages, "answer_question"
                ):
                    if not chunk:
                        continue
                    answer_parts.append(chunk)
                    if shelled:
                        continue
                    if prose:
                        yield _sse({"type": "delta", "text": chunk})
                        continue
                    # 形态未定：先攒着。教学模式偶发把整段答案包成 {"title","content"}，
                    # 逐块直发的话用户会在气泡里看到裸 JSON（真机截图已复现），
                    # 而 app.js 的 stripAnswerJsonWrapper 只认 answer 字段、又属硬约束不能改
                    # —— 所以这里等外壳闭合、剥掉后再发正文。引导轮回复本就 2~4 句，
                    # 等一下远比看到一坨 JSON 好；普通正文首个非空 chunk 就放行，无感。
                    held.append(chunk)
                    buffered = "".join(held)
                    if not buffered.lstrip():
                        continue
                    if buffered.lstrip().startswith("{"):
                        # 用 _shell_end 而不是 _first_json_object：后者的 json.loads 会被
                        # LaTeX 反斜杠（\pi / \delta）判成非法转义，外壳永远认不出来，
                        # 于是整段原文被攒到流结束才在兜底分支直发 —— 用户照样看到裸 JSON。
                        if _shell_end(buffered.lstrip()) >= 0:
                            unwrapped = _unwrap_answer_json(buffered)
                            shelled = True
                            held = []
                            if unwrapped.strip():
                                yield _sse({"type": "delta", "text": unwrapped})
                        # 否则：以 { 开头但外壳还没闭合 → 继续攒
                        continue
                    # 另一种漏法：模型不写 JSON，直接以 `content: ...` 起头（同一锚点）。
                    # 形态判定期间要连"可能正在写标签词"（`cont`）一起等 —— 否则
                    # `content:` 会被拆成两个 delta 直发，用户照样看到那截字段名。
                    label_state = _field_label_state(buffered)
                    if label_state == "maybe":
                        continue
                    prose = True
                    tail_text = (
                        _strip_field_label(buffered)
                        if label_state == "label"
                        else buffered
                    )
                    held = []
                    if tail_text.strip():
                        yield _sse({"type": "delta", "text": tail_text})
            except (ModelApiError, ModelOutputError) as exc:
                yield _sse({"type": "error", "message": str(exc)})
                return
            except Exception as exc:  # noqa: BLE001 - SSE 里任何异常都要变成事件
                LOGGER.exception("chat stream failed project=%s", project_id)
                yield _sse({"type": "error", "message": f"流式生成失败：{exc}"})
                return

            # 兜底：外壳始终没闭合（或不是外壳）时，别把攒下的内容吞掉。
            if not prose and not shelled:
                tail = _unwrap_answer_json("".join(held))
                if tail.strip():
                    yield _sse({"type": "delta", "text": tail})

            answer = _strip_thought_blocks(
                _unwrap_answer_json("".join(answer_parts)).strip()
            )
            # 普通对话流没有工具累加器，但模型可能被历史里的调用格式带跑（它的系统提示词
            # 自称「学习辅导 Agent」，而会话历史里存着 Agent 模式用过的 JSON 调用），
            # 于是把调用格式当正文吐出来。必须在收尾处摘掉，否则既显示给用户也存进库。
            answer = _strip_literal_tool_calls(answer)
            if not answer:
                yield _sse({"type": "error", "message": "模型未返回任何内容。"})
                return
            # 先落用户消息、再用它的 id 写证据 —— reference_id 指向原话，审计可直达。
            question_message = db.add_message(
                project_id, "user", payload.message, node_ids, source_ids,
                conversation_id=cid,
            )
            if node_ids:
                # 提问默认不给正确度（与 /chat 的 question 语义一致）
                record_evidence(
                    db,
                    project_id,
                    node_ids,
                    "question",
                    None,
                    confidence,
                    reference_id=question_message.message_id,
                )
            assistant_message = db.add_message(
                project_id, "assistant", answer, node_ids, source_ids,
                conversation_id=cid,
            )
            record_message_append(
                user, project_id, before_ids, f"提问「{payload.message[:24]}」", cid
            )
            # 字段与非流式 /chat 保持一致，前端可复用同一套 appendMessage 渲染逻辑
            yield _sse(
                {
                    "type": "done",
                    "answer": answer,
                    "answer_segments": [],
                    "node_ids": node_ids,
                    "source_ids": source_ids,
                    "question": model_to_dict(question_message),
                    "message": model_to_dict(assistant_message),
                    "question_message_id": question_message.message_id,
                    "message_id": assistant_message.message_id,
                    "question_created_at": model_to_dict(question_message)[
                        "created_at"
                    ],
                    "message_created_at": model_to_dict(assistant_message)[
                        "created_at"
                    ],
                    "source_refs": [
                        {
                            "source_id": sid,
                            "filename": next(
                                (s.filename for s in sources if s.source_id == sid), ""
                            ),
                        }
                        for sid in source_ids
                    ],
                }
            )

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "X-Accel-Buffering": "no",  # 禁止反代缓冲，保证逐块到达
            },
        )

    # ============================================================
    # AI 同学讨论模式：开局 start + 推进 act（T5）
    # 会话状态存于 kb_conversations.summary(JSON)；消息落 messages。
    # 请求模型 DiscussionStartRequest/DiscussionActRequest 定义在模块顶层。
    # ============================================================
    def _sse_discussion(event: dict[str, Any]) -> str:
        return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

    def _discussion_state(conversation: dict[str, Any]) -> dict[str, Any]:
        st = conversation.get("summary") or {}
        return {
            "stage": st.get("stage", OPEN),
            "round": int(st.get("round", 1) or 1),
            "node_id": conversation.get("node_id", ""),
            "topic": st.get("topic", conversation.get("title", "")),
            "source": st.get("source", ""),
            "quote": st.get("quote") or None,
            "last_consensus": st.get("last_consensus") or "",
            # 推进账本：已说过的要点（防复述）+ 上一轮未对齐的分歧（供插入收分歧环节）
            "said": list(st.get("said") or []),
            "last_tension": st.get("last_tension") or "",
            "last_persona": st.get("last_persona") or "",
        }

    def _discussion_ledger(state: dict[str, Any]) -> dict[str, Any]:
        """本轮的跨轮账本：共识 / 已说过要点 / 未对齐分歧 / 上一位发言人。"""
        return {
            "consensus": state.get("last_consensus") or "",
            "said": state.get("said") or [],
            "tension": state.get("last_tension") or "",
            "last_persona": state.get("last_persona") or "",
        }

    @application.post("/api/projects/{project_id}/discussion/start")
    def discussion_start(
        project_id: str, request: Request, payload: DiscussionStartRequest = Body(...)
    ) -> StreamingResponse:
        user = require_user(request)
        require_project_access(project_id, request)
        anchor = anchor_discussion_source(db, project_id, payload.node_id)
        if not anchor:
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "node_not_found", "该知识点不存在或暂无可锚定资料。"
                ),
            )
        conversation = db.create_conversation(
            project_id,
            user.user_id,
            node_id=anchor["node_id"],
            title=f"讨论·{anchor['topic']}",
        )
        conv_id = conversation["conversation_id"]
        db.update_conversation_summary(
            conv_id,
            {
                "kind": "discussion",
                "stage": OPEN,
                "round": 1,
                "topic": anchor["topic"],
                "source": anchor["source_text"],
                "quote": (payload.quote or "").strip() or None,
            },
        )

        async def event_stream() -> Any:
            current_stage = OPEN
            turn = next_step(current_stage, round_offset=0)
            yield _sse_discussion(
                {
                    "type": "meta",
                    "conversation_id": conv_id,
                    "node_id": anchor["node_id"],
                    "stage": OPEN,
                    "round": 1,
                    "persona": turn.persona,
                    "ask_user": turn.ask_user,
                    "move": turn.move,
                }
            )
            messages = build_turn_messages(
                turn.persona,
                anchor["topic"],
                anchor["source_text"],
                [],
                turn.instruction,
                quote=(payload.quote or "").strip() or None,
            )
            parts: list[str] = []
            try:
                async for chunk in llm.astream_chat_content(
                    messages, "discussion_speak"
                ):
                    if not chunk:
                        continue
                    parts.append(chunk)
                    yield _sse_discussion({"type": "delta", "text": chunk})
            except (ModelApiError, ModelOutputError) as exc:
                yield _sse_discussion({"type": "error", "message": str(exc)})
                return
            except Exception as exc:  # noqa: BLE001
                LOGGER.exception("discussion start failed project=%s", project_id)
                yield _sse_discussion(
                    {"type": "error", "message": f"讨论生成失败：{exc}"}
                )
                return
            # 同上：讨论流也共用会话历史，模型可能被历史里的调用格式带跑。
            text = _strip_literal_tool_calls(_strip_thought_blocks("".join(parts)).strip())
            if not text:
                yield _sse_discussion(
                    {"type": "error", "message": "模型未返回任何内容。"}
                )
                return
            db.add_message(
                project_id,
                "assistant",
                f"{turn.persona}：{text}",
                node_ids=[anchor["node_id"]],
                conversation_id=conv_id,
                meta={
                    "discussion": True,
                    "stage": current_stage,
                    "round": 1,
                    "persona": turn.persona,
                    "ask_user": turn.ask_user,
                },
            )
            next_stage = transition(current_stage)
            db.update_conversation_summary(
                conv_id,
                {
                    "kind": "discussion",
                    "stage": next_stage,
                    "round": 1,
                    "topic": anchor["topic"],
                    "source": anchor["source_text"],
                    "quote": (payload.quote or "").strip() or None,
                },
            )
            yield _sse_discussion(
                {
                    "type": "done",
                    "stage": next_stage,
                    "round": 1,
                    "next_persona": persona_for_stage(next_stage, round_offset=0),
                }
            )

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @application.post("/api/projects/{project_id}/discussion/act")
    def discussion_act(
        project_id: str, request: Request, payload: DiscussionActRequest = Body(...)
    ) -> StreamingResponse:
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            conversation = db.get_conversation(payload.conversation_id)
        except KeyError:
            raise HTTPException(
                status_code=404,
                detail=error_payload("conv_not_found", "讨论会话不存在"),
            )
        if conversation.get("project_id") != project_id:
            raise HTTPException(
                status_code=404,
                detail=error_payload("conv_not_found", "讨论会话不存在"),
            )
        state = _discussion_state(conversation)
        current_stage = state["stage"]
        need_reply = (
            current_stage == "wait_user"
            and not payload.listen_only
            and not payload.force_skip  # 自由对话：可点「继续讨论」跳过作答
            and not (payload.user_reply or "").strip()
        )
        if need_reply:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "discussion_need_reply", "该环节需要你先回答，再继续讨论。"
                ),
            )

        # 先记录用户发言与掌握度，再流式产同学反馈。
        # 关键修正：不管当前在哪个阶段，只要用户发了话就必须被记录、被回应，
        # 不能像以前那样只在 wait_user 才存（否则用户打字=石沉大海，"AI 不鸟我"）。
        user_reply = (payload.user_reply or "").strip()
        has_reply = bool(user_reply) and not payload.listen_only
        learner = {"reply": user_reply, "correct": payload.correct}
        if has_reply:
            reply_message = db.add_message(
                project_id,
                "user",
                user_reply,
                node_ids=[state["node_id"]] if state["node_id"] else None,
                conversation_id=payload.conversation_id,
                meta={"discussion": True, "self_correct": bool(payload.correct)},
            )
            if state["node_id"]:
                is_right = bool(payload.correct)
                # ⚠️ 这里的 confidence 是**映射置信度**（由「答对/答错」推导），不是学习者把握度；
                # discuss 的 correctness 本身来自 UI 上一句「我答对了」，已经不可靠，
                # 所以本处不采集 self_confidence —— 别往它上面再叠一层自评。
                record_evidence(
                    db,
                    project_id,
                    [state["node_id"]],
                    "discuss",
                    correctness=1.0 if is_right else None,
                    confidence=0.95 if is_right else 0.60,
                    reference_id=reply_message.message_id,
                )

        ledger = _discussion_ledger(state)
        ledger["learner"] = learner
        # 用户一开口，下一步必定是「回应学习者」的 assess 轮，而不是自顾自往下推；
        # 没开口但点了「继续讨论」跳过作答时，也照旧推进（保持原行为）。
        next_stage = (
            ASSESS
            if (has_reply or (current_stage == "wait_user" and not payload.listen_only))
            else transition(
                current_stage, payload.user_reply, payload.listen_only, context=ledger
            )
        )
        round_no = state["round"]

        async def event_stream() -> Any:
            nonlocal round_no, next_stage, ledger
            # 自由对话：把账本（已确认共识 + 已说过要点 + 未对齐分歧）注入每一步，
            # 保证每轮都在推进，不重讲已经说清的部分；有分歧时由第三人先收分歧再往下走。
            turn = next_step(
                next_stage,
                payload.listen_only,
                round_offset=round_no - 1,
                context=ledger,
            )
            transcript = [
                f"（你）：{m.content}" if m.role == "user" else m.content
                for m in db.list_conversation_messages(
                    project_id, payload.conversation_id
                )
            ]
            messages = build_turn_messages(
                turn.persona,
                state["topic"],
                state["source"],
                transcript,
                turn.instruction,
                quote=state.get("quote") or None,
                ledger=ledger,
                learner=learner if has_reply else None,
            )
            yield _sse_discussion(
                {
                    "type": "meta",
                    "conversation_id": payload.conversation_id,
                    "node_id": state["node_id"],
                    "stage": next_stage,
                    "round": round_no,
                    "persona": turn.persona,
                    "ask_user": turn.ask_user,
                    "move": turn.move,
                }
            )
            parts: list[str] = []
            try:
                async for chunk in llm.astream_chat_content(
                    messages, "discussion_speak"
                ):
                    if not chunk:
                        continue
                    parts.append(chunk)
                    yield _sse_discussion({"type": "delta", "text": chunk})
            except (ModelApiError, ModelOutputError) as exc:
                yield _sse_discussion({"type": "error", "message": str(exc)})
                return
            except Exception as exc:  # noqa: BLE001
                LOGGER.exception("discussion act failed project=%s", project_id)
                yield _sse_discussion(
                    {"type": "error", "message": f"讨论生成失败：{exc}"}
                )
                return
            # 同上：讨论流也共用会话历史，模型可能被历史里的调用格式带跑。
            text = _strip_literal_tool_calls(_strip_thought_blocks("".join(parts)).strip())
            if not text:
                yield _sse_discussion(
                    {"type": "error", "message": "模型未返回任何内容。"}
                )
                return
            db.add_message(
                project_id,
                "assistant",
                f"{turn.persona}：{text}",
                node_ids=[state["node_id"]] if state["node_id"] else None,
                conversation_id=payload.conversation_id,
                meta={
                    "discussion": True,
                    "stage": next_stage,
                    "round": round_no,
                    "persona": turn.persona,
                    "ask_user": turn.ask_user,
                },
            )
            # 账本回写：本轮发言压成「已说过要点」防后续复述；粗判是否留下未对齐分歧
            said_points = list(state.get("said") or [])
            point = compress_point(text)
            if point:
                said_points.append(point)
            ledger = {
                "consensus": state.get("last_consensus") or "",
                "said": said_points[-8:],
                "tension": "" if next_stage == ARBITRATE else detect_tension(text),
                "last_persona": turn.persona,
            }
            after = transition(
                next_stage, payload.user_reply, payload.listen_only, context=ledger
            )
            # 收束判定：只听连播模式下，一旦同学在 conclude 阶段明确把共识收拢住就自然收束，
            # 而不是被轮数硬切断（用户反馈的「没有收束」）；交互模式交给用户随时停。
            finished = bool(
                next_stage == "conclude"
                and payload.listen_only
                and detect_convergence(text)
            )
            round_no += (
                1  # 自由对话：每成功推进一步，推进序号 +1，供认知层面/分工轮换来取模
            )
            summary_update = {
                "kind": "discussion",
                "stage": after,
                "round": round_no,
                "topic": state["topic"],
                "source": state["source"],
                "quote": state.get("quote"),
                "said": ledger["said"],
                "last_tension": ledger["tension"],
                "last_persona": ledger["last_persona"],
            }
            if next_stage == "conclude" and text.strip():
                # 温和小结达成：存入当前已共同确定的结论，供后续小段接续引用（累积共识）
                summary_update["last_consensus"] = text.strip()
            db.update_conversation_summary(payload.conversation_id, summary_update)
            yield _sse_discussion(
                {
                    "type": "done",
                    "stage": after,
                    "round": round_no,
                    "finished": finished,
                    "next_persona": persona_for_stage(
                        after,
                        payload.listen_only,
                        round_offset=round_no - 1,
                        avoid=turn.persona,
                    ),
                }
            )

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    _AGENT_FINALIZE_INSTRUCTION = (
        "请基于刚才已执行的工具查询结果，针对我最初的问题「{question}」，"
        "用中文给出最终的、结构化的整理/汇报正文。"
        "这一步不要再调用任何工具（关键：不要输出 tool_calls），也不要再用 JSON 或任何标签包裹顶层；"
        "直接输出可读的段落式回答。若依据不足，请明确指出缺什么。"
    )

    def _agent_answer_nonstream(
        llm: Any,
        messages: list[dict[str, Any]],
        *,
        db: Any,
        project_id: str,
        sources: list[Any],
        nodes: list[Any],
        owner_id: str | None,
        conversation_id: str | None,
        question: str,
    ) -> tuple[str, list[dict[str, Any]], bool]:
        """非流式工具循环（旧版 /agent 的完整逻辑），供流式主路径异常时整包兜底。

        返回 (answer, trace, used_tools)。多轮工具循环最多 3 轮，模型没生成有效正文时
        走「收尾合写」再走 _agent_trace_answer，保证任何情况下都有可读回答。
        """
        trace: list[dict[str, Any]] = []
        used_tools = False
        rounds = 0

        def _res_with_literal_normalized(res: dict[str, Any]) -> dict[str, Any]:
            # 文字伪工具调用兜底：模型把工具调用吐成 <function=...> 正文时，
            # 归一化为与原生 tool_calls 一致的形态，确保裸 XML 不会进入最终回答。
            if res.get("kind") != "tool_calls":
                _lit = _LiteralToolCallAccumulator(
                    {t.get("function", {}).get("name", "") for t in LEARNING_AGENT_TOOLS}
                )
                _lit.feed(res.get("content") or "")
                _lit_call = _lit.pop_call()
                if _lit_call is not None and _lit_call.get("name"):
                    # 两个字段两种形状，别混：
                    #   tool_calls     —— 消费侧（与 llm._normalize_tool_call 同构：扁平 name/arguments）
                    #   raw_tool_calls —— 塞进 messages 的协议形状（嵌套 function）
                    arguments = _agent_call_arguments(_lit_call["arguments"])
                    call = {
                        "id": "lit",
                        "name": _lit_call["name"],
                        "arguments": arguments,
                    }
                    return {
                        "kind": "tool_calls",
                        "tool_calls": [call],
                        "raw_tool_calls": [
                            {
                                "id": "lit",
                                "type": "function",
                                "function": {
                                    "name": _lit_call["name"],
                                    "arguments": json.dumps(
                                        arguments, ensure_ascii=False
                                    ),
                                },
                            }
                        ],
                        "content": "",
                    }
            return res

        res = _res_with_literal_normalized(
            llm.complete_with_tools(messages, "agent_chat", LEARNING_AGENT_TOOLS)
        )
        while (
            res.get("kind") == "tool_calls" and res.get("raw_tool_calls") and rounds < 3
        ):
            rounds += 1
            used_tools = True
            messages.append(
                {
                    "role": "assistant",
                    "content": res.get("content") or "",
                    "tool_calls": res["raw_tool_calls"],
                }
            )
            for call in res["tool_calls"]:
                observation = _run_agent_tool(
                    call["name"],
                    _agent_call_arguments(call["arguments"]),
                    db=db,
                    project_id=project_id,
                    sources=sources,
                    nodes=nodes,
                    owner_id=owner_id,
                    conversation_id=conversation_id,
                    current_llm=llm,
                    # study_kit / exam_scheduler / knowledge_doc 都是 create_app 闭包里的缓存
                    # store（模块级函数拿不到），读取工具要靠它们，且避免每次调用新建 sqlite
                    # 连接 —— StudyKitStore/ExamScheduler/KnowledgeDocStore 的 __init__ 都会
                    # eager 建连接，ExamScheduler 还会在读时建表。
                    study_kit=study_kit_store(),
                    exam_scheduler=exam_scheduler(),
                    knowledge_doc=knowledge_doc_store(),
                )
                trace.append(
                    {
                        "name": call["name"],
                        "arguments": call["arguments"],
                        "observation": observation[:600],
                    }
                )
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": call["id"],
                        "name": call["name"],
                        "content": observation,
                    }
                )
            res = _res_with_literal_normalized(
                llm.complete_with_tools(messages, "agent_chat", LEARNING_AGENT_TOOLS)
            )
        answer = collapse_repeated_lines((res.get("content") or "").strip())
        if answer and _is_degenerate_repetition(answer):
            answer = ""

        if not answer and (used_tools or trace):
            messages.append(
                {
                    "role": "user",
                    "content": _AGENT_FINALIZE_INSTRUCTION.format(question=question),
                }
            )
            try:
                tail = llm.complete_with_tools(
                    messages, "agent_chat", LEARNING_AGENT_TOOLS
                )
                answer = collapse_repeated_lines((tail.get("content") or "").strip())
                if answer and _is_degenerate_repetition(answer):
                    answer = ""
            except Exception:
                answer = ""
        if not answer:
            answer = (
                _agent_trace_answer(trace)
                if trace
                else "我没有生成有效的回答内容。如果刚才是知识库相关的问题，"
                "可以确认项目里已经有可用的知识框架后再试；也可以用更具体的方式重问一次。"
            )
        return answer, trace, used_tools

    # Function Calling 版学习 Agent 的实现体（/agent 与 /chat/stream 的 agent 分支共用）。
    # 保持嵌套在 create_app 内：函数体原本就缩进在这里，抽出去要重排四百多行，没收益。
    def _agent_stream_impl(
        project_id: str,
        payload: ChatRequest,
        request: Request,
        *,
        auto_create_conversation: bool = True,
        require_write_confirmation: bool = False,
    ) -> StreamingResponse:
        """Function Calling 版学习 Agent：由模型自主决定是否调用工具。

        返回 SSE 流（data: {...}），事件类型：
          - delta  正文增量（逐 token 到达，前端边收边渲染）
          - done   终态：answer / conversation_id / 工具轨迹 / 消息 id / 时间戳
          - error  错误（JSON 结构同旧版 error_payload）

        若网关不支持「tools + stream」组合（如返回 400），自动退化为原非流式
        工具循环整包兜底（单次 delta + done），工具能力与旧版完全一致，不报错中断。

        auto_create_conversation：/agent 端点传 True（无会话就新建一条）；
        主界面 /chat/stream 的 agent 分支传 False —— 空 conversation_id 在那里
        表示「项目默认单线程」，与原 RAG 链路的落库口径保持一致，不能偷偷新建会话。

        require_write_confirmation：主界面传 True —— 写库类工具（AGENT_WRITE_TOOLS）
        只登记成待确认动作，由界面的确认卡片决定是否执行；同时工具集收窄到
        AGENT_TOOLS_DEFAULT、轮数放宽到 AGENT_MAX_ROUNDS_WRITABLE。
        /agent 传 False，写操作与工具集与改造前完全一致。
        """
        user = require_user(request)
        require_project_access(project_id, request)

        all_sources = db.list_sources(project_id)
        valid_source_ids = {source.source_id for source in all_sources}
        if payload.source_ids is None:
            selected_source_ids = valid_source_ids
        else:
            selected_source_ids = {
                sid for sid in payload.source_ids if sid in valid_source_ids
            }
        sources = [
            source
            for source in all_sources
            if source.source_id in selected_source_ids
            and source.status == "ok"
            and source.text.strip()
        ]
        active_source_ids = {source.source_id for source in sources}
        nodes = db.list_framework_nodes(project_id)
        scoped_nodes = [
            node
            for node in nodes
            if payload.source_ids is None
            or not node.source_ids
            or any(sid in active_source_ids for sid in node.source_ids)
        ]
        node_ids, confidence = _map_nodes(
            payload.message, payload.node_ids, scoped_nodes
        )

        # —— 会话归属：无则按当前节点新建，有则复用（校验存在性 + 归属一致） ——
        # node_id 为空时视为「库级全局会话」，仍按节点独立过滤下拉会话
        node_id = (payload.node_id or "").strip() or payload.focus_node_id or ""
        # 空 conversation_id：/agent 端点按「没有会话就新建」处理；
        # 主界面 /chat/stream 传 auto_create_conversation=False，此时空串就是
        # 项目默认单线程，必须原样保留，否则老布局的历史会分叉到一条新会话里。
        conversation_id = (payload.conversation_id or "").strip() or (
            None if auto_create_conversation else ""
        )
        if conversation_id is None:
            conv = db.create_conversation(
                project_id, user.user_id, title=payload.message[:40], node_id=node_id
            )
            conversation_id = conv["conversation_id"]
            payload.focus_node_id = payload.focus_node_id or node_id
        elif conversation_id:
            # 两种会话壳都要认：
            #   csess_* → 主界面问答会话（chat_sessions 表，B 线的每项目多会话）
            #   conv_*  → 整理助手会话（kb_conversations 表，/agent 面板自己的）
            # 原来只查 kb_conversations，主界面传 csess_* 进来会直接 404。
            is_main_session = (
                db.get_chat_session(project_id, conversation_id) is not None
            )
            if not is_main_session:
                try:
                    conv = db.get_conversation(conversation_id)
                except KeyError as exc:
                    raise HTTPException(
                        status_code=404,
                        detail=error_payload("conversation_not_found", "会话不存在。"),
                    ) from exc
                # 会话必须归属当前项目，防止旧课程的有效会话 id 被串到新课程
                if conv.get("project_id") != project_id:
                    conversation_id = None

        # —— 知识库现状摘要（长期整体记忆）注入 system ——
        digest_info = db.get_digest(project_id)
        if digest_info is None:
            try:
                digest_info = build_kb_digest(db, project_id, llm)
            except Exception:
                digest_info = build_kb_digest(db, project_id, None)
        digest_text = render_digest_text(digest_info)
        system_prompt = _agent_system_prompt(
            db,
            project_id,
            payload.mode,
            payload.focus_node_id,
            payload.message,
            surface="conversation" if require_write_confirmation else "kb",
        )
        if digest_text:
            system_prompt = f"{system_prompt}\n\n【知识库现状（模型长期记忆，自动生成）】\n{digest_text}"
        # 用户画像素描占位（P2 完善；此处仅读取注入）
        _profile_getter = getattr(db, "get_user_profile", None)
        if callable(_profile_getter):
            try:
                profile = _profile_getter(project_id, user.user_id)
                if isinstance(profile, dict) and profile.get("summary"):
                    system_prompt = f"{system_prompt}\n【用户画像】{profile['summary']}"
            except Exception:
                pass

        messages: list[dict[str, Any]] = [
            {"role": "system", "content": system_prompt},
        ]
        # 会话历史（最近 K=8 轮 user/assistant）
        _CONVERGE_UX = {
            "apply": "（用户已确认进入下一步）",
            "redo": "（用户重做当前题）",
            "stop": "（用户停止引导）",
        }
        for m in db.list_conversation_messages(project_id, conversation_id)[-16:]:
            if m.role in ("user", "assistant") and m.content:
                content = m.content
                # 历史里若残留裸收敛 token，统一换成中性描述，避免模型每轮再被误导成元推理循环
                if m.role == "user":
                    lowered = content.strip().lower()
                    if lowered in _CONVERGE_UX:
                        content = _CONVERGE_UX[lowered]
                messages.append({"role": m.role, "content": content})
        messages.append({"role": "user", "content": payload.message})

        def _sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream() -> Any:
            answer_parts: list[str] = []
            trace: list[dict[str, Any]] = []
            used_tools = False
            rounds = 0
            # 本轮工具留下的痕迹：资料命中（[n] → source_id）与待用户确认的写操作。
            # 两者都只在这一次请求内存活，done 事件里带给前端，不落库。
            cited_sources: dict[int, dict[str, Any]] = {}
            # 写操作闸门只在主界面对话区启用（require_write_confirmation）。
            # kb 面板必须是 None —— 传空列表同样会触发闸门，那边的收敛条就是执行入口。
            staged_actions: list[dict[str, Any]] | None = (
                [] if require_write_confirmation else None
            )
            source_by_id = {source.source_id: source for source in sources}
            try:
                # apply / redo / stop 三个收敛键由界面按钮承载语义，统一在进入模型工具循环前短路处理：
                #   stop  确定性停止，完全不进模型（杜绝死循环）；
                #   redo  原样重出当前题（单次、无工具生成，指令明确）；
                #   apply 出下一道新题（单次、无工具生成，指令明确）。
                # 一律不把『apply/redo/stop』的裸 token 当自然语言喂给模型做自由元推理，
                # 避免 Socratic 模型陷入「用户是要应用建议还是有新输入?」的自我复述死循环。
                conv_cmd = (payload.message or "").strip().lower()
                is_converge_cmd = (payload.mode or "") == "guide" and conv_cmd in (
                    "apply",
                    "redo",
                    "stop",
                )
                if is_converge_cmd:
                    used_tools = True
                    if conv_cmd == "stop":
                        _answer = await asyncio.to_thread(lambda: _run_agent_tool(
                            "converge",
                            {"decision": "stop", "item_ids": []},
                            db=db,
                            project_id=project_id,
                            sources=sources,
                            nodes=scoped_nodes,
                            owner_id=user.user_id,
                            conversation_id=conversation_id,
                            current_llm=llm,
                            cited_sources=cited_sources,
                            staged_actions=staged_actions,
                        ))
                        answer_parts.append(_answer)
                        yield _sse({"type": "delta", "text": _answer})
                    else:
                        # 用清晰、自足的用户指令替换原始收敛 token，再走单次无工具生成。
                        # 单次生成有界（无 while 工具循环），即使模型跑偏也不会无限死循环。
                        directive = (
                            "用户已确认掌握当前内容并选择“继续下一问”，请你直接提出下一道**新的**苏格拉底问题"
                            "（换一个知识点，或对当前知识点更深一层追问）。输出仍保持苏格拉底 JSON 格式："
                            '{"question":"...","hints":[...],"answer_hidden":true,"next_action":"..."}。'
                            "其中 question 必须是**全新的下一问题干**，hints 是对下一问的渐进提示。"
                            "【禁止】在 question 或 hints 里回顾、复述或讲解上一问的正确答案与判定，"
                            "不给上一题的完整解答，不寒暄，不讨论补全笔记等其它内容。"
                            if conv_cmd == "apply"
                            # 查看答案走纯 Markdown，不要求 JSON：答案往往是大段多段落文字，
                            # 塞进 JSON 字符串极易因裸换行/未转义引号导致前端解析失败，
                            # 整段原始 JSON 直接漏给用户（实际发生过）。
                            else (
                                "用户选择「查看答案」。请针对当前这一问，直接给出完整的答案与讲解，"
                                "不要再让我作答，也不要提出新的问题。"
                                "【格式要求·本次特例】这一次**不要输出 JSON**，不要用代码块包裹，"
                                "也不要出现 question/hints/answer/answer_hidden 这类字段名；"
                                "直接输出 Markdown 正文，依次包含三部分（用加粗小标题分隔）："
                                "**题目回顾**（原样复述当前题干）、**最终答案**、**解题思路与易错点**。"
                                "段落之间用空行分隔，公式用 LaTeX。"
                                "【本次例外】系统提示中「输出苏格拉底 JSON」「不给完整答案」的要求"
                                "在这一轮全部不适用，把完整解答直接写出来。"
                                "不寒暄，不讨论补全笔记等其它内容。"
                            )
                        )
                        messages[-1]["content"] = directive
                        async for chunk in llm.astream_chat_content(
                            messages, "agent_chat"
                        ):
                            if chunk:
                                answer_parts.append(chunk)
                                yield _sse({"type": "delta", "text": chunk})
                else:
                    # 主界面（对话区）默认收窄到"该场景真能用上"的工具：
                    # 苏格拉底出题 / 建议稿 / 提案列表属于 kb 面板的专属交互，
                    # 挂在这里只会白占 tool schema 的 token，还会让模型去调用界面上不存在的东西。
                    tools = (
                        AGENT_TOOLS_DEFAULT
                        if require_write_confirmation
                        else LEARNING_AGENT_TOOLS
                    )
                    max_rounds = (
                        AGENT_MAX_ROUNDS_WRITABLE if require_write_confirmation else 3
                    )
                    while True:
                        got_tools = False
                        # 把当前工具集的名字告诉捕获器：平铺 JSON 形态必须靠它兜底，
                        # 否则正文里贴一段 {"name": "张三", "age": 30} 会被当成调用吞掉。
                        literal = _LiteralToolCallAccumulator(
                            {t.get("function", {}).get("name", "") for t in tools}
                        )
                        async for ev in llm.astream_chat_with_tools(
                            messages, "agent_chat", tools
                        ):
                            if ev["type"] == "delta":
                                # 进入「文字伪工具调用」捕获态后不再把文本当正文转发；
                                # 未捕获时也先经 flush_ready 放行 —— 开头 40 个字符要扣住
                                # 探测，否则 `{"name":` 的前几个字必然漏到用户眼前。
                                if literal.feed(ev["text"]):
                                    continue
                                ready = literal.flush_ready()
                                if ready:
                                    answer_parts.append(ready)
                                    yield _sse({"type": "delta", "text": ready})
                            elif ev["type"] == "tool_calls":
                                got_tools = True
                                used_tools = True
                                rounds += 1
                                # 丢弃本轮工具调用前模型的残句（弱模型偶尔先吐半句再调工具），
                                # 并通知前端清空已显示的瞬时文本、切换为「正在查询」状态
                                answer_parts = []
                                yield _sse(
                                    {
                                        "type": "tool",
                                        "names": [call["name"] for call in ev["calls"]],
                                    }
                                )
                                messages.append(
                                    {
                                        "role": "assistant",
                                        "content": ev.get("content") or "",
                                        "tool_calls": ev["raw"],
                                    }
                                )
                                for call in ev["calls"]:
                                    observation = await asyncio.to_thread(
                                        _run_agent_tool,
                                        call["name"],
                                        _agent_call_arguments(call["arguments"]),
                                        db=db,
                                        project_id=project_id,
                                        sources=sources,
                                        nodes=scoped_nodes,
                                        owner_id=user.user_id,
                                        conversation_id=conversation_id,
                                        current_llm=llm,
                                        cited_sources=cited_sources,
                                        staged_actions=staged_actions,
                                        # 与下面伪调用分支（L18799）必须传同一组 store：
                                        # 天大网关没有原生函数调用，实际跑的是伪调用那条，
                                        # 漏传会让三个读取工具拿到 None 然后谎报「没有数据」。
                                        study_kit=study_kit_store(),
                                        exam_scheduler=exam_scheduler(),
                                        knowledge_doc=knowledge_doc_store(),
                                    )
                                    trace.append(
                                        {
                                            "name": call["name"],
                                            "arguments": call["arguments"],
                                            "observation": observation[:600],
                                        }
                                    )
                                    messages.append(
                                        {
                                            "role": "tool",
                                            "tool_call_id": call["id"],
                                            "name": call["name"],
                                            "content": observation,
                                        }
                                    )
                        # 文字伪工具调用兜底：这一轮模型把工具调用吐成 `<function=...>`
                        # 或一段 JSON 正文时，与原生 tool_calls 同样拿到工具结果并续轮，
                        # 不让裸标记进最终答案。
                        lit_calls: list[dict[str, Any]] = []
                        while True:
                            one = literal.pop_call()
                            if one is None:
                                break
                            lit_calls.append(one)
                        if lit_calls:
                            # 摘走工具调用后，剩下的文本是模型的正经正文，必须转发 ——
                            # 少了它，用户会只看到一张选项卡、配文却没了。
                            got_tools = True
                            used_tools = True
                            rounds += 1
                            # 模型先吐半句再调用工具时，那半句已经被显示过；清掉，
                            # 与原生 tool_calls 分支同口径。
                            answer_parts = []
                            yield _sse(
                                {
                                    "type": "tool",
                                    "names": [c["name"] for c in lit_calls],
                                }
                            )
                            # 一个 assistant 消息 + N 个 tool 消息，与原生并行 tool_calls 同构
                            messages.append(
                                {
                                    "role": "assistant",
                                    "content": "",
                                    "tool_calls": [
                                        {
                                            "id": f"lit-{rounds}-{index}",
                                            "type": "function",
                                            "function": {
                                                "name": lit_call["name"],
                                                "arguments": lit_call["arguments"],
                                            },
                                        }
                                        for index, lit_call in enumerate(lit_calls)
                                    ],
                                }
                            )
                            for index, lit_call in enumerate(lit_calls):
                                observation = await asyncio.to_thread(
                                    _run_agent_tool,
                                    lit_call["name"],
                                    _agent_call_arguments(lit_call["arguments"]),
                                    db=db,
                                    project_id=project_id,
                                    sources=sources,
                                    nodes=scoped_nodes,
                                    owner_id=user.user_id,
                                    conversation_id=conversation_id,
                                    current_llm=llm,
                                    cited_sources=cited_sources,
                                    staged_actions=staged_actions,
                                    # ⚠️ 这条分支才是天大实际跑的（网关没有原生函数调用）。
                                    # 三个读取工具全靠这三个 store；漏传会让工具回
                                    # 「当前入口没有接入…存储」，模型转头就告诉用户
                                    # 「没有学习路径/速查表/文档」——而库里其实全都有。
                                    study_kit=study_kit_store(),
                                    exam_scheduler=exam_scheduler(),
                                    knowledge_doc=knowledge_doc_store(),
                                )
                                trace.append(
                                    {
                                        "name": lit_call["name"],
                                        "arguments": lit_call["arguments"],
                                        "observation": observation[:600],
                                    }
                                )
                                messages.append(
                                    {
                                        "role": "tool",
                                        "tool_call_id": f"lit-{rounds}-{index}",
                                        "name": lit_call["name"],
                                        "content": observation,
                                    }
                                )
                        # 残余正文：摘走工具调用之后模型又说的话、以及「攒了半天
                        # 却不是一次合法调用」退回的那段（正文里恰好出现了这个形态）。
                        # 不转发就会凭空少一句话，所以统一在这里处理。
                        leftover = literal.flush_all().strip()
                        if leftover:
                            answer_parts.append(leftover)
                            yield _sse({"type": "delta", "text": leftover})
                        if not got_tools:
                            break
                        if rounds >= max_rounds:
                            break
            except Exception as exc:  # noqa: BLE001 - 任何异常都要兜底而不是中断 SSE
                LOGGER.warning(
                    "agent stream fell back to non-streaming. project=%s err=%s",
                    project_id,
                    exc,
                )
                try:
                    fallback_answer, fallback_trace, fallback_tools = (
                        await asyncio.to_thread(lambda: _agent_answer_nonstream(
                            llm,
                            messages,
                            db=db,
                            project_id=project_id,
                            sources=sources,
                            nodes=scoped_nodes,
                            owner_id=user.user_id,
                            conversation_id=conversation_id,
                            question=payload.message,
                        ))
                    )
                except Exception as exc2:  # noqa: BLE001 - 兜底也失败（如未配置密钥）时发错误事件
                    LOGGER.exception(
                        "agent non-stream fallback failed. project=%s", project_id
                    )
                    yield _sse({"type": "error", "message": f"回答生成失败：{exc2}"})
                    return
                answer_parts = [fallback_answer]
                trace = fallback_trace
                used_tools = fallback_tools
                if fallback_answer:
                    yield _sse({"type": "delta", "text": fallback_answer})

            answer = "".join(answer_parts).strip()
            # 兜底：主循环有累加器摘调用，但万一某条路径漏了，成型的伪调用不能进正文。
            # 正文里真的讨论这个 JSON 形态（教学场景）不受影响 —— 只摘"完整调用对象"。
            answer = _strip_literal_tool_calls(answer)
            # 解掉模型偶发输出的双重编码 JSON 字符串（引导续问多次后易出现），
            # 保证前端能解析成苏格拉底问题卡片、库里也是干净的 JSON 对象，而不是一坨转义文本
            answer = _unwrap_double_encoded_json(answer)
            # 防退化：模型复读/输出一连串无意义「搜索。」之类时视为未给出有效正文，
            # 交由下方收尾合写（有工具结果）或兜底，避免把复读串直接写给用户
            _degraded = bool(answer) and _is_degenerate_repetition(answer)
            answer = collapse_repeated_lines(answer)
            if _degraded or (answer and _is_degenerate_repetition(answer)):
                LOGGER.warning(
                    "agent answer degraded/repetitive, dropping. project=%s", project_id
                )
                answer = ""

            # 工具已跑但流式正文为空（轮数截断/模型空返回）：收尾合写一次
            if not answer and (used_tools or trace):
                messages.append(
                    {
                        "role": "user",
                        "content": _AGENT_FINALIZE_INSTRUCTION.format(
                            question=payload.message
                        ),
                    }
                )
                try:
                    async for chunk in llm.astream_chat_content(messages, "agent_chat"):
                        # 收尾这段没有工具累加器，模型可能再吐一次伪调用 —— 必须逐块清洗，
                        # 否则那段 JSON 会同时出现在流式正文和最终答案里（存库也会脏）。
                        cleaned = _strip_literal_tool_calls(chunk)
                        if cleaned:
                            answer_parts.append(cleaned)
                            yield _sse({"type": "delta", "text": cleaned})
                except Exception as exc:  # noqa: BLE001
                    LOGGER.warning(
                        "agent tail stream failed. project=%s err=%s",
                        project_id,
                        exc,
                    )
                answer = _strip_literal_tool_calls("".join(answer_parts).strip())
                if answer and _is_degenerate_repetition(answer):
                    answer = ""

            if not answer:
                answer = (
                    _agent_trace_answer(trace)
                    if trace
                    else "我没有生成有效的回答内容。如果刚才是知识库相关的问题，"
                    "可以确认项目里已经有可用的知识框架后再试；也可以用更具体的方式重问一次。"
                )
                yield _sse({"type": "delta", "text": answer})

            # 兜底检索：模型整轮没碰资料就作答（网关不支持 tools、或模型自己偷懒）时，
            # 答案就没有资料支撑，违背"优先依据你的资料作答"。这里补一次本地检索并重跑，
            # 命中结果同时登记成来源编号，回答里的 [n] 就能变回可点 chip。
            if not cited_sources and answer and not is_converge_cmd:
                fallback_hits = _agent_source_hits(sources, payload.message)
                if fallback_hits:
                    for index, hit in enumerate(fallback_hits, start=1):
                        cited_sources[index] = hit
                    blocks = "\n\n".join(
                        f"【{index}】{hit['filename']}\n{hit['text']}"
                        for index, hit in enumerate(fallback_hits, start=1)
                    )
                    yield _sse(
                        {"type": "tool", "names": ["search_sources"], "auto": True}
                    )
                    messages.append(
                        {
                            "role": "user",
                            "content": (
                                "请用下面这些资料片段重新组织你的回答，只依据片段作答，"
                                "并在有依据的句末标出来源编号（如 [1]）；片段里没有的内容就直说资料没写。\n\n"
                                f"{blocks}"
                            ),
                        }
                    )
                    answer_parts = []
                    try:
                        async for chunk in llm.astream_chat_content(
                            messages, "agent_chat"
                        ):
                            if chunk:
                                answer_parts.append(chunk)
                                yield _sse({"type": "delta", "text": chunk})
                        answer = "".join(answer_parts).strip()
                    except Exception as exc:  # noqa: BLE001
                        LOGGER.warning(
                            "agent fallback retrieval failed. project=%s err=%s",
                            project_id,
                            exc,
                        )
                    if not answer:
                        answer = _agent_trace_answer(trace) if trace else ""

            # 溯源：把答案里的 [n] 还原成 segments（前端据此渲染可点 chip），
            # 并只登记真正标注过的资料。
            answer_segments, answer_source_ids = _agent_answer_segments(
                answer, cited_sources, source_by_id
            )
            # done.answer 是权威全文（前端收尾按它重渲染），落库的也是它 —— 都要是干净文本：
            # 来源编号由 chip 承担，正文里留着 [1] 只会变成噪声。
            if answer_source_ids:
                answer = _AGENT_CITATION_MARKER_RE.sub("", answer).strip()

            # 落库：user + assistant（与旧版一致，撤销基线在流式前已记录）
            before_ids = {
                message.message_id
                for message in db.list_messages(project_id, conversation_id="")
            }
            question_message = db.add_message(
                project_id,
                "user",
                payload.message,
                node_ids,
                [],
                conversation_id=conversation_id,
            )
            if node_ids:
                record_evidence(
                    db,
                    project_id,
                    node_ids,
                    "question",
                    None,
                    confidence,
                    reference_id=question_message.message_id,
                )
            assistant_message = db.add_message(
                project_id,
                "assistant",
                answer,
                node_ids,
                answer_source_ids,
                conversation_id=conversation_id,
                meta={"trace": trace},
            )
            record_message_append(
                user, project_id, before_ids, f"提问「{payload.message[:24]}」", conversation_id
            )
            yield _sse(
                {
                    "type": "done",
                    "answer": answer,
                    "used_tools": used_tools,
                    "tool_trace": trace,
                    "node_ids": node_ids,
                    # 只报本轮真正检索到并标注过的资料，而不是"当前勾选的全部资料"，
                    # 否则每条回答都挂着 N 个来源，溯源信息等于没有。
                    "source_ids": answer_source_ids,
                    "source_refs": [
                        {"source_id": hit["source_id"], "filename": hit["filename"]}
                        for hit in cited_sources.values()
                        if hit["source_id"] in answer_source_ids
                    ],
                    "answer_segments": answer_segments,
                    "staged_actions": staged_actions or [],
                    "conversation_id": conversation_id,
                    "question_message_id": question_message.message_id,
                    "message_id": assistant_message.message_id,
                    "question_created_at": model_to_dict(question_message)[
                        "created_at"
                    ],
                    "message_created_at": model_to_dict(assistant_message)[
                        "created_at"
                    ],
                }
            )

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={
                "Cache-Control": "no-cache",
                "X-Accel-Buffering": "no",  # 禁止反代缓冲，保证逐块到达
            },
        )

    @application.post("/api/projects/{project_id}/agent")
    def agent_chat(
        project_id: str, payload: ChatRequest, request: Request
    ) -> StreamingResponse:
        """Function Calling 版学习 Agent（知识库 Agent 面板入口）。

        实现体在 _agent_stream_impl —— 主界面对话区打开 agent 开关后走的是同一段逻辑。
        """
        return _agent_stream_impl(project_id, payload, request)

    @application.post("/api/projects/{project_id}/agent/actions/execute")
    async def agent_execute_actions(
        project_id: str, request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """执行用户在对话区确认卡片上拍板的写库动作。

        模型那一轮只是**登记**（见 _run_agent_tool 的写操作闸门），真正的写入发生在这里，
        因此这是唯一需要严格收口的入口：
          - 权限：与其它端点一致走 require_user + require_project_access（越权一律 404）
          - 白名单：只接受 AGENT_WRITE_TOOLS 里的四个工具，不接受任意函数名
          - 确认语义：用户已在界面上点了确认，所以 delete_node / 覆盖笔记必需的
            confirm=True 由这里补齐，而不是让模型自己声称用户已同意
        """
        user = require_user(request)
        require_project_access(project_id, request)
        actions = payload.get("actions")
        if not isinstance(actions, list) or not actions:
            raise HTTPException(
                status_code=422,
                detail=error_payload("agent_actions_empty", "没有需要执行的写操作。"),
            )
        if len(actions) > 20:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "agent_actions_too_many", "一次最多执行 20 项写操作。"
                ),
            )
        all_sources = [
            source
            for source in db.list_sources(project_id)
            if source.status == "ok" and source.text.strip()
        ]
        nodes = db.list_framework_nodes(project_id)
        # 四个写工具在 _run_agent_tool 里都被同一条前置挡住：没有知识框架就一律返回
        # 「请先构建知识框架」。与其在这里逐条执行再把那句话当成成功，不如先说清楚。
        if not nodes:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "agent_actions_need_framework",
                    "当前项目还没有知识框架，先构建知识框架再让 AI 修改知识库。",
                ),
            )
        conversation_id = str(payload.get("conversation_id") or "").strip()
        results: list[dict[str, Any]] = []
        changed = False
        before_ids = {
            message.message_id
            for message in db.list_messages(project_id, conversation_id="")
        }
        for raw in actions:
            if not isinstance(raw, dict):
                continue
            name = str(raw.get("tool") or "").strip()
            arguments = raw.get("arguments")
            if name not in AGENT_WRITE_TOOLS or not isinstance(arguments, dict):
                results.append(
                    {
                        "tool": name,
                        "label": str(raw.get("label") or name),
                        "ok": False,
                        "message": "不支持的写操作，已忽略。",
                    }
                )
                continue
            # 用户已在界面确认过：删除与覆盖既有笔记这类破坏轨不再要求模型再传一次 confirm。
            arguments = dict(arguments)
            if name in {"delete_node", "update_node"}:
                arguments["confirm"] = True
            try:
                # nodes 每轮重取：同一批里前一个动作可能刚建/删了节点，
                # 拿循环外那份快照会让后面的动作对着过期世界做判断。
                observation = await asyncio.to_thread(
                    _run_agent_tool,
                    name,
                    arguments,
                    db=db,
                    project_id=project_id,
                    sources=all_sources,
                    nodes=db.list_framework_nodes(project_id),
                    owner_id=user.user_id,
                    conversation_id=conversation_id or None,
                    current_llm=llm,
                )
                # 两种失败都要认：破坏轨要confirm（闸门语言），以及写工具自己的
                # 失败前缀（AGENT_WRITE_FAILED_PREFIX）。漏掉后者会让「节点不存在」
                # 这类明确的失败被报成成功 —— 前端显示「✅全部完成」而库没变。
                needs_confirm = observation.startswith("[需要确认]")
                write_failed = observation.startswith(AGENT_WRITE_FAILED_PREFIX)
                failed = needs_confirm or write_failed
                message = observation
                if write_failed:
                    message = message[len(AGENT_WRITE_FAILED_PREFIX) :].strip()
                results.append(
                    {
                        "tool": name,
                        "label": str(raw.get("label") or name),
                        "ok": not failed,
                        "message": message,
                    }
                )
                changed = changed or not failed
            except Exception as exc:  # noqa: BLE001 - 单条失败不能连带其它动作
                LOGGER.warning(
                    "agent action failed. project=%s tool=%s err=%s",
                    project_id,
                    name,
                    exc,
                )
                results.append(
                    {
                        "tool": name,
                        "label": str(raw.get("label") or name),
                        "ok": False,
                        "message": f"执行失败：{exc}",
                    }
                )
        if changed:
            record_message_append(
                user, project_id, before_ids, "确认执行 Agent 的写操作", conversation_id
            )
            for node in db.list_framework_nodes(project_id):
                try:
                    _prune_digest_gap(db, project_id, node.node_id)
                except Exception:  # noqa: BLE001 - 摘要维护失败不影响已落库的修改
                    pass
        return {"ok": any(item["ok"] for item in results), "results": results}

    @application.get("/api/projects/{project_id}/agent/sessions")
    async def agent_list_sessions(project_id: str, request: Request) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        node_id = (request.query_params.get("node_id") or "").strip()
        convs = db.list_conversations(project_id, node_id=node_id)
        return {"sessions": convs}

    @application.get("/api/projects/{project_id}/agent/sessions/{cid}")
    async def agent_get_session(
        project_id: str, cid: str, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            conv = db.get_conversation(cid)
        except KeyError as exc:
            raise HTTPException(
                status_code=404,
                detail=error_payload("conversation_not_found", "会话不存在。"),
            ) from exc
        messages = db.list_conversation_messages(project_id, cid)
        return {"session": conv, "messages": [model_to_dict(m) for m in messages]}

    @application.post("/api/projects/{project_id}/agent/sessions/{cid}")
    async def agent_send_to_session(
        project_id: str,
        cid: str,
        payload: ChatRequest,
        request: Request,
    ) -> dict[str, Any]:
        """复用 /agent 的发送逻辑：强制绑定到指定会话。"""
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            db.get_conversation(cid)
        except KeyError as exc:
            raise HTTPException(
                status_code=404,
                detail=error_payload("conversation_not_found", "会话不存在。"),
            ) from exc
        bound_payload = ChatRequest(
            message=payload.message,
            node_ids=payload.node_ids,
            source_ids=payload.source_ids,
            conversation_id=cid,
        )
        # agent_chat 是同步端点（体里没有 await，同步执行才会走 FastAPI 线程池、
        # 不占事件循环）——所以这里不能 await 它（await 非协程会直接 TypeError），
        # 改为丢进线程池并等结果。
        return await asyncio.to_thread(agent_chat, project_id, bound_payload, request)

    @application.delete("/api/projects/{project_id}/agent/sessions/{cid}")
    async def agent_delete_session(
        project_id: str, cid: str, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            db.get_conversation(cid)
        except KeyError as exc:
            raise HTTPException(
                status_code=404,
                detail=error_payload("conversation_not_found", "会话不存在。"),
            ) from exc
        db.delete_conversation(cid)
        for m in db.list_conversation_messages(project_id, cid):
            db.delete_messages(project_id, [m.message_id])
        return {"deleted": True}

    @application.get("/api/projects/{project_id}/kb/digest")
    async def kb_digest_stats(project_id: str, request: Request) -> dict[str, Any]:
        """返回知识库现状摘要（含统计与薄弱点），供整理助手头部记忆徽标使用。"""
        user = require_user(request)
        require_project_access(project_id, request)
        digest = db.get_digest(project_id)
        if digest is None:
            digest = build_kb_digest(db, project_id, None)
        return {
            "digest": digest,
            "text": render_digest_text(digest),
        }

    @application.post("/api/projects/{project_id}/kb/node/{node_id}/complete")
    def kb_node_complete_note(
        project_id: str, node_id: str, request: Request
    ) -> dict[str, Any]:
        """整理助手「补全当前节点笔记」：用高质量原子笔记人设为单个节点生成详细建议稿（不直接改库）。

        生成一线建议稿（详细 Markdown），写入待批准队列，用户批准后才落库。
        若该节点已有待批准建议稿则不再重复生成，直接返回既有稿。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            node = db.get_framework_node(project_id, node_id)
        except NodeNotFound as exc:
            raise HTTPException(
                status_code=404,
                detail=error_payload("node_not_found", "知识节点不存在。"),
            ) from exc
        pending = [
            p
            for p in db.list_proposals(project_id, status="pending")
            if p["node_id"] == node_id
        ]
        if pending:
            return {
                "proposal": pending[0],
                "created": False,
                "reason": "该节点已有待批准建议稿，未重复生成。",
            }
        all_sources = db.list_sources(project_id)
        sources = [
            s for s in all_sources if s.status == "ok" and (s.text or "").strip()
        ]
        g = _generate_node_detail_proposal(db, llm, project_id, node_id, sources)
        proposal = db.create_proposal(
            project_id,
            node_id,
            "complete_note",
            g["content"],
            type_="complete_note",
            reason=g["reason"],
        )
        record_undo(
            user,
            project_id,
            "kb_proposal_apply",
            f"补全笔记建议稿：「{node.name}」",
            {
                "project_id": project_id,
                "node_id": node.node_id,
                "proposal_id": proposal["proposal_id"],
                "action": "complete_note",
                "type": "complete_note",
                "before_noted": (node.note_content or "") != "",
            },
        )
        return {"proposal": proposal, "created": True, "reason": g["reason"]}

    @application.get("/api/projects/{project_id}/proposals")
    async def proposals_list(
        project_id: str, request: Request, status: str | None = None
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        return {"proposals": db.list_proposals(project_id, status=status or None)}

    @application.patch("/api/projects/{project_id}/proposals/{proposal_id}")
    async def proposal_apply(
        project_id: str,
        proposal_id: str,
        payload: ProposalActionRequest,
        request: Request,
    ) -> dict[str, Any]:
        """审批建议稿：拒绝直接置状态；批准/编辑后落库节点笔记并记录撤销。"""
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            proposal = db.get_proposal(project_id, proposal_id)
        except KeyError as exc:
            raise HTTPException(
                status_code=404,
                detail=error_payload("proposal_not_found", "建议稿不存在。"),
            ) from exc

        if payload.status == "rejected":
            db.update_proposal(project_id, proposal_id, status="rejected")
            return {"proposal": db.get_proposal(project_id, proposal_id)}

        # accepted：用建议稿原文；edited：以用户提供的 content 覆盖后视为 accepted
        final_content = proposal["proposed_content"]
        if payload.status == "edited":
            content = (payload.content or "").strip()
            if not content:
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "proposal_content_required", "编辑后批准需要提供内容。"
                    ),
                )
            final_content = content

        try:
            node = db.get_framework_node(project_id, proposal["node_id"])
        except NodeNotFound as exc:
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "proposal_node_missing", "建议稿对应的知识节点已不存在。"
                ),
            ) from exc

        before = {
            "note_content": node.note_content,
            "tags": node.tags,
            "wikilinks": node.wikilinks,
        }
        db.update_node_note(project_id, node.node_id, note_content=final_content)
        db.update_proposal(project_id, proposal_id, status="accepted")
        record_undo(
            user,
            project_id,
            "kb_proposal_apply",
            f"批准建议稿：{node.name} 笔记更新",
            {
                "project_id": project_id,
                "node_id": node.node_id,
                "before": before,
            },
        )
        # 增量刷新摘要 gaps：把已补笔记的节点从缺笔记清单中摘除
        _prune_digest_gap(db, project_id, node.node_id)
        return {"proposal": db.get_proposal(project_id, proposal_id)}

    @application.post("/api/projects/{project_id}/solve")
    def solve(
        project_id: str, payload: SolveRequest, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        cid = str(payload.conversation_id or "")
        before_ids = {
            message.message_id
            for message in db.list_messages(project_id, conversation_id=cid)
        }
        result = _study_action(
            application,
            db,
            project_id,
            payload.problem,
            payload.node_ids,
            payload.source_ids,
            "solve",
            correctness=payload.correctness,
            conversation_id=cid,
        )
        record_message_append(
            user, project_id, before_ids, f"解题「{payload.problem[:24]}」", cid
        )
        return result

    @application.post("/api/projects/{project_id}/solve-image")
    async def solve_image(
        project_id: str,
        request: Request,
        image: UploadFile = File(...),
        message: str = Form(default=""),
        source_ids: str = Form(default="[]"),
        conversation_id: str = Form(default=""),
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        filename = image.filename or "题目截图.png"
        suffix = Path(filename).suffix.lower()
        if suffix not in {".png", ".jpg", ".jpeg"}:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "unsupported_problem_image", "题目截图仅支持 PNG、JPG 或 JPEG。"
                ),
            )
        content = await image.read()
        if not content:
            raise HTTPException(
                status_code=422,
                detail=error_payload("empty_problem_image", "题目截图为空。"),
            )
        if len(content) > 10 * 1024 * 1024:
            raise HTTPException(
                status_code=413,
                detail=error_payload(
                    "problem_image_too_large", "题目截图不能超过 10 MB。"
                ),
            )
        # 会话归属：空串 = 项目默认单线程（Agent 布局由前端表单带上）
        cid = str(conversation_id or "")
        try:
            parsed_source_ids = json.loads(source_ids)
        except json.JSONDecodeError as exc:
            raise HTTPException(
                status_code=422,
                detail=error_payload("invalid_source_ids", "对话来源参数格式不正确。"),
            ) from exc
        if not isinstance(parsed_source_ids, list) or not all(
            isinstance(item, str) for item in parsed_source_ids
        ):
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "invalid_source_ids", "对话来源参数必须是字符串列表。"
                ),
            )
        before_ids = {
            message.message_id
            for message in db.list_messages(project_id, conversation_id=cid)
        }
        result = await asyncio.to_thread(lambda: _study_action(
            application,
            db,
            project_id,
            message.strip() or "请识别并解答截图中的题目。",
            [],
            parsed_source_ids,
            "solve",
            image={
                "content": content,
                "filename": filename,
                "mime_type": image.content_type
                or ("image/png" if suffix == ".png" else "image/jpeg"),
            },
            conversation_id=cid,
        ))
        record_message_append(user, project_id, before_ids, "识图解题", cid)
        return result

    @application.post("/api/projects/{project_id}/cards/generate")
    async def generate_cards(
        project_id: str,
        request: Request,
        payload: CardGenerateRequest | None = None,
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        all_sources = db.list_sources(project_id)
        usable_sources = [
            source
            for source in all_sources
            if source.status == "ok" and source.text.strip()
        ]
        if not usable_sources:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "missing_course_materials",
                    "请先导入课程资料。在左侧上传 PDF、Word、PPT 或粘贴文本后，才能生成知识卡片。",
                ),
            )
        requested_source_ids = (
            set(payload.source_ids)
            if payload is not None and payload.source_ids is not None
            else None
        )
        sources = [
            source
            for source in usable_sources
            if (
                requested_source_ids is None or source.source_id in requested_source_ids
            )
        ]
        if requested_source_ids is not None and not sources:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "missing_card_sources",
                    "请至少选择一个可用课程来源后再生成知识卡片。",
                ),
            )
        active_source_ids = {source.source_id for source in sources}
        nodes = [
            node.model_copy(
                update={
                    "source_ids": [
                        source_id
                        for source_id in node.source_ids
                        if source_id in active_source_ids
                    ]
                }
            )
            for node in db.list_framework_nodes(project_id)
            if not active_source_ids
            or any(source_id in active_source_ids for source_id in node.source_ids)
        ]
        existing_cards = db.list_cards(project_id)
        progression_cards = [
            card
            for card in existing_cards
            if not active_source_ids or set(card.source_ids) & active_source_ids
        ]
        target_difficulty = _requested_or_auto_difficulty(
            payload.difficulty if payload is not None else None,
            _next_card_difficulty(progression_cards, sources),
        )
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "知识卡片生成需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        fallback = (
            not application.state.settings.tju_api_key
            and application.state.llm.responder is None
        )
        if fallback:
            cards = generate_fallback_cards(
                nodes, sources, target_difficulty, existing_cards
            )
        else:
            cards = await _generate_cards_with_strategies(
                application.state.llm,
                nodes=nodes,
                sources=sources,
                existing_cards=existing_cards,
                target_difficulty=target_difficulty,
                log_label=f"project_id={project_id}",
            )
        saved = db.add_cards(project_id, [_clean_card(card) for card in cards])
        if saved:
            record_undo(
                user,
                project_id,
                "cards.add",
                f"生成 {len(saved)} 张知识卡片",
                {
                    "project_id": project_id,
                    "card_ids": [card.card_id for card in saved],
                },
            )
        return {
            "cards": [_card_payload(card) for card in saved],
            "source_ids": sorted(active_source_ids),
            "fallback": fallback,
        }

    @application.post("/api/projects/{project_id}/recommend-questions")
    async def recommend_deep_questions(
        project_id: str,
        request: Request,
        payload: RecommendQuestionsRequest | None = None,
    ) -> dict[str, Any]:
        """用大模型基于知识框架与课程资料生成具体、有深度的推荐问题。"""
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        if not nodes:
            return {"questions": [], "fallback": True, "reason": "no_framework"}
        sources = [
            source
            for source in db.list_sources(project_id)
            if source.status == "ok" and str(source.text or "").strip()
        ]
        exclude = [
            str(q).strip()
            for q in (payload.exclude if payload is not None else [])
            if str(q).strip()
        ]
        if not application.state.settings.tju_api_key:
            return {"questions": [], "fallback": True, "reason": "no_api_key"}
        try:
            by_id = {n.node_id: n for n in nodes}
            kids: dict[str, list[str]] = {}
            for n in nodes:
                if n.parent_id and n.parent_id in by_id:
                    kids.setdefault(n.parent_id, []).append(n.name)
            node_briefs = [
                {
                    "name": n.name,
                    "description": (n.description or "")[:200],
                    "mastery_score": n.mastery_score,
                    "learning_status": n.learning_status,
                    "parent": by_id[n.parent_id].name
                    if n.parent_id and n.parent_id in by_id
                    else "",
                    "children": kids.get(n.node_id, []),
                    "prerequisites": [
                        by_id[pid].name
                        for pid in (n.prerequisite_ids or [])
                        if pid in by_id
                    ],
                }
                for n in nodes
            ]
            excerpts = source_excerpts(sources)
            result = await asyncio.to_thread(
                application.state.llm.complete_json,
                "recommend_deep_questions",
                {
                    "nodes": node_briefs,
                    "sources": excerpts,
                    "exclude": exclude,
                    "count": 5,
                },
            )
            questions = [
                str(q).strip()
                for q in (result.get("questions") if isinstance(result, dict) else [])
                if str(q).strip()
            ]
            questions = [q for q in questions if q not in exclude][:5]
            if not questions:
                return {"questions": [], "fallback": True, "reason": "llm_empty"}
            return {"questions": questions, "fallback": False}
        except Exception:
            return {"questions": [], "fallback": True, "reason": "llm_error"}

    @application.post("/api/projects/{project_id}/recommend-questions/stream")
    def recommend_deep_questions_stream(
        project_id: str,
        request: Request,
        payload: RecommendQuestionsRequest | None = None,
    ):
        """流式大模型推荐问题：每生成完一道题就立刻下发，前端可边生成边渲染。

        事件流：{type:"question", index, text} ×N → {type:"done", questions, fallback}
        异常/缺前置条件时发 {type:"fallback"} 或 {type:"error"}，前端据此回退本地模板。
        """
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        sources = [
            source
            for source in db.list_sources(project_id)
            if source.status == "ok" and str(source.text or "").strip()
        ]
        exclude = [
            str(q).strip()
            for q in (payload.exclude if payload is not None else [])
            if str(q).strip()
        ]

        def _sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream():
            if not nodes:
                yield _sse({"type": "fallback", "reason": "no_framework"})
                return
            if not application.state.settings.tju_api_key:
                yield _sse({"type": "fallback", "reason": "api_key_required"})
                return
            try:
                by_id = {n.node_id: n for n in nodes}
                kids: dict[str, list[str]] = {}
                for n in nodes:
                    if n.parent_id and n.parent_id in by_id:
                        kids.setdefault(n.parent_id, []).append(n.name)
                node_briefs = [
                    {
                        "name": n.name,
                        "description": (n.description or "")[:200],
                        "mastery_score": n.mastery_score,
                        "learning_status": n.learning_status,
                        "parent": by_id[n.parent_id].name
                        if n.parent_id and n.parent_id in by_id
                        else "",
                        "children": kids.get(n.node_id, []),
                        "prerequisites": [
                            by_id[pid].name
                            for pid in (n.prerequisite_ids or [])
                            if pid in by_id
                        ],
                    }
                    for n in nodes
                ]
                excerpts = source_excerpts(sources)
                buffer = ""
                emitted = 0
                async for chunk in application.state.llm.astream_complete_content(
                    "recommend_deep_questions",
                    {
                        "nodes": node_briefs,
                        "sources": excerpts,
                        "exclude": exclude,
                        "count": 5,
                    },
                ):
                    if not chunk:
                        continue
                    buffer += chunk
                    completed = _extract_completed_questions(buffer)
                    for question in completed[emitted:]:
                        emitted += 1
                        yield _sse(
                            {"type": "question", "index": emitted - 1, "text": question}
                        )
                final = [
                    str(q).strip()
                    for q in _extract_completed_questions(buffer)
                    if str(q).strip() and q not in exclude
                ]
                yield _sse(
                    {"type": "done", "questions": final[:5], "fallback": not final}
                )
            except Exception as exc:
                yield _sse({"type": "error", "message": str(exc)})

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

