    @application.patch("/api/projects/{project_id}/favorites/{favorite_id}")
    async def update_favorite(
        project_id: str, favorite_id: str, payload: FavoriteUpdate, request: Request
    ) -> dict[str, Any]:
        user = require_user(request)
        require_project_access(project_id, request)
        before = db.get_favorite_row(project_id, favorite_id)
        current = db.get_favorite(project_id, favorite_id)
        title = payload.title.strip() if payload.title is not None else current.title
        chapter_name = (
            payload.chapter_name.strip()
            if payload.chapter_name is not None
            else current.chapter_name
        )
        note = payload.note.strip() if payload.note is not None else current.note
        highlight_color = (
            payload.highlight_color.strip()
            if payload.highlight_color is not None
            else current.highlight_color
        )
        if not title or not chapter_name:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "invalid_favorite_update", "笔记标题和所属章节不能为空。"
                ),
            )
        if highlight_color not in {"yellow", "green", "red", "blue", "purple", "none"}:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "invalid_favorite_highlight_color", "高亮颜色无效。"
                ),
            )
        matching_node = next(
            (
                node
                for node in db.list_framework_nodes(project_id)
                if node.name == chapter_name
            ),
            None,
        )
        updated = db.update_favorite(
            project_id,
            favorite_id,
            title=title,
            chapter_node_id=matching_node.node_id if matching_node else None,
            chapter_name=chapter_name,
            note=note,
            highlight_color=highlight_color,
        )
        record_undo(
            user,
            project_id,
            "favorite.update",
            f"编辑笔记「{before['title'][:20]}」",
            {"before": before},
        )
        return model_to_dict(updated)

