    # ---- 课工按钮：递归列课程目录 + 批量拉用户勾选的文件 ----
    # 警告：本节涉及从第三方仓库批量下载课件 / 试卷等材料，调用方必须在 UI 上
    # 明示版权风险并取得用户明确确认。开发者与平台不为版权后果承担任何责任。

    # 与 parsers.SUPPORTED_EXTENSIONS 保持一致；前端按 kind 分组
    TJU_KIND_BY_EXT: dict[str, str] = {
        ".pdf": "pdf",
        ".pptx": "pptx",
        ".ppt": "ppt",
        ".docx": "docx",
        ".doc": "doc",
        ".txt": "text",
        ".md": "text",
        ".png": "image",
        ".jpg": "image",
        ".jpeg": "image",
    }

    def _tju_kind(filename: str) -> str:
        from pathlib import Path as _Path

        suffix = _Path(filename).suffix.lower()
        return TJU_KIND_BY_EXT.get(suffix, "other")

    async def _crawl_tju_dir_tree(
        client: Any, dir_path: str, depth: int, is_root: bool = True
    ) -> list[dict[str, Any]]:
        """递归拉课程共享站（OneDrive）目录，返回嵌套树结构（文件夹 + 文件）。

        递归深度上限由 MAX_TJU_RECURSIVE_DEPTH 控制，避免被异常深目录拖死。
        根目录（depth==0）的 API 失败会抛出异常，让上层返回明确错误信息；
        子目录的 API 失败静默返回空列表，避免个别子目录拉不到就全盘失败。
        """
        if depth > MAX_TJU_RECURSIVE_DEPTH:
            return []
        url = f"{TJU_SHARE_BASE_URL}/api/?path=/{quote(dir_path, safe='/')}"
        # 根目录带一次重试
        for attempt in range(2 if is_root else 1):
            try:
                resp = await client.get(url, headers={"User-Agent": "knoworigin-local"})
            except Exception as exc:  # noqa: BLE001
                if is_root and attempt == 0:
                    await asyncio.sleep(1.5)
                    continue
                if is_root:
                    raise RuntimeError(
                        f"无法连接课程共享站（{type(exc).__name__}），请检查网络后重试"
                    ) from exc
                return []
            if resp.status_code != 200:
                if is_root and attempt == 0:
                    await asyncio.sleep(1.5)
                    continue
                if is_root:
                    raise RuntimeError(
                        f"课程共享站返回 HTTP {resp.status_code}，可能此课程资料尚未上传或仓库地址变更"
                    )
                return []
            break  # 成功，跳出重试循环
        try:
            payload = resp.json()
            value = payload.get("folder", {}).get("value", [])
        except Exception as exc:  # noqa: BLE001
            if is_root:
                raise RuntimeError(
                    "课程共享站返回了无法解析的数据格式，请联系开发者"
                ) from exc
            return []
        if not isinstance(value, list):
            if is_root:
                raise RuntimeError("课程共享站返回了意外的数据结构，请联系开发者")
            return []
        result: list[dict[str, Any]] = []
        # 收集子目录项，稍后并发爬取
        dir_indices: list[tuple[int, str, str]] = []  # (result_index, name, child_path)
        next_idx = 0
        for item in value:
            fname = item.get("name") or ""
            child_path = f"{dir_path.rstrip('/')}/{fname}" if dir_path else fname
            if item.get("folder") is not None:
                dir_indices.append((next_idx, fname, child_path))
                result.append(None)  # 占位，后续回填
            else:
                result.append(
                    {
                        "type": "file",
                        "name": fname,
                        "path": child_path,
                        "size_bytes": int(item.get("size") or 0),
                        "kind": _tju_kind(fname),
                        "is_readme": fname.lower() == "readme.md",
                    }
                )
            next_idx += 1
        if dir_indices:
            children_results = await asyncio.gather(
                *(
                    _crawl_tju_dir_tree(client, child_path, depth + 1, is_root=False)
                    for _, _, child_path in dir_indices
                ),
                return_exceptions=True,
            )
            for (idx, name, child_path), children in zip(dir_indices, children_results):
                if isinstance(children, Exception):
                    children = []
                result[idx] = {
                    "type": "dir",
                    "name": name,
                    "path": child_path,
                    "children": children,
                }
        return result

    def _detect_proxy() -> str | None:
        """检测系统代理（Windows registry / 环境变量），返回 http://host:port 或 None。"""
        import os

        proxy = os.environ.get("HTTPS_PROXY") or os.environ.get("https_proxy")
        if proxy:
            return proxy
        # Windows: 读注册表 ProxyServer
        try:
            import winreg

            key = winreg.OpenKey(
                winreg.HKEY_CURRENT_USER,
                r"Software\Microsoft\Windows\CurrentVersion\Internet Settings",
            )
            enable, _ = winreg.QueryValueEx(key, "ProxyEnable")
            if enable:
                server, _ = winreg.QueryValueEx(key, "ProxyServer")
                winreg.CloseKey(key)
                if server and ":" in server:
                    return f"http://{server}"
        except Exception:
            pass
        return None

    async def _fetch_tju_file_bytes(
        client: Any, path_in_repo: str
    ) -> tuple[bytes | None, int]:
        """按课程共享站的 path 拉字节（/api/raw/ 会 307 重定向到真实文件）。
        返回 (bytes or None, http_status)——单文件超 MAX_TJU_FILE_BYTES 时返回 (None, 413)。
        带一次重试，避免偶发超时。
        """
        url = f"{TJU_SHARE_BASE_URL}/api/raw/?path=/{quote(path_in_repo, safe='/')}"
        for attempt in range(2):
            try:
                resp = await client.get(
                    url,
                    headers={"User-Agent": "knoworigin-local"},
                    follow_redirects=True,
                )
            except Exception:
                if attempt == 0:
                    import asyncio

                    await asyncio.sleep(1)
                    continue
                return (None, 0)
            if resp.status_code == 200:
                body = resp.content
                if len(body) > MAX_TJU_FILE_BYTES:
                    return (None, 413)
                return (body, 200)
            if resp.status_code == 404 and attempt == 0:
                return (None, 404)  # 404 不重试
            if attempt == 0:
                import asyncio

                await asyncio.sleep(1)
                continue
            return (None, resp.status_code)
        return (None, 0)

    @application.get("/api/tju-courses/{code}/files")
    async def list_tju_course_files(code: str, request: Request) -> dict[str, Any]:
        """列出某课程目录下所有可解析的文件（含 README），供前端「课工」对话框使用。

        kind 取值: pdf / pptx / ppt / docx / doc / image / text / other。
        仅当后缀命中已知映射才算文件大小，否则归到 other；other 类型仍会出现在列表里，
        但前端可不让用户勾选。
        """
        require_user(request)
        course = next((c for c in TJU_COURSES if c[0] == code), None)
        if course is None:
            return {
                "ok": False,
                "reason": "课程库未收录此课程代码",
                "files": [],
                "course": None,
            }
        _, cname, discipline = course
        dir_name = f"{code}_{cname}"

        import httpx

        try:
            _proxy = _detect_proxy()
            async with httpx.AsyncClient(timeout=20, proxy=_proxy) as client:
                tree = await _crawl_tju_dir_tree(client, dir_name, 0)
        except RuntimeError as exc:
            return {
                "ok": False,
                "reason": str(exc),
                "files": [],
                "course": {"code": code, "name": cname, "discipline": discipline},
            }
        except Exception as exc:  # noqa: BLE001
            return {
                "ok": False,
                "reason": f"拉取失败：{type(exc).__name__}（多半是网络或仓库临时不可达）",
                "files": [],
                "course": {"code": code, "name": cname, "discipline": discipline},
            }

        # 若目录树为空，尝试直接拉 README.md 确认课程是否存在
        if not tree:
            try:
                import httpx as _httpx

                readme_url = f"{TJU_SHARE_BASE_URL}/api/raw/?path=/{quote(dir_name, safe='/')}/README.md"
                async with _httpx.AsyncClient(timeout=15, proxy=_proxy) as _client:
                    _resp = await _client.get(
                        readme_url,
                        headers={"User-Agent": "knoworigin-local"},
                        follow_redirects=True,
                    )
                if _resp.status_code == 200:
                    tree = [
                        {
                            "type": "file",
                            "name": "README.md",
                            "path": f"{dir_name}/README.md",
                            "size_bytes": len(_resp.content),
                            "kind": "text",
                            "is_readme": True,
                        }
                    ]
            except Exception:
                pass  # 回退检查失败不影响主流程

        return {
            "ok": True,
            "course": {"code": code, "name": cname, "discipline": discipline},
            "dir": dir_name,
            "tree": tree,
        }

    # TJU 导入进度追踪（project_id → {total, completed, current_file, status}）
    _tju_import_progress: dict[str, dict[str, Any]] = {}

    @application.get("/api/projects/{project_id}/sources/import-tju-folder/progress")
    async def get_tju_import_progress(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """轮询 TJU 批量导入的实时进度。"""
        require_user(request)
        require_project_access(project_id, request)
        progress = _tju_import_progress.get(project_id)
        if progress is None:
            return {"total": 0, "completed": 0, "current_file": "", "status": "idle"}
        return progress

    @application.post("/api/projects/{project_id}/sources/import-tju-folder")
    async def import_tju_folder(
        project_id: str,
        payload: ImportTjuFolderRequest,
        request: Request,
    ) -> dict[str, Any]:
        """从 cs.tjuse.com 课程共享站批量拉取用户在「课工」对话框勾选的文件。

        行为约定：
        - paths 为空 + include_readme=False → 直接 200 imported=0（用户主动放弃）
        - paths 不为空 → 逐文件下载、解析、入 source；任一失败不影响其它成功
        - 单文件 / 单批字节上限见 MAX_TJU_FILE_BYTES / MAX_TJU_BATCH_BYTES
        - 总是写一条 import.readme（当 include_readme=True 且 README.md 在目录里）
        - 返回 results 数组 + imported/skipped/failed 计数，前端可一一展示
        - 入库后追加 undo 记录，便于 Ctrl+Z 一次性撤回整批

        版权：调用前必须在 UI 上明示用户「自负版权风险」，本函数不为版权后果负责。
        """
        user = require_user(request)
        require_project_access(project_id, request)

        course: tuple[str, str, str] | None = None
        if payload.code:
            for entry in TJU_COURSES:
                if entry[0] == payload.code:
                    course = entry
                    break
        if course is None and payload.name:
            for entry in TJU_COURSES:
                if entry[1] == payload.name:
                    course = entry
                    break
        if course is None:
            return {
                "imported": 0,
                "skipped": 0,
                "failed": 0,
                "results": [],
                "reason": "课程库未收录此课程，请先用课名模糊匹配确认是否在 116 门之内。",
            }
        code, name, discipline = course
        dir_name = f"{code}_{name}"

        # 把用户勾选列表 + README 合并；README 单独走题目库默认 header
        targets: list[tuple[str, bool]] = []  # (path, is_readme)
        seen_paths: set[str] = set()
        for p in payload.paths:
            # 安全过滤：必须以 dir_name/ 开头，且不得跳出仓库
            p = (p or "").strip().replace("\\", "/")
            if not p or not p.startswith(dir_name + "/"):
                # 允许用户直接传 README 路径
                if p.lower().endswith("/readme.md") or p.lower() == "readme.md":
                    p = f"{dir_name}/README.md"
                else:
                    continue
            if p in seen_paths:
                continue
            seen_paths.add(p)
            targets.append((p, p.endswith("/README.md")))
        if payload.include_readme and not any(t[1] for t in targets):
            targets.append((f"{dir_name}/README.md", True))

        def _collect_linked_files(text_bytes: bytes, base_path: str) -> list[str]:
            """从 Markdown/文本里提取相对链接，返回仓库内有效路径列表。"""
            try:
                text = text_bytes.decode("utf-8", errors="ignore")
            except Exception:
                return []
            linked: list[str] = []
            # Markdown 链接 / 图片
            for m in re.finditer(r"!?\[([^\]]*)\]\(([^)]+)\)", text):
                url = m.group(2).strip()
                if url.startswith("http") or url.startswith("#"):
                    continue
                # 去掉锚点
                url = url.split("#")[0].split("?")[0]
                if not url:
                    continue
                # 相对路径 -> 绝对仓库路径
                abs_path = (
                    base_path.rsplit("/", 1)[0] + "/" + url
                    if "/" in base_path and not url.startswith("/")
                    else dir_name + "/" + url.lstrip("/")
                )
                abs_path = re.sub(r"/+", "/", abs_path)
                if abs_path.startswith(dir_name + "/"):
                    linked.append(abs_path)
            # 裸 URL（行内自动链接）
            for m in re.finditer(
                r"https?://raw\.githubusercontent\.com/superpung/TJU-CourseSharing/main/([^\s)]+)",
                text,
            ):
                raw_path = m.group(1).strip()
                if raw_path.startswith(dir_name + "/"):
                    linked.append(raw_path)
            return linked

        if not targets:
            return {"imported": 0, "skipped": 0, "failed": 0, "results": []}

        # 初始化进度追踪
        _tju_import_progress[project_id] = {
            "total": len(targets),
            "completed": 0,
            "current_file": "",
            "status": "downloading",
            "stage": "downloading",
            "stage_label": "正在下载并解析文件",
            "ocr_used": False,
            "current_kind": "",
            "current_size_bytes": 0,
        }

        # 总批次字节预算
        import httpx

        ordered_results: list[dict[str, Any] | None] = [None] * len(targets)
        linked_results: list[dict[str, Any]] = []
        batch_used = 0
        imported = 0
        skipped = 0
        failed = 0
        inserted_sources: list[Any] = []
        save_lock = asyncio.Lock()
        extra_linked: list[str] = []
        try:
            _proxy = _detect_proxy()
            async with httpx.AsyncClient(
                timeout=60,
                proxy=_proxy,
                limits=httpx.Limits(max_connections=16, max_keepalive_connections=8),
                follow_redirects=True,
            ) as client:
                # 流水线：每个文件独立走完 下载→解析→入库，各阶段重叠进行
                download_sem = asyncio.Semaphore(8)
                pdf_parse_sem = asyncio.Semaphore(2)

                async def save_source(
                    fname: str, body: bytes, extracted: Any, persist: bool
                ) -> Any | None:
                    """串行入库 + 落盘 + 批次预算检查。成功返回 Source，跳过/失败返回 None。"""
                    nonlocal batch_used
                    if getattr(extracted, "status", "ok") not in ("ok", "empty"):
                        return None
                    async with save_lock:
                        if batch_used + len(body) > MAX_TJU_BATCH_BYTES:
                            return None
                        saved = await asyncio.to_thread(
                            db.add_source, project_id, extracted
                        )
                        if persist and body:
                            await _persist_source_file(application, saved, body)
                        inserted_sources.append(saved)
                        batch_used += len(body)
                    return saved

                async def process_one(idx: int, path: str, is_readme: bool) -> None:
                    nonlocal imported, skipped, failed
                    fname = path.rsplit("/", 1)[-1]
                    try:
                        async with download_sem:
                            body, status = await _fetch_tju_file_bytes(client, path)
                        if body is None:
                            skipped += 1
                            ordered_results[idx] = {
                                "path": path,
                                "name": fname,
                                "ok": False,
                                "reason": (f"HTTP {status}" if status else "网络异常")
                                + ("（单文件超过 30MB 限制）" if status == 413 else ""),
                            }
                            return
                        # 报告当前文件类型与是否扫描件，供前端显示等待提示
                        kind_label = _file_kind_label(fname)
                        ocr_used = await asyncio.to_thread(_file_needs_ocr, fname, body)
                        async with save_lock:
                            _tju_import_progress[project_id]["current_file"] = fname
                            _tju_import_progress[project_id]["current_kind"] = (
                                kind_label
                            )
                            _tju_import_progress[project_id]["current_size_bytes"] = (
                                len(body)
                            )
                            _tju_import_progress[project_id]["ocr_used"] = ocr_used
                        if is_readme:
                            try:
                                text = body.decode("utf-8")
                            except UnicodeDecodeError:
                                text = body.decode("utf-8", errors="ignore")
                            header = (
                                f"<!-- 导入自 cs.tjuse.com（{dir_name}）\n"
                                f"     许可：CC BY-NC-SA 4.0（署名 - 非商业性使用 - 相同方式共享）\n"
                                f"     本文件含课程 README 文本（选课攻略/学长经验）。 -->\n\n"
                            )
                            extracted = await asyncio.to_thread(
                                extract_source,
                                filename=f"{dir_name} README.md",
                                content=b"",
                                pasted_text=header + text,
                            )
                        elif fname.lower().endswith(".pdf"):
                            async with pdf_parse_sem:
                                extracted = await _extract_uploaded_source(
                                    application, fname, body
                                )
                        else:
                            extracted = await asyncio.to_thread(
                                extract_source, filename=fname, content=body
                            )
                        if getattr(extracted, "status", "ok") not in ("ok", "empty"):
                            failed += 1
                            ordered_results[idx] = {
                                "path": path,
                                "name": fname,
                                "ok": False,
                                "reason": getattr(extracted, "error_message", None)
                                or extracted.status,
                            }
                            return
                        saved = await save_source(fname, body, extracted, not is_readme)
                        if saved is None:
                            skipped += 1
                            ordered_results[idx] = {
                                "path": path,
                                "name": fname,
                                "ok": False,
                                "reason": f"本批累计超过 {MAX_TJU_BATCH_BYTES // 1024 // 1024}MB 上限",
                            }
                            return
                        imported += 1
                        ordered_results[idx] = {
                            "path": path,
                            "name": fname,
                            "ok": True,
                            "source_id": saved.source_id,
                            "size_bytes": len(body),
                        }
                        # 收集 Markdown/文本里的相对链接文件，主批次后统一并发拉取
                        if (
                            payload.include_linked
                            and not is_readme
                            and fname.lower().endswith((".md", ".txt", ".markdown"))
                        ):
                            for linked_path in _collect_linked_files(body, path):
                                if linked_path in seen_paths:
                                    continue
                                seen_paths.add(linked_path)
                                extra_linked.append(linked_path)
                    except Exception as exc:  # noqa: BLE001
                        failed += 1
                        ordered_results[idx] = {
                            "path": path,
                            "name": fname,
                            "ok": False,
                            "reason": f"处理异常：{type(exc).__name__}",
                        }
                    finally:
                        async with save_lock:
                            _tju_import_progress[project_id]["completed"] += 1
                            _tju_import_progress[project_id]["current_file"] = fname

                await asyncio.gather(
                    *(
                        process_one(idx, path, is_readme)
                        for idx, (path, is_readme) in enumerate(targets)
                    )
                )

                # 第二轮：并发拉取关联文件（失败静默跳过，不计入 failed）
                if extra_linked:
                    _tju_import_progress[project_id]["stage"] = "downloading"
                    _tju_import_progress[project_id]["stage_label"] = "正在拉取关联文件"

                    async def process_linked(linked_path: str) -> None:
                        nonlocal imported
                        linked_fname = linked_path.rsplit("/", 1)[-1]
                        try:
                            async with download_sem:
                                lb, _ = await _fetch_tju_file_bytes(client, linked_path)
                            if lb is None:
                                return
                            kind_label = _file_kind_label(linked_fname)
                            ocr_used = await asyncio.to_thread(
                                _file_needs_ocr, linked_fname, lb
                            )
                            async with save_lock:
                                _tju_import_progress[project_id]["current_file"] = (
                                    linked_fname
                                )
                                _tju_import_progress[project_id]["current_kind"] = (
                                    kind_label
                                )
                                _tju_import_progress[project_id][
                                    "current_size_bytes"
                                ] = len(lb)
                                _tju_import_progress[project_id]["ocr_used"] = ocr_used
                            if linked_fname.lower().endswith(".pdf"):
                                async with pdf_parse_sem:
                                    lex = await _extract_uploaded_source(
                                        application, linked_fname, lb
                                    )
                            else:
                                lex = await asyncio.to_thread(
                                    extract_source, filename=linked_fname, content=lb
                                )
                            lsaved = await save_source(linked_fname, lb, lex, True)
                            if lsaved is None:
                                return
                            imported += 1
                            linked_results.append(
                                {
                                    "path": linked_path,
                                    "name": linked_fname,
                                    "ok": True,
                                    "source_id": lsaved.source_id,
                                    "size_bytes": len(lb),
                                }
                            )
                        except Exception:  # noqa: BLE001
                            return

                    await asyncio.gather(*(process_linked(p) for p in extra_linked))
        except Exception as exc:  # noqa: BLE001
            LOGGER.warning("import-tju-folder batch aborted: %s", exc, exc_info=True)
            _tju_import_progress[project_id]["status"] = "error"
            return {
                "imported": imported,
                "skipped": skipped,
                "failed": failed + 1,
                "results": [r for r in ordered_results if r is not None]
                + linked_results,
                "reason": f"批次中断：{type(exc).__name__}",
            }

        # 整批追加一条 undo 记录，便于一次性撤回
        if inserted_sources:
            try:
                row_payload = [
                    db.get_source_row(project_id, s.source_id) for s in inserted_sources
                ]
                record_undo(
                    user,
                    project_id,
                    "source.batch_add",
                    f"导入天大课程库 {name} 的 {len(inserted_sources)} 份资料",
                    {"project_id": project_id, "sources": row_payload},
                )
            except Exception:  # noqa: BLE001
                LOGGER.warning(
                    "record_undo failed for import-tju-folder", exc_info=True
                )

        _tju_import_progress[project_id]["status"] = "complete"
        return {
            "imported": imported,
            "skipped": skipped,
            "failed": failed,
            "results": [r for r in ordered_results if r is not None] + linked_results,
            "course": {"code": code, "name": name, "discipline": discipline},
        }

    @application.post("/api/projects/{project_id}/sources/import-tju")
    async def import_tju_source(
        project_id: str, payload: ImportTjuRequest, request: Request
    ) -> dict[str, Any]:
        """从 cs.tjuse.com 拉取该课 README.md 作为项目 source。

        ponytail: 用 httpx.AsyncClient 异步下载，避免阻塞事件循环；
        失败/404 时返回 imported=False，绝不创建空 source 污染项目。
        ponytail: 文本前注入 CC BY-NC-SA 4.0 署名头，模块级合规可追溯。
        """
        user = require_user(request)
        require_project_access(project_id, request)

        # 1. 在课程库里找课（code 优先，name 兜底）
        course: tuple[str, str, str] | None = None
        if payload.code:
            for entry in TJU_COURSES:
                if entry[0] == payload.code:
                    course = entry
                    break
        if course is None and payload.name:
            for entry in TJU_COURSES:
                if entry[1] == payload.name:
                    course = entry
                    break
        if course is None:
            return {
                "imported": False,
                "reason": "课程库未收录此课程，请先用课名模糊匹配确认是否在 116 门之内。",
            }
        code, name, discipline = course
        dir_name = f"{code}_{name}"

        # 2. 异步下载课程共享站 README
        import httpx

        url = (
            f"{TJU_SHARE_BASE_URL}/api/raw/?path=/{quote(dir_name, safe='/')}/README.md"
        )
        try:
            async with httpx.AsyncClient(timeout=15, proxy=_detect_proxy()) as client:
                resp = await client.get(
                    url,
                    headers={"User-Agent": "knoworigin-local"},
                    follow_redirects=True,
                )
            if resp.status_code == 404:
                return {
                    "imported": False,
                    "reason": "该课程目录下暂无 README 资料（仓库里可能只有课件/试卷）。",
                }
            resp.raise_for_status()
            readme_text = resp.text
        except Exception as exc:  # noqa: BLE001 - 网络层异常要透传给前端
            return {
                "imported": False,
                "reason": f"拉取失败：{type(exc).__name__}（多半是网络或仓库临时不可达）",
            }

        # 3. 加合规头：来源 + 许可 + 「仅 README 不含课件」
        header = (
            f"<!-- 导入自 cs.tjuse.com（{dir_name}）\n"
            f"     许可：CC BY-NC-SA 4.0（署名 - 非商业性使用 - 相同方式共享）\n"
            f"     本文件仅含课程 README 文本（选课攻略/学长经验），不含课件/试卷等资料。 -->\n\n"
        )
        final_text = header + readme_text

        # 4. 入库
        from core.parsers import extract_source

        extracted = extract_source(
            filename=f"{dir_name} README.md",
            content=b"",
            pasted_text=final_text,
        )
        saved = db.add_source(project_id, extracted)
        record_undo(
            user,
            project_id,
            "source.add",
            f"导入天大课程库 {name} 的 README",
            {
                "project_id": project_id,
                "sources": [db.get_source_row(project_id, saved.source_id)],
            },
        )
        return {
            "imported": True,
            "source_id": saved.source_id,
            "filename": saved.filename,
            "size_bytes": len(final_text.encode("utf-8")),
            "course": {"code": code, "name": name, "discipline": discipline},
        }

    # ==========================================================================
    # AI 用量记账 / 长期记忆 / 通知中心
    # --------------------------------------------------------------------------
    # **全部为新增端点**，既有端点的路径、签名、行为一律未改。
    # 命名空间：/api/usage/* · /api/memory/* · /api/notices/* · /api/admin/usage
    # （这四个顶层段此前均未占用）
    #
    # 三条硬约束：
    #   1. 三个 store 复用主库 sqlite 文件、独立连接（带 busy_timeout），表名带前缀
    #      （ai_usage / memory_* / notices），**不写 learning_events**，
    #      因此上线不会改变任何既有用户的掌握度与打卡曲线；
    #   2. 未登录 401、越权 404，沿用既有约定；
    #   3. 生成靠**懒触发**、无常驻定时任务 —— 本地优先产品没有东西会在用户
    #      不在场时替他跑 cron，也绝不在他不知情时调用模型花钱。
    #
    # 设计与取舍写在 core/usage.py · core/user_memory.py · core/notify.py 的模块头。
    # ==========================================================================

    def _aux_charge(owner_id: str, task: str) -> Any:
        """给后台任务（周报 / 记忆提取）手动记账的回调。

        这些任务刻意走**原始客户端**（不经过记账代理）—— 走代理的话，代理会在
        调用结束后再次检查"要不要提取"，形成递归。代价是用量得手动上报，
        否则"AI 自己偷偷花钱"在账面上就看不见了。
        """

        def _charge(prompt_text: str, output_text: str) -> None:
            try:
                usage_store().record(
                    owner_id=owner_id,
                    task=task,
                    mode="stream",
                    prompt_chars=len(prompt_text or ""),
                    output_chars=len(output_text or ""),
                    est_tokens=estimate_tokens(prompt_text)
                    + estimate_tokens(output_text),
                )
            except Exception:
                pass

        return _charge

    # ---------------------------- 用量 ---------------------------- #
    @application.get("/api/usage/me")
    async def my_ai_usage(request: Request, days: int = 7) -> dict[str, Any]:
        """当前用户的 AI 用量。口径是**估算**，界面必须如实标注。"""
        user = require_user(request)
        window = max(1, min(int(days), 90))
        summary = usage_store().summary(user.user_id, window)
        settings_now = application.state.settings
        quota = int(getattr(settings_now, "usage_daily_quota", 0) or 0)
        today = int(summary["today_tokens"])
        return {
            **summary,
            "quota": quota,
            # quota 为 0（未设限额）时 remaining 用 null，前端据此显示"未设限额"
            "remaining": (max(0, quota - today) if quota > 0 else None),
            "tracking_enabled": bool(
                getattr(settings_now, "usage_tracking_enabled", True)
            ),
            "estimated": True,
        }

    @application.get("/api/admin/usage")
    async def admin_ai_usage(request: Request, days: int = 7) -> dict[str, Any]:
        """全局用量排行（管理员）。用来回答"额度被谁、花在哪了"。"""
        require_admin(request)
        store = usage_store()
        window = max(1, min(int(days), 90))
        return {
            "totals": store.totals(),
            "ranking": store.admin_ranking(window, limit=50),
            "window_days": window,
            "quota": int(
                getattr(application.state.settings, "usage_daily_quota", 0) or 0
            ),
            "estimated": True,
        }

    # ---------------------------- 长期记忆 ---------------------------- #
    @application.get("/api/memory/notes")
    async def list_memory_notes(request: Request) -> dict[str, Any]:
        """列出 AI 记住的关于我的事。

        「可看、可删、可清空」是上线这个功能的前提 —— 记忆是关于人的数据，
        比资料敏感。做不到这三点就不该做。
        """
        user = require_user(request)
        store = memory_store()
        settings_now = application.state.settings
        return {
            "notes": store.list_notes(user.user_id, limit=200),
            "state": store.state(user.user_id),
            "enabled": bool(getattr(settings_now, "memory_enabled", True)),
            "kinds": [
                {"key": key, "label": label}
                for key, label in MEMORY_KIND_LABELS.items()
            ],
        }

    @application.post("/api/memory/notes", status_code=201)
    async def create_memory_note(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """手动添加一条记忆。用户自己写的，永远不会被"清空自动记忆"带走。"""
        user = require_user(request)
        kind = str(payload.get("kind") or "").strip()
        content = str(payload.get("content") or "").strip()
        if not content:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "memory_content_required", "请先写下要记住的内容。"
                ),
            )
        if len(content) > 200:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "memory_content_too_long",
                    "记忆内容请控制在 200 字以内 —— 太长会挤占资料上下文。",
                ),
            )
        if kind not in MEMORY_KIND_LABELS:
            kind = "preference"
        created = memory_store().add_note(user.user_id, kind, content, source="manual")
        if not created:
            raise HTTPException(
                status_code=409,
                detail=error_payload("memory_duplicate", "这条已经记过了。"),
            )
        return {"created": True}

    @application.delete("/api/memory/notes/{note_id}")
    async def delete_memory_note(note_id: str, request: Request) -> dict[str, Any]:
        user = require_user(request)
        removed = memory_store().delete_note(user.user_id, note_id)
        if not removed:
            # 与既有约定一致：越权/不存在一律 404，不泄漏"这条是否存在"
            raise HTTPException(
                status_code=404,
                detail=error_payload("memory_not_found", "这条记忆不存在。"),
            )
        return {"deleted": True}

    @application.post("/api/memory/clear")
    async def clear_memory(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """清空记忆。

        默认行为与既有版本**完全一致**（只清 AI 自动记的、保留手写的）——
        ``scope`` 是本次新增的**可选**参数，两个存储都按它分层清：
          - 不传 / ``all``（默认）：旧表 + 槽位表全清，保留手写条目
          - ``global``：只清全局画像
          - ``project``：只清当前项目的项目级记忆（全局画像不动）
        """
        user = require_user(request)
        keep_manual = payload.get("keep_manual", True)
        scope = str(payload.get("scope") or "all").strip().lower()
        if scope not in ("all", "global", "project"):
            scope = "all"
        store = memory_store()
        removed = store.clear(user.user_id, keep_manual=bool(keep_manual))
        if scope == "global":
            removed += store.clear_slots(user.user_id, scope=SCOPE_GLOBAL)
        elif scope == "project":
            # 同单格写入：/api/memory/* 不在 /api/projects/ 路径下，得显式带 project_id。
            # ⚠️ 拿不到就 400，绝不静默 no-op —— 「以为清掉了其实没清」是最危险的失效。
            target_project = str(
                payload.get("project_id") or ""
            ).strip() or _request_project_id(request)
            if not target_project:
                raise HTTPException(
                    status_code=400,
                    detail=error_payload(
                        "memory_project_required", "请先打开一个项目，再清空它的记忆。"
                    ),
                )
            removed += store.clear_slots(
                user.user_id, scope=SCOPE_PROJECT, project_id=target_project
            )
        else:
            removed += store.clear_slots(user.user_id, scope="all")
        return {"removed": removed, "kept_manual": bool(keep_manual), "scope": scope}

    @application.post("/api/memory/extract")
    async def extract_memory_now(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """立即从最近的对话里提取一次记忆。

        自动提取是攒批 + 后台跑的（见 core/user_memory.py），这里是给用户的
        手动入口：刚聊完一大段、想让它马上记住，不用等攒够轮数 —— 因此**绕过阈值**。
        """
        user = require_user(request)
        store = memory_store()
        owner = user.user_id
        # ⚠️ /api/memory/* 不在 /api/projects/{pid}/ 路径下，路径正则捞不到当前
        # 项目 —— 与 /api/memory/clear 同款：接受 body 显式带的 project_id。
        # 不带的话 extract_memories 只写全局格，项目级记忆永远学不到（2026-09-28）。
        target_project = (
            str(payload.get("project_id") or "").strip()
            or _request_project_id(request)
        ) or None
        result = await asyncio.to_thread(
            extract_memories,
            _raw_llm,
            store,
            owner,
            project_id=target_project,
            charge=_aux_charge(owner, "extract_user_memory"),
            weak_points_fn=_weak_nodes_for,
        )
        return {
            "added": result.get("added", 0),
            "items": result.get("items", []),
            "error": result.get("error", ""),
        }

    # ---------------------- 长期记忆 v2（两层槽位） ---------------------- #

    def _slot_payload(
        store: MemoryStore, owner_id: str, project_id: str
    ) -> dict[str, Any]:
        """把两层槽位渲染成前端直接能画的结构。

        ⚠️ 这里必须带上 ``vocab`` —— 词表只有 core/user_memory.py 一处定义，
        前端不许再抄一份（抄了就会漂移，两边对不上）。同理，空槽位也要返回
        （前端要画出「还没设置」的格子，而不是整块消失）。
        """
        data = store.list_slots(owner_id, project_id or None)
        state = store.state(owner_id)

        def _render(keys: tuple[str, ...], store_key: str) -> list[dict[str, Any]]:
            source = data[store_key]
            out: list[dict[str, Any]] = []
            for key in keys:
                row = source.get(key)
                if row is None:
                    out.append(
                        {
                            "slot_key": key,
                            "label": MEMORY_SLOT_LABELS.get(key, key),
                            "filled": False,
                        }
                    )
                    continue
                out.append(
                    {
                        "slot_key": key,
                        "label": row["label"],
                        "filled": True,
                        "value": row["value_data"],
                        "source": row["source"],
                        "evidence": row["evidence"],
                        "updated_at": row["updated_at"],
                        "last_injected_at": row["last_injected_at"],
                        # 旧值链：让用户看得见「AI 改了什么」
                        "history": store.history(row["slot_id"]),
                    }
                )
            return out

        return {
            "global": _render(GLOBAL_SLOTS, "global"),
            "project": _render(PROJECT_SLOTS, "project"),
            "project_id": project_id or "",
            "state": state,
            "onboarded": bool(state.get("onboarded_at")),
            "consent": bool(state.get("consent_at")),
            "memory_off": bool(int(state.get("memory_off") or 0)),
            "vocab": vocab_payload(),
        }

    @application.get("/api/memory/slots")
    async def list_memory_slots(
        request: Request, project_id: str = ""
    ) -> dict[str, Any]:
        """两层槽位全量。全局画像 + 当前项目的项目级记忆 + 推荐词表。"""
        user = require_user(request)
        target = project_id or _request_project_id(request)
        settings_now = application.state.settings
        payload = _slot_payload(memory_store(), user.user_id, target)
        payload["enabled"] = bool(getattr(settings_now, "memory_enabled", True))
        return payload

    @application.put("/api/memory/profile")
    async def update_memory_profile(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """一次性提交全局画像（首次引导用）。

        全局画像**只能被用户端点写** —— 提取流程对它只读。这正是 v1 那 7 条重复
        「在学量子力学」的根治手段：那些信息本来就该由用户自己声明。
        """
        user = require_user(request)
        store = memory_store()
        values = payload.get("slots") or payload
        if not isinstance(values, dict):
            raise HTTPException(
                status_code=400,
                detail=error_payload("memory_profile_invalid", "画像格式不对。"),
            )
        saved: list[str] = []
        skipped: list[str] = []
        for key in GLOBAL_SLOTS:
            if key not in values:
                continue
            raw = values[key]
            # 空值表示「清掉这一格」，不是「填了个空」
            if raw in (None, "", [], {}):
                store.delete_slot(user.user_id, key, scope=SCOPE_GLOBAL)
                saved.append(key)
                continue
            try:
                normalized = normalize_value(key, raw)
            except SlotValueError:
                skipped.append(key)
                continue
            store.upsert_slot(
                user.user_id,
                SCOPE_GLOBAL,
                key,
                normalized,
                source="declared",
            )
            saved.append(key)
        return {
            "saved": saved,
            "skipped": skipped,
            **_slot_payload(store, user.user_id, _request_project_id(request)),
        }

    @application.put("/api/memory/slots/{slot_key}")
    async def update_memory_slot(
        slot_key: str,
        request: Request,
        payload: dict[str, Any] = Body(default={}),
    ) -> dict[str, Any]:
        """改一格（全局或项目级）。手动改的条目标记 source=manual。"""
        user = require_user(request)
        if slot_key not in MEMORY_SLOT_LABELS:
            raise HTTPException(
                status_code=404,
                detail=error_payload("memory_slot_not_found", "没有这一格。"),
            )
        scope = str(payload.get("scope") or "").strip().lower()
        if scope not in (SCOPE_GLOBAL, SCOPE_PROJECT):
            scope = SCOPE_GLOBAL if slot_key in GLOBAL_SLOTS else SCOPE_PROJECT
        # 作用域与槽位必须匹配，否则「当前的卡点」会被写进全局画像
        if (scope == SCOPE_GLOBAL) != (slot_key in GLOBAL_SLOTS):
            raise HTTPException(
                status_code=400,
                detail=error_payload("memory_scope_mismatch", "这一格不属于该作用域。"),
            )
        # ⚠️ /api/memory/* 不在 /api/projects/{pid}/ 路径下，中间件的路径正则捞不到
        # 当前项目 —— 所以这里必须接受 body 里显式带的 project_id。
        project_id = str(
            payload.get("project_id") or ""
        ).strip() or _request_project_id(request)
        if scope == SCOPE_PROJECT and not project_id:
            raise HTTPException(
                status_code=400,
                detail=error_payload("memory_project_required", "请先打开一个项目。"),
            )
        store = memory_store()
        value = payload.get("value")
        if value in (None, "", [], {}):
            store.delete_slot(
                user.user_id, slot_key, scope=scope, project_id=project_id or None
            )
            return {"deleted": True, **_slot_payload(store, user.user_id, project_id)}
        try:
            normalized = normalize_value(slot_key, value)
        except SlotValueError as exc:
            raise HTTPException(
                status_code=400,
                detail=error_payload("memory_value_invalid", str(exc)),
            ) from exc
        outcome = store.upsert_slot(
            user.user_id,
            scope,
            slot_key,
            normalized,
            project_id=project_id or None,
            source="manual",
        )
        return {"outcome": outcome, **_slot_payload(store, user.user_id, project_id)}

    @application.delete("/api/memory/slots/{slot_key}")
    async def delete_memory_slot(
        slot_key: str,
        request: Request,
        scope: str = "",
        project_id: str = "",
    ) -> dict[str, Any]:
        user = require_user(request)
        if slot_key not in MEMORY_SLOT_LABELS:
            raise HTTPException(
                status_code=404,
                detail=error_payload("memory_slot_not_found", "没有这一格。"),
            )
        target_scope = (scope or "").strip().lower()
        if target_scope not in (SCOPE_GLOBAL, SCOPE_PROJECT):
            target_scope = SCOPE_GLOBAL if slot_key in GLOBAL_SLOTS else SCOPE_PROJECT
        target_project = project_id or _request_project_id(request)
        store = memory_store()
        removed = store.delete_slot(
            user.user_id,
            slot_key,
            scope=target_scope,
            project_id=target_project or None,
        )
        if not removed:
            # 与既有约定一致：越权/不存在一律 404
            raise HTTPException(
                status_code=404,
                detail=error_payload("memory_slot_not_found", "这一格是空的。"),
            )
        return {"deleted": True, **_slot_payload(store, user.user_id, target_project)}

    @application.post("/api/memory/consent")
    async def mark_memory_consent(request: Request) -> dict[str, Any]:
        """首次告知已读。

        原设计只做了「可看、可删、可清空」——那是**事后控制**。对多用户产品还缺
        **事前告知**：记忆是关于人的数据，用户有权在被记录之前就知道。
        """
        user = require_user(request)
        at = memory_store().set_consent(user.user_id)
        return {"consent_at": at}

    @application.post("/api/memory/onboarded")
    async def mark_memory_onboarded(request: Request) -> dict[str, Any]:
        """标记首次引导已完成（或已跳过）。"""
        user = require_user(request)
        at = memory_store().set_onboarded(user.user_id)
        return {"onboarded_at": at}

    @application.post("/api/memory/opt-out")
    async def set_memory_opt_out(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """per-user 总开关：一键关闭 / 重新打开记忆。

        首次告知里那句「随时能关」必须是真的能关，不是弹一句提示。
        数据不删（重新打开即恢复），但从此**两条注入路径都不再带记忆** ——
        关的总开关在 ``memory_block_for``，messages 与 payload 两条路都过它。
        """
        user = require_user(request)
        off = bool(payload.get("off", True))
        memory_store().set_memory_off(user.user_id, off)
        return {
            "memory_off": off,
            **_slot_payload(memory_store(), user.user_id, _request_project_id(request)),
        }

    # ---------------------------- 通知中心 ---------------------------- #
    @application.get("/api/notices")
    async def list_notices(request: Request, limit: int = 40) -> dict[str, Any]:
        """通知列表。**打开即补齐** —— 这是本地优先产品的"定时任务"替代方案。"""
        user = require_user(request)
        store = notice_store()
        owner = user.user_id
        try:
            notify_mod.refresh(
                store,
                owner,
                llm=_raw_llm,
                owner_name=user.name,
                charge=_aux_charge(owner, "weekly_report"),
                weekly_enabled=bool(
                    getattr(application.state.settings, "notice_weekly_enabled", True)
                ),
            )
        except Exception:
            # 通知生成失败绝不该让面板打不开
            LOGGER.warning("notices refresh failed", exc_info=True)
        return {
            "notices": store.list_notices(owner, limit=max(1, min(int(limit), 100))),
            "unread": store.unread_count(owner),
        }

