    # ==========================================================================
    # 间隔复习（FSRS）· 掌握度可信度审计 · 文献引用导出
    # --------------------------------------------------------------------------
    # **全部为新增端点**，既有端点的路径、签名、行为一律未改。
    # 命名空间：
    #   /api/review/*                          —— 间隔复习
    #   /api/projects/{id}/mastery/audit       —— 掌握度可信度审计
    #   /api/literature/{id}/citation          —— BibTeX / CSL JSON 导出
    #   /api/literature/{id}/enrich-metadata   —— Crossref 补全 DOI
    #
    # 三条硬约束：
    #   1. FSRS **复用 core/english_vocab.py 的既有实现**（同一套算法不写第二遍），
    #      SRS 状态独立成表 card_srs_state，不碰 cards 表与其 payload JSON；
    #   2. 掌握度**只审计、不改分** —— 改权重会动到所有既有用户的历史曲线，
    #      比误判本身更糟。审计如实摆出证据结构，让分数可被质疑；
    #   3. 引用导出**绝不编造字段**（缺就省略），DOI 补全失败一律降级。
    # ==========================================================================

    # ------------------------- 间隔复习 ------------------------- #
    @application.get("/api/review/queue")
    async def review_queue(
        request: Request, project_id: str = "", limit: int = 30
    ) -> dict[str, Any]:
        """今日到期队列：已到期的旧卡 + 有限张新卡。

        不传 project_id 时跨全部项目取 —— "今天该复习什么"本来就是跨课程的。
        """
        user = require_user(request)
        if project_id:
            require_project_access(project_id, request)
        store = review_store()
        size = max(1, min(int(limit), 100))
        return {
            "cards": store.due_cards(user.user_id, project_id=project_id, limit=size),
            "stats": store.stats(user.user_id, project_id=project_id),
            "forecast": store.forecast(user.user_id, days=7),
            "recent": store.recent_logs(user.user_id, limit=15),
        }

    @application.get("/api/review/preview")
    async def review_preview(request: Request, card_id: str) -> dict[str, Any]:
        """四个评级各自会把下次复习推到多久 —— 给按钮标注"4 天 / 12 天"。

        用户在 Again 和 Easy 之间犹豫时，唯一能帮他决策的信息就是"选这个下次什么时候见"。
        """
        user = require_user(request)
        store = review_store()
        context = store.card_context(card_id)
        if context is None or context["owner_id"] != user.user_id:
            # 越权与不存在一律 404，与既有约定一致
            raise HTTPException(
                status_code=404,
                detail=error_payload("card_not_found", "这张卡片不存在。"),
            )
        return {
            "card_id": card_id,
            "intervals": interval_preview(
                store, owner_id=user.user_id, card_id=card_id
            ),
            "retention": retention_of(store, owner_id=user.user_id, card_id=card_id),
        }

    @application.post("/api/review/submit")
    async def review_submit(
        request: Request, payload: dict[str, Any] = Body(default={})
    ) -> dict[str, Any]:
        """提交一次复习。

        除了推进 FSRS 状态，还会**同步写一条 kind="card" 的掌握度证据** ——
        否则会出现"复习了但掌握度不动"这种两个模块各说各话的状态。
        """
        user = require_user(request)
        card_id = str(payload.get("card_id") or "").strip()
        if not card_id:
            raise HTTPException(
                status_code=400,
                detail=error_payload("card_id_required", "缺少卡片标识。"),
            )
        store = review_store()
        context = store.card_context(card_id)
        if context is None or context["owner_id"] != user.user_id:
            raise HTTPException(
                status_code=404,
                detail=error_payload("card_not_found", "这张卡片不存在。"),
            )

        try:
            elapsed_ms = max(0, int(payload.get("elapsed_ms") or 0))
        except (TypeError, ValueError):
            elapsed_ms = 0

        result = submit_review(
            store,
            owner_id=user.user_id,
            card_id=card_id,
            project_id=context["project_id"],
            rating=payload.get("rating"),
            elapsed_ms=elapsed_ms,
            self_answer=str(payload.get("self_answer") or ""),
        )

        # 同步掌握度：卡片关联的节点各自记一笔证据。
        node_ids = context["node_ids"]
        if node_ids:
            try:
                # 多节点时可信度调低 —— 一张卡同时打多个节点，单点证据更弱
                confidence = 0.9 if len(node_ids) <= 1 else 0.7
                review_fp = _item_fingerprint(
                    (context.get("card_front") or "") or card_id
                )
                record_evidence(
                    db,
                    context["project_id"],
                    node_ids,
                    "card",
                    result["correctness"],
                    confidence,
                    card_id,
                    difficulty=int(context.get("card_difficulty") or 1),
                    item_fingerprint=review_fp,
                    repeat_count=_count_item_repeats(
                        db, context["project_id"], review_fp
                    ),
                )
            except Exception:
                # 掌握度更新失败不该让复习白做 —— SRS 状态已经落库了
                LOGGER.warning("review_submit mastery update failed", exc_info=True)

        return result

