    # ------------------------- 掌握度可信度审计 ------------------------- #
    @application.get("/api/projects/{project_id}/mastery/audit")
    async def mastery_audit(project_id: str, request: Request) -> dict[str, Any]:
        """找出「分数高、但证据薄」的节点。

        典型情形：在一个节点上提问十几次，掌握度就到 80% 了，却从没做过一道题。
        本端点**不改分数**，只把证据构成摆出来供质疑 —— 详见 core/mastery_audit.py。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        return await asyncio.to_thread(
            mastery_audit_mod.audit_project, db.path, user.user_id, project_id
        )

    # ======================================================================
    # 迁移（泛化）：换个情境试试 · 迁移分 · 跨项目概念图
    # ======================================================================
    #
    # 命名空间刻意新开在 ``/api/transfer/*``：``/api/projects/{id}/...`` 已有同段数
    # 通配端点，新端点挂在那儿会被注册顺序抢走并返回 404（第一梯队已踩过一次，
    # 见 /api/review/status 的注释）。迁移又不是某个项目的从属数据 ——
    # 跨项目那一半根本不属于单个项目，所以放项目路径下语义也不对。
    #
    # 三个只读端点 + 两个写端点。两个写端点都要确认项目归属，
    # 且**都不删任何既有数据**（迁移只加分，不改 mastery_score）。

    def _transfer_store() -> ConceptStore:
        return ConceptStore(db.path)

    # 位阶排序权重：候选列表按「先看会了没、再看掌握度」排。
    # 与 progress_engine.STAGE_ORDER 同值 —— 只在这里复制一份是漂移温床，
    # 所以下面直接引用它，而不是再写一个 STAGE_RANK。
    STAGE_RANK = {
        stage: index
        for index, stage in enumerate(progress_engine_mod.STAGE_ORDER)
    }

    def _recommended_transfer_node(
        project_id: str,
    ) -> tuple[str | None, dict[str, Any]]:
        """挑「最该补迁移证据」的节点，并说明为什么挑它。

        纪律与 progress_engine 一致：**只按已有的结构事实排序**。
        没有前置图的节点不进候选 —— 它出不了组合题，出去了也只会退回成
        又一道识记题，那样只是白烧一次模型调用。
        """
        nodes = db.list_framework_nodes(project_id)
        if not nodes:
            return None, {"reason": "这个项目还没有知识框架，先生成框架再来验迁移。"}
        layers = _node_layer_map(nodes)
        by_id = {n.node_id: n for n in nodes}
        stage_map = _stage_by_node(db, project_id)
        scored: list[tuple[int, str]] = []
        for node in nodes:
            gap = transfer_mod.transfer_gap_score(
                stage=stage_map.get(node.node_id, "none"),
                transfer_score=node.transfer_score,
                has_prereq=bool(node.prerequisite_ids),
                due_cards=0,
            )
            if gap:
                scored.append((gap, node.node_id))
        if not scored:
            return None, {
                "reason": (
                    "现在没有「已经会了、但还没验过迁移」的知识点 —— "
                    "先把框架里的点学到「会了」，再回来验迁移。"
                )
            }
        scored.sort(key=lambda item: (-item[0], item[1]))
        best_gap, best_id = scored[0]
        node = by_id[best_id]
        return best_id, {
            "reason": (
                f"「{node.name}」已经会了，迁移还是未验证，而且它有前置"
                f"（第 {layers.get(best_id, 0)} 层）—— 只有这种点才出得了组合题。"
            ),
            "gap": best_gap,
            "layer": layers.get(best_id, 0),
            "candidates": [by_id[n].name for _, n in scored[:5] if n in by_id],
        }

    @application.get("/api/transfer/{project_id}/readiness")
    async def transfer_readiness(
        project_id: str, request: Request, node_id: str = ""
    ) -> dict[str, Any]:
        """这个项目（或某个节点）的迁移准备度：为什么现在该验迁移。

        只读。不调模型 —— 所以它可以在「还没有 API Key」时也照常返回，
        前端据此决定要不要显示「换个情境试试」这个入口。
        """
        require_project_access(project_id, request)
        nodes = db.list_framework_nodes(project_id)
        layers = _node_layer_map(nodes)
        by_id = {n.node_id: n for n in nodes}
        stage_map = _stage_by_node(db, project_id)

        def _one(nid: str) -> dict[str, Any]:
            node = by_id.get(nid)
            if node is None:
                return {"node_id": nid, "error": "node_not_found"}
            stage = stage_map.get(nid, "none")
            return {
                "node_id": nid,
                "name": node.name,
                "layer": layers.get(nid, 0),
                "stage": stage,
                "mastery_score": round(node.mastery_score, 4),
                "transfer_score": round(node.transfer_score, 4),
                "transfer_stage": transfer_mod.transfer_stage(node.transfer_score),
                "transfer_stage_label": transfer_mod.TRANSFER_STAGE_LABELS[
                    transfer_mod.transfer_stage(node.transfer_score)
                ],
                "prereq_count": len(node.prerequisite_ids or []),
                "prereq_names": [
                    by_id[p].name for p in (node.prerequisite_ids or []) if p in by_id
                ],
                "ready": bool(
                    transfer_mod.transfer_gap_score(
                        stage=stage,
                        transfer_score=node.transfer_score,
                        has_prereq=bool(node.prerequisite_ids),
                        due_cards=0,
                    )
                ),
            }

        picked, why = (
            (node_id, {})
            if node_id
            else _recommended_transfer_node(project_id)
        )
        # 候选兜底：**推荐为 0 也要给得出手动可选的节点**。
        # 迁移桶的门槛是位阶「会了」，而一个刚开始学的项目里没有任何节点到过那里 ——
        # 于是「换个情境试试」会整个消失，用户永远看不到这个能力长什么样。
        # 推荐是推荐，不是许可：只要节点有前置（出得了组合题）就允许试一次。
        # 顺序按「位阶高 → 掌握度高」排，最值得试的自然浮到前面。
        candidates = [
            _one(nid)
            for nid in sorted(
                (
                    n.node_id
                    for n in nodes
                    if n.prerequisite_ids and any(p in by_id for p in (n.prerequisite_ids or []))
                ),
                key=lambda nid: (
                    -STAGE_RANK.get(stage_map.get(nid, "none"), 0),
                    -by_id[nid].mastery_score,
                    by_id[nid].name,
                ),
            )
        ][:12]
        store = _transfer_store()
        try:
            recent = (
                store.recent_attempts(project_id=project_id, node_id=node_id or None)
                if node_id
                else []
            )
            # 历史：出过的**每一道**都留痕（含还没作答的）。
            # 前端用它做「历史」区，也用它做「关掉弹窗再回来还是原来那道」——
            # 后者是「关闭后不重新开始」的落点：真值在库里，不在页面内存里。
            history = store.list_attempts(project_id=project_id, limit=10)
        finally:
            store.close()
        # 最新一轮测验实际跨了几个知识点。这是**实测值**（生成时回算的），
        # 不是 payload 里写的计划 —— 界面显示的必须是实际发生过的交错。
        latest_quiz = db.get_latest_quiz(project_id) or {}
        latest_spread = latest_quiz.get("spread") or {}
        return {
            "project_id": project_id,
            "recommended_node_id": picked,
            "recommendation": why,
            "target": _one(picked) if picked else None,
            "candidates": candidates,
            "has_recommendation": bool(picked),
            "latest_quiz": {
                "quiz_id": latest_quiz.get("quiz_id"),
                "difficulty": latest_quiz.get("difficulty"),
                "node_count": int(latest_spread.get("node_count") or 0),
                "interleaved": bool(latest_spread.get("interleaved")),
                "planned": bool(latest_quiz.get("interleave_planned")),
            },
            "distances": [
                {"key": key, "label": transfer_mod.TRANSFER_DISTANCE_LABELS[key],
                 "hint": transfer_mod.TRANSFER_DISTANCE_HINTS[key]}
                for key in transfer_mod.TRANSFER_DISTANCES
            ],
            "recent_attempts": recent,
            "history": history,
            "history_total": (history[0]["total"] if history else 0),
            "rules": {
                "min_alignment_steps": transfer_mod.MIN_ALIGNMENT_STEPS,
                "distance_labels": transfer_mod.TRANSFER_DISTANCE_LABELS,
            },
        }

    @application.post("/api/transfer/{project_id}/task")
    async def transfer_task(
        project_id: str, request: Request, payload: TransferRequest
    ) -> dict[str, Any]:
        """出一道渐进式对齐的迁移题。

        三个设计决定：
        1. **模型不出结构就整题作废**（``normalize_transfer_task`` 返回 None）。
           降级成一段「它们很像」的文字看起来无害，实际上是零迁移 ——
           所以宁可回 502 让前端如实说「这次没出成」，也不要展示一道假题。
        2. 无 API Key → 503，与卡片/测验同一套处理。
        3. 距离档位由后端按节点情况**推荐**并在响应里说明理由；用户显式指定时
           以用户为准，但会在响应里如实标注这是手动选择。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "迁移题需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        nodes = db.list_framework_nodes(project_id)
        if not nodes:
            raise HTTPException(
                status_code=409,
                detail=error_payload(
                    "framework_required",
                    "还没有知识框架，先把材料拆成知识点再来验迁移。",
                ),
            )
        layers = _node_layer_map(nodes)
        by_id = {n.node_id: n for n in nodes}

        picked = (payload.node_id or "").strip()
        if picked and picked not in by_id:
            raise HTTPException(
                status_code=404,
                detail=error_payload("node_not_found", "这个知识点不存在。"),
            )
        distance_reason = ""
        if not picked:
            picked, why = _recommended_transfer_node(project_id)
            distance_reason = str(why.get("reason") or "")
        if not picked:
            raise HTTPException(
                status_code=409,
                detail=error_payload("no_transfer_candidate", distance_reason or "现在没有适合验迁移的知识点。"),
            )
        node = by_id[picked]

        # 距离档位：显式指定优先；否则按「层差」推 —— 有层差 ≥1 的前置才配远档。
        if payload.distance:
            distance = payload.distance
            distance_reason = distance_reason or "距离档位由你手动指定。"
        else:
            gap_layers = [
                layers.get(p, 0) for p in (node.prerequisite_ids or []) if p in by_id
            ]
            if any(abs(layers.get(picked, 0) - value) >= 1 for value in gap_layers):
                distance = "far"
                distance_reason = distance_reason or (
                    "它与某个前置之间还隔着别的知识点（层差 ≥1），"
                    "所以默认给一道远迁移（换领域、只留结构）。"
                )
            else:
                distance = "near"
                distance_reason = distance_reason or (
                    "它与前置紧挨着（层差 0），组合不出新东西，默认给一道近迁移（换条件）。"
                )

        source_text = _node_context_text(project_id, picked)
        store = _transfer_store()
        try:
            recent = store.recent_attempts(project_id=project_id, node_id=picked, limit=8)
            payload_dict = transfer_mod.build_transfer_payload(
                node={
                    "node_id": picked,
                    "name": node.name,
                    "description": node.description,
                },
                prereqs=_prereq_briefs([node], by_id, layers, limit=5),
                sources_text=source_text,
                distance=distance,
                answered_recently=[item["question"] for item in recent],
            )
            payload_dict["avoid_repeating"] = [
                item["question"] for item in recent if item["question"]
            ]
            try:
                response = await asyncio.to_thread(
                    application.state.llm.complete_json,
                    # 字面量而非 transfer_mod.TRANSFER_TASK_NAME：提示词目录门禁
                    # (tools/check_prompt_catalog.py) 只认字面量/模块级字符串常量，
                    # 用属性访问它会把这个任务误判成「死条目」（界面上有按钮但没有调用点）。
                    # 一致性由 tools/verify_transfer_regression.py 钉住。
                    "transfer_variant",
                    payload_dict,
                )
            except ModelOutputError as exc:
                LOGGER.warning("transfer task malformed output: %s", str(exc)[:300])
                raise HTTPException(
                    status_code=502,
                    detail=error_payload(
                        "transfer_task_rejected",
                        "这次的迁移题没出成：模型没有给出必须的对齐结构（逐项对齐表不足 "
                        f"{transfer_mod.MIN_ALIGNMENT_STEPS} 步，或缺采分点）。"
                        "再点一次试试；这是宁可不出也不出假题的取舍。",
                    ),
                ) from exc
            cleaned = transfer_mod.normalize_transfer_task(
                response.get("transfer") or response
            )
            if not cleaned:
                raise HTTPException(
                    status_code=502,
                    detail=error_payload(
                        "transfer_task_rejected",
                        "这次的迁移题没出成：没通过结构校验（对齐表或采分点不完整）。"
                        "再点一次试试。",
                    ),
                )
            attempt_id = store.record_attempt(
                owner_id=user.user_id,
                project_id=project_id,
                node_id=picked,
                distance=cleaned["distance"],
                payload=cleaned,
            )
            return {
                "attempt_id": attempt_id,
                "project_id": project_id,
                "node_id": picked,
                "node_name": node.name,
                "distance": cleaned["distance"],
                "distance_label": transfer_mod.TRANSFER_DISTANCE_LABELS[cleaned["distance"]],
                "distance_reason": distance_reason,
                "prereq_names": [
                    by_id[p].name for p in (node.prerequisite_ids or []) if p in by_id
                ],
                "task": cleaned,
                "recent_count": len(recent),
            }
        finally:
            store.close()

    @application.post("/api/transfer/{project_id}/submit")
    async def transfer_submit(
        project_id: str, request: Request, payload: TransferSubmitRequest
    ) -> dict[str, Any]:
        """提交一道迁移题。

        写的是 ``transfer_score``，**不碰 mastery_score**。理由写在
        core/transfer.py 的模块头：记忆分与迁移分是两个构念，
        合成一个数字就等于告诉用户「刷识记题就能学会迁移」。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        store = _transfer_store()
        try:
            attempt = store.get_attempt(payload.attempt_id)
            if attempt is None or attempt["project_id"] != project_id:
                raise HTTPException(
                    status_code=404,
                    detail=error_payload("attempt_not_found", "这道迁移题不存在或已被清理。"),
                )
            if attempt["submitted_at"]:
                # 已提交过：如实说，而不是默默把分数再加一次
                return {
                    "already_submitted": True,
                    "correctness": attempt["correctness"],
                    "transfer_score": _node_transfer_score(db, project_id, attempt["node_id"]),
                    "message": "这道题已经提交过了，分数不会再加一次。",
                }
            if payload.self_rating is None:
                # 迁移题必然是开放题，没有判分依据就不能记分 —— 拒绝而不是猜
                raise HTTPException(
                    status_code=422,
                    detail=error_payload(
                        "self_rating_required",
                        "迁移题没有标准答案，必须给出你的自评（0~4）才能计入迁移分。",
                    ),
                )
            correctness = min(
                _self_rating_correctness(payload.self_rating),
                _SELF_ASSESSED_TRANSFER_CEILING,
            )
            store.submit_attempt(
                attempt_id=payload.attempt_id,
                answer=payload.answer,
                correctness=correctness,
            )
            node_id = attempt["node_id"]
            distance = attempt["distance"]
            updated = record_evidence(
                db,
                project_id,
                [node_id],
                MASTERY_TRANSFER_KIND,
                correctness,
                0.95,
                reference_id=payload.attempt_id,
                self_confidence=payload.self_confidence,
                difficulty=3,
                repeat_count=_count_transfer_attempts(
                    store, project_id, node_id, distance
                ),
                target="transfer",
                transfer_distance=distance,
            )
            score = updated[0].transfer_score if updated else 0.0
            stage = transfer_mod.transfer_stage(score)
            return {
                "already_submitted": False,
                "node_id": node_id,
                "correctness": correctness,
                "distance": distance,
                "distance_label": transfer_mod.TRANSFER_DISTANCE_LABELS.get(distance, distance),
                "transfer_score": round(score, 4),
                "transfer_stage": stage,
                "transfer_stage_label": transfer_mod.TRANSFER_STAGE_LABELS[stage],
                "next_hint": _transfer_next_hint(stage),
                "updated_nodes": [model_to_dict(n) for n in updated],
            }
        finally:
            store.close()

    @application.get("/api/transfer/{project_id}/attempts")
    async def transfer_attempts(
        project_id: str, request: Request, limit: int = 20, node_id: str = ""
    ) -> dict[str, Any]:
        """历史：出过的每一道迁移题（新的在前，带「第几道」序号）。

        只读。作答结果在 ``transfer_attempts.correctness``，迁移分的真值仍在
        ``framework_nodes.transfer_score`` —— 历史只负责「留痕」，不负责算分。
        """
        require_project_access(project_id, request)
        store = _transfer_store()
        try:
            items = store.list_attempts(
                project_id=project_id,
                limit=max(1, min(int(limit or 20), 200)),
                node_id=node_id or None,
            )
            return {
                "project_id": project_id,
                "items": items,
                "total": items[0]["total"] if items else 0,
                "distance_labels": transfer_mod.TRANSFER_DISTANCE_LABELS,
            }
        finally:
            store.close()

    @application.get("/api/transfer/{project_id}/attempts/{attempt_id}")
    async def transfer_attempt_detail(
        project_id: str, attempt_id: str, request: Request
    ) -> dict[str, Any]:
        """重新打开某一道历史迁移题（含完整对齐表与采分点）。

        这就是「关掉弹窗再回来还是原来那道、不会重新开始」的服务端依据：
        题目内容一直在库里，前端不必靠页面内存撑住它，刷新浏览器也还在。
        """
        require_project_access(project_id, request)
        store = _transfer_store()
        try:
            attempt = store.get_attempt(attempt_id)
            if attempt is None or attempt["project_id"] != project_id:
                raise HTTPException(
                    status_code=404,
                    detail=error_payload("attempt_not_found", "这道迁移题不存在。"),
                )
            node = db.get_framework_node(project_id, attempt["node_id"])
            item = next(
                (
                    x
                    for x in store.list_attempts(project_id=project_id, limit=200)
                    if x["attempt_id"] == attempt_id
                ),
                None,
            )
            return {
                "attempt_id": attempt["attempt_id"],
                "project_id": project_id,
                "node_id": attempt["node_id"],
                "node_name": node.name,
                "distance": attempt["distance"],
                "distance_label": transfer_mod.TRANSFER_DISTANCE_LABELS.get(
                    attempt["distance"], attempt["distance"]
                ),
                "task": attempt["payload"],
                "answered": bool(attempt["submitted_at"]),
                "correctness": attempt["correctness"],
                "transfer_score": round(node.transfer_score, 4),
                "transfer_stage_label": transfer_mod.TRANSFER_STAGE_LABELS[
                    transfer_mod.transfer_stage(node.transfer_score)
                ],
                "seq": (item or {}).get("seq"),
                "total": (item or {}).get("total"),
                "created_at": attempt["created_at"],
                "submitted_at": attempt["submitted_at"],
            }
        finally:
            store.close()

    @application.get("/api/transfer/{project_id}/concepts")
    async def transfer_concepts(
        project_id: str, request: Request, min_projects: int = 2, limit: int = 50
    ) -> dict[str, Any]:
        """跨项目概念视图：同一个概念在各项目里的掌握度/迁移分对照。

        先按需建一次对齐（框架变了才需要），再返回视图。
        对齐走本地 hash，不调模型 —— 快、免费、离线可用。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        store = _transfer_store()
        try:
            store.align_project(
                owner_id=user.user_id,
                project_id=project_id,
                nodes=_concept_nodes(db, project_id),
            )
            store.sync_scores(owner_id=user.user_id, project_id=project_id)
            return await asyncio.to_thread(
                store.cross_project_view,
                owner_id=user.user_id,
                min_projects=max(2, int(min_projects or 2)),
                limit=max(1, min(int(limit or 50), 200)),
            )
        finally:
            store.close()

    @application.get("/api/transfer/queue")
    async def transfer_queue(
        request: Request, limit: int = 6
    ) -> dict[str, Any]:
        """跨项目泛化队列：**在别的项目验过、在这个项目还没验过**的同一概念。

        路径是 ``/api/transfer/queue``（两段），刻意不挂在 ``/api/transfer/{project_id}/...``
        下面 —— 那是三段通配，会把「queue」当成 project_id 抢走并 404。
        """
        user = require_user(request)
        store = _transfer_store()
        try:
            # 先把所有项目同步一遍：分数一直在变，队列不能是上一次打开时的快照
            for project in db.list_projects(user.user_id):
                try:
                    store.align_project(
                        owner_id=user.user_id,
                        project_id=project.project_id,
                        nodes=_concept_nodes(db, project.project_id),
                    )
                    store.sync_scores(
                        owner_id=user.user_id, project_id=project.project_id
                    )
                except Exception:
                    # 单个项目坏掉不该让整个队列 500
                    LOGGER.warning(
                        "concept align failed for project %s",
                        project.project_id,
                        exc_info=True,
                    )
            return store.transfer_queue(
                owner_id=user.user_id, limit=max(1, min(int(limit or 6), 50))
            )
        finally:
            store.close()

    @application.post("/api/transfer/{project_id}/align")
    async def transfer_align_concepts(
        project_id: str, request: Request, payload: ConceptAlignRequest
    ) -> dict[str, Any]:
        """跨学科术语对齐（可选、需手动触发）：把本项目术语对齐到已知概念清单。

        为什么默认不做：本地 hash 只能合并「写法相近」的术语，
        「傅里叶变换」与「Fourier Transform」不会自动并成同一个概念 ——
        那需要一次显式的模型判断，而模型判断会引入「合并错」的风险。
        所以这里做成手动开关，并把 confidence 低的结果如实标出来。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "跨学科术语对齐需要大模型 API（它要把不同课程的说法并成同一个概念）。",
                ),
            )
        nodes = db.list_framework_nodes(project_id)
        wanted = {n.strip() for n in (payload.node_ids or []) if n.strip()}
        selected = [n for n in nodes if not wanted or n.node_id in wanted]
        if not selected:
            return {"merged": [], "note": "没有可对齐的知识点。"}
        store = _transfer_store()
        try:
            existing = store.cross_project_view(
                owner_id=user.user_id, min_projects=1, limit=200
            )
            payload_dict = concept_graph_mod.align_payload(
                [
                    {"term": n.name, "node_id": n.node_id}
                    for n in selected
                ],
                existing.get("concepts") or [],
            )
            try:
                response = await asyncio.to_thread(
                    application.state.llm.complete_json,
                    "concept_align",
                    payload_dict,
                )
            except ModelOutputError as exc:
                raise HTTPException(
                    status_code=502,
                    detail=error_payload(
                        "concept_align_failed",
                        "这次术语对齐没跑成，概念图保持原样（不做半吊子合并）。",
                    ),
                ) from exc
            merged = _apply_concept_align(store, response.get("items") or [])
            store.sync_scores(owner_id=user.user_id, project_id=project_id)
            return {
                "merged": merged,
                "accepted": [m for m in merged if m["accepted"]],
                "rejected": [m for m in merged if not m["accepted"]],
            }
        finally:
            store.close()

    # ------------------------- 文献引用导出 ------------------------- #
    def _citation_meta(project_id: str) -> dict[str, Any]:
        meta = db.get_literature_meta(project_id) or {}
        # 标题兜底：meta 没抽出来时用项目名，否则 citekey 会是一片空
        if not str(meta.get("title") or "").strip():
            meta = {**meta, "title": db.get_project(project_id).subject}
        return meta

    @application.get("/api/literature/{project_id}/citation")
    async def literature_citation(
        project_id: str, request: Request, format: str = "bibtex", download: int = 0
    ) -> Any:
        """导出单篇文献的引用（BibTeX 或 CSL JSON）。

        数据全部来自 ``literature_meta`` —— 那张表本来就有 title/authors/year/venue/doi，
        所以这里是纯粹换格式，不碰任何 schema。
        """
        require_project_access(project_id, request)
        meta = _citation_meta(project_id)
        fmt = (format or "bibtex").strip().lower()

        if fmt in ("csl", "csl-json", "csljson", "json"):
            item = citation_mod.to_csl_json(meta)
            body = json.dumps([item], ensure_ascii=False, indent=2)
            filename, media = "citation.json", "application/json; charset=utf-8"
        else:
            body = citation_mod.to_bibtex(meta)
            filename, media = "citation.bib", "text/plain; charset=utf-8"

        if download:
            return Response(
                content=body,
                media_type=media,
                headers={"Content-Disposition": f'attachment; filename="{filename}"'},
            )
        return {"format": fmt, "filename": filename, "content": body}

    @application.get("/api/citations/export")
    async def literature_citations(
        request: Request, project_ids: str = "", format: str = "bibtex"
    ) -> Any:
        """批量导出多篇文献的引用（逗号分隔的 project_ids）。

        写综述时最需要的就是这一下：一次拿到整批参考文献。

        ⚠️ 路径刻意用 ``/api/citations/export`` 而不是 ``/api/literature/citations`` ——
        后者是**三段路径**，与既有的 ``GET /api/literature/{project_id}``（单篇详情）
        段数相同，FastAPI 按注册顺序匹配，请求会被既有端点抢走并返回 404。
        新端点要新开命名空间，别挤在既有的通配路径旁边。
        """
        user = require_user(request)
        wanted = [
            item.strip() for item in (project_ids or "").split(",") if item.strip()
        ]
        if not wanted:
            return {"format": format, "filename": "citations.bib", "content": ""}
        entries: list[dict[str, Any]] = []
        for project_id in wanted[:200]:
            try:
                # 逐条校验归属：别人的文献不能因为 id 泄漏就被导出去
                project = db.get_project(project_id, user.user_id)
            except Exception:
                continue
            entries.append(_citation_meta(project.project_id))

        fmt = (format or "bibtex").strip().lower()
        if fmt in ("csl", "csl-json", "csljson", "json"):
            body = json.dumps(
                [citation_mod.to_csl_json(item) for item in entries],
                ensure_ascii=False,
                indent=2,
            )
            filename = "citations.json"
        else:
            body = citation_mod.to_bibtex_many(entries)
            filename = "citations.bib"
        return {
            "format": fmt,
            "filename": filename,
            "content": body,
            "count": len(entries),
        }

    @application.post("/api/literature/{project_id}/enrich-metadata")
    async def literature_enrich(project_id: str, request: Request) -> dict[str, Any]:
        """按标题 + 作者去 Crossref 补全 DOI / 年份 / 期刊。

        **只补空字段，不覆盖** —— LLM 从正文里抽出来的信息通常比 Crossref 的
        更贴合"这份文件"（工作论文 vs 正式期刊版），不该被外部数据盖掉。

        失败一律降级：这是锦上添花的一步，查不到就如实说查不到。
        """
        require_project_access(project_id, request)
        meta = _citation_meta(project_id)
        if str(meta.get("doi") or "").strip():
            return {"updated": {}, "message": "已经有 DOI 了，无需补全。"}

        title = str(meta.get("title") or "").strip()
        if len(title) < 6:
            return {
                "updated": {},
                "message": "标题太短，无法可靠匹配。建议先点「抽取元数据」。",
            }

        found = await asyncio.to_thread(
            citation_mod.lookup_doi, title, str(meta.get("authors") or "")
        )
        if not found:
            return {
                "updated": {},
                "message": "Crossref 里没有找到足够匹配的条目，保持原样。",
            }

        patch = citation_mod.merge_missing(meta, found)
        if not patch:
            return {
                "updated": {},
                "matched": found.get("title") or "",
                "message": "查到了一条相近记录，但已有的字段更完整，未做改动。",
            }
        db.upsert_literature_meta(project_id, patch)
        return {
            "updated": patch,
            "matched": found.get("title") or "",
            "match_score": found.get("match_score"),
            "message": f"已补全：{'、'.join(patch.keys())}",
        }

    # ===================== 学情洞察（2026-09-25 新增，四项一个命名空间） =====================
    #
    #   GET/PUT /api/teaching-mode                       教学模式三档（每用户一份）
    #   GET     /api/projects/{id}/mastery/bkt           加权分 vs BKT 并排（只读，不改分）
    #   GET     /api/projects/{id}/study-kit             一页速查表 / 学习路径
    #   POST    /api/projects/{id}/study-kit/generate
    #   GET     /api/projects/{id}/conflicts             资料矛盾（只呈现，不裁决）
    #   POST    /api/projects/{id}/conflicts/scan
    #   PATCH   /api/projects/{id}/conflicts/{conflict_id}
    #
    # 全部是新端点。既有的 /mastery/rules|breakdown|audit、/obsidian/*、/notes/* 一行未动。
    # 路径安全性：`/mastery/bkt` 与既有 `rules/breakdown/audit` 同为 5 段、末段都是字面量，
    # 互不抢占；`study-kit` / `conflicts` 在第 3 段就与 `notes` / `favorites` 区分开。

    @application.get("/api/teaching-mode")
    async def get_teaching_mode(request: Request) -> dict[str, Any]:
        """当前用户的教学模式档位。默认 direct —— 等同既有行为，不改变任何存量体验。"""
        user = require_user(request)
        mode = teaching_mode_for(user.user_id)
        return {
            "mode": mode,
            "label": teaching_mode_mod.MODE_LABELS.get(mode, mode),
            "hint": teaching_mode_mod.MODE_HINTS.get(mode, ""),
            "modes": teaching_mode_mod.modes_payload(),
            "tutor_tasks": sorted(teaching_mode_mod.TUTOR_TASKS),
        }

    @application.put("/api/teaching-mode")
    async def put_teaching_mode(request: Request) -> dict[str, Any]:
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        raw = (body or {}).get("mode")
        # 显式校验而不是静默回落：写错了要当场告诉用户，而不是偷偷存成默认档。
        if str(raw or "").strip().lower() not in teaching_mode_mod.MODES:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "invalid_teaching_mode",
                    "教学模式只支持 direct（直接回答）、guided（引导模式）两档，收到的是"
                    f"「{raw}」。",
                ),
            )
        mode = await asyncio.to_thread(teaching_store().set, user.user_id, raw)
        _teaching_cache[user.user_id] = mode  # 立刻生效，不必等下一次请求
        return {
            "mode": mode,
            "label": teaching_mode_mod.MODE_LABELS.get(mode, mode),
            "hint": teaching_mode_mod.MODE_HINTS.get(mode, ""),
            "modes": teaching_mode_mod.modes_payload(),
            "tutor_tasks": sorted(teaching_mode_mod.TUTOR_TASKS),
        }

    @application.get("/api/projects/{project_id}/mastery/bkt")
    async def mastery_bkt(project_id: str, request: Request) -> dict[str, Any]:
        """贝叶斯知识追踪：给掌握度一个会区分「猜对」和「真会」的参照。

        与既有的加权累加**并排**展示，两者差距越大越值得看一眼 —— 详见 core/mastery_bkt.py。
        本端点只读，不改任何分数。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        return await asyncio.to_thread(
            mastery_bkt_mod.bkt_project, db.path, user.user_id, project_id
        )

    # 进步引擎（core/progress_engine.py）：把掌握度翻译成「位置」，让下一步永远有路可走。
    # 与 /mastery/bkt 的分工是刻意的 —— BKT 藏进引擎当闸门，不端给用户看数字。
    # 路径新开 /api/progress 顶层命名空间，避免与 /api/projects/{id}/** 的通配段互抢。
    # 两个端点都只读，不写任何表、不改任何分数。

    @application.get("/api/progress/{project_id}/plan")
    async def progress_plan(
        project_id: str, request: Request, limit: int = 3
    ) -> dict[str, Any]:
        """今天的下一步：按桶各取一个（先修 / 补资料 / 解锁 / 临门一脚 / 开个头 / 复习），
        最后一个固定是探索位。前置没到「会了」的节点不会被推，只作为「还差哪几块」列出。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        safe_limit = max(1, min(int(limit or 3), 8))
        return await asyncio.to_thread(
            progress_engine_mod.plan,
            db.path,
            user.user_id,
            project_id,
            limit=safe_limit,
        )

    @application.get("/api/progress/{project_id}/digest")
    async def progress_digest(
        project_id: str, request: Request, days: int = 7
    ) -> dict[str, Any]:
        """这一周往前挪了多少格 —— 由事件流回放得出，不建新表、不存历史快照。"""
        require_project_access(project_id, request)
        user = require_user(request)
        safe_days = max(1, min(int(days or 7), 90))
        return await asyncio.to_thread(
            progress_engine_mod.digest,
            db.path,
            user.user_id,
            project_id,
            days=safe_days,
        )

    @application.post("/api/progress/{project_id}/suggest")
    async def progress_suggest(
        project_id: str, request: Request, limit: int = 6
    ) -> dict[str, Any]:
        """AI 生成优先复习建议：进步引擎选好候选（按桶各取一个），模型只写文案。

        只读、不写任何表、不改分数。无 API Key 直接 503，让前端回退到规则模板文案。
        模型不可用或输出对不上时，逐条退回 progress_engine 的模板 reason（诚实降级）。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "AI 复习建议需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )
        safe_limit = max(1, min(int(limit or 6), 8))
        plan = await asyncio.to_thread(
            progress_engine_mod.plan, db.path, user.user_id, project_id, limit=safe_limit
        )
        steps = plan.get("steps") or []
        if not steps:
            return {
                "project_id": project_id,
                "steps": [],
                "ai": False,
                "fallback": True,
            }

        def _ctx(step: dict[str, Any]) -> dict[str, Any]:
            detail = step.get("detail") or {}
            return {
                "node_id": step.get("node_id"),
                "name": step.get("name"),
                "stage": step.get("stage_label"),
                "bucket": step.get("bucket_label"),
                "reason": step.get("reason"),
                "error_type": detail.get("error_type_label") or "",
                "overconfident_misses": detail.get("overconfident_misses", 0),
                "due_cards": detail.get("due_cards", 0),
                "unlock_gain": detail.get("unlock_gain", 0),
                "exam_weight": step.get("exam_weight"),
            }

        try:
            result = await asyncio.to_thread(
                application.state.llm.complete_json,
                "suggest_review",
                {"steps": [_ctx(s) for s in steps]},
            )
        except Exception as exc:  # 模型挂了/超时/JSON 修复仍失败 → 整体回退规则文案
            LOGGER.warning("progress_suggest LLM failed: %s", exc)
            result = {}
        suggestions: dict[str, str] = {}
        raw = result.get("suggestions") if isinstance(result, dict) else None
        if isinstance(raw, list):
            for item in raw:
                if not isinstance(item, dict):
                    continue
                node_id = str(item.get("node_id") or "")
                text = str(item.get("suggestion") or "").strip()
                if node_id and 1 <= len(text) <= 120:
                    suggestions[node_id] = text

        any_ai = False
        enriched: list[dict[str, Any]] = []
        for step in steps:
            node_id = step.get("node_id")
            ai_text = suggestions.get(node_id, "")
            if ai_text:
                any_ai = True
            enriched.append(
                {
                    **step,
                    "suggestion": ai_text or step.get("reason") or "",
                    "ai": bool(ai_text),
                }
            )
        result = {
            "project_id": project_id,
            "steps": enriched,
            "ai": any_ai,
            "fallback": not any_ai,
            "saved": True,
        }
        # 落盘：重启后 GET 能直接恢复，不必再花一次 LLM（2026-09-30）
        try:
            await asyncio.to_thread(
                progress_engine_mod.save_suggestions,
                db.path,
                user.user_id,
                project_id,
                result,
            )
        except Exception as exc:  # 保存失败不影响本次返回
            LOGGER.warning("progress_suggest 保存失败：%s", exc)
        return result

    @application.get("/api/progress/{project_id}/suggest")
    async def progress_suggest_get(
        project_id: str, request: Request
    ) -> dict[str, Any]:
        """读回上次保存的 AI 优先复习建议（不重新调 LLM）。没保存过就返回空 steps。"""
        require_project_access(project_id, request)
        user = require_user(request)
        saved = await asyncio.to_thread(
            progress_engine_mod.load_suggestions, db.path, user.user_id, project_id
        )
        if not saved or not isinstance(saved, dict) or not saved.get("steps"):
            return {
                "project_id": project_id,
                "steps": [],
                "ai": False,
                "fallback": True,
                "saved": False,
            }
        return {**saved, "saved": True}

    # ==================================================================
    # 陪练台：这一轮该做什么、提示该给到哪一步、你准不准
    # ==================================================================
    #
    # 这一族解决的是一个具体问题：**默认档位（direct）下没有任何支架分级**。
    # teaching_mode 的护栏只做在 guided 一档上，全仓唯一把掌握度接进提示词的地方
    # 是上面那个单向的 weak_flag（mastery_score < 0.3，只会「多给一点」）。
    # 于是「稳了」的节点照样被逐题喂完整答案 —— Kalyuga et al. (2003) 的专业知识
    # 反转效应：冗余支架对已有图式的人从帮助变成干扰，而用户只会觉得「它啰嗦」。
    #
    # 所以这里按 BKT 后验给出一条五档、会往上也会往下走的支架梯子
    # （core/scaffold.py），并把 learning_events.self_confidence 那一列
    # 聚合成一句可行动的校准结论（core/calibration.py）。
    #
    # 三条承诺：
    #   1. 全部只读 —— 不写任何表、不改任何分数、不调模型。
    #   2. 不新增逐题自评 —— Double et al. (2025, N=710) 显示逐题问 confidence
    #      会损害规则学习与迁移；已有的把握度只被**聚合成一句结论**，
    #      什么时候值得再问一次由 calibration.probe() 决定。
    #   3. 只给时间不给件数 —— 「你还有 47 张卡片」把外部压力和**能力评价**耦在
    #      一起，是自我决定理论里典型的不合意压力；件数只用来决定休息插几次。
    #
    # 命名空间用 /api/coach/* 而不是挂在 /api/projects/{project_id}/… 下：
    # 那个前缀有同段数通配会互相抢注册（上面 review / transfer 家族都记过这条）。

    def _coach_scaffold_for(
        target_project_id: str,
        owner_id: str,
        node_id: str,
        *,
        demand: str,
    ) -> dict[str, Any]:
        """取一个节点的「支架强度 + 位阶 + BKT」，并拼好提示词块。

        走 ``progress_engine._load`` 而不是自己连库：位阶、BKT 参数、FSRS 闸门
        全在那一份实现里，绕开它就会出现第二套 BKT 参数（项目已经踩过一次）。
        拿不到（空项目 / 节点不存在 / 越权）时如实返回 ``available: False``，
        不编一个默认档位出来。
        """
        try:
            loaded = progress_engine_mod._load(
                db.path, owner_id, target_project_id
            )
        except Exception as exc:  # noqa: BLE001 —— 读路径不许因为脏数据炸掉整个面板
            LOGGER.warning("陪练台读取节点状态失败：%s", exc)
            return {"available": False, "reason": "读不出这个节点的学习记录"}

        if loaded is None or node_id not in loaded.nodes:
            return {"available": False, "reason": "还没有这个知识点的学习记录"}

        stage = loaded.stage_of(node_id)
        bkt_value = loaded.bkt_of(node_id)
        observations = len(loaded.verified_observations(node_id))
        node_name = str(loaded.nodes[node_id].get("name") or node_id)
        demand_safe = "hard" if demand == "hard" else "normal"

        decided = scaffold_mod.explain(
            bkt_value,
            stage,
            observations=observations,
            demand=demand_safe,
        )
        return {
            "available": True,
            "node_id": node_id,
            "node_name": node_name,
            "stage": stage,
            "stage_label": progress_engine_mod.STAGE_LABELS.get(stage, stage),
            "demand": demand_safe,
            "observations": observations,
            # bkt 原始值只给「界面上不显示分数」的判定用：前端拿它做颜色分档，
            # 不做数值展示。这与 progress_engine._bkt_of 是同一份值，不另算。
            "bkt": round(float(bkt_value), 4),
            **decided,
            "prompt_block": scaffold_mod.prompt_block(
                decided["level"], node_name=node_name, demand=demand_safe
            ),
        }

    @application.get("/api/coach/{project_id}/scaffold")
    async def coach_scaffold(
        project_id: str,
        request: Request,
        node_id: str = "",
        demand: str = "normal",
    ) -> dict[str, Any]:
        """一个知识点该给多强的提示，以及**为什么是这个强度**。

        ``demand="hard"`` 用于 D3 / 迁移 / 换情境 —— 任务一变，学习者就是新手，
        即使他对原概念的 BKT 很高也要把支架加回一档。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        if not str(node_id or "").strip():
            raise HTTPException(
                status_code=400,
                detail=error_payload("node_id_required", "请先指定一个知识点。"),
            )
        return await asyncio.to_thread(
            _coach_scaffold_for,
            project_id,
            user.user_id,
            str(node_id).strip(),
            demand=str(demand or "normal"),
        )

    @application.get("/api/coach/{project_id}/calibration")
    async def coach_calibration(
        project_id: str, request: Request, days: int = 30
    ) -> dict[str, Any]:
        """你自己觉得有多准，和实际有多准，差多少。

        原料是 ``learning_events.self_confidence``（1.0 我确定 / 0.0 我不确定 / NULL 没勾）
        —— 这一列项目一直在存、``progress_engine`` 也用它做单点判据，但从来没聚合成
        用户看得懂的结论。样本不足 8 条时如实返回「还看不出来」，不用 3 次作答编一个
        「你高估自己」出来。
        """
        require_project_access(project_id, request)
        user = require_user(request)
        safe_days = max(1, min(int(days or 30), 180))
        report = await asyncio.to_thread(
            calibration_mod.report, db.path, user.user_id, project_id
        )
        trend = await asyncio.to_thread(
            calibration_mod.recent_predictions,
            db.path,
            user.user_id,
            project_id,
            days=safe_days,
        )
        return {**report, "trend": trend}

    @application.get("/api/coach/{project_id}/round")
    async def coach_round(project_id: str, request: Request) -> dict[str, Any]:
        """本轮怎么走：下一步（复用进步引擎的桶）+ 支架强度 + 校准 + 时间盒。

        三块刻意放一个端点里，因为它们回答的是同一个问题 —— 「现在这一轮」。
        分成三个端点会让前端多两次往返，也更容易出现「时间盒按 A、支架按 B」的错位。
        """
        require_project_access(project_id, request)
        user = require_user(request)

        steps_payload = await asyncio.to_thread(
            progress_engine_mod.plan, db.path, user.user_id, project_id, limit=4
        )
        steps = [item for item in (steps_payload.get("steps") or []) if item]
        # 「换个情境」桶本来就是新任务，按 hard 要支架；其余按 normal。
        demand = "hard" if any(item.get("bucket") == "transfer" for item in steps) else "normal"

        target = ""
        target_name = ""
        for item in steps:
            if item.get("node_id"):
                target = str(item["node_id"])
                target_name = str(item.get("name") or "")
                break

        scaffold_info = await asyncio.to_thread(
            _coach_scaffold_for,
            project_id,
            user.user_id,
            target,
            demand=demand,
        ) if target else {"available": False, "reason": "今天还没有可练的节点"}

        due_cards = 0
        for item in steps:
            detail = item.get("detail") or {}
            try:
                due_cards += int(detail.get("due_cards") or 0)
            except (TypeError, ValueError):
                continue

        report = await asyncio.to_thread(
            calibration_mod.report, db.path, user.user_id, project_id
        )

        return {
            "project_id": project_id,
            "generated_at": steps_payload.get("generated_at"),
            "stage_counts": steps_payload.get("stage_counts") or {},
            "stage_labels": steps_payload.get("stage_labels") or {},
            "step_labels": steps_payload.get("step_labels") or {},
            "steps": steps,
            "blocked": steps_payload.get("blocked") or [],
            "demand": demand,
            "focus": {"node_id": target, "name": target_name},
            "scaffold": scaffold_info,
            "calibration": {
                "verdict": report.get("verdict"),
                "verdict_label": report.get("verdict_label"),
                "advice": report.get("advice"),
                "samples": report.get("samples"),
                "min_samples": report.get("min_samples"),
                "probe": report.get("probe") or {},
                "evidence": report.get("evidence") or [],
            },
            "shape": scaffold_mod.shape_session(
                len(steps), due_cards=due_cards
            ),
            "ladder": list(scaffold_mod.SCAFFOLD_LADDER),
            "ladder_labels": scaffold_mod.SCAFFOLD_LABELS,
        }

    def _study_kit_kinds() -> list[dict[str, str]]:
        return [
            {
                "value": key,
                "label": study_kit_mod.KIND_LABELS[key],
                "hint": study_kit_mod.KIND_HINTS[key],
            }
            for key in study_kit_mod.KINDS
        ]

    @application.get("/api/projects/{project_id}/study-kit")
    async def list_study_kit(project_id: str, request: Request) -> dict[str, Any]:
        """该项目已生成的一页速查表 / 学习路径。"""
        require_project_access(project_id, request)
        kits = await asyncio.to_thread(study_kit_store().list_for_project, project_id)
        return {"kits": kits, "kinds": _study_kit_kinds()}

    @application.post("/api/projects/{project_id}/study-kit/generate")
    async def generate_study_kit(project_id: str, request: Request) -> dict[str, Any]:
        """生成（或覆盖）一页速查表 / 学习路径 / 清单报告。一次调用出完整一篇，不做分块。

        body: ``{"kind": "cheatsheet"}`` = 整份材料那一份；
        额外给 ``{"node_id": "node_xxx"}`` = 只针对那个知识点（连同它的子树）出一份窄表。
        """
        project = require_project_access(project_id, request)
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        raw_kind = (body or {}).get("kind")
        if str(raw_kind or "").strip().lower() not in study_kit_mod.KINDS:
            valid = "、".join(study_kit_mod.KIND_LABELS[k] for k in study_kit_mod.KINDS)
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "invalid_study_kit_kind",
                    f"只支持 {valid} 这几种，收到的是「{raw_kind}」。",
                ),
            )
        kind = study_kit_mod.normalize_kind(raw_kind)

        # node_id 是可选的：不给就是整份材料那一份（既有行为，别把它改成必填）。
        raw_node_id = str((body or {}).get("node_id") or "").strip()
        focus = None
        if raw_node_id:
            try:
                focus = db.get_framework_node(project_id, raw_node_id)
            except Exception:
                focus = None
            if focus is None:
                raise HTTPException(
                    status_code=404,
                    detail=error_payload(
                        "study_kit_unknown_node",
                        f"这个项目里找不到知识节点「{raw_node_id}」，无法针对它生成。",
                    ),
                )

        nodes = await asyncio.to_thread(db.list_framework_nodes, project_id)
        sources = await asyncio.to_thread(db.list_sources, project_id)
        focus_name = ""
        if focus is not None:
            # 针对性生成：把输入收窄到那棵子树 + 它关联的资料。不收窄的话，
            # 「针对康普顿散射出张速查表」和「出整章速查表」产出的东西没有区别。
            focus_name = str(getattr(focus, "name", "") or "")
            nodes, scope_source_ids = study_kit_mod.focus_scope(nodes, focus)
            if scope_source_ids:
                scoped = [
                    s for s in sources
                    if str(getattr(s, "source_id", "") or "") in set(scope_source_ids)
                ]
                # 资料与框架没挂上钩时（source_ids 为空）宁可给全量资料，
                # 也别对着一个空壳子让模型输出满屏「资料未覆盖」。
                if scoped:
                    sources = scoped
        if not nodes and not sources:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "study_kit_needs_material",
                    "这个项目里还没有任何资料或知识节点，无法生成。请先导入课件/教材，或先生成知识框架。",
                ),
            )

        payload = study_kit_mod.build_payload(
            kind,
            project_name=f"{project.subject}（{project.year}）",
            subject=project.subject,
            nodes=nodes,
            sources=sources,
            focus_node=focus_name,
        )
        try:
            resp = await asyncio.to_thread(
                application.state.llm.complete_json, "make_study_kit", payload
            )
        except Exception as exc:  # noqa: BLE001 —— 要变成人能看懂的一句话，不是堆栈
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "study_kit_generation_failed",
                    f"生成{study_kit_mod.KIND_LABELS[kind]}时模型调用失败：{exc}。"
                    "可以稍后重试，或在「模型配置」里确认 API 可用。",
                ),
            ) from exc

        content = str((resp or {}).get("content") or "").strip()
        if not content:
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "study_kit_empty_output",
                    "模型这次没有返回正文内容，可能被输入长度截断了。可以少选几份资料后重试。",
                ),
            )

        # 标题带节点名：台历左栏同时挂着整份材料那一份和若干节点级窄表，
        # 光看「一页速查表」分不出是哪一份。
        title = study_kit_mod.KIND_LABELS[kind] + (f" · {focus_name}" if focus_name else "")
        saved = await asyncio.to_thread(
            study_kit_store().save,
            project_id=project_id,
            owner_id=user.user_id,
            kind=kind,
            title=title,
            content_md=content,
            source_ids=[getattr(s, "source_id", "") for s in sources][:24],
            node_id=(getattr(focus, "node_id", None) if focus is not None else None),
        )
        return {"kit": saved, "kinds": _study_kit_kinds()}

    @application.patch("/api/projects/{project_id}/study-kit/{kind}")
    async def update_study_kit(
        project_id: str, kind: str, request: Request
    ) -> dict[str, Any]:
        """编辑已生成的学习路径 / 清单报告正文（覆盖 content_md，保留来源与关联节点）。"""
        require_project_access(project_id, request)
        user = require_user(request)
        normalized = study_kit_mod.normalize_kind(kind)
        if normalized != kind or normalized not in study_kit_mod.KINDS:
            raise HTTPException(
                status_code=400,
                detail=error_payload("invalid_study_kit_kind", f"不支持的 kind：{kind}。"),
            )
        existing = await asyncio.to_thread(study_kit_store().get, project_id, normalized)
        try:
            body = await request.json()
        except Exception:
            body = {}
        content_md = str((body or {}).get("content_md") or "").strip()
        if not content_md:
            raise HTTPException(
                status_code=400,
                detail=error_payload("empty_study_kit_content", "报告内容不能为空。"),
            )
        title = str((body or {}).get("title") or "").strip() or (
            existing or {}
        ).get("title") or study_kit_mod.KIND_LABELS[normalized]
        saved = await asyncio.to_thread(
            study_kit_store().save,
            project_id=project_id,
            owner_id=user.user_id,
            kind=normalized,
            title=title,
            content_md=content_md,
            node_id=(existing or {}).get("node_id"),
            source_ids=(existing or {}).get("source_ids") or [],
        )
        return {"kit": saved, "kinds": _study_kit_kinds()}

    @application.post("/api/projects/{project_id}/study-kit/ask")
    async def ask_study_kit(project_id: str, request: Request) -> StreamingResponse:
        """就着「学习文档」（速查表 / 学习路径 / 清单报告）提问，答案以 SSE 流式返回。

        与 ``/knowledge-doc/ask`` 是同一套证据边界与同一套提示词，**只换了材料来源**：
        那边读知识点文档（``knowledge_docs``），这边读三类成文产物（``study_kits``）。
        为什么不复用那个端点：它的 ``scope=project`` 写死了去读合订稿，拿它来答
        「速查表里这条为什么这么写」会答成另一份文档的内容。

        边界（与生成阶段一致，别在这里放松）：默认只依据这份文档作答，材料里没写的
        直说没写；``allow_extra=true`` 是第二档，材料外的知识可以答但必须放进
        ``## 材料外补充`` 整段自报家门。

        body: ``{question, kind?, selection?, section?, history?, allow_extra?}``。
        ``kind`` 指定以哪一份为主 —— 三份都会带上，只是把它排在前面（``excerpt_around``
        定位不到时会退回头部截断，排前面才不会被挤出去）。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        question = str(body.get("question") or "").strip()
        if not question:
            raise HTTPException(
                status_code=400,
                detail=error_payload("study_kit_question_required", "先写一句想问的问题。"),
            )
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "提问需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，"
                    "或编辑 .env 设置 TJU_API_KEY。",
                ),
            )

        kits = await asyncio.to_thread(study_kit_store().list_for_project, project_id)
        # 只收**项目级**那一份（node_id 为空）—— 与前端「学习文档」同一口径：
        # 节点级窄表混进来，这份「整份文档」就变成了某个知识点的表。
        available = {
            str(kit.get("kind") or ""): kit
            for kit in kits
            if kit and not kit.get("node_id") and str(kit.get("content_md") or "").strip()
        }
        if not available:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "study_kit_not_generated",
                    "这门课还没有学习文档。先生成速查表 / 学习路径 / 清单报告中的任意一份，再来提问。",
                ),
            )
        focus = study_kit_mod.normalize_kind(body.get("kind"))
        ordered = [focus] + [key for key in study_kit_mod.KINDS if key != focus]
        context = "\n\n".join(
            f"## {study_kit_mod.KIND_LABELS[key]}\n\n{str(available[key]['content_md']).strip()}"
            for key in ordered
            if key in available
        )
        selection = str(body.get("selection") or "")
        section = str(body.get("section") or "")
        # 没选中原文时用「当前小节标题」当定位探针：三份合起来常超过 ASK_MAX_CONTEXT，
        # 不定位就退成头部截断 —— 用户明明在读清单报告，模型手里却只有速查表。
        context = knowledge_doc_mod.excerpt_around(context, selection or section)
        allow_extra = bool(body.get("allow_extra"))

        payload = knowledge_doc_mod.build_ask_payload(
            question=question,
            selection=selection,
            scope="project",
            context=context,
            section=section,
            history=body.get("history") if isinstance(body.get("history"), list) else [],
            allow_extra=allow_extra,
        )
        messages = [
            {
                "role": "system",
                "content": stream_system_prompt(
                    "ask_knowledge_doc", ask_allow_extra=allow_extra
                ),
            },
            {
                "role": "user",
                "content": json.dumps(
                    {"task": "ask_knowledge_doc", "payload": payload}, ensure_ascii=False
                ),
            },
        ]

        def _kit_sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream() -> AsyncIterator[str]:
            yield _kit_sse(
                {
                    "type": "start",
                    "kits": [key for key in ordered if key in available],
                    "context_chars": len(context),
                }
            )
            pieces: list[str] = []
            try:
                async for chunk in application.state.llm.astream_chat_content(
                    messages, "ask_knowledge_doc"
                ):
                    pieces.append(chunk)
                    yield _kit_sse({"type": "delta", "text": chunk})
            except Exception as exc:  # noqa: BLE001 —— 要变成人能看懂的一句话，不是堆栈
                LOGGER.warning("study kit ask failed: %s", exc)
                yield _kit_sse({"type": "error", "message": f"这次没答上来：{exc}"})
                return
            answer = knowledge_doc_mod.clean_answer("".join(pieces))
            if not answer:
                yield _kit_sse(
                    {"type": "error", "message": "模型这次没有返回内容，可以再问一次。"}
                )
                return
            yield _kit_sse({"type": "done", "text": answer})

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    # —— 知识点文档（2026-09-30）：单节点「复习用详解」 + 按框架层级合订整份 ——
    # 质量机制：一次只讲一个知识点；
    # 结构化字段逐项校验（哪一项不合格就只退那一项的本地兜底，其余照用）；
    # 只喂证据、不许编。合订是**纯本地拼装**、零模型调用 —— 所以
    # 「先深挖几个点 → 以后再补 → 重新合订」是自然用法，不必一次跑完。

    def _knowledge_doc_sources(project_id: str, node: Any) -> tuple[list[Any], str]:
        """这个节点的资料：优先它自己关联的来源；一份都没有时退到项目来源（限 3 份）并如实标注。"""
        all_sources = [s for s in db.list_sources(project_id) if s.status == "ok"]
        scoped = [s for s in all_sources if s.source_id in (node.source_ids or [])]
        if scoped:
            return scoped, "node"
        return all_sources[:3], "project"

    def _knowledge_doc_context(project_id: str, node: Any) -> tuple[list[Neighbor], list[str]]:
        """节点的一跳邻居 + 从根到父的路径。

        邻居是「与相邻知识点的关系」一节**唯一**的事实来源 —— 关系类型和应用全部来自
        框架本身的 prerequisite_ids / 父子结构，不让模型自己联想。
        """
        nodes = db.list_framework_nodes(project_id)
        by_id = {n.node_id: n for n in nodes}
        out: list[Neighbor] = []
        seen = {node.node_id}
        for prereq_id in node.prerequisite_ids or []:
            target = by_id.get(prereq_id)
            if target and target.node_id not in seen:
                seen.add(target.node_id)
                out.append(Neighbor(target.name, "prereq", target.description or ""))
        for other in nodes:
            if other.node_id in seen:
                continue
            if node.node_id in (other.prerequisite_ids or []):
                seen.add(other.node_id)
                out.append(Neighbor(other.name, "next", other.description or ""))
        if node.parent_id and node.parent_id in by_id:
            parent = by_id[node.parent_id]
            if parent.node_id not in seen:
                seen.add(parent.node_id)
                out.append(Neighbor(parent.name, "parent", parent.description or ""))
        for other in nodes:
            if other.node_id in seen or other.parent_id != node.node_id:
                continue
            seen.add(other.node_id)
            out.append(Neighbor(other.name, "child", other.description or ""))
        for other in nodes:
            if other.node_id in seen:
                continue
            if other.parent_id and other.parent_id == node.parent_id:
                seen.add(other.node_id)
                out.append(Neighbor(other.name, "related", other.description or ""))
        path: list[str] = []
        cursor = node
        for _ in range(8):
            if not cursor.parent_id or cursor.parent_id not in by_id:
                break
            cursor = by_id[cursor.parent_id]
            path.insert(0, cursor.name)
        return out[:8], path

    def _knowledge_doc_tree_order(nodes: list[Any]) -> list[tuple[Any, list[str]]]:
        """深度优先展开框架树，父在子前 —— 与速查表的排列一致，合订稿的可读性靠它。

        实现搬到了 ``core/knowledge_doc.py`` 的 ``tree_order``：递进链（层号/站号）
        必须用同一个顺序来标，放两处早晚会不一致。
        """
        return knowledge_doc_mod.tree_order(nodes)

    # ------------------------------------------------------------------
    # 读书（Reading）
    #
    # 两件自动化（这是本模块与「文献精读」最大的不同）：
    #   1. **按需建项目** —— 项目承载框架 / 卡片 / 测验 / 掌握度 / 撤销 / 导出，
    #      但**加入书架时不再凭空建**：只有真要往里放东西时（导入 / 取回正文、
    #      生成收获沉淀卡片）才建。刚加入的书往往只有元数据、没有资料，
    #      给它建空项目只会把侧栏塞满；
    #   2. **收获自动沉淀为知识卡片** —— 生成《读书收获》时把自测题回流进 cards 表
    #      （前缀 rd_，机制照搬 knowledge_doc）。
    #
    # 多书源是「获取正文」的解 —— 微信读书只给书架/封面/划线，**给不了整本正文**，
    # 所以公版书走古腾堡/维基文库，本地书走导入，商业书只保留元数据与外链。
    # ------------------------------------------------------------------

    def reading_store() -> ReadingStore:
        return _aux_store("reading", ReadingStore)

    def _reading_project_for(owner_id: str, book_key: str) -> str:
        """确保这本书有项目并返回 project_id（没有就建）。

        **按需调用** —— 只在真的要往项目里放东西时才建（导入 / 取回正文、
        生成收获沉淀卡片）。加入书架本身不再触发它。
        """
        return reading_store().ensure_project(
            owner_id,
            book_key,
            create_project=lambda title: db.create_book_project(owner_id, title).project_id,
        )

    def _reading_book_or_404(owner_id: str, book_key: str) -> dict[str, Any]:
        book = reading_store().get_book(owner_id, book_key)
        if not book:
            raise HTTPException(
                status_code=404,
                detail=error_payload("reading_book_not_found", "书架里没有这本书。"),
            )
        return book

    def _reading_signature(highlights: Any, thoughts: Any) -> str:
        """划线 + 想法的指纹。正文变了才需要重新生成，避免无谓的模型调用。"""
        parts: list[str] = []
        for group in (highlights, thoughts):
            if isinstance(group, list):
                for item in group:
                    if isinstance(item, dict):
                        parts.append(str(item.get("mark_text") or item.get("text") or item.get("content") or ""))
        blob = "\n".join(parts)
        return hashlib.sha1(blob.encode("utf-8", "replace")).hexdigest()[:16]

    @application.get("/api/reading/sources")
    async def reading_sources(request: Request) -> dict[str, Any]:
        """书源能力清单：每个源能给全文 / 只能给元数据 / 只能外链，以及版权状态。"""
        require_user(request)
        return {"sources": book_sources_mod.list_sources()}

    @application.post("/api/reading/search")
    async def reading_search(request: Request) -> dict[str, Any]:
        """跨书源搜书。单源失败只算 0 条，不影响其它源。"""
        require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        query = str(body.get("query") or "").strip()
        if not query:
            raise HTTPException(
                status_code=400,
                detail=error_payload("reading_query_required", "先写一句要搜的书名或作者。"),
            )
        raw_sources = body.get("sources")
        source_ids = [str(s) for s in raw_sources] if isinstance(raw_sources, list) else None
        try:
            limit = int(body.get("limit") or 8)
        except Exception:
            limit = 8
        result = await asyncio.to_thread(
            book_sources_mod.search_books,
            query,
            source_ids=source_ids,
            limit_per_source=limit,
        )
        records = result.get("results") or []
        # 需要代理却还没配的源：前端要把这句话说出来，否则「线路不通」会被
        # 用户读成「这个功能没做」。
        blocked = [
            s["id"] for s in book_sources_mod.list_sources()
            if s.get("blocked") and s.get("searchable")
        ]
        return {
            "query": result.get("query", ""),
            "results": records,
            "sources": result.get("sources", {}),
            # 把「书源是否可达」一并带出去 —— 前端要靠它把「网络连不上」和
            # 「确实没这本书」分开显示，否则零结果会被误读成功能没做。
            "source_status": result.get("source_status", {}),
            "all_failed": bool(result.get("all_failed")),
            "blocked_sources": blocked,
            "proxy_in_use": book_sources_mod.using_proxy(),
            "groups": book_sources_mod.group_by_category(records),
            "summary": book_sources_mod.fulltext_summary(records),
        }

    @application.get("/api/reading/books")
    async def reading_list_books(request: Request, category: str = "") -> dict[str, Any]:
        """我的书架（本地缓存，按一级领域分组）。"""
        user = require_user(request)
        books = await asyncio.to_thread(
            reading_store().list_books, user.user_id, category=category.strip()
        )
        buckets: dict[str, list[dict[str, Any]]] = {}
        for book in books:
            buckets.setdefault(book.get("category") or "其他", []).append(book)
        groups = [
            {"category": name, "count": len(items), "books": items}
            for name, items in sorted(buckets.items(), key=lambda kv: (-len(kv[1]), kv[0]))
        ]
        return {
            "books": books,
            "groups": groups,
            "summary": {
                "total": len(books),
                "reading": len([b for b in books if b.get("reading_status") == "reading"]),
                "finished": len([b for b in books if int(b.get("progress") or 0) >= 100]),
                "fulltext": len([b for b in books if b.get("has_fulltext")]),
            },
        }

    @application.post("/api/reading/books", status_code=201)
    async def reading_add_book(request: Request) -> dict[str, Any]:
        """把一本书加入书架。

        **默认不建项目** —— 刚加入的书通常只有元数据、没有资料，为它凭空建一个
        空项目只会把侧栏塞满。只有调用方显式要求（``with_project=True``，用于
        「本地导入」「导入正文」这类马上要往里放资料的场景）时，才顺手把项目建好；
        生成收获、取回正文也会各自按需建，不依赖这里。
        """
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        record = body.get("book") if isinstance(body.get("book"), dict) else body
        book = await asyncio.to_thread(reading_store().upsert_book, user.user_id, record)
        if not book:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "reading_book_invalid",
                    "这本书缺少来源标识或书名，无法加入书架。",
                ),
            )
        # 已有项目就沿用；没项目且调用方明确要，才建。
        project_id = str(book.get("project_id") or "")
        if not project_id and body.get("with_project"):
            project_id = await asyncio.to_thread(
                _reading_project_for, user.user_id, book["book_key"]
            )
        return {"book": {**book, "project_id": project_id}, "project_id": project_id}

    @application.get("/api/reading/books/{book_key}")
    async def reading_book_detail(book_key: str, request: Request) -> dict[str, Any]:
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        store = reading_store()
        digest = await asyncio.to_thread(store.get_doc, user.user_id, book_key, "digest")
        intro = await asyncio.to_thread(store.get_doc, user.user_id, book_key, "intro")
        # 书源侧的简介（成段材料）。拉不到就空串，不报错 —— 它是增强不是依赖。
        book_intro = ""
        if not intro:
            book_intro = await asyncio.to_thread(_reading_book_intro, book)
        return {
            "book": book,
            "digest": digest or None,
            "intro": intro or None,
            "book_intro": book_intro,
        }

    @application.put("/api/reading/books/{book_key}/doc")
    async def reading_save_doc(book_key: str, request: Request) -> dict[str, Any]:
        """手工编辑正文。只改 ``content_md``，结构化留档与指纹不动。"""
        user = require_user(request)
        await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        kind = reading_store_mod.normalize_kind(body.get("kind"))
        content = str(body.get("content_md") or "")
        if not content.strip():
            raise HTTPException(
                status_code=400,
                detail=error_payload("reading_content_required", "正文不能为空。"),
            )
        try:
            doc = await asyncio.to_thread(
                reading_store().save_markdown, user.user_id, book_key, content, kind
            )
        except ValueError as exc:
            raise HTTPException(
                status_code=400,
                detail=error_payload("reading_content_required", str(exc)),
            ) from exc
        if not doc:
            raise HTTPException(
                status_code=404,
                detail=error_payload("reading_doc_not_found", "还没有生成过这份文档，先生成再编辑。"),
            )
        return {"doc": doc}

    async def _generate_reading_digest(
        user: Any, book: dict[str, Any], body: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        """生成一本书的《读书收获》并沉淀卡片。**单本路由与批量路由共用这一个实现。**

        抽出来是为了批量：书架上有十本书时，用户不该一本一本点。
        逻辑一行都没改，只是把「取 body / 取 book」留给调用方。
        """
        book_key = str(book.get("book_key") or "")
        body = body if isinstance(body, dict) else {}
        highlights = body.get("highlights") if isinstance(body.get("highlights"), list) else []
        thoughts = body.get("thoughts") if isinstance(body.get("thoughts"), list) else []
        reviews = body.get("reviews") if isinstance(body.get("reviews"), list) else []
        excerpts = body.get("excerpts") if isinstance(body.get("excerpts"), list) else []
        chapters_in = body.get("chapters") if isinstance(body.get("chapters"), list) else []

        source = str(book.get("source") or "")
        # 微信读书的书：**服务端自己把材料拉齐**（章节目录 + 热门划线 + 用户自己的划线）。
        # 让前端去拉会漏、也会因网络抖动少一块；这里拉齐了，「逐章精读」才有料。
        if source == "weread":
            if not chapters_in:
                chapters_in = await asyncio.to_thread(
                    lambda: weread_mod.outline_chapters(
                        _weread_grouped_outline(book["source_id"])
                    )
                )
            if not highlights and not thoughts:
                try:
                    fetched = await asyncio.to_thread(_fetch_weread_notes, book["source_id"])
                    highlights = fetched.get("highlights") or []
                    thoughts = fetched.get("thoughts") or []
                except Exception:
                    pass

        project_id = await asyncio.to_thread(_reading_project_for, user.user_id, book_key)
        title = str(book.get("title") or "")
        author = str(book.get("author") or "")

        # 本地导入 / 公版书：把项目资料正文喂进去（那份才是真全文）。
        # **优先按章切** —— 切得出章节，收获就能逐章展开。
        if source != "weread" and not excerpts and not chapters_in:
            # ⚠️ 用刚 ensure 出来的 ``project_id``，不是 ``book`` 里那个旧值 ——
            # 惰性建项目后，书可能到这一刻才第一次有项目。
            local_chapters, local_excerpts = await asyncio.to_thread(
                _reading_material_for, project_id
            )
            chapters_in = local_chapters
            excerpts = local_excerpts

        # 简介：前端没给就自己去书源拉。它是唯一的**成段材料** —— 少了它，
        # 模型只能把「20 条金句 + 章节标题」重新排列，产出必然还是碎片。
        book_intro = str(body.get("book_intro") or "").strip()
        if not book_intro:
            book_intro = await asyncio.to_thread(_reading_book_intro, book)

        payload = reading_digest_mod.build_digest_payload(
            title=title,
            author=author,
            book_intro=book_intro,
            highlights=highlights,
            thoughts=thoughts,
            reviews=reviews,
            progress=int(book.get("progress") or 0),
            chapters=chapters_in,
            excerpts=excerpts,
        )
        result: dict[str, Any] = {}
        used_fallback = False
        insufficient = False
        material = payload.get("material") or {}
        if reading_digest_mod.material_is_empty(material):
            # 简介 / 目录 / 划线**全空**时绝不调模型 —— 它没有可依据的东西，
            # 只会拿训练数据里对这本书的印象把 schema 填满，产出一篇
            # 读着像模像样、实则与这本书无关的文档（「无效信息太多」的元凶）。
            result = reading_digest_mod.build_insufficient_digest(title=title, material=material)
            insufficient = True
        elif application.state.settings.tju_api_key or application.state.llm.responder is not None:
            try:
                raw = await asyncio.to_thread(
                    application.state.llm.complete_json, "make_reading_digest", payload
                )
                result = reading_digest_mod.normalize_digest_result(raw, {})
            except Exception:  # noqa: BLE001 —— 生成失败要走本地兜底，不是 500
                result = {}
        if not insufficient and not reading_digest_mod.digest_has_content(result):
            result = reading_digest_mod.build_digest_fallback(
                title=title, highlights=highlights, thoughts=thoughts
            )
            used_fallback = True
        # 「这份文档到底是什么」的如实声明由**系统**给出，不经模型 ——
        # 没有个人划线时它挂在正文最前面，读者才不会把「书籍导读」当成自己的收获。
        material = payload.get("material") or {}
        scope_note = reading_digest_mod.digest_scope_note(material)
        heading = "读书收获" if payload.get("mode") == "personal" else "书籍导读"
        content_md = reading_digest_mod.render_digest_markdown(
            result, title=title, author=author, scope_note=scope_note, heading=heading
        )

        doc = await asyncio.to_thread(
            reading_store().save_doc,
            owner_id=user.user_id,
            book_key=book_key,
            kind="digest",
            title=f"{title} · {heading}",
            result=result,
            content_md=content_md,
            signature=_reading_signature(highlights, thoughts),
            project_id=project_id,
        )
        wanted = reading_store_mod.build_sync_cards(result, book_key=book_key)
        synced = await asyncio.to_thread(
            reading_store_mod.sync_cards, db, project_id, wanted=wanted
        )
        return {
            "doc": doc,
            "cards": synced,
            "project_id": project_id,
            "fallback": used_fallback,
            "insufficient": insufficient,
            "mode": payload.get("mode") or "personal",
        }

    @application.post("/api/reading/books/{book_key}/digest")
    async def reading_generate_digest(book_key: str, request: Request) -> dict[str, Any]:
        """生成《读书收获》，并**自动把自测题沉淀为该书项目的知识卡片**。

        body: ``{highlights?, thoughts?, reviews?, book_intro?}`` —— 划线/想法由前端从
        书源取来（微信读书走 ``/book/bookmarklist``，本地书走正文解析）。模型不可用时
        自动退化为本地兜底（只原样呈现用户自己的划线，**不编造**）。
        """
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        try:
            body = await request.json()
        except Exception:
            body = {}
        return await _generate_reading_digest(user, book, body if isinstance(body, dict) else {})

    async def _generate_reading_intro(
        user: Any, book: dict[str, Any], body: dict[str, Any] | None = None
    ) -> dict[str, Any]:
        """生成一本书的【检视结论 + 介绍】。

        对应《如何阅读一本书》的**检视阅读**：不读全书，只凭简介、目录与用户自己的划线，
        判断这本书**值不值得读、该用哪档力气读、先读哪几章**。
        「这本书不用读」是一个合法的、而且是高频的结论 —— 所以 `read_mode` 会被要求真分档。
        """
        book_key = str(book.get("book_key") or "")
        body = body if isinstance(body, dict) else {}
        highlights = body.get("highlights") if isinstance(body.get("highlights"), list) else []
        thoughts = body.get("thoughts") if isinstance(body.get("thoughts"), list) else []

        if str(book.get("source") or "") == "weread" and not highlights and not thoughts:
            try:
                fetched = await asyncio.to_thread(_fetch_weread_notes, book["source_id"])
                highlights = fetched.get("highlights") or []
                thoughts = fetched.get("thoughts") or []
            except Exception:  # noqa: BLE001 —— 划线是增强，拉不到不代表不能检视
                pass

        book_intro = str(body.get("book_intro") or "").strip()
        if not book_intro:
            book_intro = await asyncio.to_thread(_reading_book_intro, book)

        payload = reading_digest_mod.build_intro_payload(
            title=str(book.get("title") or ""),
            author=str(book.get("author") or ""),
            native_category=str(book.get("category") or ""),
            book_intro=book_intro,
            highlights=highlights,
            thoughts=thoughts,
        )
        result: dict[str, Any] = {}
        used_fallback = False
        if application.state.settings.tju_api_key or application.state.llm.responder is not None:
            try:
                raw = await asyncio.to_thread(
                    application.state.llm.complete_json, "make_book_intro", payload
                )
                result = reading_digest_mod.normalize_intro_result(raw, {})
            except Exception:  # noqa: BLE001
                result = {}
        if not (result.get("intro") or result.get("one_liner")):
            result = reading_digest_mod.build_intro_fallback(
                title=str(book.get("title") or ""),
                author=str(book.get("author") or ""),
                native_category=str(book.get("category") or ""),
                book_intro=book_intro,
            )
            used_fallback = True
        # 分类顺手落回书架：检视时 AI 给的领域往往比「按书名猜」准。
        if result.get("category") and result["category"] != "其他":
            try:
                await asyncio.to_thread(
                    reading_store().upsert_book,
                    user.user_id,
                    {**book, "category": result["category"]},
                )
            except Exception:  # noqa: BLE001 —— 分类是顺带的，失败不该让整次检视挂掉
                pass

        project_id = str(book.get("project_id") or "")
        doc = await asyncio.to_thread(
            reading_store().save_doc,
            owner_id=user.user_id,
            book_key=book_key,
            kind="intro",
            title=f"{book.get('title') or ''} · 书籍检视",
            result=result,
            content_md=reading_digest_mod.render_intro_markdown(
                result, title=str(book.get("title") or "")
            ),
            signature=_reading_signature(highlights, thoughts),
            project_id=project_id,
        )
        return {"doc": doc, "fallback": used_fallback}

    @application.post("/api/reading/books/{book_key}/intro")
    async def reading_generate_intro(book_key: str, request: Request) -> dict[str, Any]:
        """生成《书籍检视》：值不值得读 / 用哪档力气读 / 先读哪几章。"""
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        try:
            body = await request.json()
        except Exception:
            body = {}
        return await _generate_reading_intro(user, book, body if isinstance(body, dict) else {})

    @application.post("/api/reading/digests/generate-missing")
    async def reading_generate_missing_digests(request: Request) -> dict[str, Any]:
        """**一键补全**：给所有还没有收获的书批量生成。

        为什么需要它：知识网络的节点来自各书的「可复用模型」，一本都没生成时网络是空的；
        而书一多，一本一本点就成了负担。批量跑完，网络才有东西可连。

        body: ``{limit?: int}`` —— 单次上限（默认 8，最大 20）。
        **逐本 try**：某本书失败（模型超时、书源挂了）不影响其余，失败原因回传给前端。
        """
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        try:
            limit = int(body.get("limit", 8))
        except Exception:
            limit = 8
        limit = max(1, min(limit, 20))

        store = reading_store()
        pending: list[dict[str, Any]] = []
        for book in await asyncio.to_thread(store.list_books, user.user_id):
            existing = await asyncio.to_thread(
                store.get_doc, user.user_id, book["book_key"], "digest"
            )
            if existing:
                continue
            pending.append(book)
            if len(pending) >= limit:
                break

        done: list[dict[str, Any]] = []
        failed: list[dict[str, Any]] = []
        for book in pending:
            try:
                result = await _generate_reading_digest(user, book, {})
                done.append(
                    {
                        "book_key": book["book_key"],
                        "title": book.get("title") or "",
                        "cards": (result.get("cards") or {}).get("synced", 0),
                        "fallback": bool(result.get("fallback")),
                    }
                )
            except Exception as exc:  # noqa: BLE001 —— 逐本兜，不让一本拖垮整批
                failed.append(
                    {"book_key": book["book_key"], "title": book.get("title") or "",
                     "error": f"{type(exc).__name__}: {exc}"[:200]}
                )
        return {
            "generated": len(done),
            "failed": len(failed),
            "remaining": max(0, len(pending) - limit) if len(pending) >= limit else 0,
            "books": done,
            "errors": failed,
        }

    @application.get("/api/reading/books/{book_key}/cards")
    async def reading_book_cards(book_key: str, request: Request) -> dict[str, Any]:
        """这本书沉淀出来的知识卡片（只列回流卡，用户手工建的卡不在这里）。"""
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        project_id = str(book.get("project_id") or "")
        if not project_id:
            return {"cards": []}
        cards = await asyncio.to_thread(db.list_cards, project_id)
        return {
            "cards": [
                {"card_id": c.card_id, "front": c.front, "back": c.back, "category": c.category}
                for c in cards
                if str(getattr(c, "card_id", "") or "").startswith(reading_store_mod.SYNC_CARD_PREFIX)
            ]
        }

    # ---- 微信读书：书架同步（元数据 + 划线；**不含正文**）----

    # 本地凭据文件里的键名。值与模型密钥同一套 DPAPI 加密，存在 data/（已 gitignore）。
    _WEREAD_KEY_SLOT = "weread_api_key"

    def _weread_key() -> tuple[str, str]:
        """解析微信读书 Key，返回 ``(key, 来源)``。

        **绝不落任何日志**：只回传来源名（env / config），不回传 key 本身。
        """
        env_key = str(os.environ.get("WEREAD_API_KEY") or "").strip()
        if env_key:
            return env_key, "env"
        try:
            stored = read_extra_local_secret(application.state.settings.data_dir, _WEREAD_KEY_SLOT)
        except Exception:
            stored = ""
        return (stored, "config") if stored else ("", "")

    def _weread_client() -> weread_mod.WereadClient:
        key, _ = _weread_key()
        return weread_mod.WereadClient(key)

    @application.get("/api/reading/weread/status")
    async def weread_status(request: Request, probe: int = 0) -> dict[str, Any]:
        """微信读书连接状态。``probe=1`` 时真的打一次接口验证 Key 是否有效。"""
        require_user(request)
        key, origin = _weread_key()
        payload: dict[str, Any] = {
            "configured": bool(key),
            "origin": origin,
            "capabilities": {
                "shelf": True,
                "cover": True,
                "progress": True,
                "notes": True,
                "fulltext": False,   # 微信读书不提供正文，这是商业边界
            },
            "note": "微信读书只提供书架、封面、进度与你的划线；整本正文需用公版书源或本地导入。",
        }
        if key and probe:
            try:
                shelf = await asyncio.to_thread(_weread_client().shelf)
                payload["shelf"] = weread_mod.shelf_counts(shelf)
                payload["ok"] = True
            except Exception as exc:  # noqa: BLE001 —— 探测失败要给人话，不是 500
                payload["ok"] = False
                payload["error"] = str(exc)
        return payload

    @application.put("/api/reading/weread/key")
    async def weread_save_key(request: Request) -> dict[str, Any]:
        """保存微信读书 API Key（``wrk-`` 开头）。

        写入 ``data/local_api_config.json``（DPAPI 密文，data/ 已 gitignore），
        与模型密钥同一套加密 —— 重启不用重填。**响应里绝不回显 key**。
        """
        require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        raw = str(body.get("api_key") or "").strip()
        if raw and not raw.startswith("wrk-"):
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "weread_key_format",
                    "微信读书 API Key 应以 wrk- 开头。请到官方渠道获取后重试。",
                ),
            )
        try:
            await asyncio.to_thread(
                save_extra_local_secret, application.state.settings.data_dir, _WEREAD_KEY_SLOT, raw
            )
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(
                status_code=500,
                detail=error_payload("weread_key_save_failed", f"保存失败：{exc}"),
            ) from exc
        return {"configured": bool(raw), "origin": "config" if raw else ""}

    @application.post("/api/reading/weread/sync")
    async def weread_sync(request: Request) -> dict[str, Any]:
        """同步微信读书书架：拉书 → 入库。

        **不建项目** —— 同步往往一次进来几百本，全是元数据，给每本都建项目会瞬间
        塞满侧栏。真要用到时（生成收获 / 导入正文）再按需建。

        body: ``{progress_limit?: int}`` —— 顺带拉最近阅读的 N 本书的进度（默认 5，
        上限 20）。书架可能有几百本，逐本拉进度会打爆接口，所以只取最近在读的几本。
        """
        user = require_user(request)
        key, _ = _weread_key()
        if not key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "weread_key_missing",
                    "还没有配置微信读书 API Key。填入 wrk- 开头的 Key 后即可同步书架。",
                ),
            )
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        try:
            limit = int(body.get("progress_limit", 5))
        except Exception:
            limit = 5
        limit = max(0, min(limit, 20))

        client = _weread_client()
        try:
            shelf = await asyncio.to_thread(client.shelf)
        except Exception as exc:  # noqa: BLE001 —— 网络/凭据问题都要变成人话
            raise HTTPException(
                status_code=502,
                detail=error_payload("weread_sync_failed", f"同步书架失败：{exc}"),
            ) from exc

        records = weread_mod.shelf_records(shelf)
        store = reading_store()
        added: list[dict[str, Any]] = []
        for record in records:
            book = await asyncio.to_thread(store.upsert_book, user.user_id, record)
            if not book:
                continue
            project_id = str(book.get("project_id") or "")
            added.append({"book_key": book["book_key"], "title": book["title"], "project_id": project_id})

        # 最近阅读的几本顺带拉进度（按 readUpdateTime 降序）。
        progressed = 0
        recent = sorted(records, key=lambda r: r.get("read_update_time", 0), reverse=True)[:limit]
        for record in recent:
            try:
                payload = await asyncio.to_thread(client.progress, record["source_id"])
            except Exception:
                continue
            info = weread_mod.progress_from_payload(payload)
            book_key = reading_store_mod.book_key_for(record["source"], record["source_id"])
            status = "finished" if info["progress"] >= 100 else ("reading" if info["progress"] > 0 else "unread")
            await asyncio.to_thread(
                store.update_progress, user.user_id, book_key,
                progress=info["progress"], status=status,
            )
            progressed += 1

        return {
            "synced": len(added),
            "progressed": progressed,
            "counts": weread_mod.shelf_counts(shelf),
            "books": added,
        }

    @application.get("/api/reading/weread/books/{book_id}/notes")
    async def weread_book_notes(book_id: str, request: Request) -> dict[str, Any]:
        """拉某本书的划线与个人想法 —— 收获文档的直接输入。"""
        require_user(request)
        key, _ = _weread_key()
        if not key:
            raise HTTPException(
                status_code=503,
                detail=error_payload("weread_key_missing", "还没有配置微信读书 API Key。"),
            )
        client = _weread_client()
        try:
            bookmarks = await asyncio.to_thread(client.bookmarks, book_id)
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(
                status_code=502,
                detail=error_payload("weread_notes_failed", f"拉取划线失败：{exc}"),
            ) from exc
        reviews: dict[str, Any] = {}
        try:
            reviews = await asyncio.to_thread(client.my_reviews, book_id)
        except Exception:
            reviews = {}
        notes = weread_mod.extract_notes(bookmarks, reviews)
        return {"book_id": book_id, **notes}

    def _weread_grouped_outline(book_id: str) -> list[dict[str, Any]]:
        """章节目录 + 按章归组的热门划线。**「逐章精读」与「精华阅读」共用这一份数据。**

        两处调用都各自 try：章节目录拿不到就整段返回空，热门划线拿不到就只出目录 ——
        缺一半也比整块消失强。
        """
        key, _ = _weread_key()
        if not key:
            return []
        client = weread_mod.WereadClient(key)
        try:
            chapters = weread_mod.chapter_list(client.chapters(book_id))
        except Exception:
            return []
        if not chapters:
            return []
        try:
            marks = weread_mod.best_bookmarks(client.best_bookmarks(book_id))
        except Exception:
            marks = {"items": []}
        return weread_mod.group_by_chapter(chapters, marks.get("items") or [])

    def _reading_book_intro(book: dict[str, Any]) -> str:
        """按书源拉**书籍简介** —— 收获文档里唯一的成段材料。

        微信读书只给 20 条热门划线、章节目录只是标题，两者都是碎片。
        简介（以及豆瓣条目的简介）是成段论述，缺了它，模型只能把碎片重新排列，
        产出的东西自然还是碎片。所以这一步不是锦上添花，是**减少碎片化的关键**。
        """
        source = str(book.get("source") or "")
        sid = str(book.get("source_id") or "")
        if not sid:
            return ""
        if source == "weread":
            key, _ = _weread_key()
            if not key:
                return ""
            try:
                return weread_mod.book_intro(weread_mod.WereadClient(key).book_info(sid))
            except Exception:
                return ""
        if source == "douban":
            try:
                return book_sources_mod.douban_detail(sid).get("intro", "")
            except Exception:
                return ""
        return ""

    def _fetch_weread_notes(book_id: str) -> dict[str, Any]:
        """拉某本书的划线与个人想法。收获接口用它补齐材料，前端不必先拉一遍。"""
        key, _ = _weread_key()
        if not key:
            return {"highlights": [], "thoughts": []}
        client = weread_mod.WereadClient(key)
        try:
            bookmarks = client.bookmarks(book_id)
        except Exception:
            bookmarks = {}
        try:
            reviews = client.my_reviews(book_id)
        except Exception:
            reviews = {}
        return weread_mod.extract_notes(bookmarks, reviews)

    def _reading_material_for(project_id: str) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        """本地导入 / 公版书的收获材料，返回 ``(chapters, excerpts)``。

        先试着**按章节切**（``book_sources.split_chapters``）—— 切得出来，收获就能
        逐章展开，这是本地书相对微信读书的最大优势：**它有真全文**。
        切不出来（标题不规范）才退化成整块摘录，让模型自己去认结构。
        """
        if not project_id:
            return [], []
        try:
            rows = db.list_sources(project_id)
        except Exception:
            return [], []
        chapters: list[dict[str, Any]] = []
        excerpts: list[dict[str, Any]] = []
        for row in rows or []:
            text = str(getattr(row, "text", "") or "").strip()
            if not text:
                continue
            name = str(getattr(row, "filename", "") or "")
            found = book_sources_mod.split_chapters(text)
            if found and len(chapters) < 20:
                for item in found:
                    if len(chapters) >= 20:
                        break
                    chapters.append({"title": item["title"], "excerpt": item["excerpt"]})
                continue
            for start in range(0, len(text), 1400):
                piece = text[start : start + 1400].strip()
                if len(piece) < 200:
                    continue
                excerpts.append({"book": name, "text": piece})
                if len(excerpts) >= 30:
                    break
        return chapters, excerpts

    @application.get("/api/reading/weread/recommend")
    async def weread_recommend(request: Request, count: int = 12) -> dict[str, Any]:
        """「为你推荐」——**搜不到书时的发现入口**。

        官方 ``/store/search`` 对部分 API Key 会返回空结果（实测如此），
        而推荐接口是通的。所以发现路径是「书架同步 + 为你推荐 + 本地导入」，
        不是「搜索」。
        """
        require_user(request)
        key, _ = _weread_key()
        if not key:
            raise HTTPException(
                status_code=503,
                detail=error_payload("weread_key_missing", "还没有配置微信读书 API Key。"),
            )
        try:
            payload = await asyncio.to_thread(
                _weread_client().recommend, count=max(1, min(int(count), 40))
            )
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(
                status_code=502,
                detail=error_payload("weread_recommend_failed", f"获取推荐失败：{exc}"),
            ) from exc
        records = weread_mod.recommend_records(payload)
        return {
            "books": records,
            "groups": book_sources_mod.group_by_category(records),
            "summary": book_sources_mod.fulltext_summary(records),
        }

    @application.get("/api/reading/books/{book_key}/outline")
    async def reading_book_outline(book_key: str, request: Request) -> dict[str, Any]:
        """「精华阅读」的数据：章节目录 + 每章最热的原文片段。

        微信读书**不提供整本正文**（商业边界，改不了），但它提供全书热门划线 ——
        那是读者公认最重要的原文片段。按章摆开，就是这本书能读到的「精华版」。
        本地导入的书则直接读它的资料正文（那份是真的全文）。
        """
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        source = str(book.get("source") or "")

        # ⚠️ **项目资料优先于书源**：只要这本书的项目里已经有正文（本地导入 / 用户
        # 把自备的 EPUB·PDF·TXT 传进来了），就读它 —— 那才是真全文。
        # 微信读书的书一旦导入正文，也该走这条分支；否则用户明明导入了，
        # 阅读页还是只给他 20 条热门划线，会以为导入没成功。
        project_id = str(book.get("project_id") or "")
        sources: list[dict[str, Any]] = []
        if project_id:
            try:
                rows = await asyncio.to_thread(db.list_sources, project_id)
            except Exception:
                rows = []
            for row in rows or []:
                text = str(getattr(row, "text", "") or "")
                sources.append(
                    {
                        "source_id": getattr(row, "source_id", ""),
                        "filename": getattr(row, "filename", ""),
                        "chars": len(text),
                        "preview": text[:1200],
                    }
                )
        if sources:
            return {
                "kind": "fulltext",
                "note": "这本书的正文已导入项目，可直接阅读并提问。",
                "sources": sources,
                "chapters": [],
                "total_highlights": 0,
            }

        if source == "weread":
            grouped = await asyncio.to_thread(_weread_grouped_outline, book["source_id"])
            return {
                "kind": "highlights",
                "note": (
                    "微信读书不提供整本正文，这里是全书热门划线按章排列的精华版。"
                    "想要能全文检索、能划词提问的正文，把这本书的 EPUB / PDF / TXT 传进来即可。"
                ),
                "chapters": grouped,
                "total_highlights": sum(len(c.get("highlights") or []) for c in grouped),
                "can_import_fulltext": True,
            }

        return {
            "kind": "empty",
            "note": "还没有导入正文。",
            "sources": [],
            "chapters": [],
            "total_highlights": 0,
            "can_import_fulltext": True,
        }

    @application.post("/api/reading/books/{book_key}/ask")
    async def reading_book_ask(book_key: str, request: Request) -> StreamingResponse:
        """选中一段 → 就这一段跟 AI 讨论（SSE 流式）。

        上下文由**前端**给出：它知道读者选中的是哪一块（收获正文 / 检视结论 /
        精华阅读的划线 / 正文预览）。拿不到时依次退到这本书的《读书收获》与项目正文
        （复用既有的 ``_literature_texts``，不另写一份取正文）。
        整本送进去既贵、又会让模型在中段丢掉「先贴书、再发散」这条主线，所以只送
        **选区所在的那一块**（``core/knowledge_doc.excerpt_around``）。

        口径：这是**陪读讨论**，不是文档问答 —— 默认就要发散（见
        ``reading_digest.READING_ASK_SYSTEM``）。选区只是讨论的**锚点**，不是答案的边界：
        模型先贴着书说清这段，再往别的书 / 学科 / 现实 / 反方 / 思想实验上放开铺，
        只要书外内容自报家门、不编造具体书目与人名即可。温度也给高一档（0.8），
        发散要的是联想宽度，不是唯一解。
        """
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        question = str(body.get("question") or "").strip()
        if not question:
            raise HTTPException(
                status_code=400,
                detail=error_payload("reading_question_required", "先写一句想问的。"),
            )
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "讨论需要大模型 API。请先登录后在「API 配置」里填写 API Key。",
                ),
            )
        selection = str(body.get("selection") or "")
        context = str(body.get("context") or "").strip()
        if not context:
            doc = await asyncio.to_thread(
                reading_store().get_doc, user.user_id, book_key, "digest"
            )
            context = str((doc or {}).get("content_md") or "").strip()
        if not context:
            # 只有真的有项目时才去翻项目正文 —— 没项目的书（纯元数据，如豆瓣条目）
            # 直接落到下面的「没材料」分支给一句人话；否则 list_sources("") 会抛
            # 「课程项目不存在：」，把「没材料」误报成「项目丢了」。
            project_id = str(book.get("project_id") or "")
            if project_id:
                context = await asyncio.to_thread(_literature_texts, project_id)
        context = knowledge_doc_mod.excerpt_around(context, selection)
        payload = reading_digest_mod.build_reading_ask_payload(
            question=question,
            selection=selection,
            context=context,
            book=book,
            history=body.get("history") if isinstance(body.get("history"), list) else [],
        )
        if not reading_digest_mod.ask_needs_material(payload):
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "reading_ask_no_material",
                    "这本书还没有可依据的材料：先在页面里选中一段原文，或先生成一次《读书收获》。",
                ),
            )
        messages = [
            {"role": "system", "content": reading_digest_mod.READING_ASK_SYSTEM},
            {
                "role": "user",
                "content": json.dumps(
                    {"task": "reading_ask", "payload": payload}, ensure_ascii=False
                ),
            },
        ]

        def _ask_sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream() -> AsyncIterator[str]:
            yield _ask_sse({"type": "start", "context_chars": len(context)})
            pieces: list[str] = []
            try:
                async for chunk in application.state.llm.astream_chat_content(
                    messages, "reading_ask",
                    temperature=reading_digest_mod.READING_ASK_TEMPERATURE,
                ):
                    pieces.append(chunk)
                    yield _ask_sse({"type": "delta", "text": chunk})
            except Exception as exc:  # noqa: BLE001 —— 要变成人能看懂的一句话
                LOGGER.warning("reading ask failed: %s", exc)
                yield _ask_sse({"type": "error", "message": f"这次没答上来：{exc}"})
                return
            answer = knowledge_doc_mod.clean_answer("".join(pieces))
            if not answer:
                yield _ask_sse(
                    {"type": "error", "message": "模型这次没有返回内容，可以再问一次。"}
                )
                return
            yield _ask_sse({"type": "done", "text": answer})

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @application.put("/api/reading/books/{book_key}/fulltext")
    async def reading_mark_fulltext(book_key: str, request: Request) -> dict[str, Any]:
        """把一本书标记为「已导入正文」。

        前端先把文件传进这本书的项目（走既有的上传 / 解析 / OCR 链路），
        成功后调这里落一个标记 —— 于是书架卡片会打上「全文」徽标，
        阅读页也会切到真全文视图。**不重复造上传逻辑**，只补这一步状态。
        """
        user = require_user(request)
        await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        fmt = str(body.get("format") or "").strip().lstrip(".").lower()
        book = await asyncio.to_thread(
            reading_store().mark_fulltext, user.user_id, book_key, fmt
        )
        return {"book": book}

    @application.post("/api/reading/books/{book_key}/fulltext/fetch")
    async def reading_fetch_fulltext(book_key: str, request: Request) -> dict[str, Any]:
        """**自动取正文**：把公版书的整本正文抓进这本书自己的项目。

        这是「本地导入」之外的第二条正文路径 —— 之前 `fetch_fulltext()` 写好了却没有
        任何入口，等于公版书全文能力一直闲置。现在补上：

        1. 按书源取正文（Standard Ebooks / 古腾堡 / Internet Archive / 维基文库）；
        2. **复用「粘贴文本」那条既有链路**入库（解析 → 项目资料），不另造一套；
        3. 落 ``mark_fulltext`` 标记，书架徽标与阅读页立刻切成真全文。

        有版权的书在这里必然被拒（``fetch_fulltext`` 的版权红线），返回原因是给用户看的，
        不是给日志看的 —— 所以直接透出去。
        """
        user = require_user(request)
        book = await asyncio.to_thread(_reading_book_or_404, user.user_id, book_key)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        # 搜索结果里的入口（files / read_url）比书架记录更全，允许前端带上来补足。
        # 只覆盖非空字段，避免把书架上的状态字段冲掉。
        incoming = body.get("book") if isinstance(body.get("book"), dict) else {}
        record = {**book, **{k: v for k, v in incoming.items() if v not in (None, "", [], {})}}

        result = await asyncio.to_thread(book_sources_mod.fetch_fulltext, record)
        if not result.get("ok"):
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "reading_fulltext_fetch_failed",
                    str(result.get("reason") or "取正文失败。"),
                ),
            )
        text = str(result.get("text") or "")
        if len(text) < 200:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "reading_fulltext_too_short",
                    f"抓到的正文只有 {len(text)} 字，明显不完整，已放弃入库。",
                ),
            )

        project_id = await asyncio.to_thread(
            _reading_project_for, user.user_id, book_key
        )
        filename = f"{str(record.get('title') or '公版书').strip()[:60]}.txt"
        # ⚠️ 走「粘贴文本」而不是「上传文件」：正文已经在内存里，再落一次临时文件
        # 只会多一份磁盘拷贝，还要自己清理。
        extracted = extract_source(filename, b"", pasted_text=text)
        saved = await asyncio.to_thread(db.add_source, project_id, extracted)
        row = await asyncio.to_thread(db.get_source_row, project_id, saved.source_id)
        record_undo(
            user,
            project_id,
            "source.add",
            f"自动获取《{str(record.get('title') or '')}》正文（{len(text)} 字）",
            {"project_id": project_id, "sources": [row]},
        )
        fmt = str(result.get("format") or "txt")
        updated = await asyncio.to_thread(
            reading_store().mark_fulltext, user.user_id, book_key, fmt
        )
        return {
            "book": updated,
            "source": _source_payload(application, saved),
            "chars": len(text),
            "format": fmt,
            "chapters": len(result.get("chapters") or []),
        }

    @application.post("/api/reading/links")
    async def reading_file_links(request: Request) -> dict[str, Any]:
        """**找文件链接**：给一本书找「哪里能读 / 能借 / 能下」。

        这是「取正文」之外的另一条路，而且经常更有用 —— 有版权的书正文拿不到，
        但一个能立刻打开的正确入口是拿得到的（HathiTrust 馆藏、Open Library 借阅、
        Internet Archive 扫描本、出版社直链…）。用户要的往往就是这个。
        """
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        record = body.get("book") if isinstance(body.get("book"), dict) else body
        record = record if isinstance(record, dict) else {}
        # 允许只传 book_key：书架上的记录更权威（含 source/source_id/isbn）。
        book_key = str(body.get("book_key") or "").strip()
        if book_key:
            stored = await asyncio.to_thread(reading_store().get_book, user.user_id, book_key)
            if stored:
                record = {**record, **stored}
        if not record.get("title"):
            raise HTTPException(
                status_code=400,
                detail=error_payload("reading_links_book_required", "先选一本书。"),
            )
        result = await asyncio.to_thread(book_sources_mod.find_file_links, record)
        return {
            "ok": bool(result.get("ok")),
            "links": result.get("links") or [],
            "reason": str(result.get("reason") or ""),
            "checked": result.get("checked") or [],
            "proxy_in_use": book_sources_mod.using_proxy(),
        }

    # ------------------------------------------------------------------
    # 跨书知识网络
    #
    # 输入是**各书的《读书收获》**（models = 可复用框架，connections = 关联对象）。
    # 输出是一张图 + 三类结构信息：hub（枢纽）、bridge（桥，割点）、跨书支持度。
    #
    # 「桥」是整张网里最值钱的东西：去掉它，图就断成两半 —— 它连接的是两个
    # 原本无关的领域（Munger 说的「不同学科指向同一结论」；前沿图推理论文里的
    # bridging nodes）。所以界面上要把桥单独拎出来，并且能**就着这个簇生成方法论**。
    # ------------------------------------------------------------------

    def net_store() -> NetStore:
        return _aux_store("net", NetStore)

    def _reading_digests(owner_id: str) -> list[dict[str, Any]]:
        """把该用户所有书的收获文档收成知识网络的输入。没有收获的书自然不进网。"""
        store = reading_store()
        out: list[dict[str, Any]] = []
        for book in store.list_books(owner_id):
            doc = store.get_doc(owner_id, book["book_key"], "digest")
            if not doc:
                continue
            content = doc.get("content") or {}
            if not isinstance(content, dict):
                continue
            out.append(
                {
                    "book": str(book.get("title") or ""),
                    "book_key": str(book.get("book_key") or ""),
                    "models": content.get("models") or [],
                    "connections": content.get("connections") or [],
                }
            )
        return out

    def _net_analysis(owner_id: str) -> dict[str, Any]:
        """现算整张网（含用户确认过的合并）。"""
        return knowledge_net_mod.analyze(
            _reading_digests(owner_id),
            merges=net_store().list_merges(owner_id),
        )

    @application.get("/api/reading/net")
    async def reading_net(request: Request) -> dict[str, Any]:
        """整张跨书知识网络 + 结构分析（枢纽 / 桥 / 跨书支持度）。"""
        user = require_user(request)
        data = await asyncio.to_thread(_net_analysis, user.user_id)
        data["methodologies"] = await asyncio.to_thread(
            net_store().list_methodologies, user.user_id
        )
        return data

    @application.get("/api/reading/net/candidates")
    async def reading_net_candidates(request: Request) -> dict[str, Any]:
        """可能该合并的概念对。**只给候选，合并要用户点**（不猜合并）。"""
        user = require_user(request)
        data = await asyncio.to_thread(_net_analysis, user.user_id)
        return {"candidates": knowledge_net_mod.candidate_pairs(data["nodes"])}

    @application.post("/api/reading/net/merge")
    async def reading_net_merge(request: Request) -> dict[str, Any]:
        """确认合并两个概念（``{from_key, to_key}``）。可撤销。"""
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        from_key = str(body.get("from_key") or "").strip()
        to_key = str(body.get("to_key") or "").strip()
        if not from_key or not to_key or from_key == to_key:
            raise HTTPException(
                status_code=400,
                detail=error_payload("net_merge_invalid", "需要两个不同的概念键。"),
            )
        await asyncio.to_thread(net_store().add_merge, user.user_id, from_key, to_key)
        data = await asyncio.to_thread(_net_analysis, user.user_id)
        return {"ok": True, **data}

    @application.delete("/api/reading/net/merge/{from_key}")
    async def reading_net_unmerge(from_key: str, request: Request) -> dict[str, Any]:
        user = require_user(request)
        await asyncio.to_thread(net_store().remove_merge, user.user_id, from_key)
        return {"ok": True, **await asyncio.to_thread(_net_analysis, user.user_id)}

    @application.post("/api/reading/net/methodology")
    async def reading_net_methodology(request: Request) -> dict[str, Any]:
        """就着某个概念所在的**簇**生成一份《方法论》，并沉淀技能卡。

        body: ``{anchor_key}`` —— 一般传一个**桥**（bridge）的键，
        因为桥所在的那个簇横跨两个领域，归纳出来的方法论最有用。
        """
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        anchor_key = str(body.get("anchor_key") or "").strip()
        if not anchor_key:
            raise HTTPException(
                status_code=400,
                detail=error_payload("net_anchor_required", "需要指定要归纳哪个概念所在的簇。"),
            )

        data = await asyncio.to_thread(_net_analysis, user.user_id)
        cluster_key = (data.get("cluster_keys") or {}).get(anchor_key, "")
        members = set()
        for group in data.get("clusters") or []:
            if anchor_key in group:
                members = set(group)
                break
        if not members:
            raise HTTPException(
                status_code=404,
                detail=error_payload("net_cluster_not_found", "这个概念还不在网络里。"),
            )
        by_key = {n["concept_key"]: n for n in data.get("nodes") or []}
        cluster_nodes = [by_key[k] for k in members if k in by_key]
        cluster_edges = [
            e for e in (data.get("edges") or [])
            if e.get("source") in members and e.get("target") in members
        ]
        anchor_name = (by_key.get(anchor_key) or {}).get("name") or anchor_key

        payload = knowledge_net_mod.build_methodology_payload(cluster_nodes, cluster_edges)
        result: dict[str, Any] = {}
        used_fallback = False
        if application.state.settings.tju_api_key or application.state.llm.responder is not None:
            try:
                raw = await asyncio.to_thread(
                    application.state.llm.complete_json, "make_methodology", payload
                )
                result = knowledge_net_mod.normalize_methodology_result(raw)
            except Exception:  # noqa: BLE001 —— 失败要走兜底，不是 500
                result = {}
        if not knowledge_net_mod.methodology_has_content(result):
            result = knowledge_net_mod.build_methodology_fallback(cluster_nodes)
            used_fallback = True
        content_md = knowledge_net_mod.render_methodology_markdown(
            result, concepts=[n.get("name") or "" for n in cluster_nodes]
        )

        saved = await asyncio.to_thread(
            net_store().save_methodology,
            user.user_id,
            cluster_key=cluster_key,
            result=result,
            content_md=content_md,
            anchor_key=anchor_key,
            anchor_name=anchor_name,
        )

        # 技能卡：沉淀到簇里**任意一本有项目的书**下 —— 卡是项目级的，
        # 而这些概念本来就来自那几本书。
        synced = {"synced": 0, "updated": 0, "removed": 0, "card_ids": []}
        wanted = knowledge_net_mod.build_skill_cards(result, cluster_key=cluster_key)
        if wanted:
            names = (by_key.get(anchor_key) or {}).get("books") or []
            by_title = {b.get("title"): b for b in reading_store().list_books(user.user_id)}
            project_id = ""
            # 先挑一本已经有项目的书（生成过收获 / 导入过正文）。
            for name in names:
                book = by_title.get(name)
                if book and book.get("project_id"):
                    project_id = str(book["project_id"])
                    break
            # 都没有就按需给锚点书建一个 —— 技能卡是**有产出**的，值得一个项目承载。
            if not project_id:
                for name in names:
                    book = by_title.get(name)
                    if book:
                        project_id = await asyncio.to_thread(
                            _reading_project_for, user.user_id, book["book_key"]
                        )
                        if project_id:
                            break
            if project_id:
                synced = await asyncio.to_thread(
                    reading_store_mod.sync_cards, db, project_id, wanted=wanted
                )
        return {
            "methodology": saved,
            "cluster_key": cluster_key,
            "cluster": [{"concept_key": n["concept_key"], "name": n.get("name"),
                         "books": n.get("books") or []} for n in cluster_nodes],
            "cards": synced,
            "fallback": used_fallback,
        }

    @application.post("/api/reading/net/ask")
    async def reading_net_ask(request: Request) -> StreamingResponse:
        """就着**整张跨书知识网**提问（SSE 流式）。

        与 ``/api/reading/books/{book_key}/ask``（陪读讨论）分工不同，别合并：
        陪读是「读者正读着一本书、选中了一段」，这边是「读者手上是一张跨书的网」。
        所以这里**没有原文选段**这回事 —— 材料就是整张网的结构化描述，
        由**前端**渲染后送来（它手上有整张网，也才知道用户当前停在哪个领域 / 概念）。
        """
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        body = body if isinstance(body, dict) else {}
        question = str(body.get("question") or "").strip()
        if not question:
            raise HTTPException(
                status_code=400,
                detail=error_payload("reading_question_required", "先写一句想问的。"),
            )
        if not application.state.settings.tju_api_key and application.state.llm.responder is None:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "提问需要大模型 API。请先登录后在「API 配置」里填写 API Key。",
                ),
            )
        payload = knowledge_net_mod.build_net_ask_payload(
            question=question,
            context=body.get("context") if isinstance(body.get("context"), str) else "",
            scope=str(body.get("scope") or "network"),
            anchor=str(body.get("anchor") or ""),
            history=body.get("history") if isinstance(body.get("history"), list) else [],
        )
        if not knowledge_net_mod.net_ask_needs_material(payload):
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "reading_net_ask_no_material",
                    "这张网还没有可依据的材料：先生成至少两本书的《读书收获》。",
                ),
            )
        messages = [
            {"role": "system", "content": knowledge_net_mod.NET_ASK_SYSTEM},
            {
                "role": "user",
                "content": json.dumps(
                    {"task": "reading_net_ask", "payload": payload}, ensure_ascii=False
                ),
            },
        ]

        def _net_sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def net_event_stream() -> AsyncIterator[str]:
            yield _net_sse({"type": "start", "context_chars": len(payload["context"])})
            pieces: list[str] = []
            try:
                async for chunk in application.state.llm.astream_chat_content(
                    messages, "reading_ask"
                ):
                    pieces.append(chunk)
                    yield _net_sse({"type": "delta", "text": chunk})
            except Exception as exc:  # noqa: BLE001 —— 要变成人能看懂的一句话
                LOGGER.warning("reading net ask failed: %s", exc)
                yield _net_sse({"type": "error", "message": f"这次没答上来：{exc}"})
                return
            answer = knowledge_doc_mod.clean_answer("".join(pieces))
            if not answer:
                yield _net_sse({"type": "error", "message": "模型这次没有返回内容，可以再问一次。"})
                return
            yield _net_sse({"type": "done", "text": answer})

        return StreamingResponse(
            net_event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @application.post("/api/projects/{project_id}/nodes/{node_id}/doc")
    async def generate_node_doc(
        project_id: str,
        node_id: str,
        request: Request,
        refresh: bool = False,
        sync_cards: bool = True,
    ) -> dict[str, Any]:
        """为单个知识点生成「复习用详解」。

        结果按「节点 + 资料指纹」缓存（core/node_study_plan.py 的 fingerprint 口径）：
        资料没变直接复用上次结果、不重跑模型；资料变了自动失效；``?refresh=true`` 强制重算。

        ``sync_cards``（默认 true）控制要不要把文档里的自测题回流成知识卡片。
        这是**会改变用户可见状态**的副作用（多出几张卡、进复习队列、之后会写掌握度），
        所以前端第一次生成前必须问过用户，用户选「只生成文档」就传 false ——
        传 false 时 cards 表一个字节都不动，连已有回流卡的更新/回收也一并跳过，
        语义是「这一轮我不参与卡片」。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        node = db.get_framework_node(project_id, node_id)
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "生成知识点文档需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )

        scoped_sources, source_scope = _knowledge_doc_sources(project_id, node)
        neighbors, path = _knowledge_doc_context(project_id, node)
        store = knowledge_doc_store()
        doc_key = knowledge_doc_mod.doc_key_for(
            user.user_id, project_id, scope="node", node_id=node_id
        )
        signature = signature_for(node, scoped_sources)

        # 复用：同一节点 + 资料没变，直接拿上次结果（省一次模型调用，也不覆盖用户已看到的内容）
        if not refresh:
            cached = await asyncio.to_thread(store.get, doc_key)
            if cached and cached.get("signature") == signature and cached.get("content_md"):
                return {
                    **cached,
                    "cached": True,
                    "degraded": False,
                    "stale_sections": [],
                    "source_scope": source_scope,
                }

        payload = knowledge_doc_mod.build_node_payload(
            node=node,
            path=path,
            neighbors=neighbors,
            sources=scoped_sources,
            exam_weight_label=str(getattr(node, "exam_weight", "") or ""),
        )
        try:
            raw = await asyncio.to_thread(
                application.state.llm.complete_json, "make_knowledge_doc", payload
            )
        except Exception as exc:  # noqa: BLE001 —— 要变成人能看懂的一句话，不是堆栈
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "knowledge_doc_generation_failed",
                    f"生成「{node.name}」的文档时模型调用失败：{exc}。"
                    "可以稍后重试，或在「模型配置」里确认 API 可用。",
                ),
            ) from exc

        fallback = knowledge_doc_mod.build_node_fallback(
            node=node, path=path, neighbors=neighbors, sources=scoped_sources
        )
        merged = knowledge_doc_mod.normalize_node_result(raw, fallback)
        if not knowledge_doc_mod.result_has_content(merged):
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "knowledge_doc_empty",
                    "模型这次没有返回可用内容，这个节点自身也没有说明。"
                    "可以先给节点补一句说明或挂上资料，再重新生成。",
                ),
            )

        substance = {"summary", "definition", "mechanism", "formulas", "pitfalls", "relations", "self_check"}
        degraded = not (set(merged.get("_filled") or []) & substance)
        stale = [
            key
            for key in ("progression", "definition", "mechanism", "formulas", "pitfalls", "relations", "self_check")
            if not merged.get(key)
        ]
        # progression 的兜底是「从框架的前置边推出来的承接关系」，必须标明来路，
        # 不能让它冒充模型依据资料写的那句递进理由（_filled 只在模型真给了 why_order 时记录它）。
        if "progression" not in set(merged.get("_filled") or []) and "progression" not in stale:
            stale.append("progression")
        content_md = knowledge_doc_mod.render_node_markdown(
            merged,
            title=node.name,
            path=path,
            mastery=node.mastery_score,
            stale_sections=stale,
            degraded=degraded,
            generated_at=knowledge_doc_mod.local_stamp(),
        )
        saved = await asyncio.to_thread(
            store.save,
            doc_key=doc_key,
            owner_id=user.user_id,
            project_id=project_id,
            scope="node",
            node_id=node_id,
            title=node.name,
            signature=signature,
            content=merged,
            content_md=content_md,
        )
        # 自测题回流成知识卡片：正文一个字都不改，只是让这些题进了复习队列与掌握度。
        # 同步失败不该让「文档生成成功」变成失败 —— 内容已经落库了，如实降级返回。
        # 用户明确选「只生成文档」时 sync_cards=false，这里整个跳过、卡片表零改动。
        sync: dict[str, Any] = {
            "synced": 0, "updated": 0, "removed": 0, "card_ids": [], "skipped": not sync_cards,
        }
        if sync_cards:
            try:
                sync = await asyncio.to_thread(
                    knowledge_doc_mod.sync_cards,
                    db,
                    project_id,
                    node_id=node_id,
                    wanted=knowledge_doc_mod.build_sync_cards(
                        merged,
                        node_id=node_id,
                        source_ids=[getattr(s, "source_id", "") for s in scoped_sources],
                    ),
                )
            except Exception as exc:  # noqa: BLE001 —— 回流是附加价值，不是文档的成败
                LOGGER.warning("knowledge_doc 自测回流失败（文档已生成）：%s", exc)
                sync = {**sync, "error": str(exc)}
        return {
            **saved,
            "cached": False,
            "degraded": degraded,
            "stale_sections": stale,
            "source_scope": source_scope,
            "check_cards": sync,
        }

    @application.get("/api/projects/{project_id}/nodes/{node_id}/doc")
    async def get_node_doc(project_id: str, node_id: str, request: Request) -> dict[str, Any]:
        """读已生成的知识点文档（不调模型，纯读库）。"""
        user = require_user(request)
        require_project_access(project_id, request)
        doc = await asyncio.to_thread(
            knowledge_doc_store().get_node, user.user_id, project_id, node_id
        )
        if not doc or not str(doc.get("content_md") or "").strip():
            return {"doc": None}
        return {"doc": doc}

    @application.delete("/api/projects/{project_id}/nodes/{node_id}/doc")
    async def delete_node_doc(project_id: str, node_id: str, request: Request) -> dict[str, Any]:
        """删掉某个知识点的文档。合订稿不会跟着变，需要的话重新合订一次。"""
        user = require_user(request)
        require_project_access(project_id, request)
        removed = await asyncio.to_thread(
            knowledge_doc_store().delete,
            user.user_id,
            project_id,
            scope="node",
            node_id=node_id,
        )
        # 连同它回流出去的自测卡一起收掉，否则会留下一批「原文已经没了」的孤儿卡
        # 继续占用复习队列。同步只碰本节点名下、kd_ 前缀的卡。
        try:
            await asyncio.to_thread(
                knowledge_doc_mod.sync_cards, db, project_id, node_id=node_id, wanted=[]
            )
        except Exception as exc:  # noqa: BLE001 —— 文档已删，卡片残留可事后手动清理
            LOGGER.warning("knowledge_doc 删除时回收自测卡失败：%s", exc)
        return {"removed": removed}

    @application.get("/api/projects/{project_id}/knowledge-doc")
    async def list_knowledge_docs(project_id: str, request: Request) -> dict[str, Any]:
        """知识点文档的覆盖情况：哪些节点已有详解、有没有合订稿。

        ⚠️ 刻意**不返回正文** —— 一个项目的详解加起来可能上百 KB，列表每刷一次都传就太贵了。
        正文用 `nodes/{node_id}/doc` 与 `knowledge-doc/compiled` 单独取。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        nodes = await asyncio.to_thread(db.list_framework_nodes, project_id)
        docs = await asyncio.to_thread(
            knowledge_doc_store().list_for_project, user.user_id, project_id
        )
        node_docs = {d["node_id"]: d for d in docs if d["scope"] == "node"}
        compiled = next((d for d in docs if d["scope"] == "project"), None)
        items = [
            {
                "node_id": node.node_id,
                "name": node.name,
                "parent_id": node.parent_id,
                "has_doc": node.node_id in node_docs,
                "updated_at": (node_docs.get(node.node_id) or {}).get("updated_at"),
            }
            for node in nodes
        ]
        return {
            "total": len(nodes),
            "generated": sum(1 for item in items if item["has_doc"]),
            "items": items,
            "compiled": (
                {
                    "title": compiled["title"],
                    "updated_at": compiled["updated_at"],
                    "chars": len(str(compiled.get("content_md") or "")),
                }
                if compiled
                else None
            ),
        }

    @application.get("/api/projects/{project_id}/knowledge-doc/compiled")
    async def get_compiled_knowledge_doc(project_id: str, request: Request) -> dict[str, Any]:
        """读合订稿全文（不调模型）。"""
        user = require_user(request)
        require_project_access(project_id, request)
        doc = await asyncio.to_thread(
            knowledge_doc_store().get,
            knowledge_doc_mod.doc_key_for(user.user_id, project_id, scope="project"),
        )
        if not doc or not str(doc.get("content_md") or "").strip():
            return {"doc": None}
        return {"doc": doc}

    @application.put("/api/projects/{project_id}/knowledge-doc/content")
    async def save_knowledge_doc_content(project_id: str, request: Request) -> dict[str, Any]:
        """保存手工改过的正文 —— 高亮与直接编辑 Markdown 都走这一条。

        body：``{scope: "node"|"project", node_id: "", content_md: "..."}``。
        只写 content_md：结构化留档、指纹、回流卡片一概不动。重新生成会用模型结果
        覆盖手工改动，这是有意的（手工编辑是盖在生成结果上的一层）。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            payload_body = await request.json()
        except Exception:
            payload_body = {}
        payload_body = payload_body if isinstance(payload_body, dict) else {}
        scope = knowledge_doc_mod.normalize_scope(payload_body.get("scope"))
        node_id = str(payload_body.get("node_id") or "") if scope == "node" else ""
        content_md = str(payload_body.get("content_md") or "")
        if not content_md.strip():
            raise HTTPException(
                status_code=400,
                detail=error_payload("knowledge_doc_empty_content", "正文是空的，没有保存。"),
            )
        saved = await asyncio.to_thread(
            knowledge_doc_store().save_markdown,
            knowledge_doc_mod.doc_key_for(
                user.user_id, project_id, scope=scope, node_id=node_id
            ),
            content_md,
        )
        if not saved:
            raise HTTPException(
                status_code=404,
                detail=error_payload("knowledge_doc_not_found", "这份文档还不存在，先生成一份再编辑。"),
            )
        return {"ok": True, "scope": scope, "node_id": node_id, "chars": len(content_md)}

    @application.get("/api/projects/{project_id}/knowledge-doc/layers")
    async def list_knowledge_doc_layers(project_id: str, request: Request) -> dict[str, Any]:
        """每个前置层号上各有几个知识点 —— 前端画「只读到第 N 层」的选择器要用。

        层号来自 ``compute_progression_chain``：前置链最长长度 + 1，第 1 层没有前置。
        ⚠️ 必须按**全量**节点算，不能只算已生成详解的那些：否则某个知识点因为还没
        生成而消失，把它依赖的前置也一起漏掉，层号会整体下移（1.10 突然变成 L1）。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        nodes = await asyncio.to_thread(db.list_framework_nodes, project_id)
        chain = knowledge_doc_mod.compute_progression_chain(nodes)
        documented = {
            d["node_id"]
            for d in knowledge_doc_store().list_for_project(user.user_id, project_id)
            if d["scope"] == "node" and str(d.get("content_md") or "").strip()
        }
        rows: dict[int, dict[str, int]] = {}
        for node in nodes:
            layer = int((chain.get(node.node_id) or {}).get("layer", 1))
            row = rows.setdefault(layer, {"layer": layer, "total": 0, "documented": 0})
            row["total"] += 1
            if node.node_id in documented:
                row["documented"] += 1
        return {"items": [rows[key] for key in sorted(rows)]}

    @application.post("/api/projects/{project_id}/knowledge-doc/compile")
    async def compile_knowledge_doc(project_id: str, request: Request) -> dict[str, Any]:
        """把已生成的各节点详解合订成一份长文。**纯本地拼装，不调模型**。

        body 可带两个参数，都只影响「顺序与收录范围」，不改任何正文、不调模型：

        - ``order="layer"`` —— 改按**前置层号**排（第 1 层一章、第 2 层一章……），
          初学者由浅入深顺着读。默认 ``"tree"``：按框架树的章节顺序，与速查表一致。
          两者必须能选 —— 框架树按章节组织、层号按依赖算，本来就不对齐，
          按树排会出现「L1 之后直接跳到 L8」。
        - ``max_layer=N`` —— 只收进第 1~N 层，给「刚入门、只想先看基础」的人。
        """
        user = require_user(request)
        project = require_project_access(project_id, request)
        try:
            payload_body = await request.json()
        except Exception:
            payload_body = {}
        by_layer = str(payload_body.get("order") or "").strip().lower() == "layer"
        try:
            max_layer = max(0, int(payload_body.get("max_layer") or 0))
        except (TypeError, ValueError):
            max_layer = 0

        nodes = await asyncio.to_thread(db.list_framework_nodes, project_id)
        store = knowledge_doc_store()
        docs = await asyncio.to_thread(
            store.list_for_project, user.user_id, project_id
        )
        by_node = {
            d["node_id"]: d
            for d in docs
            if d["scope"] == "node" and str(d.get("content_md") or "").strip()
        }
        if not by_node:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "knowledge_doc_nothing_to_compile",
                    "还没有任何知识点文档可以合订。先给知识点点「＋文档」，或用顶部的「一键生成整份」。",
                ),
            )

        # 递进坐标（第几站 / 第几层 / 承接与引出谁）纯本地算：事实来源是框架的前置边，
        # 不该让模型编，也不该多花一次模型调用。
        chain = knowledge_doc_mod.compute_progression_chain(nodes)
        if by_layer or max_layer > 0:
            # 截断后站号必须重新算，否则正文里会出现「第 87 站」而全文只有 20 节。
            nodes, chain = knowledge_doc_mod.order_by_layer(
                nodes, chain, max_layer=max_layer
            )

        sections: list[tuple[Any, str, list[str]]] = []
        for node, path in _knowledge_doc_tree_order(nodes):
            doc = by_node.get(node.node_id)
            if doc:
                sections.append((node, doc["content_md"], path or [node.name]))
        if by_layer:
            # tree_order 给的是「父在子前」的树序；层序要按 (层, 树序) 重新排一遍。
            # 同层内没有依赖先后，树序就是稳定序。
            position = {item[0].node_id: i for i, item in enumerate(sections)}
            sections.sort(
                key=lambda item: (
                    int((chain.get(item[0].node_id) or {}).get("layer", 1)),
                    position[item[0].node_id],
                )
            )
        sources = await asyncio.to_thread(db.list_sources, project_id)
        subject = str(getattr(project, "subject", "") or "课程")
        year = str(getattr(project, "year", "") or "")
        content_md = knowledge_doc_mod.render_compiled_markdown(
            project_label=f"{subject}（{year}）" if year else subject,
            sections=sections,
            node_total=len(nodes),
            source_count=sum(1 for s in sources if s.status == "ok"),
            generated_at=knowledge_doc_mod.local_stamp(),
            progression=chain,
            group_by_layer=by_layer,
            layer_limit=max_layer if by_layer else 0,
        )
        # 各节的递进坐标随正文一起落库：前端左目录靠它给每一节挂「第 N 层 · 承 X」徽标，
        # 不必再去解析正文里的 `> 递进 · …` 那一行。
        section_meta = [
            {
                "node_id": node.node_id,
                "name": node.name,
                "layer": (chain.get(node.node_id) or {}).get("layer", 1),
                "station": (chain.get(node.node_id) or {}).get("station", 0),
                "before": (chain.get(node.node_id) or {}).get("before") or [],
                "after": (chain.get(node.node_id) or {}).get("after") or [],
            }
            for node, _body, _path in sections
        ]
        saved = await asyncio.to_thread(
            store.save,
            doc_key=knowledge_doc_mod.doc_key_for(user.user_id, project_id, scope="project"),
            owner_id=user.user_id,
            project_id=project_id,
            scope="project",
            title=f"{subject} · 知识文档",
            signature="",
            content={
                "node_count": len(sections),
                "node_total": len(nodes),
                "sections": section_meta,
                # 这次的排序/截断口径跟着正文一起落库：重新打开这份文档时，
                # 顶栏要能告诉用户「这份是按层序、只到第 3 层合的」
                "order": "layer" if by_layer else "tree",
                "max_layer": max_layer,
            },
            content_md=content_md,
        )
        return {
            "doc": saved,
            "covered": len(sections),
            "total": len(nodes),
            "order": "layer" if by_layer else "tree",
            "max_layer": max_layer,
        }

    @application.post("/api/projects/{project_id}/knowledge-doc/ask")
    async def ask_knowledge_doc(project_id: str, request: Request) -> StreamingResponse:
        """读到一半选中一段话提问，答案以 SSE 流式返回（2026-09-30）。

        证据边界和生成时保持一致：只把「这一节的正文 + 学生选中的原文 + 节点说明与
        相邻知识点」交给模型，默认提示词里写死「材料里没写就直说没写」。
        合订稿可能几万字，所以只送**选区附近的窗口**（core/knowledge_doc.excerpt_around），
        既省 token，也避免模型在中段丢掉指令。

        ``allow_extra=true`` 是第二档（2026-10-05）：材料外确实需要的知识可以答，但必须
        放进 `## 材料外补充` 整段自报家门。为什么不默认放开 —— 详解本身就是按「宁缺勿滥」
        生成的，答题时偷偷用通识补料，等于把生成阶段守住的那条线在问答阶段又漏回去。
        """
        user = require_user(request)
        require_project_access(project_id, request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        question = str(body.get("question") or "").strip()
        if not question:
            raise HTTPException(
                status_code=400,
                detail=error_payload("knowledge_doc_question_required", "先写一句想问的问题。"),
            )
        if not application.state.settings.tju_api_key:
            raise HTTPException(
                status_code=503,
                detail=error_payload(
                    "api_key_required",
                    "提问需要大模型 API。请先配置 API Key：登录后在「API 配置」页填写，或编辑 .env 设置 TJU_API_KEY。",
                ),
            )

        scope = knowledge_doc_mod.normalize_scope(body.get("scope"))
        node_id = str(body.get("node_id") or "").strip()
        selection = str(body.get("selection") or "")
        section = str(body.get("section") or "")
        history = body.get("history") if isinstance(body.get("history"), list) else []
        store = knowledge_doc_store()

        node: Any = None
        path: list[str] = []
        neighbors: list[Neighbor] = []
        context = ""
        if scope == "node" and node_id:
            node = await asyncio.to_thread(db.get_framework_node, project_id, node_id)
            neighbors, path = _knowledge_doc_context(project_id, node)
            doc = await asyncio.to_thread(store.get_node, user.user_id, project_id, node_id)
            context = str((doc or {}).get("content_md") or "")
            if not context:
                # 详解还没生成也能问：退到节点自己的说明与笔记，比什么都不给强
                context = "\n\n".join(
                    str(part).strip()
                    for part in (getattr(node, "description", ""), getattr(node, "note_content", ""))
                    if str(part or "").strip()
                )
        else:
            doc = await asyncio.to_thread(
                store.get,
                knowledge_doc_mod.doc_key_for(user.user_id, project_id, scope="project"),
            )
            context = str((doc or {}).get("content_md") or "")
        context = knowledge_doc_mod.excerpt_around(context, selection)

        # 两档：默认严格（材料外直说没写），学生显式勾了才允许发散，且要求分段标注。
        # 前端 bool 只当开关用，不当授权来源 —— 任何 truthy 都当成开启。
        allow_extra = bool(body.get("allow_extra"))

        payload = knowledge_doc_mod.build_ask_payload(
            question=question,
            selection=selection,
            scope=scope,
            node=node,
            path=path,
            neighbors=neighbors,
            context=context,
            section=section,
            history=history,
            allow_extra=allow_extra,
        )
        messages = [
            {
                "role": "system",
                "content": stream_system_prompt(
                    "ask_knowledge_doc", ask_allow_extra=allow_extra
                ),
            },
            {
                "role": "user",
                "content": json.dumps(
                    {"task": "ask_knowledge_doc", "payload": payload}, ensure_ascii=False
                ),
            },
        ]

        def _ask_sse(event: dict[str, Any]) -> str:
            return f"data: {json.dumps(event, ensure_ascii=False)}\n\n"

        async def event_stream() -> AsyncIterator[str]:
            yield _ask_sse(
                {"type": "start", "scope": scope, "context_chars": len(context)}
            )
            pieces: list[str] = []
            try:
                async for chunk in application.state.llm.astream_chat_content(
                    messages, "ask_knowledge_doc"
                ):
                    pieces.append(chunk)
                    yield _ask_sse({"type": "delta", "text": chunk})
            except Exception as exc:  # noqa: BLE001 —— 要变成人能看懂的一句话，不是堆栈
                LOGGER.warning("knowledge doc ask failed: %s", exc)
                yield _ask_sse({"type": "error", "message": f"这次没答上来：{exc}"})
                return
            answer = knowledge_doc_mod.clean_answer("".join(pieces))
            if not answer:
                yield _ask_sse(
                    {"type": "error", "message": "模型这次没有返回内容，可以再问一次。"}
                )
                return
            yield _ask_sse({"type": "done", "text": answer})

        return StreamingResponse(
            event_stream(),
            media_type="text/event-stream",
            headers={"Cache-Control": "no-cache", "X-Accel-Buffering": "no"},
        )

    @application.get("/api/projects/{project_id}/knowledge-doc/export.md")
    async def export_knowledge_doc(project_id: str, request: Request) -> Response:
        """下载 Markdown。``scope=project``（默认，合订稿）或 ``scope=node&node_id=xxx``。"""
        user = require_user(request)
        project = require_project_access(project_id, request)
        scope = str(request.query_params.get("scope") or "project").strip().lower()
        if scope not in knowledge_doc_mod.SCOPES:
            scope = "project"
        store = knowledge_doc_store()
        if scope == "node":
            node_id = str(request.query_params.get("node_id") or "").strip()
            if not node_id:
                raise HTTPException(
                    status_code=400,
                    detail=error_payload("knowledge_doc_node_required", "导出单个知识点文档需要 node_id。"),
                )
            doc = await asyncio.to_thread(store.get_node, user.user_id, project_id, node_id)
            node = await asyncio.to_thread(db.get_framework_node, project_id, node_id)
            raw_title = f"{node.name}-知识点文档"
        else:
            doc = await asyncio.to_thread(
                store.get,
                knowledge_doc_mod.doc_key_for(user.user_id, project_id, scope="project"),
            )
            raw_title = f"{str(getattr(project, 'subject', '') or '课程')}-知识文档"
        if not doc or not str(doc.get("content_md") or "").strip():
            raise HTTPException(
                status_code=404,
                detail=error_payload("knowledge_doc_not_found", "这份文档还没有生成。"),
            )
        safe_title = re.sub(r'[\\/:*?"<>|\r\n]+', "_", raw_title).strip(" .")[:80] or "知识点文档"
        encoded = quote(f"{safe_title}.md", safe="")
        return Response(
            content=doc["content_md"],
            media_type="text/markdown; charset=utf-8",
            headers={
                "Content-Disposition": (
                    'attachment; filename="knowledge-doc.md"; '
                    f"filename*=UTF-8''{encoded}"
                )
            },
        )

    @application.get("/api/projects/{project_id}/conflicts")
    async def list_conflicts(project_id: str, request: Request) -> dict[str, Any]:
        """该项目已发现的资料矛盾。只呈现分歧，不判定谁对。"""
        require_project_access(project_id, request)
        store = conflict_store()
        items = await asyncio.to_thread(store.list_for_project, project_id)
        summary = await asyncio.to_thread(store.summary, project_id)
        return {"conflicts": items, "summary": summary}

    @application.post("/api/projects/{project_id}/conflicts/scan")
    async def scan_conflicts(project_id: str, request: Request) -> dict[str, Any]:
        """扫描多份资料之间的矛盾。

        宁缺勿滥：模型返回后会再过一遍清洗（两边必须有足够长的原文摘录、
        摘录不能相同、topic 不能重复），伪冲突在这里就被丢掉。
        """
        project = require_project_access(project_id, request)
        user = require_user(request)
        nodes = await asyncio.to_thread(db.list_framework_nodes, project_id)
        sources = await asyncio.to_thread(db.list_sources, project_id)
        usable = [s for s in sources if str(getattr(s, "text", "") or "").strip()]
        if len(usable) < 2:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "conflict_scan_needs_sources",
                    f"至少要两份有正文的资料才能比对矛盾，现在只有 {len(usable)} 份。"
                    "请再导入一些讲义或教材。",
                ),
            )

        payload = conflicts_mod.build_scan_payload(
            project_name=f"{project.subject}（{project.year}）",
            nodes=nodes,
            sources=usable,
        )
        try:
            resp = await asyncio.to_thread(
                application.state.llm.complete_json, "detect_conflicts", payload
            )
        except Exception as exc:  # noqa: BLE001
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "conflict_scan_failed",
                    f"扫描资料矛盾时模型调用失败：{exc}。可以稍后重试，或减少资料份数再试。",
                ),
            ) from exc

        cleaned = conflicts_mod.normalize_conflicts((resp or {}).get("conflicts"))
        node_index = {node.name: node.node_id for node in nodes}
        rows = await asyncio.to_thread(
            conflict_store().replace_all,
            project_id=project_id,
            owner_id=user.user_id,
            conflicts=cleaned,
            node_index=node_index,
        )
        store = conflict_store()
        summary = await asyncio.to_thread(store.summary, project_id)
        return {
            "scanned_sources": len(usable),
            "raw_count": len(((resp or {}).get("conflicts") or [])),
            "kept_count": len(rows),
            "conflicts": await asyncio.to_thread(store.list_for_project, project_id),
            "summary": summary,
        }

    @application.patch("/api/projects/{project_id}/conflicts/{conflict_id}")
    async def update_conflict(
        project_id: str, conflict_id: str, request: Request
    ) -> dict[str, Any]:
        """把一条矛盾标为「已判定」或改回「待判定」。

        重扫时**已判定**的记录会被保留 —— 那是用户自己做过判断的痕迹，不该被机器覆盖。
        """
        require_project_access(project_id, request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        raw = (body or {}).get("status")
        if str(raw or "").strip().lower() not in conflicts_mod.STATUSES:
            raise HTTPException(
                status_code=400,
                detail=error_payload(
                    "invalid_conflict_status",
                    f"状态只支持 open（待判定）与 resolved（已判定），收到的是「{raw}」。",
                ),
            )
        updated = await asyncio.to_thread(
            conflict_store().set_status, project_id, conflict_id, raw
        )
        if updated is None:
            raise HTTPException(
                status_code=404,
                detail=error_payload(
                    "conflict_not_found", "这条矛盾记录不存在或已被重新扫描覆盖。"
                ),
            )
        return {"conflict": updated}

    # ===================== 论文全网搜索 & 期刊检索（2026-09-25 新增） =====================
    #
    #   GET  /api/search/papers          —— 论文关键词搜索（Semantic Scholar）
    #   GET  /api/search/authors         —— 学者搜索（Semantic Scholar）
    #   GET  /api/search/author-papers   —— 学者论文列表
    #   GET  /api/search/paper-detail    —— 单篇论文详情
    #   GET  /api/search/journals        —— 期刊搜索（OpenAlex）
    #   GET  /api/search/journal-detail  —— 期刊详情
    #
    # 全部为新增端点，命名空间 /api/search/*，与既有端点零冲突。
    # 不需要项目上下文，只需登录态。

    from core import paper_search as _ps
    from core import paper_recall as _pr

    @application.get("/api/search/papers")
    async def api_search_papers(
        request: Request,
        q: str = "",
        offset: int = 0,
        limit: int = 20,
        year: str | None = None,
        fields: str | None = None,
        open_access: bool | None = None,
        min_citations: int | None = None,
        sort: str | None = None,
        rewrite: bool = True,
    ) -> dict[str, Any]:
        """论文全网搜索（多源并发 + RRF 融合 + 规则精排）。

        2026-09-26 起走 core/paper_recall.py 的四层管线：查询理解 → 多路召回 → 融合 → 精排。
        原单源实现（Semantic Scholar，限流后掉进无语义排序的 Crossref）保留为异常兜底。

        响应是旧结构的**超集**：total / offset / papers 三个键含义不变，
        新增 sources（各源命中与状态）/ degraded（降级原因）/ query_plan（改写结果）/ pipeline。
        `rewrite=false` 可关闭中文→英文改写（按原词检索）。
        """
        require_user(request)
        if not q.strip():
            return {
                "total": 0,
                "offset": 0,
                "papers": [],
                "sources": [],
                "degraded": [],
                "query_plan": None,
                "pipeline": "recall-v2",
            }
        llm = getattr(application.state, "llm", None)
        try:
            return await asyncio.to_thread(
                _pr.search_papers_smart,
                q.strip(),
                offset,
                limit,
                year=year,
                fields_of_study=fields,
                open_access=open_access,
                min_citation=min_citations,
                sort=sort,
                llm=llm,
                rewrite=rewrite,
            )
        except Exception as exc:  # noqa: BLE001 - 新管线不能把检索整个打死
            LOGGER.warning(
                "paper recall pipeline failed, falling back to single-source: %s", exc
            )
            result = await asyncio.to_thread(
                _ps.search_papers,
                q.strip(),
                offset,
                limit,
                year=year,
                fields_of_study=fields,
                open_access=open_access,
                min_citation=min_citations,
                sort=sort,
            )
            result.setdefault("sources", [])
            result.setdefault(
                "degraded",
                [{"source": "pipeline", "reason": f"多源管线异常，已退回单源：{exc}"}],
            )
            result.setdefault("query_plan", None)
            result["pipeline"] = "single-source-fallback"
            return result

