    @application.post("/api/search/paper-deep-analysis")
    async def api_search_paper_deep_analysis(
        request: Request,
        payload: dict[str, Any] = Body(default={}),
    ) -> dict[str, Any]:
        """对任意论文生成顶刊科研级 6 维深度解析（TL;DR、动机、架构方法、定量指标、审稿挑刺、抗辩战术）。

        配置科研画像后，额外附带相关度判定与阅读建议三字段；
        未配置画像则这三字段诚实降级为「无法判断 / 未配置画像」。
        """
        user = require_user(request)
        paper_dict = (
            payload.get("paper") if isinstance(payload.get("paper"), dict) else payload
        )
        llm = getattr(application.state, "llm", None)
        profile_store = getattr(application.state, "research_profile_store", None)
        profile = profile_store.load(user.user_id) if profile_store else None
        analysis = await asyncio.to_thread(
            _ps.generate_paper_deep_analysis, paper_dict, llm, profile
        )
        return {"ok": True, "analysis": analysis}

    @application.get("/api/research-profile")
    async def api_get_research_profile(request: Request) -> dict[str, Any]:
        """读取当前用户的科研画像（未配置时返回默认空画像）。"""
