    @application.post("/api/search/import-paper")
    async def api_search_import_paper(request: Request):
        """从搜索结果的 PDF URL 下载论文并导入到用户的文献库。

        改为 SSE 流式返回进度（download→parse→save→meta→done/error）：
        之前是单个阻塞请求，下载大 PDF 可能几十秒无反馈，用户不知道卡在哪一步。
        """
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        pdf_url = (body.get("pdf_url") or "").strip()
        title = (body.get("title") or "").strip() or "论文"
        doi = (body.get("doi") or "").strip()
        authors = (body.get("authors") or "").strip()

        if not pdf_url:
            raise HTTPException(
                status_code=422,
                detail=error_payload("missing_url", "请提供论文 PDF 链接。"),
            )

        # 下载 PDF。用浏览器 UA + Accept 头：仅用 "KnowOrigin/1.0" 会被 Europe PMC / NCBI
        # 等 OA 源识别为爬虫直接 403/500。
        import httpx as _httpx

        _pdf_headers = {
            "User-Agent": (
                "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                "(KHTML, like Gecko) Chrome/124.0 Safari/537.36"
            ),
            "Accept": "application/pdf,application/octet-stream,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
        }

        def _sse(ev: dict[str, Any]) -> str:
            return f"data: {json.dumps(ev, ensure_ascii=False)}\n\n"

        async def event_stream():
            # 阶段 1：下载（流式，带字节进度）
            yield _sse({"type": "stage", "stage": "download", "message": "正在下载 PDF…"})
            content = b""
            try:
                async with _httpx.AsyncClient(timeout=120, follow_redirects=True) as client:
                    async with client.stream("GET", pdf_url, headers=_pdf_headers) as resp:
                        resp.raise_for_status()
                        total = 0
                        try:
                            total = int(resp.headers.get("content-length") or 0)
                        except (TypeError, ValueError):
                            total = 0
                        done = 0
                        last = 0
                        async for chunk in resp.aiter_bytes():
                            content += chunk
                            done += len(chunk)
                            # 节流：每前进 2% 或 64KB 发一次，避免大 PDF 刷屏
                            if total > 0 and (done - last >= max(total // 50, 65536) or done >= total):
                                yield _sse({
                                    "type": "progress", "stage": "download",
                                    "done": done, "total": total,
                                })
                                last = done
            except Exception as exc:
                yield _sse({
                    "type": "error",
                    "message": "下载 PDF 失败（可能是付费墙 / 反爬 / 网络不通）：" + str(exc),
                })
                return

            if len(content) < 100:
                yield _sse({"type": "error", "message": "下载的文件太小，可能不是有效的 PDF。"})
                return

            # 很多 OA 链接返回的是 HTML 落地页而非 PDF 本体，提前识别
            if not content[:5] == b"%PDF-":
                yield _sse({
                    "type": "error",
                    "message": "该链接返回的不是 PDF 文件（付费墙或需要浏览器访问的落地页）。"
                               "请点击 DOI 链接打开原文页，手动下载 PDF 后再导入。",
                })
                return

            # 阶段 2：解析
            yield _sse({"type": "stage", "stage": "parse", "message": "正在解析 PDF…"})
            filename = title[:80] + ".pdf"
            try:
                extracted = await _extract_uploaded_source(application, filename, content)
            except Exception as exc:
                yield _sse({"type": "error", "message": "解析 PDF 失败：" + str(exc)})
                return
            if extracted.status == "unsupported":
                yield _sse({"type": "error", "message": "无法解析下载的文件。"})
                return

            # 阶段 3：写入文献库
            yield _sse({"type": "stage", "stage": "save", "message": "正在写入文献库…"})
            try:
                project = db.create_literature(user.user_id, title)
                saved = db.add_source(project.project_id, extracted)
                await _persist_source_file(application, saved, content)
            except Exception as exc:
                yield _sse({"type": "error", "message": "写入文献库失败：" + str(exc)})
                return

            # 阶段 4：提取元数据（失败不阻断导入）
            yield _sse({"type": "stage", "stage": "meta", "message": "正在提取元数据…"})
            try:
                meta = await asyncio.to_thread(lambda: _literature_extract(project.project_id))
                if doi and not meta.get("doi"):
                    meta["doi"] = doi
                if authors and not meta.get("authors"):
                    meta["authors"] = authors
                db.upsert_literature_meta(project.project_id, meta)
            except Exception:
                pass

            yield _sse({"type": "done", "project_id": project.project_id, "title": title})

        return StreamingResponse(event_stream(), media_type="text/event-stream")

    # =========================================================================
    # 科研全流程高阶加速：PRISMA 结构化综述矩阵 + 顶刊同行评审红队
    # =========================================================================

    @application.post("/api/research/matrix/generate", status_code=201)
    async def api_research_matrix_generate(request: Request) -> dict[str, Any]:
        """为选中的论文生成 PRISMA 结构化综述对比矩阵。"""
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        project_id = str(body.get("project_id") or "").strip()
        topic = str(body.get("topic") or "").strip()
        title = str(body.get("title") or "").strip()
        custom_columns = body.get("custom_columns") or []

        raw_papers = body.get("papers") or []
        paper_ids = body.get("paper_ids") or []

        papers_to_process = list(raw_papers)
        if paper_ids:
            for pid in paper_ids:
                found = False
                # 策略 A: pid 本身是独立文献项目 ID (Literature Project)
                try:
                    p_obj = db.get_project(pid)
                    if p_obj:
                        p_meta = db.get_literature_meta(pid) or {}
                        p_sources = [
                            s
                            for s in db.list_sources(pid)
                            if (
                                getattr(s, "text", "")
                                or getattr(s, "content", "")
                                or ""
                            ).strip()
                        ]
                        if not p_sources:
                            p_sources = db.list_sources(pid)
                        txt = "\n\n".join(
                            (getattr(s, "text", "") or getattr(s, "content", ""))
                            for s in p_sources
                        )[:8000]
                        p_title = (
                            p_meta.get("title")
                            or p_obj.subject
                            or (p_sources[0].filename if p_sources else "论文")
                        )
                        papers_to_process.append(
                            {
                                "paper_id": pid,
                                "title": p_title,
                                "authors": p_meta.get("authors", ""),
                                "year": p_meta.get("year", ""),
                                "venue": p_meta.get("venue", ""),
                                "abstract": p_meta.get("abstract", ""),
                                "content": txt,
                            }
                        )
                        found = True
                except Exception:
                    pass

                # 策略 B: pid 是当前 project 下的 source_id
                if not found and project_id:
                    try:
                        p_sources = db.list_sources(project_id)
                        p_meta = db.get_literature_meta(project_id) or {}
                        for s in p_sources:
                            if s.source_id == pid:
                                papers_to_process.append(
                                    {
                                        "paper_id": s.source_id,
                                        "title": s.filename,
                                        "authors": p_meta.get("authors", ""),
                                        "year": p_meta.get("year", ""),
                                        "venue": p_meta.get("venue", ""),
                                        "abstract": p_meta.get("abstract", ""),
                                        "content": (
                                            getattr(s, "text", "")
                                            or getattr(s, "content", "")
                                        )[:8000],
                                    }
                                )
                                found = True
                                break
                    except Exception:
                        pass

        if not papers_to_process:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "need_papers", "请至少提供 1 篇文献进行结构化抽取。"
                ),
            )

        payload = matrix_mod.build_matrix_payload(
            papers_to_process,
            topic=topic,
            custom_columns=custom_columns,
        )

        try:
            extracted = await asyncio.to_thread(
                application.state.llm.complete_json,
                "extract_evidence_matrix",
                payload,
            )
        except Exception as exc:
            raise HTTPException(
                status_code=502,
                detail=error_payload(
                    "extraction_failed", f"模型抽取综述矩阵失败：{exc}"
                ),
            )

        rows = extracted.get("rows") or []
        summary_md = extracted.get("summary_md") or ""
        columns = matrix_mod.DEFAULT_COLUMNS

        saved = await asyncio.to_thread(
            evidence_matrix_store().save,
            project_id=project_id or "global_research",
            owner_id=user.user_id,
            title=title or (f"{topic} 综述矩阵" if topic else "系统综述证据矩阵"),
            topic=topic,
            columns=columns,
            rows=rows,
            summary_md=summary_md,
        )
        return {"matrix": saved}

