    @application.post("/api/research/reviewer/critique", status_code=201)
    async def api_research_reviewer_critique(request: Request) -> dict[str, Any]:
        """启动顶刊同行评审专家红队，生成全套挑刺与防守报告。"""
        user = require_user(request)
        try:
            body = await request.json()
        except Exception:
            body = {}
        project_id = str(body.get("project_id") or "").strip()
        target_type = str(body.get("target_type") or "literature").strip()
        target_id = str(body.get("target_id") or "").strip()
        title = str(body.get("title") or "").strip()
        abstract = str(body.get("abstract") or "").strip()
        content = str(body.get("content") or "").strip()
        venue_tier = str(
            body.get("venue_tier") or "IEEE Trans / Optica 顶级期刊"
        ).strip()
        author_notes = str(body.get("author_notes") or "").strip()

        if target_type == "literature" and target_id:
            # 策略 A: target_id 本身是文献项目 ID (Literature Project)
            try:
                p_obj = db.get_project(target_id)
                if p_obj:
                    meta = db.get_literature_meta(target_id) or {}
                    sources = [
                        s
                        for s in db.list_sources(target_id)
                        if (
                            getattr(s, "text", "") or getattr(s, "content", "") or ""
                        ).strip()
                    ]
                    if not sources:
                        sources = db.list_sources(target_id)
                    title = (
                        title
                        or meta.get("title")
                        or p_obj.subject
                        or (sources[0].filename if sources else "论文")
                    )
                    abstract = abstract or meta.get("abstract") or ""
                    content = (
                        content
                        or "\n\n".join(
                            (getattr(s, "text", "") or getattr(s, "content", ""))
                            for s in sources
                        )[:10000]
                    )
            except Exception:
                pass

            # 策略 B: target_id 是某个项目下的 source_id
            if not content and project_id:
                try:
                    sources = db.list_sources(project_id)
                    for s in sources:
                        if s.source_id == target_id:
                            title = title or s.filename
                            content = (
                                content
                                or (
                                    getattr(s, "text", "") or getattr(s, "content", "")
                                )[:10000]
                            )
                            break
                    meta = db.get_literature_meta(project_id) or {}
                    abstract = abstract or meta.get("abstract", "")
                except Exception:
                    pass

        if not title and not abstract and not content:
            raise HTTPException(
                status_code=422,
                detail=error_payload(
                    "missing_content", "请提供待评审的论文题目、摘要或正文草稿。"
                ),
            )

        payload = peer_review_mod.build_peer_review_payload(
            title=title,
            abstract=abstract,
            content=content,
            venue_tier=venue_tier,
            author_notes=author_notes,
        )

        try:
            review_res = await asyncio.to_thread(
                application.state.llm.complete_json,
                "peer_reviewer_critique",
                payload,
            )
        except Exception as exc:
            raise HTTPException(
                status_code=502,
                detail=error_payload("critique_failed", f"审稿专家模型调用失败：{exc}"),
            )

        overall_score = review_res.get("overall_score") or 5
        recommendation = review_res.get("recommendation") or "Borderline"
        summary_of_work = review_res.get("summary_of_work") or ""

        saved = await asyncio.to_thread(
            peer_review_store().save,
            project_id=project_id or "global_research",
            owner_id=user.user_id,
            target_type=target_type,
            target_id=target_id or None,
            target_title=title or "待审论文工作",
            venue_tier=venue_tier,
            overall_score=overall_score,
            recommendation=recommendation,
            summary_of_work=summary_of_work,
            review_data=review_res,
        )
        return {"review": saved}

