    @application.post("/api/exams/add")
    async def api_exams_add(
        request: Request, payload: dict[str, Any] = Body(...)
    ) -> dict[str, Any]:
        """添加或更新考试安排。"""
        user = require_user(request)
        course_name = str(payload.get("course_name") or "").strip()
        exam_time = str(payload.get("exam_time") or "").strip()
        if not course_name or not exam_time:
            raise HTTPException(
                status_code=422,
                detail=error_payload("missing_fields", "科目名称和考试时间为必填项。"),
            )

        proj_id = payload.get("project_id")
        if not proj_id:
            all_projs = db.list_projects(user.user_id)
            c_lower = course_name.lower()
            for p in all_projs:
                p_sub = (getattr(p, "subject", "") or getattr(p, "name", "")).lower()
                if c_lower in p_sub or p_sub in c_lower:
                    proj_id = p.project_id
                    break

        sched = exam_scheduler()
        saved = await asyncio.to_thread(
            sched.add_or_update_exam,
            owner_id=user.user_id,
            course_name=course_name,
            exam_time=exam_time,
            exam_id=payload.get("exam_id"),
            location=str(payload.get("location") or ""),
            seat_number=str(payload.get("seat_number") or ""),
            project_id=proj_id,
            exam_type=str(payload.get("exam_type") or "期末考试"),
            target_score=int(payload.get("target_score") or 90),
            focus_chapters=payload.get("focus_chapters"),
            notes=str(payload.get("notes") or ""),
        )
        return {"ok": True, "exam": saved}

